window.QURAN_TAFSIRS["waseet"] = {"1":{"1":"{ بسم ٱلله الرَّحْمٰنِ الرَّحِيـمِ }الاسم: اللفظ الذى يدل على ذات أو معنى. وقد اختلف النحويون فى اشتقاقه على وجهين، فقال البصريون: هو مشتق من السمو، وهو العلو والرفعة، فقيل: اسم، لأن صاحبه بمنزلة المرتفع به.وقال الكوفيون: إنه مشتق من السمة وهى العلامة، لأن الاسم علامة لمن وضع له، فأصل اسم على هذا \" وسم \".ويرى المحققون أن رأى البصريين أرجح، لأنه يقال فى تصغير \" اسم \" سُمىَ، وفى جمعه أسماء، والتصغير والجمع يردان الأشياء إلى أصولها. ولو كان أصله وسم - كما قال الكوفيون - لقيل فى جمعه: أوسام، وفى تصغيره وسيم.ولفظ الجلالة وهو \" الله \" علم على ذات الخالق - عز وجل - تفرد به - سبحانه - ولا يطلق على غيره، ولا يشاركه فيه أحد.قال القرطبى: قوله \" الله \" هذا الاسم أكبر أسمائه - سبحانه - وأجمعها حتى قال بعض العلماء: إنه اسم الله الأعظم ولم يتسم به غيره، ولذلك لم يثن ولم يجمع: فالله اسم للموجود الحق الجامع لصفات الإِلهية، المنعوت بنعوت الربوبيه، المنفرد بالوجود الحقيقى، لا إله إلا هو - سبحانه -و { ٱلرَّحْمـٰنِ ٱلرَّحِيمِ } صفتان مشتقتان من الرحمة. والرحمة فى أصل اللغة: رقة فى القلب تقتضى الإِحسان، وهذا المعنى لا يليق أن يكون وصفاً لله - تعالى-، ولذا فسرها بعض العلماء بإرادة الإِحسان. وفسرها آخرون بالإِحسان نفسه.والموافق لمذهب السلف أن يقال: هى صفة قائمة بذاته - تعالى - لا نعرف حقيقتها، وإنما نعرف أثرها الذى هو الإِحسان.وقد كثرت أقوال المفسرين فى العلاقة بين هاتين الصفتين، فبعضهم يرى أن { ٱلرَّحْمـٰنِ } هو المنعم على جميع الخلق. وأن { ٱلرَّحِيمِ } هو المنعم على المؤمنين خاصه. ويرى آخرون أن { ٱلرَّحْمـٰنِ } هو المنعم بجلائل النعم، وأن { ٱلرَّحِيمِ } هو المنعم بدقائقها.ويرى فريق ثالث أن الوصفين بمعنى واحد وأن الثانى منهما تأكيد للأول. والذى يراه المحققون من العلماء أن الصفتين ليستا بمعنى واحد، بل روعى فى كل منهما معنى لم يراع فى الآخر، فالرحمن بمعنى عظيم الرحمة، لأن فعلان صيغة مبالغة فى كثرة الشئ وعظمته، ويلزم منه الدوام كغضبان وسكران. والرحيم بمعنى دائم الرحمة، لأن صيغته فعيل تستعمل فى الصفات الدائمة ككريم وظريف. فكأنه قيل: العظيم الرحمة الدائمة.أو أن { ٱلرَّحْمـٰنِ } صفة ذاتية هى مبدأ الرحمة والإِحسان. و { ٱلرَّحِيمِ } صفة فعل تدل على وصول الرحمة والإِحسان وتعديهما إلى المنعم عليه.ولعل مما يؤيد ذلك أن لفظ الرحمن لم يذكر فى القرآن إلا مجرى عليه الصفات كما هو الشأنِ فى أسماء الذات. قال - تعالى-:{ ٱلرَّحْمَـٰنُ عَلَّمَ ٱلْقُرْآنَ } و{ ٱلرَّحْمَـٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ }{ قُلِ ٱدْعُواْ ٱللَّهَ أَوِ ٱدْعُواْ ٱلرَّحْمَـٰنَ }وهكذا...أما لفظ الرحيم فقد كثر فى القرآن استعماله وصفاً فعلياً، وجاء فى الغالب بأسلوب التعدية والتعلق بالمنعم عليه. قال - تعالى -{ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ }{ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيماً }{ إِنَّهُ كَانَ بِكُمْ رَحِيماً }إلخ.قال بعض العلماء \" وهذا الرأى فى نظرنا هو أقوى الآراء، فإن تخصيص أحد الوصفين بدقائق النعم أو ببعض المنعم عليهم لا دليل عليه، كما أنه ليس مستساغاً أن يقال فى القرآن: إن كلمة ذكرت بعد أخرى لمجرد تأكيد المعنى المستفاد منها \".والجار والمجرور \" بسم \" متعلق بمحذوف تقديره ابتدئ.والمعنى: ابتدئ قراءتى متبركاً ومتيمناً باسم الله الذى هو الأول والآخر، والظاهر والباطن، والذى رحمته وسعت كل شئ، وأتبرأ مما كان يفعله المشركون والضالون، من ابتدائهم قراءتهم وأفعالهم باسم اللات أو باسم العزى أو باسم غيرهما من الآلهة الباطلة.هذا وقد أجمع العلماء على أن البسملة جزء آية من سورة النمل فى قوله - تعالى -{ إِنَّهُ مِن سُلَيْمَانَ وَإِنَّهُ بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ }ثم اختلفوا بعد ذلك فى كونها آية مستقلة أنزلت للفصل بين السور مرة واحدة، أو هى آية من سورة الفاتحة ومن كل سورة ألخ.فبعضهم يرى أن البسملة آية من الفاتحة ومن كل سورة، ومن حججهم أن السلف قد أثبتوها فى المصحف مع الأمر بتجريد القرآن مما ليس منه، ولذا لم يكتبوا \" آمين \". فثبت بهذا أن البسملة جزء من الفاتحة ومن كل سورة.وبهذا الرأى قال ابن عباس وابن عمر وأبو هريرة وسعيد بن جبير والشافعى، وأحمد فى أحد قوليه.ويرى آخرون أن البسملة ليست آية من الفاتحة ولا من غيرها من السور، وقالوا: إنها آية فذة. من القرآن أنزلت للفصل والتبرك للابتداء بها، ومن حججهم أنها لو كانت آية من الفاتحة ومن كل سورة، لما اختلف الناس فى ذلك، ولما اضطربت أقوالهم فى كونها آية من كل سورة أو من الفاتحة فقط.وكما وقع الخلاف بين العلماء فى كونها آية مستقلة أو آية من كل سورة، فقد وقع الخلاف بينهم - أيضاً - فى وجوب قراءتها فى الصلاة، وفى الجهر بها أو الإِسرار إذا قرئت.وتحقيق القول فى ذلك مرجعه إلى كتب الفقه، وإلى كتب التفسير التى عنيت بتفسير آيات الأحكام.","2":"{ الحمد } هو الثناء باللسان على الجميل الصادر عن اختيار من نعمة أو غيرها.{ رب العالمين } أى: مالكهم، إذ الرب مصدر \" ربه يربه \" إذا تعاهده بالتربية حتى يبلغ به شيئاً فشيئا درجة الكمال. وهو اسم من أسماء الله - تعالى - ولا يطلق على غيره إلا مقيداً فيقال: رب الدار، ورب الضيعة أى: صاحبها ومالكها.والعالمين: جمع عالم، وهو كل موجود سوى الله - تعالى -قال القرطبى: \" وهو مأخوذ من العلم والعلامة لأنه يدل على موجده \" وقيل: المراد بالعالمين أولو العلم من الإِنس والجن والملائكة.وقد افتتحت سورة الفاتحة بهذه الجملة الكريمة { ٱلْحَمْدُ للَّهِ رَبِّ ٱلْعَالَمِينَ } لأنه سبحانه أول كل شئ وآخر كل شئ، ولكى يعلمنا - سبحانه - أن نبدأ كتبنا وخطبنا بالحمد والثناء عليه، حتى نبدأ ونحن فى صلة بالله تكشف عن النفوس أغشيتها، وتجلو عن القلوب أصداءها.والمعنى - كما قال ابن جرير - \" الشكر خالصاً لله - جل ثناؤه - دون سائر ما يعبد من دونه، ودون كل ما برأ من خلقه بما أنعم على عباده من النعم التى لا يحصيها العدد. ولا يحيط بعددها غيره أحد، فى تصحيح الآلات لطاعته، وتمكين جوارح أجسام المكلفين لأداء فرائضه، مع ما بسط لهم فى دنياهم من الرزق، وغذاهم به من نعيم العيش، عن غير استحقاق لهم عليه، ومع ما نبههم عليه ودعاهم إليه، من الأسباب المؤدية إلى دوام الخلود فى دار المقام فى النعيم المقيم. لربنا الحمد على ذلك كله أولا وآخراً.فالآية الكريمة قد قررت بصراحة ووضوح ثبوت الثناء المطلق الذى لا يحد لله - تعالى - وانه ليس لأحد أن ينازعه إباه - سبحانه - هو رب العالمين.وجملة { ٱلْحَمْدُ للَّهِ } مفيدة لقصر الحمد عليه - سبحانه - نحو قولهم: \" الكرم فى العرب \". كما أن أل فى \" الحمد \" للاستغراق. أى: أن جميع أجناس الحمد ثابتة لله رب العالمين.وإنما كان الحمد مقصوراً فى الحقيقة على الله، لأن كل ما يستحق أن يقابل بالثناء فهو صادر عنه ومرجعه إليه، إذ هو الخالق لكل شئ، وما يقدم إلى بعض الناس من حمد جزاء إحسانهم، فهو فى الحقيقة حمد لله، لأنه - سبحانه - هو الذى وفقهم لذلك وأعانهم عليه.ولم تفتتح السورة بصيغة الأمر بأن يقال: احمدوا الله، وإنما افتتحت بصيغة الخبر { ٱلْحَمْدُ للَّهِ } ، لأن الأمر يقتضى التكليف: والتكليف قد تنفر منه النفوس أحياناً، فأراد - سبحانه - وهو يبادئهم بشرعة جديدة وتكاليف لم يعهدوها، أن يؤنس نفوسهم، ويؤلف قلوبهم، فساق لهم الخطاب بصيغة الخبر، ترفقا بهم، حتى يديموا الإِصغاء لما سيلقيه عليهم من تكاليف.وقد تكلم بعض المفسرين عن الحكمة فى ابتداء السورة الكريمة بقوله - تعالى - { ٱلْحَمْدُ للَّهِ } ، دون قوله - تعالى -: المدح لله، أو: الشكر لله. فقال:اعلم أن المدح أعم من الحمد، والحمد أعم من الشكر. أما بيان أن المدح أعم من الحمد فلأن المدح يحصل للعاقل وغير العاقل، ألا ترى أنه كما يحسن مدح الرجل العاقل على أنواع فضائله، فكذلك قد يمدح اللؤلؤ لحسن شكله.أما الحمد فإنه لا يحصل إلا للفاعل المختار على ما يصدر منه من الإِنعام والإِحسان، فثبت أن المدح أعم من الحمد.وأما بيان أن الحمد أعم من الشكر، فلأن الحمد عبارة عن تعظيم الفاعل لأجل ما صدر عنه من الإِنعام. سواء أكان ذلك الإِنعام واصلا إليك أم إلى غيرك. وأما الشكر فهو عبارة عن تعظيمه لأجل إنعام وصل إليك، فثبت بما ذكرنا أن المدح أعم من الحمد، وأن الحمد أعم من الشكر.إذا عرفت هذا فنقول: إنما لم يقل: المدح لله، لأننا بينا أن المدح كما يحصل للفاعل المختار فقد يحصل لغيره. وأما الحمد فإنه لا يحصل إلا للفاعل المختار. فكان قوله \" الحمد لله \" تصريحاً بأن المؤثر فى وجود هذا العالم فاعل مختار خلقه بالقدرة والمشيئة... وإنما لم يقل: الشكر لله، لأننا بينا أن الشكر عبارة عن تعظيمه بسبب إنعام صدر منه ووصل إليك، وهذا يشعر بأن العبد إذا ذكر تعظيمه بسبب ما وصل إليه من النعمة. فحينئذ يكون المطلوب الأصلى له وصول النعمة إليه. وهذه درجة حقيرة. فأما إذا قال \" الحمد لله \" ، فهذا يدل على أن العبد حمده لأجل كونه مستحقا للحمد لا لخصوص أنه - سبحانه - أوصل النعمة إليه، فيكون الإِخلاص أكمل، واستغراق القلب فى مشاهدة نور الحق أتم، وانقطاعه عما سوى الحق أقوى وأثبت.وقد أجرى - سبحانه - على لفظ الجلالة نعت الربوبيه للعالمين، ليكون كالاستدلال على استحقاقه - تعالى - للحمد وحده، وفى ذلك إشعار لعباده بأنهم مكرمون من ربهم، إذ الأمر بغير توجيه فيه إيماء إلى إهمال عقولهم، أما إذا كان موجهاً ومعللا فإنه يكون فيه إشعار لهم برعاية ناحية العقل فيهم، وفى تلك الرعاية تشريف وتكريم لهم.فكأنه - سبحانه - يقول لهم: اجعلوا حمدكم وثناءكم لى وحدى. لأنى أنا رب العالمين. وأنا الذى تعهدتكم برعايتى وتربيتى منذ تكوينكم من الطين حتى استويتم عقلاء مفكرين.","3":"وقد أتبع - سبحانه - هذا الوصف وهو { رَبِّ ٱلْعَالَمِينَ } ، بوصف آخر هو { ٱلرَّحْمـٰنِ ٱلرَّحِيمِ } لحكم سامية من أبرزها: أن وصفه - تعالى - بـ { رَبِّ ٱلْعَالَمِينَ } أى: مالكهم، قد يثير فى النفوس شيئاً من الخوف أو الرهبة، فإن المربى قد يكون خشناً جباراً متعنتاً، وذلك مما يخدش من جميل التربية، وينقص من فضل التعهد.لذا قرن - سبحانه - كونه مربياً، بكونه الرحمن الرحيم، لينفى بذلك هذا الاحتمال، وليفهم عباده بأن ربوبيته لهم مصدرها عموم رحمته وشمول إحسانه، فهم برحمته يوجدون، وبرحمته يتصرفون ويرزقون، وبرحمته يبعثون ويسألون.ولا شك أن فى هذا الإِفهام تحريضاً لهم على حمده وعبادته بقلوب مطمئنة، ونفوس مبتهجة، ودعوة لهم إلى أن يقيموا حياتهم على الرحمة والإِحسان، لا على الجبروت والطغيان، فالراحمون يرحمهم الرحمن.","4":"بعد أن بين - سبحانه - لعباده موجبات حمده، وأنه الجدير وحده بالحمد، لأنه المربى الرحيم، والمنعم الكريم، أتبع ذلك ببيان أنه - سبحانه - { مَـٰلِكِ يَوْمِ ٱلدِّينِ }.والمالك وصف من الملك - بكسر الميم - بمعنى حيازة الشئ مع القدرة على التصرف فيه. واليوم فى العرف: ما يكون من طلوع الشمس إلى غروبها، وليس هذا مراداً هنا، وإنما المراد مطلق الزمن وهو يوم القيامة.والدين: الجزاء والحساب، يقال: دنته بما صنع، أى: جازيته على صنيعه، ومنه قولهم. كما تدين تدان. أى: كما تفعل تجازى، وفى الحديث \" الكيس من دان نفسه وعمل لما بعد الموت \" أى: حاسب نفسه: والمعنى: أنه - تعالى - يتصرف فى أمور يوم الدين من حساب وثواب وعقاب، تصرف المالك فيما يملك، كما قال - تعالى -{ يَوْمَ لاَ تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئاً وَٱلأَمْرُ يَوْمَئِذٍ لِلَّهِ }وهناك قراءة أخرى للآية وهى { مَـٰلِكِ يَوْمِ ٱلدِّينِ } من الملك - بضم الميم - وعليها يكون المعنى: أنه - تعالى - هو المدبر لأمور يوم الدين، وأن له على ذلك اليوم هيمنة الملوك وسيطرتهم، فكل شئ فى ذلك اليوم يجرى بأمره، وكل تصرف فيه ينفذ باسمه، كما قال - تعالى -{ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ لِلَّهِ ٱلْوَاحِدِ ٱلْقَهَّارِ }قال الإِمام ابن كثير: \" وتخصيص الملك بيوم الدين لا ينفيه عما عداه، لأنه قد تقدم الإِخبار بأنه رب العالمين، وذلك عام فى الدنيا والآخرة. وإنما أضيف إلى يوم الدين، لأنه لا يدعى أحد هنالك شيئاً، ولا يتكلم أحد إلا بإذنه، كما قال - تعالى -{ يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلاَئِكَةُ صَفّاً لاَّ يَتَكَلَّمُونَ إِلاَّ مَنْ أَذِنَ لَهُ ٱلرَّحْمَـٰنُ وَقَالَ صَوَاباً }والملك فى الحقيقة هو الله، قال - تعالى -{ هُوَ ٱللَّهُ ٱلَّذِي لاَ إِلَـٰهَ إِلاَّ هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلاَمُ }وفى الصحيحين عن أبى هريرة، عن رسول الله - صلى الله عليه وسلم - أنه قال: \" يقبض الله الأرض، ويطوى السماء بيمينه ثم يقول: أنا الملك أين ملوك الأرض؟ أين الجبارون، أين المتكبرون \" ثم قال: وأما تسمية غيره فى الدنيا بملك فعلى سبيل المجاز كما قال - تعالى -{ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكاً }وفى هذه الأوصاف التى أجريت على الله تعالى، من كونه ربا للعالمين وملكا للأمر كله يوم الجزاء، بعد الدلالة على اختصاص الحمد به فى قوله: { ٱلْحَمْدُ للَّهِ } فى كل ذلك دليل على أن من كانت هذه صفاته لم يكن أحد أحق منه للحمد والثناء عليه، بل لا يستحق ذلك على الحقيقة سواه، فإن ترتب الحكم على الوصف مشعر بعليته له \".والمتدبر لهذه الآية الكريمة يراها خير وسيلة لتربية الإِنسان وغرس الإِيمان العميق فى قلبه، لأنه إذا آمن بأن هناك يوما يظهر فيه إحسان المحسن وإساءة المسئ، وأن زمام الحكم فى ذلك اليوم لله الواحد القهار، فإنه فى هذه الحالة سيقوى عنده خلق المراقبة لخالقه، ويجتهد فى السير على الطريق المستقيم.","5":"كانت الآيات الثلاث التى تقدمت هذه الآية تقريراً للحقيقة فى جانب الربوبية وعظمتها وعموم سلطانها وسعة رحمتها تقريرا جمع أمور الدنيا والآخرة ثم جاءت هذه الآية لتقرر أن الذى يجدر بنا أن نعبده وأن نسعتين به إنما هو الله الذى تجلت أوصافه، ووضحت عظمته، وثبتت هيمنته على هذا الكون.ولفظ \" إيا \" ضمير منفصل، و \" الكاف \" الملحقة به للخطاب.والعبارة تفيد أن الطاعة البالغة حد النهاية فى الخضوع والخشوع والتعظيم، والعبادة الصحيحة تتأتى للمسلم بتحقق أمرين: إخلاصها لله، وموافقتها لما جاء به النبى صلى الله عليه وسلم.قال ابن جرير: \" لأن العبودية عند جميع العرب أصلها الذلة، وأنها تسمى الطريق المذلل الذى وطئته الأقدام وذللته السابلة معبداً \".والاستعانة: طلب المعونة، من أجل الأقتدار على الشئ والتمكن من فعله.والمعنى: لك يا ربنا وحدك نخشع ونذل ونستكين، فقد توليتنا برعايتك وغمرتنا برحمتك، فنحن نخصك بطلب الإِعانة على طاعتك وعلى أمورنا كلها، ولا نتوجه بهذا الطلب إلى أحد سواك، فأنت المستحق للعبادة، وأنت القدير على كل شئ، والعليم ببواطن الأمور وظواهرها، لا تخفى عليك طوية، ولا تتوارى عنك نية.وقدم - سبحانه - المعبود على العبادة فقال: { إِيَّاكَ نَعْبُدُ } ، لإِفادة قصر العبادة عليه، وهو ما يقتضيه التوحيد الخالص.وقال: { نعبد } بنون الجماعة ولم يقل أعبد، ليدل على أن العبادة أحسن ما تكون فى جماعة المؤمنين، وللإِشعار بأن المؤمنين المخلصين يكونون فى اتحادهم وإخائهم بحيث يقوم كل واحد منهم فى الحديث عن شئونهم الظاهرة وغير الظاهرة مقام جميعهم، فهم كما قال النبى صلى الله عليه وسلم: \" المؤمنون تتكافأ دماؤهم، ويسعى بذمتهم أدناهم، وهم يد على من سواهم \".وقدمت العبادة على الاستعانة، لكون الأولى وسيلة إلى الثانية. وتقديم الوسائل سبب فى تحصيل المطالب، وليدل على أنهم لا يستقلون بإقامة العبادات، بل إن عون الله هو الذى ييسر لهم أداءها.ولم يذكر المستعان عليه من الأعمال، ليشمل الطلب كل ما تتجه إليه نفس الإِنسان من الأعمال الصالحة.وجاءت الآية الكريمة بأسلوب الخطاب على طريقة الالتفات، تلوينا لنظم الكلام من أسلوب إلى أسلوب. وقد وضح هذا المعنى صاحب الكشاف فقال: \" فإن قلت: لم عدل عن لفظ الغيبة إلى لفظ الخطاب؟ قلت: هذا يسمى الالتفات فى علم البيان.وهو قد يكون من الغيبة إلى الخطاب، ومن الخطاب إلى الغيبة، ومن الغيبة إلى التكلم... وذلك على عادة العرب فى افتنانهم فى الكلام وتصرفهم فيه. لأن الكلام إذا نقل من أسلوب إلى أسلوب، كان ذلك أحسن تطرية لنشاط السامع، وإيقاظاً للإِصغاء إليه من إجرائه على أسلوب واحد: وقد تختص مواضعه بفوائد. ومما اختص به هذا الموضع: أنه لما ذكر الحقيق بالحمد، وأجرى عليه تلك الصفات العظام، تعلق العلم بمعلوم عظيم الشأن، حقيق بالثناء وغاية للخضوع والاستعانة فى المهمات، فخوطب ذلك المعلوم المتميز بتلك الصفات فقيل: إياك يا من هذه صفاته نخصك بالعبادة والاستعانة، ولا نعبد غيرك ولا نستعينه... \".هذا، وقد جاءت فى فضل هذه الآية الكريمة آثار متعددة، ومن ذلك قول بعض العلماء: الفاتحة سر القرآن، وسرها هذه الكلمة { إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ } فالأول تبرؤ من الشرك، والثانى تبرؤ من الحول والقوة والتفويض إلى الله \".","6":"ثم بين - سبحانه - أن أفضل شئ يطلبه العبد من ربه، إنما هو هدايته إلى الطريق الذى يوصل إلى أسمى الغايات، وأعظم المقاصد، فقال - تعالى -:{ ٱهْدِنَا ٱلصِّرَاطَ ٱلْمُسْتَقِيمَ صِرَاطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِم وَلاَ ٱلضَّآلِّينَ }.والهداية: هى الإِرشاد والدلالة بلطف على ما يوصل إلى البغية، وتسند الهداية إلى الله وإلى النبى وإلى القرآن، وقد يراد منها الإِيصال إلى ما فيه خير، وهى بهذا المعنى لا تضاف إلى الله - تعالى -.قال أبو حيان فى البحر ما ملخصه: وقد تأتى بمعنى التبيين كما فى قوله - تعالى -{ وَأَمَّا ثَمُودُ فَهَدَيْنَاهُمْ }أى بينا لهم طريق الخير. أو بمعنى الإِلهام كما فى قوله تعالى.{ قَالَ فَمَن رَّبُّكُمَا يٰمُوسَىٰ قَالَ رَبُّنَا ٱلَّذِيۤ أَعْطَىٰ كُلَّ شَيءٍ خَلْقَهُ ثُمَّ هَدَىٰ }قال المفسرون معناه: ألهم الحيوانات كلها إلى منافعها، أو بمعنى الدعاء كما فى قوله. تعالى:{ وَلِكُلِّ قَوْمٍ هَادٍ }أى: داع. والأصل فى هدى أن يصل إلى ثانى معموليه باللام كما فى قوله. تعالى.{ إِنَّ هَـٰذَا ٱلْقُرْآنَ يَِهْدِي لِلَّتِي هِيَ أَقْوَمُ }أو بإلى كما فى قوله تعالى:{ وَإِنَّكَ لَتَهْدِيۤ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ }ثم يتسع فيه فيعدى إليه بنفسه ومنه: { ٱهْدِنَا ٱلصِّرَاطَ ٱلْمُسْتَقِيمَ }.والصراط: الجادة والطريق، من سَرط الشئ إذا ابتلعه، وسمى الطريق بذلك لأنه يبتلع المارين فيه، وتبدل سينه صاد على لغة قريش.والمستقيم: المعتدل الذى لا اعوجاج فيه.وأنعمت عليهم: النعمة لين العيش وخفضه، ونعم الله كثيرة لا تحصى.{ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِم } الغضب هيجان النفس وثورتها، عند الميل إلى الانتقام، وهو ضد الرضا. وإذا أسند إلى الله فسر بمعنى إرادة الانتقام أو بمعنى الانتقام نفسه.والموافق لمذهب السلف أن يقال: هو صفة له - تعالى - لائقة بجلاله لا نعلم حقيقتها مجردة عن اللوازم البشرية وإنما نعرف أثرها وهو الانتقام من العصاة، وإنزال العقوبة بهم.والمعنى: اهدنا يا ربنا إلى طريقك المستقيم، الذى يوصلنا إلى سعادة الدنيا والآخرة، ويجعلنا مع الذين أنعمت عليهم من خلقك، وجنبنا يا مولانا طريق الذين غضبت عليهم من الأمم السابقة أو الأجيال اللاحقة بسبب سوء أعمالهم وطريق الذين هاموا فى الضلالات، فانحرفوا عن القصد، وحق عليهم العذاب.وفى هذا الدعاء أسمى ألوان الأدب، لأن هذا الدعاء قد تضرع به المؤمنون إلى خالقهم بعد أن اعترفوا له - سبحانه - قبل ذلك بأنه هو المستحق لجميع المحامد، وأنه هو رب العالمين، والمتصرف فى أحوالهم يوم الدين.قال الإِمام ابن كثير: وهذا أكمل أحوال السائل. أن يمدح مسئوله ثم يسأل حاجته وحاجة إخوانه المؤمنين بقوله: { ٱهْدِنَا ٱلصِّرَاطَ ٱلْمُسْتَقِيمَ } لأنه أنجح للحاجة، وأنجع للإِجابة، ولهذا أرشدنا الله إليه لأنه الأكمل.وقد تكلم المفسرون كلاماً كثيراً عن المراد بالصراط المستقيم الذى جعل الله طلب الهداية إليه فى هذا السورة أول دعوة علمها لعباده. والذى نراه: أن أجمع الأقوال فى ذلك أن المراد بالصراط المستقيم، هو ما جاء به الإِسلام من عقائد وآداب وأحكام، توصل الناس متى اتبعوها إلى سعادة الدنيا والآخرة، فإن طريق السلام هو الطريق الذى ختم الله به الرسالات السماوية، وجعل القرآن دستوره الشامل، ووكل إلى النبى صلى الله عليه وسلم أمر تبليغه وبيانه.وقد ورد فى الأحاديث النبوية ما يؤيد هذا القول، ومن ذلك ما أخرجه الإِمام أحمد فى مسنده، عن النواس بن سمعان، عن رسول الله صلى الله عليه وسلم أنه قال: \" ضرب الله مثلا صراطا مستقيما، وعلى جنبتى الصراط سوران فيهما أبواب مفتحة، وعلى الأبواب ستور مرخاة، وعلى باب الصراط داع يقول: يا أيها الناس ادخلوا الصراط جميعاً ولا تعوجوا، وداع يدعو من فوق الصراط، فإذا أراد الإِنسان أن يفتح شيئاً من تلك الأبواب قال له: ويحك لا تفتحه، فإنك إن تفتحه تلجه، فالصراط الإِسلام، والسوران حدود الله، والأبواب المفتحة محارم الله، وذلك الداعى من فوق الصراط واعظ الله فى قلب كل مسلم \".والمراد بقوله - تعالى - { ٱهْدِنَا ٱلصِّرَاطَ ٱلْمُسْتَقِيمَ } أى: ثبتنا عليه، واجعلنا من المداومين على السير فى سبيله، فإن العبد مفتقر إلى الله فى كل وقت لكى يثبته على الهداية، ويزيده منها، ويعينه عليها. وقد أمر سبحانه المؤمنين أن يقولوا:{ رَبَّنَا لاَ تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ ٱلْوَهَّابُ }وجملة { صِرَاطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ } بدل من الصراط المستقيم.ولم يقل: اهدنا صراط الذين أنعمت عليهم مستغنياً عن ذكر الصراط المستقيم، ليدل أن صراط هؤلاء المنعم عليهم هو الصراط المستقيم.","7":"وجملة { صِرَاطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ } بدل من الصراط المستقيم.ولم يقل: اهدنا صراط الذين أنعمت عليهم مستغنياً عن ذكر الصراط المستقيم، ليدل أن صراط هؤلاء المنعم عليهم هو الصراط المستقيم.وقال: { صِرَاطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ } ولم يقل صراط الأنبياء أو الصالحين، ليدل على أن الدين فى ذاته نعمة عظيمة، ويكفى للدلالة على عظمتها إسنادها إليه - تعالى - فى قوله: { أَنْعَمْتَ عَلَيْهِمْ } لأن المراد بالإِنعام هنا - على الراجح - الإِنعام الدينى. فالمنعم عليهم هم من عرفوا الحق فتمسكوا به، وعرفوا الخير فعملوا به.قال بعض العلماء: (وإنما اختار فى البيان أن يضيف الصراط إلى المنعم عليهم لمعنيين:أولهما: هو إبراز نفسية المحب المخلص، وأنه يكون شديد الاحتياط دقيق التحرى عن الطريق الموصل إلى ساحة الرضا فى ثقة تملأ نفسه، وتفعم قلبه، ولا يجد فى مثل هذا المقام ما يملأ نفسه ثقة إلا أن يبين الطريق، بأنه الطريق الذى وصل بالسير عليه من قبله الأنبياء والصديقون والشهداء والصالحون.وثانيهما: أن من خواطر المؤمل فى نعيم ربه أن يكون تمام أنسه فى رفقة من الناس صالحين، وصحب منهم محسنين).وقوله - تعالى - { غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِم } بدل من { ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ } وأتى فى وصف الإِنعام بالفعل المسند إلى الله - تعالى - فقال: { أنعمت عليهم } فى وصف الغضب باسم المفعول فقال: { غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِم } وفى ذلك تعليم لأدب جميل، وهو أن الإِنسان يجمل به أن يسند أفعال الإِحسان إلى الله، ويتحامى أن يسند إليه أفعال العقاب والابتلاء، وإن كان كل من الإِحسان والعقاب صادراً منه، ومن شواهد هذا قوله - تعالى - حكاية عن مؤمنى الجن{ وَأَنَّا لاَ نَدْرِيۤ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَداً }وحرف (لا) فى قوله { وَلاَ ٱلضَّآلِّينَ } جئ به لتأكيد معنى النفى المستفاد من كلمة غير. والمراد بالمغضوب عليهم اليهود. وبالضالين النصارى. وقد ورد هذا التفسير عن النبى صلى الله عليه وسلم فى حديث رواه الإِمام أحمد فى مسنده وابن حبان فى صحيحه.ومن المفسرين من قال بأن المراد بالمغضوب عليهم من فسدت إرادتهم حيث علموا الحق ولكنهم تركوه عناداً وجحودا، وأن المراد بالضالين من فقدوا العلم فهم تائهون فى الضلالات دون أن يهتدوا إلى طريق قويم.وقدم المغضوب عليهم على الضالين، لأن معنى المغضوب عليهم كالضد لمعنى المنعم عليهم، ولأن المقابلة بينهما أوضح منها بين المنعم عليهم والضالين، فكان جديراً بأن يوضع فى مقابلته قبل الضالين.قال العلماء: ويستحب لمن يقرأ الفاتحة أن يقول بعدها (آمين) ومعناه اللهم استجب وليس هذا اللفظ من القرآن بدليل أنه لم يثبت فى المصاحف والدليل على استحباب التأمين ما رواه الإِمام أحمد وأبو داود والترمذى عن وائل بن حجر قال: سمعت النبى صلى الله عليه وسلم قرأ { غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِم وَلاَ ٱلضَّآلِّينَ } فقال: (آمين) مد بها صوته.وفى الصحيحين عن أبى هريرة أن رسول الله صلى الله عليه وسلم قال: \" إذا أمن الإِمام فأمنوا، فإن من وافق تأمينه تأمين الملائكة غفر الله له ما تقدم من ذنبه \".هذا، وقد أفاض العلماء فى الحديث عما اشتملت عليه سورة الفاتحة من آداب وعقائد وعبادات وأحكام، ومن ذلك قول ابن كثير.(اشتملت هذه السورة الكريمة، وهى سبع آيات - على حمد الله وتمجيده والثناء عليه بذكر أسمائه الحسنى المستلزمة لصفاته العليا، وعلى ذكر المعاد وهو يوم الدين، وعلى إرشاد عبيده إلى سؤاله والتضرع إليه والتبرى من حولهم وقوتهم، إلى إخلاص العبادة له وتوحيده بالألوهية، وتنزيهه عن أن يكون له شريك أو نظير، وإلى سؤالهم إياه الهداية إلى الصراط المستقيم، وهو الدين القويم وتثبيتهم عليه، واشتملت على الترغيب فى الأعمال الصالحة ليكونوا مع أهلها يوم القيامة، والتحذير من مسالك الباطل لئلا يحشروا مع سالكيها يوم القيامة، وهم المغضوب عليهم والضالون).وقال بعض العلماء: سورة الفاتحة مشتملة على أربعة أنواع من العلوم هى مناط الدين.أحدها: علم الأصول وإليه الإِشارة بقوله { ٱلْحَمْدُ للَّهِ رَبِّ ٱلْعَالَمِينَ ٱلرَّحْمـٰنِ ٱلرَّحِيمِ } ، ومعرفة النبوات وإليه الاشارة بقوله: { أَنْعَمْتَ عَلَيْهِمْ } ومعرفة المعاد وإليه الاشارة بقوله { مَـٰلِكِ يَوْمِ ٱلدِّينِ }.وثانيها: علم الفروع وأعظمه العبادات وإليه الإِشارة بقوله { إِيَّاكَ نَعْبُدُ }.وثالثها: علم الأخلاق، وإليه الإِشارة بقوله { وَإِيَّاكَ نَسْتَعِينُ ٱهْدِنَا ٱلصِّرَاطَ ٱلْمُسْتَقِيمَ }.ورابعها: علم القصص والأخبار عن الأمم السابقة السعداء منهم والأشقياء، وهو المراد بقوله { صِرَاطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِم وَلاَ ٱلضَّآلِّينَ }.وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم."},"78":{"1":"لفظ \" عم \" مركب من كلمتين ، هما حرف الجر \" عن \" و \" ما \" التى هى اسم استفهام ، فأصل هذا اللفظ : \" عن ما \" فأدغمت النون فى الميم لأن الميم تشاركها فى الغنة وحذف الألف ليتميز الخبر عن الاستفهام . والجار والمجرور متعلق بفعل \" يتساءلون \" .والتساؤل : تفاعل من السؤال ، بمعنى أن يسأل بعض الناس بعضا عن أمر معين ، على سبيل معرفة وجه الحق فيه ، أو على سبيل التهكم .والنبأ : الخبر مطلقا ، ويرى بعضهم أنه الخبر ذو الفائدة العظيمة .والمعنى : عن أى شئ يتساءل هؤلاء المشركون؟ وعن أى أمر يسأل بعضهم بعضا؟ إنهم يتساءلون عن النبأ العظيم ، والخبر الهام الذى جاءهم به الرسول صلى الله عليه وسلم ، والذى نطق به القرآن الكريم ، من أن البعث حق ، ومن أن هذا القرآن الكريم من عند الله - تعالى - ومن أن الرسول صلى الله عليه وسلم صادق فيما يأمرهم به أو ينهاهم عنه .وافتتح - سبحانه - الكلام بأسلوب الاستفهام ، لتشويق السامع إلى المستفهم عنه ، ولتهويل أمره ، وتعظيم شأنه .والضمير فى قوله ( يتساءلون ) يعود إلى المشركون ، الذين كانوا يكثرون من التساؤل فيما بينهم عن الرسول صلى الله عليه وسلم ، عما جاء به من عند ربه ، فقد أخرج ابن جرير وابن أبى حاتم عن الحسن قال : لما بعث النبى صلى الله عليه وسلم جعلوا يتساءلون فيما بينهم - عن أمره وعما جاءهم به - فنزل قوله - تعالى - : ( عَمَّ يَتَسَآءَلُونَ . عَنِ النبإ العظيم . . ) .وصح عود الضمير إليهم مع أنهم لم يسبق لهم ذكر ، لأنهم معرفون من السياق ، إذ هم - دون غيرهم - الذين كانوا يتساءلون فيما بينهم - على سبيل التهكم - عما جاء به النبى صلى الله عليه وسلم .","2":"وقوله - تعالى - : ( عَنِ النبإ العظيم ) تهويل لشأن هذا الأمر الذى يتساءلون فيما بينهم عنه ، ووصف - سبحانه - النبأ بالعظم ، زيادة فى هذا التهويل والتفخيم من شأنه ، لكى تتوجه إليه أذهانهم ، وتلتفت إليهم أفهامهم .فكأنه - سبحانه - يقول : عن أى شئ يسأل هؤلاء الجاحدون بعضهم بعضا؟ أتريدون أن تعرفوا ذلك على سبيل الحقيقة؟ ما بين منكر له إنكارا تاما ، كما حكى - سبحانه - عنهم فى قوله : ( إِنْ هِيَ إِلاَّ حَيَاتُنَا الدنيا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ ) وما بين مترد فى شأنه ، كما حكى - سبحانه - عن بعضهم فى قوله : ( وَإِذَا قِيلَ إِنَّ وعْدَ الله حَقٌّ والساعة لاَ رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِي مَا الساعة إِن نَّظُنُّ إِلاَّ ظَنّاً وَمَا نَحْنُ بِمُسْتَيْقِنِينَ ) قال صاحب الكشاف قوله : ( عم ) أصله عما ، على أنه حرف جر ، دخل على ما الاستفهامية .ومعنى هذا الاستفهام : تفخيم الشأن ، كأنه قال : عن أى شئ يتساءلون . ونحوه ما فى قولك : زيد ما زيد؟ جعلته لانقطاع قرينه ، وعدم نظيره ، كأنه شئ خفى عليك جنسه . فأنت تسأل عن جنسه ، وتفحص عن جوهره ، كما تقول : ما الغول وما العنقاء . . ؟و ( يَتَسَآءَلُونَ ) يسأل بعضهم بعضا . . والضمير لأهل مكة ، فقد كانوا يتساءلون فيما بينهم عن البعث .وقوله : ( عَنِ النبإ العظيم ) بيان للشأن المفخم .","3":"فإن قلت : قد زعمت أن الضمير فى ( يَتَسَآءَلُونَ ) للكفار ، فما تصنع بقوله : ( الذي هُمْ فِيهِ مُخْتَلِفُونَ ) ؟ قلت : كان فيهم من يقطع القول بإنكار البعث ، ومنهم من يشك .وقيل : الضمير للمسلمين والكافرين جميعا ، وكانوا جميعا يسألون عنه ، أما المسلم فليزداد خشية واستعدادا ، وأما الكافر فليزداد استهزاء . .","4":"ثم هدد - سبحانه - هؤلاء المستهزئين بما جاء به النبى صلى الله عليه وسلم تهديدا شديدا ، فقال ( كَلاَّ سَيَعْلَمُونَ . ثُمَّ كَلاَّ سَيَعْلَمُونَ ) .و \" كلا \" حرف زجر وردع ، والمقصود بها هنا : ردع أولئك المتسائلين عن النبأ العظيم ، ونوعدهم على اختلافهم فى شأنه .أى : كلا ليس الأمر كما يتوهمه أولئك المتسائلون ، من استهزائهم بما جاءهم به الرسول صلى الله عليه وسلم ومن إنكارهم لكون القرآن الكريم من عند الله ، أو لكون البعث حق . بل الحق كل الحق أن الرسول صلى الله عليه وسلم صادق كل الصدق فيما يبلغه عن ربه ، وأن هؤلاء المتسائلين سيرون عما قريب سوء عاقبة استهزائهم واختلافهم .","5":"والجملة الثانية وهى قوله : ( ثُمَّ كَلاَّ سَيَعْلَمُونَ ) جئ بها لزيادة التهديد والوعيد ، ولبيان أن الوعيد الثانى أشد وأبلغ من الوعيد الأول .وحذف مفعول ( سَيَعْلَمُونَ ) للتعميم والتهويل ، أى : سيعلمون علم اليقين ما سيحل بهم من عذاب مقيم ، وسيرون ذلك رأى العين عما قريب ، كما قال - تعالى - ( إِنَّهُمْ يَرَوْنَهُ بَعِيداً . وَنَرَاهُ قَرِيباً ).","6":"ثم ساق - سبحانه - بعد ذلك تسعة أدلة ، كلها تدل على أن البعثحق ، لأن القادر على إيجاد هذه الأشياء ، قادر - أيضا - على إعادتهم إلى الحياة ، فقال - تعالى - : ( أَلَمْ نَجْعَلِ الأرض مِهَاداً ) والاستفهام هنا للتقرير ، أى : لقد جعلنا - بقدرتنا التى لا يعجزها شئ - الأرض كالفراش الممهد الموطأ ، لتتمكنوا من الاستقرار عليها ، ومن التقلب فيها . . كما يتقلب الطفل فى مهده ، أى : فراشه .والمهاد : مصدر بمعنى الفراش الموطأ الممهد ، وهو اسم لما يوضع للصبى لكى ينام عليه ، ووصفت الأرض به على سبيل المبالغة فى جعلها مكان استقرار الناس وانتفاعهم وراحتهم ، والكلام على سبيل التشبيه البليغ ، أو على حذف مضاف .وجعل بمعنى صير . أى : لقد صيرنا الأرض بقدرتنا كفراش الصبى بالنسبة لكم ، حيث تتقلبون عليها كما يتقلب الصبى فى فراشه . . أو صيرناها ذات مهاد .قال صاحب الكشاف ما ملخصه : فإن قلت : كيف اتصل قوله : ( أَلَمْ نَجْعَلِ الأرض مِهَاداً ) بما قبله؟ قلت : لما أنكروا البعث قيل لهم : ألم يخلق من يضاف إليه البعث هذه الخلائق العجيبة الدالة على كمال قدرته ، فما وجه إنكار قدرته على البعث ، وما هو إلا اختراع كهذه الاختراعات؟ومهادا : فراشا ، وقرئ : مهدا .ومعناه : أنها لهم كالمهد للصبى ، وهو ما يمهد له فينوّم عليه ، تسمية للممهود بالصدر ، كضرب الأمير ، أو وصفت بالمصدر ، أو بمعنى ذات مهد . .","7":"وقوله : ( والجبال أَوْتَاداً ) معطوف على ما قبله ، والأوتاد : جمع وتد ، وهو ما يشد به الشئ حتى لا يتحرك أو يتضطرب ، والكلام على التشبيه - أيضا - .أى : لقد صيرنا - بقدرتنا - الأرض كالمهاد لتتمكنوا من الاستقرار عليها . . وجعلنا الجبال كالأوتاد للأرض ، لئلا تميد أو تضطرب بكم . . كما قال - تعالى - : ( وألقى فِي الأرض رَوَاسِيَ أَن تَمِيدَ بِكُمْ . . . ).","8":"وقوله - سبحانه - : ( وَخَلَقْنَاكُمْ أَزْوَاجاً ) دليل ثالث على قدرته ، والأزواج : جمع زوج . وهو اسم للعدد الذى يكرر الواحد منه مرة واحدة ، والمراد به هنا : الذكور والإِناث .أى : ومن مظاهر قدرتنا أننا خلقناكم - يا بنى آدم - مزدوجين ، أى : ذكرا وأنثى ، ليتأتى التناسل ، وحفظ النوع من الانقراض ، وتنظيم أمر المعاش فى الأرض ، عن طريق استمتاع كل نوع بالآخر ، كما قال - تعالى - : ( وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَاجاً لتسكنوا إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً . . . ) قال الآلوسى : ( أَزْوَاجاً ) أى : مزدوجين ذكرا وأنثى ليتسنى التناسل .وقيل أزواجا : أى : أصنافا فى اللون والصورة واللسان . وقيل : يجوز أن يكون المراد من الخلق أزواجا : الخلق من منيين : منى الرجل ومنى المرأة . .","9":"وقوله - تعالى - ( وَجَعَلْنَا نَوْمَكُمْ سُبَاتاً ) بيان لدليل رابع على قدرته - تعالى - على البعث . \" السبات \" مصدر بمعنى السبت ، أى : القطع ، يقال : سبت فلان الشئ سبتا ، إذا قطعه ، وسبت فلان شعره ، إذا حلقه وأزاله - وفعله كضرب ونصر - .ويصح أن يكون قوله سباتا من السبت بمعنى الراحة والسكون ، يقال : سبت فلان يسبت ، إذا استراح بعد تعب ، ومنه سمى يوم السبت ، لأن اليهود ينقطعون فيه عن أعمالهم للراحة .والمعنى : وجعلنا - بمقتضى حكمتنا ورحمتنا - نومكم \" سباتا \" أى : قطعا للحركة ، لتحصل لكم للراحة التى لا تستطيعون مواصلة العمل إلا بعدها .وهذه الحالة التى لا بد لكم منها ، وهى الراحة بعد عناء العمل عن طريق النوم ثم استيقاظكم منه ، أشبه ما تكون بإعادة الحياة إليكم بعد موتكم . .","10":"وقوله - تعالى - ( وَجَعَلْنَا الليل لِبَاساً . وَجَعَلْنَا النهار مَعَاشاً ) بيان لنعمة أخرى من نعمه التى لا تحصى ، والتى تدل على كمال قدرته . أى : وجعلنا - بقدرتنا ورحمتنا - الليل كاللباس الساتر لكم ، فهو يلفكم بظلمته ، كما يلف اللباس صاحبه .. كما أننا جعلنا النهار وقت معاشكم ، لكى تحصلوا فيه ما أنتم فى حاجة إلى تحصيله من أرزاق ومنافع .ووصف - سبحانه - الليل بأنه كاللباس ، والنهار بأنه وقت المعاش ، لأن الشأن فيهما كذلك ، إذ الليل هو وقت الراحة والسكون والاختلاء . . والنهار هو وقت السعى والحركة والانتشار .","11":"وقوله - تعالى - ( وَجَعَلْنَا الليل لِبَاساً . وَجَعَلْنَا النهار مَعَاشاً ) بيان لنعمة أخرى من نعمه التى لا تحصى ، والتى تدل على كمال قدرته . أى : وجعلنا - بقدرتنا ورحمتنا - الليل كاللباس الساتر لكم ، فهو يلفكم بظلمته ، كما يلف اللباس صاحبه .. كما أننا جعلنا النهار وقت معاشكم ، لكى تحصلوا فيه ما أنتم فى حاجة إلى تحصيله من أرزاق ومنافع .ووصف - سبحانه - الليل بأنه كاللباس ، والنهار بأنه وقت المعاش ، لأن الشأن فيهما كذلك ، إذ الليل هو وقت الراحة والسكون والاختلاء . . والنهار هو وقت السعى والحركة والانتشار .","12":"ثم لفت - سبحانه - الأنظار إلى مظاهر قدرته فى خلق السموات فقال : ( وَبَنَيْنَا فَوْقَكُمْ سَبْعاً شِدَاداً ) .أى : وبنينا وأوجدنا بقدرتنا التى لا يعجزها شئ ، فوقكم - أيها الناس - سبع سماوات قويات محكمات ، لا يتطرق إليهن فطور أو شقوق على مر العصور ، وكر الدهور .فقوله ( شِدَاداً ) جمع شديدة ، وهى الهيئة الموصوفة بالشدة والقوة .","13":"وقوله - سبحانه - ( وَجَعَلْنَا سِرَاجاً وَهَّاجاً ) نعمة أخرى من نعمه الدالة على قدرته .والمراد بالسراج الوهاج : الشمس ، وصفت بكونها سراجا ، لأنها كالمصباح فى إضاءته لما حوله . ووصف السراج بأنه وهاج ، مبالغة فى شدة ضيائه ولمعانه ، من الوهج - يفتح الواو والهاء - بمعنى شدة الضياء . .والكلام على التشبيه البليغ ، والمقصود منه تقريب صفة المشبه إلى الأذهان ، وإلا فالشمس أعظم من كل سراج .أى : وأنشأنا وأوجدنا - بقدرتنا ومنتنا - فى السماء ، سراجا زاهرا مضيئا . . هو الشمس المتوهجة من شدة حرارتها وضيائها ، والتى تشرق على هذا الكون فتحول ظلامه إلى نور ، بقدرته - تعالى - .","14":"أما الدليل التاسع على قدرته - تعالى - على البعث ، فنراه فى قوله - تعالى - :( وَأَنزَلْنَا مِنَ المعصرات مَآءً ثَجَّاجاً . لِّنُخْرِجَ بِهِ حَبّاً وَنَبَاتاً . وَجَنَّاتٍ أَلْفَافاً ) .والمعصرات - بضم الميم وكسر الصاد - السحب التى تحمل المطر ، جمع معصرة - بكسر الصاد - اسم فاعل ، من أعصرت السحابة إذا أوشكت على إنزال الماء لامتلائها به . .قال ابن كثير : عن ابن عباس : \" المعصرات \" الرياح . لأنها تستدر المطر من السحاب . . وفى رواية عنه أن المراد بها : السحاب ، وكذا قال عكرمة . . واختاره ابن جرير . .وقال الفراء : هى السحاب التى تتحلب بالماء ولم تمطر بعد ، كما يقال : امرأة معصر ، إذا حان حيضها ولم تحض بعد .وعن الحسن وقتادة : المعصرات : يعنى السموات . وهذا قول غريب ، والأظهر أن المراد بها السحاب ، كما قال - تعالى - : ( الله الذي يُرْسِلُ الرياح فَتُثِيرُ سَحَاباً فَيَبْسُطُهُ فِي السمآء كَيْفَ يَشَآءُ وَيَجْعَلُهُ كِسَفاً فَتَرَى الودق يَخْرُجُ مِنْ خِلاَلِهِ . . . ) والثجاج : المندفع بقوة وكثرة ، يقال : ثج الماء - كرد - إذا انصب بقوة وكثرة .ومطر ثجاج ، أى : شديد الانصباب جدا .وقوله : ( أَلْفَافاً ) اسم جمع لا واحد له من لفظه ، كالأوزاع للجماعات المتفرقة . وقيل : جمع لفيف ، كأشراف وشريف . أى : وأنزلنا لكم - يا بنى آدم - بقدرتنا ورحمتنا - من السحائب التى أوشكت على الإِمطار ، ماء كثيرا متدفقا بقوة ، لنخرج بهذا الماء حبا تقتاتون به - كالقمح والشعير .. ونباتا تستعملونه لدوابكم كالتبن والكلأ ، ولنخرج بهذا الماء - أيضا - بساتين قد التفت أغصانها لتقاربها وشدة نمائها .فهذه تسعة أدلة أقامها - سبحانه - على أن البعث حق ، وهى أدلة مشاهدة محسوسة ، لا يستطيع عاقل إنكار واحد منها . . وما دام الأمر كذلك فكيف ينكرون قدرته على البعث ، مع أنه - تعالى - قد أوجد لهم كل هذه النعم التى منها ما يتعلق بخلقهم ، ومنها ما يتعلق بالأرض والسموات ، ومنها ما يتعلق بنومهم ، وبالليل والنهار ، ومنها ما يتعلق بالشمس ، وبالسحب التى تحمل لهم الماء الذى لا يحاة لهم بدونه .وبعد إيراد هذه الأدلة المقنعة لكل عاقل ، أكد - سبحانه - ما اختلفوا فيه ، وما تساءلوا عنه","15":"أما الدليل التاسع على قدرته - تعالى - على البعث ، فنراه فى قوله - تعالى - :( وَأَنزَلْنَا مِنَ المعصرات مَآءً ثَجَّاجاً . لِّنُخْرِجَ بِهِ حَبّاً وَنَبَاتاً . وَجَنَّاتٍ أَلْفَافاً ) .والمعصرات - بضم الميم وكسر الصاد - السحب التى تحمل المطر ، جمع معصرة - بكسر الصاد - اسم فاعل ، من أعصرت السحابة إذا أوشكت على إنزال الماء لامتلائها به . .قال ابن كثير : عن ابن عباس : \" المعصرات \" الرياح . لأنها تستدر المطر من السحاب . . وفى رواية عنه أن المراد بها : السحاب ، وكذا قال عكرمة . . واختاره ابن جرير . .وقال الفراء : هى السحاب التى تتحلب بالماء ولم تمطر بعد ، كما يقال : امرأة معصر ، إذا حان حيضها ولم تحض بعد .وعن الحسن وقتادة : المعصرات : يعنى السموات . وهذا قول غريب ، والأظهر أن المراد بها السحاب ، كما قال - تعالى - : ( الله الذي يُرْسِلُ الرياح فَتُثِيرُ سَحَاباً فَيَبْسُطُهُ فِي السمآء كَيْفَ يَشَآءُ وَيَجْعَلُهُ كِسَفاً فَتَرَى الودق يَخْرُجُ مِنْ خِلاَلِهِ . . . ) والثجاج : المندفع بقوة وكثرة ، يقال : ثج الماء - كرد - إذا انصب بقوة وكثرة .ومطر ثجاج ، أى : شديد الانصباب جدا .وقوله : ( أَلْفَافاً ) اسم جمع لا واحد له من لفظه ، كالأوزاع للجماعات المتفرقة . وقيل : جمع لفيف ، كأشراف وشريف . أى : وأنزلنا لكم - يا بنى آدم - بقدرتنا ورحمتنا - من السحائب التى أوشكت على الإِمطار ، ماء كثيرا متدفقا بقوة ، لنخرج بهذا الماء حبا تقتاتون به - كالقمح والشعير .. ونباتا تستعملونه لدوابكم كالتبن والكلأ ، ولنخرج بهذا الماء - أيضا - بساتين قد التفت أغصانها لتقاربها وشدة نمائها .فهذه تسعة أدلة أقامها - سبحانه - على أن البعث حق ، وهى أدلة مشاهدة محسوسة ، لا يستطيع عاقل إنكار واحد منها . . وما دام الأمر كذلك فكيف ينكرون قدرته على البعث ، مع أنه - تعالى - قد أوجد لهم كل هذه النعم التى منها ما يتعلق بخلقهم ، ومنها ما يتعلق بالأرض والسموات ، ومنها ما يتعلق بنومهم ، وبالليل والنهار ، ومنها ما يتعلق بالشمس ، وبالسحب التى تحمل لهم الماء الذى لا يحاة لهم بدونه .وبعد إيراد هذه الأدلة المقنعة لكل عاقل ، أكد - سبحانه - ما اختلفوا فيه ، وما تساءلوا عنه","16":"أما الدليل التاسع على قدرته - تعالى - على البعث ، فنراه فى قوله - تعالى - :( وَأَنزَلْنَا مِنَ المعصرات مَآءً ثَجَّاجاً . لِّنُخْرِجَ بِهِ حَبّاً وَنَبَاتاً . وَجَنَّاتٍ أَلْفَافاً ) .والمعصرات - بضم الميم وكسر الصاد - السحب التى تحمل المطر ، جمع معصرة - بكسر الصاد - اسم فاعل ، من أعصرت السحابة إذا أوشكت على إنزال الماء لامتلائها به . .قال ابن كثير : عن ابن عباس : \" المعصرات \" الرياح . لأنها تستدر المطر من السحاب . . وفى رواية عنه أن المراد بها : السحاب ، وكذا قال عكرمة . . واختاره ابن جرير . .وقال الفراء : هى السحاب التى تتحلب بالماء ولم تمطر بعد ، كما يقال : امرأة معصر ، إذا حان حيضها ولم تحض بعد .وعن الحسن وقتادة : المعصرات : يعنى السموات . وهذا قول غريب ، والأظهر أن المراد بها السحاب ، كما قال - تعالى - : ( الله الذي يُرْسِلُ الرياح فَتُثِيرُ سَحَاباً فَيَبْسُطُهُ فِي السمآء كَيْفَ يَشَآءُ وَيَجْعَلُهُ كِسَفاً فَتَرَى الودق يَخْرُجُ مِنْ خِلاَلِهِ . . . ) والثجاج : المندفع بقوة وكثرة ، يقال : ثج الماء - كرد - إذا انصب بقوة وكثرة .ومطر ثجاج ، أى : شديد الانصباب جدا .وقوله : ( أَلْفَافاً ) اسم جمع لا واحد له من لفظه ، كالأوزاع للجماعات المتفرقة . وقيل : جمع لفيف ، كأشراف وشريف . أى : وأنزلنا لكم - يا بنى آدم - بقدرتنا ورحمتنا - من السحائب التى أوشكت على الإِمطار ، ماء كثيرا متدفقا بقوة ، لنخرج بهذا الماء حبا تقتاتون به - كالقمح والشعير .. ونباتا تستعملونه لدوابكم كالتبن والكلأ ، ولنخرج بهذا الماء - أيضا - بساتين قد التفت أغصانها لتقاربها وشدة نمائها .فهذه تسعة أدلة أقامها - سبحانه - على أن البعث حق ، وهى أدلة مشاهدة محسوسة ، لا يستطيع عاقل إنكار واحد منها . . وما دام الأمر كذلك فكيف ينكرون قدرته على البعث ، مع أنه - تعالى - قد أوجد لهم كل هذه النعم التى منها ما يتعلق بخلقهم ، ومنها ما يتعلق بالأرض والسموات ، ومنها ما يتعلق بنومهم ، وبالليل والنهار ، ومنها ما يتعلق بالشمس ، وبالسحب التى تحمل لهم الماء الذى لا يحاة لهم بدونه .وبعد إيراد هذه الأدلة المقنعة لكل عاقل ، أكد - سبحانه - ما اختلفوا فيه ، وما تساءلوا عنه","17":"وبين جانبا من أماراته وعلاماته فقال : ( إِنَّ يَوْمَ الفصل كَانَ مِيقَاتاً . يَوْمَ يُنفَخُ فِي الصور فَتَأْتُونَ أَفْوَاجاً . وَفُتِحَتِ السمآء فَكَانَتْ أَبْوَاباً . وَسُيِّرَتِ الجبال فَكَانَتْ سَرَاباً ) .والمراد بيوم الفصل : يوم القيامة ، لأن فيه يكون الفصل بين المحق والمبطل ، والمحسن والمسئ ، فيجازى كل إنسان على حسب عمله .والميقات - بزنة مفعال - مشتق من الوقت ، وهو الزمان المحدد لفعل ما . والمراد به هنا : قيام الساعة ، وبعث الناس من قبورهم . أى : إن يوم البعث والجزاء ، كان ميعادا ووقتا محددا لبعث الأولين والأخرين ، وما يترتب على ذلك من جزاء وثواب وعقاب .","18":"وقوله : ( يُنفَخُ فِي الصور . . . ) بدل ما قبله ، أى : يوم القيامة آت لا ريب فيه ، يوم نأمر إسرافيل بأن ينفخ فى الصور ، أى : فى القرن الذى أوجدناه لذلك .( فَتَأْتُونَ أَفْوَاجاً ) أى : فتخرجون من قبوركم جماعات جماعات ، وطوائف ، وطوائف دون أن يستطيع أحد منكمك التخلف عن الحضور إلى المكان الذى أعددناه لذلك .","19":"( وَفُتِحَتِ السمآء . . . ) فى هذا اليوم وشقت . . ( فَكَانَتْ أَبْوَاباً ) أى : فصارت شقوقها وفتحاتها كالأبواب فى سعتها وكثرتها .","20":"( وَسُيِّرَتِ الجبال . . . ) أى : وأزيلت الجبال وحركت من أماكنها بعد تفتتها .( فَكَانَتْ سَرَاباً ) أى : فصارت بعد تفتتها واقتلاعها من أماكنها . . كالسراب ، وهو ما يلوح فى الصحارى ، فيظنه الرائى ماء وهو ليس بماء .","21":"وبعد هذا البيان البديع لجانب من مظاهر قدرته - تعالى - على كل شئ ، ومن ألوان نعمه على خلقه ، ومن تقرير أن البعث حق . . بعد كل ذلك ، بين - سبحانه - جزاء الكافرين ، وجزاء المتقين فى هذا اليوم فقال - تعالى - :( إِنَّ جَهَنَّمَ كَانَتْ . . . ) .قوله - سبحانه - : ( إِنَّ جَهَنَّمَ كَانَتْ مِرْصَاداً . . . ) كلام مستأنف لبيان أهوال جهنم وأحوالها ، وجهنم : اسم لدار العذاب فى الآخرة .والمرصاد : مفعال من الرَّصَد . تقول : رصدت فلانا أرصده ، إذا ترقيته وانتظرته ، بحيث لا يهرب منك ، \" فمرصادا \" صيغة مبالغة للراصد الشديد الرصد ، وصفت جهنم بذلك ، لأن الكافرين لا يستطيعون التفلت منها مهما حاولوا ذلك .قال القرطبى : \" مرصادا \" مفعال من الرصد ، والرصد : كل شئ كان أمامك . . وقال مقاتل : \" مرصادا \" أى : محبسا . وقيل : طريقا وممرا . وذكر القشيرى : أن المرصاد : المكان الذى يرصد فيه الواحد العدد . أى : هى معدة لهم ، فالمرصاد بمعنى المحل . . وذكر الماوردى ، أنها بمعنى راصدة . . وفى الصحاح : الراصد الشئ الراقب له . تقول : رصدته أرصده ، إذا ترقبته . .والمعنى : إن جهنم التى هى دار العذاب فى الآخرة ، كانت - بأمر الله - تعالى - ومشيئته - معدة ومهيئة للكافرين ، فهى ترصدهم وترقبهم بحيث لا يستطيعون الهرب منها ، فهى كالحارس اليقظ الذى يقف بالمرصد فلا يستطيع أحد أن يتجاوزه .والمقصود بالآية الكريمة تهديد المشركين ، وبيان أنهم لا مهرب لهم من جهنم ، وأنها فى انتظارهم ، كما ينتظر العدو عدو ليقضى عليه .","22":"وقوله : ( لِّلطَّاغِينَ مَآباً ) بدل من ( مِرْصَاداً ) وقوله ( مَآباً ) من الأوب بمعنى المرجع . يقال : آب فلان يؤوب ، إذا رجع . .أى : إن جهنم كانت للمتجاوزين الحد فى الظلم والطغيان ، هى المكان المهيأ لهم ، والذى لا يستطيعون الهرب منه ، بل هى مرجعهم الوحيد الذى يرجعون إليه .","23":"وقوله : ( لاَّبِثِينَ فِيهَآ أَحْقَاباً ) أى : مقيمين فى جهنم أزمانا طويلا لا يعلم مقدارها إلا الله - تعالى - إذا الأحقاب : جمع حُقُب - بضمتين أو بضم فسكون - ، وهو الزمان الطويل .","24":"( لاَّ يَذُوقُونَ فِيهَا ) أى : فى جهنم ( بَرْداً ) أى : شيئا يخفف عنهم حرها ، من هواء بارد ، أو نسيم عليل ( وَلاَ شَرَاباً ) أى : شيئا من الشراب الذى يطفئ عطشهم ، ويخفف من عذابهم .","25":"( إِلاَّ حَمِيماً وَغَسَّاقاً ) والحميم . هو الماء الذى بلغ الغاية فى الحرارة . والغساق : هو ما يسيل من جلودهم من القيح والدماء والصديد . يقا : غسق الجرح - كضرب وسمع - غسقانا ، إذا سالت منه مياه صفراء . أى : أن هؤلاء الطغاة لا يذوقون فى جهنم شيئا نم الهواء البارد ، ولا من الشراب النافع ، لكنهم يذوقون فيها الماء الذى بلغ النهاية فى الحرارة والصديد الذى يسيل من جروحهم وجلودهم .فالاستثناء فى قوله ( إِلاَّ حَمِيماً وَغَسَّاقاً ) ، استثناء منقطع ، لأن الحميم ليس من جنس البرد فى شئ ، وكذلك الغساق ليس من جنس الشراب فى شئ .","26":"وقوله - سبحانه - ( جَزَآءً وِفَاقاً ) بيان لعدالة الله - تعالى - معهم ، أى : أننا لم نظلمهم بإلقائهم فى جهنم ، وإنما جازيناهم بذلك جزاء موافقا لأعمالهم السيئة فى الدنيا .فقوله ( جزاء ) منصوب على أنه مفعول مطلق لفعل محذوف ، وقوله ( وفاقا ) صفة له والوفاق مصدر وافق ، وهو هنا بمعنى اسم الفاعل . أى : جوزوا جزاء موافقا لأعمالهم القبيحة التى كانوا يعملونها فى الدنيا .","27":"ثم علل - سبحانه - ما أصابهم من عذاب أليم ، فقال : ( إِنَّهُمْ كَانُواْ لاَ يَرْجُونَ حِسَاباً .","28":"وَكَذَّبُواْ بِآيَاتِنَا كِذَّاباً ) أى : إن هؤلاء الطغاة كانوا فى الدنيا لا يخافون حسابنا ، ولا يفكرون فيه ، بل كانوا يكذبون به ، وبكل ما جاءهم به رسولنا تكذيبا عظيما .وقوله : ( كِذَّاباً ) مصدر كذب ، ومجئ فِعَّال بمعنى تفعيل فى مصدر فعَّل فصيح شائع الغاية فى قبحه وإفراطه . وهو منصوب على أنه مفعول مطلق مؤكد لعامله .قال صاحب الكشاف : قوله : ( كِذَّاباً ) أى : تكذيبا . وفِعَّال فى باب فَعَّل ، كله فاش فى كلام فصحاء العرب لا يقولون غيره . وهو مصدر كذَّب . .","29":"ثم بين - سبحانه - شمول علمه لكل شئ فقال : ( وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَاباً ) و \" كل \" منصوب على الاشتغال ، والإِحصاء للشئ : ضبطه ضبطا محكما . وأصله من لفظ الحصا ، واستعمل فيه لأنهم كانوا يعتمدون على الحصا فى العد ، كما يعتمد بعض الناس الآن على الأصابع .قال الجمل : وقوله : ( كِتَاباً ) فيه أوجه : أحدها : أنه مصدر من معنى أحصيناه ، أى : إحصاء فالتجوز فى نفس المصدر . والثانى : أنه مصدر لأحصينا ، لأنه فى معنى كتبنا . فالتجوز فى نفس الفعل . . أى : وكل شئ فى هذا الكو ، قد أحصيناه إحصاء تاما ، بحيث لا يعزب منه شئ عن علمنا ، مهما كان صغيرا .","30":"والفاء فى قوله ( فَذُوقُواْ فَلَن نَّزِيدَكُمْ إِلاَّ عَذَاباً ) للتفريع على ما تقدم من كون جهنم كانت مرصادا ، للطاغين مآبا . .أى : إن جهنم كانت معدة ومهيأة لهؤلاء الطغاة بسبب أعمالهم القبيحة ، وسيقال لهم يوم القيامة على سبيل الإِذلال والإِهانة ، ذوقوا سوء عاقبة كفركم وفسوقكم وعصيانكم ، فلن نزيدكم إلا عذابا فوق العذاب الذى أنتم فيه .قال ابن كثير : قال قتادة ، عن أبى أيوب الأزدى ، عن عبد الله بن عمرو قال : لم ينزل فى شأن أهل النار آية أشد من هذه الآية ( فَذُوقُواْ فَلَن نَّزِيدَكُمْ إِلاَّ عَذَاباً ) قال : فهم فى مزيد من العذاب أبدا . .","31":"وكعادة القرآن الكريم فى الموازنة بين عاقبة الأشرار والأخيار ، جاء الحديث عن حسن عاقبة المتقين ، بعد الحديث عن سوء عاقبة الطاغين فقال - تعالى - : ( إِنَّ لِلْمُتَّقِينَ مَفَازاً ) أى : للمتقين الذين صانوا أنفسهم عن كل ما لا يرضى ربهم . . ( مَفَازاً ) أى : فوزاً برضوانه وجنته فقوله ( مَفَازاً ) مصدر بمعنى الفوز والظفر بالمطلوب ، وتنوينه للتعظيم .","32":"ثم فصل - سبحانه - مظاهر هذا الفوز فقال : ( حَدَآئِقَ وَأَعْنَاباً ) أى : إن لهم فى هذه الجنان التى ظفروا بها حدائق ، أى : بساتين فيها ماء وأشجار مثمرة .. سميت بذلك تشبيها لها بحدقة العين فى الهيئة ، وحصول الماء فيها .وإن لهم - كذلك - فى هذه الجنان ( أعنابا ) جمع عنب ، وهو الكرم ، وخصبت الأعناب بالذكر ، لأنها من أعظم الفواكه وأحبها إلى النفوس .","33":"وإن لهم - أيضا - ( وَكَوَاعِبَ أَتْرَاباً ) أى : فتيات فى ريعان الشباب ، قد تقاربت أعمارهن ، وتساوين فى الجمال والنضارة وحسن الهيئة .فالكواعب ، جمع كاعب ، وهى الفتاة التى وصلت إلى سن البلوغ ، وسميت بذلك لأنها فى تلك السن يتكعب ثدياها ، أى : يستديران مع ارتفاع . .والأتراب ، جمع تِرْبِ - بكسر التاء وسكون الراء - وهو المساوى لغيره فى السن ، وأكثر ما يطلق هذا اللفظ على الإِناث . قيل : سمى من تقاربن فى السن بذلك ، على سبيل التشبيه بالترائب ، أى : بالضلوع التى فى الصدر فى التساوى . .","34":"وإن لهم - أيضا - ( وَكَأْساً دِهَاقاً ) أى : كأسا مليئة بالخمر . يقال دهق الحوض - كجعل - وأدهقه ، إذا ملأه حتى فاض من جوانبه .","35":"( لاَّ يَسْمَعُونَ فِيهَا ) أى : فى الجنة ( لَغْواً ) أى : كلاما ساقطا لا يعتد به . ولا يسمعون - أيضا - ( كِذَّاباً ) أى كلاما كاذبا .","36":"وقوله - سبحانه - : ( جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَاباً ) بيان لمظاهر فضله ومننه على هؤلاء المتقين . . وقوله : ( جَزَآءً ) منصوب بفعل محذوف من لفظه ، و ( من ) ابتدائية .أى : هؤلاء المتقون كوفئوا مكافأة صادرة من ربك على سبيل العطاء أى : الإِحسان والتفضل ، حتى شبعوا واكتفوا .فقوله : ( حسابا ) صفة للعطاء وهو بمعنى كاف . فهو مصدر أقيم مقام الوصف ، من قولهم : أحْسَبَهُ الشئُ ، إذا كفاه حتى قال حسبى ، أى : كافينى .قال صاحب الكشاف : و ( حِسَاباً ) معناه \" محسوبا \" أى : كافأهم الله - تعالى - على أعمالهم الحسنة فى الدنيا مكافأة محسوبة ، على قدر أعمالهم الطيبة .","37":"وقوله : ( رَّبِّ السماوات والأرض وَمَا بَيْنَهُمَا الرحمن . . . ) قرأه بعضهم بجر لفظ \" رب \" على أنه بدل \" من ربك \" وقرأه البعض الآخر بالرفع على أنه خبر لمبتدأ محذوف .أى : هذا الجزاء العظيم للمتقين هو كائن من ربك ، الذى هو رب أهل السموات وأهل الأرض ، ورب ما بينهما من مخلوقات لا يعلمها إلا هو ، وهو - سبحانه - صاحب الرحمة الواسعة العظيمة التى لا تقاربها رحمة . .وقوله : ( لاَ يَمْلِكُونَ مِنْهُ خِطَاباً ) مقرر ومؤكد لما قبله ، من كونه - تعالى - هو رب كل شئ . أى : أهل السموات والأرض وما بينهما ، خاضعون ومربوبون لله - تعالى - الواحد القهار ، الذى لا يقدر أحد منهم - كائنا من كان - أن يخاطبه إلا بإذنه ، ولا يملك أن يفعل ذلك إلا بمشيئته .وشبيه بهذه الآية قوله - تعالى - : ( مَن ذَا الذي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ ) وقوله - سبحانه - : ( يَوْمَ يَأْتِ لاَ تَكَلَّمُ نَفْسٌ إِلاَّ بِإِذْنِهِ فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ )","38":"والظرف فى قوله - تعالى - : ( يَوْمَ يَقُومُ الروح والملائكة صَفّاً . . . ) متعلق بقوله - تعالى - قبل ذلك : ( لاَ يَمْلِكُونَ مِنْهُ خِطَاباً ) . . والمراد بالروح : جبريل - عليه السلام - . أى : لا يملك أحد أن يخاطب الله - تعالى - إلا بإذنه ، يوم القيامة ، ويوم يقوم جبريل - عليه السلام - بين يدى خالقه قيام تذلل وخضوع ، ويقوم الملائكة - أيضا - قياما كله أدب وخشوع ، وهم فى صفوف منتظمة .( لاَّ يَتَكَلَّمُونَ ) أى : لا يستطيع جبريل ولا الملائكة ولا غيرهم الكلام ( إِلاَّ مَنْ أَذِنَ لَهُ الرحمن ) منهم بالكلام أو بالشفاعة .( وَقَالَ صَوَابا ) أى : وقال المأذون له فى الكلام قولا صوابا يرضى الخالق - عز وجل - .وكون المراد بالروح : جبريل - عليه السلام - هو الرأى الراجح ، لأن القرآن الكريم قد وصفه بذلك فى آيات منها قوله - تعالى - : ( نَزَلَ بِهِ الروح الأمين . على قَلْبِكَ لِتَكُونَ مِنَ المنذرين ) وهناك أقوال أخرى فى المراد به ، منها : أنه ملك من الملائكة ، ومنها : أرواح بنى آدم .وجملة \" لا يتكلمون \" مؤكدة لجملة ( لاَ يَمْلِكُونَ مِنْهُ خِطَاباً ) والضمير لجميع الخلائق .وقد أفادت الآية الكريمة أن الذين يتكلمون فى هذا اليوم الهائل الشديد ، هم الذين يأذن الله - تعالى - لهم بالكلام ، وهم الذين يقولون قولا صوابا يرضى الله - تعالى - عنه .وجملة : \" وقال صوابا \" يجوز أن تكون فى موضع الحال من الاسم الموصول \" من \" أى : لا يستطيع أحد منهم الكلام إلا الشخص الذى قد أذن الله - تعالى - له فى الكلام ، والحال أن هذا المأذون له قد قال صوابا .ويصح أن تكون معطوفة على جملة ( أَذِنَ لَهُ الرحمن ) أى : لا يستطيعون الكلام إلا الذين أذن لهم الرحمن فى الكلام ، وإلا الذين قالوا قولا صوابا يرضى الله ، فإنهم يتكلمون .والمقصود من الآية الكريمة ، بيان أن الخلائق جميعا يكونون فى هذا اليوم ، فى قبضة الرحمن وتحت تصرفه ، وأنهم لا يملكون لأنفسهم نفعا ولا ضرا إلا بإذنه - تعالى - .","39":"واسم الإِشارة فى قوله - تعالى - : ( ذَلِكَ اليوم الحق ) يعود إلى يوم البعث الذى يقوم الناس فيه الله رب العالمين . أى : ذلك اليوم الذى يقوم فيه الخلائق للحساب والجزاء ، هو اليوم الحق الذى لا شك فى حدوثه ، ولا ريب فى ثبوته .والفاء فى قوله - تعالى - : ( ذَلِكَ اليوم الحق فَمَن شَآءَ اتخذ إلى رَبِّهِ مَآباً ) هى الفصيحة ، ومفعول المشيئة محذوف . أى : لقد بينا لكم ما يهديكم ، وإذا كان الأمر كذلك ، فمن شاء منكم أن يتخذ إلى ربه مرجعا حسنا وطريقا إلى رضاه ، فليتخذه الآن ، من قبل أن يأتى هذا اليوم الذى لا بيع فيه ولا خلال .","40":"ثم ختم - سبحانه - السورة الكريمة بهذا الإِنذار البليغ فقال : ( إِنَّآ أَنذَرْنَاكُمْ عَذَاباً قَرِيباً يَوْمَ يَنظُرُ المرء مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الكافر ياليتني كُنتُ تُرَاباً ) .والإنذار : الإِخبار بحصول شئ تسوء عاقبته ، فى وقت يستطيع المنذر فيه أن يجنب نفسه الوقوع فى ذلك الشئ . أى : إنا أخبرناكم - أيها الناس - بأن هناك عذابا قريبا ، سيحل بمن يستحقه عما قريب .وذلك العذاب سيكون أشد هولا ، وأبقى أثرا ، يوم القيامة ، ( يَوْمَ يَنظُرُ المرء مَا قَدَّمَتْ يَدَاهُ ) أى : يوم يرى كل إنسان عمله حاضرا أمامه ، ومسجلا عليه . .( وَيَقُولُ الكافر ياليتني كُنتُ تُرَاباً ) أى : ويقول الإِنسان الكافر فى هذا اليوم على سبيل الحسرة والندامة ، يا ليتنى كنت فى الدنيا ترابا ، ولم أخلق بشرا ، ولم أكلف بشئ من التكاليف ، ولم أبعث ولم أحاسب .فالمقصود بالآية قطع أعذار المعتذرين بأبلغ وجه ، من قبل أن يأتى يوم لا ينفع فيه مال ولا بنون إلا من أتى الله بقلب سليم .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"79":{"1":"الواو فى قوله ( والنازعات . . ) وما بعده للقسم ، وجواب القسم محذوف دل عليه ما بعده ، والتقدير : وحق هذه المخلوقات العظيمة . . لتبعثن .وكذلك المقسم به محذوف ، إذ أن هذه الألفاظ وهى : النازعات ، والناشطات والسابحات ، والسابقات ، والمدبرات ، صفات لموصوفات محذوفة ، اختلف المفسرون فى المراد بها على أقوال كثيرة . أشهرها : أن المراد بهذه الموصوفات ، طوائف من الملائكة ، كلفهم الله - تعالى - فى النزع الحسى : ( وَنَزَعَ يَدَهُ فَإِذَا هِيَ بَيْضَآءُ لِلنَّاظِرِينَ ) وقوله - سبحانه - فى النزع المعنوى : ( وَنَزَعْنَا مَا فِي صُدُورِهِم مِّنْ غِلٍّ إِخْوَاناً على سُرُرٍ مُّتَقَابِلِينَ ) وقوله : ( غرقا ) اسم مصدر من أغرق ، وأصله إغراقا . والإِغراق فى الشئ ، المبالغة فيه والوصول به إلى نهايته ، يقال : أغرق فلان فلان هذا الأمر ، إذا أوغل فيه ، ومنه قوله : نزع فلان فى القوس فأغرق ، أى : بلغ غاية المد حتى انتهى إلى النَّصْل .وهو منصوب على المصدرية ، لالتقائه مع اللفظ الذى قبله فى المعنى ، وكذلك الشأن بالنسبة للالفاظ التى بعده ، وهى : \" نشطا ، و \" سبحا \" و \" سبقا \" .والمعنى : وحق الملائكة الذين ينزعون أرواح الكافرين من أجسادهم ، نزعا شديدا ، يبلغ الغاية فى القسوة والغلظة .ويشير إلى هذا المعنى قوله - تعالى - فى آيات متعددة ، منها قوله - سبحانه - : ( وَلَوْ ترى إِذْ يَتَوَفَّى الذين كَفَرُواْ الملائكة يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَارَهُمْ وَذُوقُواْ عَذَابَ الحريق ).","2":"وقوله : ( والناشطات نَشْطاً ) : المقصود به طائفة أخرى من الملائكة . والناشطات من النَّشْط ، وهو السرعة فى العمل ، والخفة فى أخذ الشئ ، ومنه الأنشوطة ، للعقدة التى يسهل حلها ، ويقال : نَشَطتُ الدول من البئر - من باب ضرب - إذا نزعتها بسرعة وخفة .أى : وحق الملائكة الذين ينشطون ويسرعون إسراعا شديدا لقبض أرواح المؤمنين بخفة وسهولة ويقولون لهم - على سبيل البشارة والتكريم - : ( ياأيتها النفس المطمئنة . ارجعي إلى رَبِّكِ رَاضِيَةً مَّرْضِيَّةً ).","3":"وقوله - سبحانه - : ( والسابحات سَبْحاً ) قسم ثالث بطائفة ثالثة من طوائف الملائكة ، التى تَسْبَحُ فى هذا الكون ، أى : تنطلق بسرعة لتنفيذ أمر الله - تعالى - ، ولتسبيحه ، وتحميده ، وتكبيره ، وتقديسه .أى : وحق الملائكة الذين يسرعون التنقل فى هذا الكون إسراعا شديدا ، لتنفيذ ما كلفهم - سبحانه - به ، ولتسبيحه وتنزيهه عن كل نقص . .","4":"وقوله - تعالى - : ( فالسابقات سَبْقاً ) المقصود به طائفة رابعة من الملائكة ، تسبق غيرها فى تنفيذ أمر الله - تعالى - ، إذ السبق معناه : أن يتجاوز السائر من يسير معه ، ويسبقه إلى المكان المقصود الوصول إليه ، كما قال - تعالى - فى صفات المتقين : ( أولئك يُسَارِعُونَ فِي الخيرات وَهُمْ لَهَا سَابِقُونَ ).","5":"وقوله : ( فالمدبرات أَمْراً ) المقصود به طائفة خامسة من الملائكة ، من وظائفهم تدبير شأن الخلائق ، وتنظيم أحوالهم بالطريقة التى يأمرهم - سبحانه - بها ، فنسبة التدبير إليهم ، إنما هى على سبيل المجاز ، لأن كل شئ فى هذا الكون إنما هو بقضاء الله وتقديره وتدبيره .والمراد بالأمر : الشأن والغرض المهم ، وتنوينه للتعظيم ، ونصبه على المفعولية للفظ المدبرات . أى : وحق الملائكة الذين يرتبون شئون الخلائق ، وينظمون أمورهم بالطريقة التى يكلفهم - سبحانه - بها .وجاء العطف فى قوله : ( فالسابقات ) ( فالمدبرات ) بالفاء ، للدلالة على ترتيب ما بعدها على ما قبلها بغير مهلة . وللإِيذان بأن هاتين الصفتين متفرعتين عما قبلهما .وعلى هذا التفسير الذى سرنا فيه على أن هذه الصفات لموصوف واحد ، سار كثير من المفسرين : فصاحب الكشاف صدر تفسيره لهذه الآيات بقوله : أقسم - سبحانه - بطوائف الملائكة ، التى تنزع الأرواح من الأجساد وبالطوائف التى تنشطها ، أى تخرجها . . بالطوائف التى تسبح فى مضيها ، أى : تسرع فتسبق إلى ما أمروا به ، فتدبر أمرا من أمور العباد مما يصلحهم فى دنيهم ودنياهم ، كما رسم الله - تعالى - لهم . . وأسند التدبير إليهم - أى إلى الملائكة - لأنهم من أسبابه .وقال الشوكانى : أقسم - سبحانه - بهذه الأشياء التى ذكرها ، وهى الملائكة التى تنزع أرواح العباد عن أجسادهم ، كما ينزع النازع القوس فيبلغ بها غاية المد ، وكذا المراد بالناشطات ، والسابحات ، والسابقات ، والمدبرات ، يعنى الملائكة ، والعطف مع اتحاد الكل لتنزيل التغاير الوصفى ، منزلة التغاير الذاتى ، كما فى قول الشاعر :إلى الملك القرم ، وابن الهام ... وليث الكتيبة فى المزدحموهذا قول الجمهور من الصحابة ، والتابعين ، ومن بعدهم . .ومنهم من يرى أن المراد بالنازعات : النجوم تنتقل من مكان إلى مكان ، أو الأقواس التى تنزع السهام ، أو الغزاة ينزعون من دار الإِسلام إلى دار الحرب . .ومنهم من يرى أن المراد بالناشطات : الكواكب السيارة ، أو السفن التى تمخر عباب الماء . . وأن المراد بالسابحات والسابقات : النجوم ، أو الشمس والقمر ، والليل والنهار . .أما المدبرات فقد أجمعوا على أن المراد بها الملائكة .قال الجمل : اختلفت عبارات المفسرين فى هذه الكلمات ، هل هى صفات لشئ واحد ، أو لأشياء مختلفة ، على أوجه : واتفقوا على أن المراد بقوله : ( فالمدبرات أَمْراً ) وصف لشئ واحد ، وهم الملائكة .ويبدو لنا أن كون هذه الصفات جميعها لشئ واحد ، هو الملائكة ، أقرب إلى الصواب لأنه المأثور عن كثير من الصحابة والتابعين ومن بعدهم .","6":"ثم شرع - سبحانه - فى بيان علامات القيامة وأهوالها فقال : ( يَوْمَ تَرْجُفُ الراجفة . تَتْبَعُهَا الرادفة . . . ) والراجفة : من الرجف وهو الاضطراب الشديد ، والحركة القوية ، لأن بسببها تضطرب الأمور ، وتختل الشئون . يقال : رجفت الأرض والجبال ، إذا اهتزت اهتزازا شديدا .والمراد بها : ما يحدث فى هذا الكون عند النفخة الأولى التى يموت بعدها جميع الخلائق .","7":"والمراد بالرادفة : النفخة الثانية ، التى تردف الأولى ، أى : تأتى بعدها ، وفيها يبعث الموتى بإذن الله - تعالى - ، يقال : فلان جاء ردف فلان ، إذا جاء فى أعقابه .أى : اذكر - أيها العاقل - لتعتبر وتتعظ ، يوم ينفخ فى الصور فتضطرب الأرض وتهتز ، ويموت جميع الخلق ، ثم يتبع ذلك نفخة أخرى يبعث بعدها الموتى - بإذن الله - تعالى - .وجملة \" تتبعها الرادفة \" فى محل نصب على الحال من الراجفة .وشبيه بهاتين الآيتين قوله - تعالى - : ( وَنُفِخَ فِي الصور فَصَعِقَ مَن فِي السماوات وَمَن فِي الأرض إِلاَّ مَن شَآءَ الله ثُمَّ نُفِخَ فِيهِ أخرى فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ ) .","8":"وقوله - سبحانه - : ( قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ . أَبْصَارُهَا خَاشِعَةٌ ) بيان لما يترتب على قيام الساعة ، وبعث الخلائق ، من خوف ورعب .أى : قلوب كثيرة فى هذا اليوم الهائل الشديد تكون فى نهاية الاضطراب والفزع . يقال : وجف القلبُ يَجِف وَجْفاً ووجيفا ، إذا ارتفعت ضرباته من شدة الخوف . .","9":"وتكون أبصار أصحاب هذه القلوب خاشعة ، أى ذليلة مهينة ، لما يعتريهم من الفزع الشديد ، والرعب الذى لا حدود له . .ولفظ \" قلوب \" مبتدأ ، وتنكيره للتكثير ، وقوله ( وَاجِفَةٌ ) صفة للقلوب ، وجملة ( أَبْصَارُهَا خَاشِعَةٌ ) خبر ثان للقلوب .والمراد بهذه القلوب : قلوب المشركين الذين أنكروا فى الدنيا البعث والجزاء ، فلما بعثوا اعتراهم الرعب الشديد ، والفزع الذى لا يقاربه فزع . .فأما قلوب المؤمنين فهى - بفضل الله ورحمته - تكون فى أمان واطمئنان ، كما قال - تعالى - : ( لاَ يَحْزُنُهُمُ الفزع الأكبر وَتَتَلَقَّاهُمُ الملائكة هذا يَوْمُكُمُ الذي كُنتُمْ تُوعَدُونَ ) وإضافة الأبصار إلى مير القلوب لأدنى ملابسة ، لأن الأبصار لأصحاب هذه القلوب ، وكلاهما من جوارح الأجساد .","10":"وقوله - سبحانه - : ( يَقُولُونَ أَإِنَّا لَمَرْدُودُونَ فِي الحافرة . أَإِذَا كُنَّا عِظَاماً نَّخِرَةً ) حكاية لما كان يقوله هؤلاء الكافرون فى الدنيا ، من إنكار للبعث ، ومن استهزاء لمن كان يذكرهم به ، ومن استبعاد شديد لحصوله . .والمراد بالحافرة : العودة إلى الحياة مرة أخرى بعد موتهم وتحولهم إلى عظام بالية .قال صاحب الكشاف : ( فِي الحافرة ) أى : فى الحالة الأولى يعنون : الحياة بعد الموت .فإن قلت : ما حقيقة هذه الكلمة؟ قلت : يقال : رجع فلان فى حافرته ، أى : فى طريقه التى جاء فيها فحفرها . أى : أثر فيها بمشيه فيها : جعل أثر قدميه حفرا . . ثم قيل لمن كان فى أمر فخرج منه ثم عاد إليه ، رجع إلى حافرته ، أى : طريقته وحالته الأولى .","11":"وقوله : ( نَّخِرَةً ) صفة مشتقة من قولهم : نَخِر العظم - بفتح النون وكسر الخاء - إذا بَلِى وصار سهل التفتيت والكسر . وقرأ حمزة والكسائى \" ناخرة \" بمعنى بالية فارغة جوفاء ، يسمع منها عند هبوب الريح نخير ، أى : صوت .أى : أن هؤلاء المشركين كانوا يقولون فى الدنيا - على سبيل التعجيب والاستهزاء والإِنكار لأمر البعث والحساب : أنرد إلى الحياة مرة أخرى بعد موتنا وبعد أن نصير فى قبورنا عظاما بالية .وعبر - سبحانه - عن قولهم هذا بالمضارع \" يقولون \" لاستحضار حالتهم الغريبة ، حيث أنكروا ما قام الدليل على عدم إنكاره ، وللإِشعار بأن هذا الإِنكار كان متجددا ومستمرا منهم .وقد ساق - سبحانه - أقوالهم هذه بأسلوب الاستفهام ، للإِيذان بأنهم كانوا يقولون ما يقولون فى شأن البعث على سبيل التهكم والتعجب ممن يحدثهم عنه ، كما هو شأن المستفهم عن شئ الذى لا يقصد معرفة الحقيقة ، وإنما يقصد التعجيب والإِنكار .وجملة ( أَإِذَا كُنَّا عِظَاماً نَّخِرَةً ) مؤكدة للجملة السابقة عليها ، التى يستبعدون فيها أمر البعث بأقوى أسلوب .","12":"وقوله - تعالى - : ( قَالُواْ تِلْكَ إِذاً كَرَّةٌ خَاسِرَةٌ ) حكاية لقول آخر من أقوالهم الفاسدة ، وهو بدل اشتمال من قوله - سبحانه - قبل ذلك : ( يَقُولُونَ أَإِنَّا لَمَرْدُودُونَ فِي الحافرة ) .واسم الإِشارة \" تلك \" يعود إلى الردة المستفادة من قولهم ( أَإِنَّا لَمَرْدُودُونَ . . . ) .ولفظ \" إذا \" جواب لكلامهم المتقدم . والكرة : المرة من الكَرّ بمعنى الرجوع ، وجمعها : كرَّات أى : يقول هؤلاء الجاحدون : أنرد إلى الحياة التى كنا فيها بعد أن نموت ونفنى؟ وبعد أن نصير عظاما نخرة؟ لو حدث هذا بأن رددنا إلى الحياة مرة أخرى ، لكانت عودتنا عودة خاسرة غير رابحة ، وهم يقصدون بهذا الكلام الزيادة فى التهكم والاستهزاء بالبعث .والخسران : أصله عدم الربح فى التجارة ، والمراد به هنا : حدوث ما يكرهونه لهم .ونسب الخسران إلى الكرة على سبيل المجاز العقلى ، للمبالغة فى وصفهم الرجعة بالخيبة والفشل ، وإلا فالمراد خيبتهم وفشلهم هم ، لأنهم تبين لهم كذبهم ، وصدق من أخبرهم بأن الساعة حق .","13":"وقد رد - سبحانه - عليهم ردا سريعا حاسما يخرس ألسنتهم فقال : ( فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ . فَإِذَا هُم بالساهرة ) .والزجرة : المرة من الزجر ، وهو الصياح المصحوب بالغضب ، يقال : زجر فلا فلانا ، إذا أمره أو نهاه عن شئ بحدة وغضب .والساهرة : الأرض المستوية الخالية من النبات .والمراد بها هنا : الأرض التى يحشر الله - تعالى - فيها الخلائق .قال القرطبى : قوله : ( فَإِذَا هُم بالساهرة ) أى : على وجه الأرض ، بعد أن كانوا فى بطنها . سميت بهذا الاسم ، لأن فيها نوم الحيوان وسهرهم ، والعرب تسمى الفلاة ووجه الأرض ساهرة ، بمعنى ذات سهر ، لأنه يسهر فيها خوفا منها ، فوصفها بصفة ما فيها . .والفاء فى قوله : ( فَإِنَّمَا هِيَ زَجْرَةٌ . . . ) للتفريع على قولهم السابق ، وضمير \" هى \" يعود إلى الحاة والقصة التى أنكروها ، وهى قيام الساعة .أى : قل لهم - أيها الرسول الكريم - على سبيل التوبيخ والتقريع : ليس الأمر كما زعمتم من أنه لا بثع ولا جزاء . . بل الحق أن ذلك لآت لا ريب فيه ، وأن عودتكم إلى الحياة مرة أخرى لا تقتضى من خالقكم سوى صيحة واحدة يصيحها ملك من ملائكته بكم ، فإذا أنتم قيام من قبوركم ، ومجتمعون فى المكان الذى يحدده الله - تعالى - لاجتماعكم ولحسابكم وجزائكم .","14":"وعبر - سبحانه - عن اجتماعهم بأرض المحشر بإذا الفجائية فقال : ( فَإِذَا هُم بالساهرة ) للإيذان بأن اجتماعهم هذا سيكون فى نهاية السرعة والخفة ، وأنه سيتحقق فى أعقاب الزجرة بدون أقل تأخير .ووصف - سبحانه - الزجرة بأنها واحدة ، لتأكيد ما فى صيغة المرة من معنى الوحدة ، أى : أن الأمر لا يقتضى سوى الإِذن منا بصيحة واحدة لا أكثر ، تنهضون بعدها من قبوركم للحساب والجزاء ، نهوضا لا تملكون معه التأخر أو التردد . . والمراد بها : النفخة الثانية .وقال - سبحانه - ( فَإِذَا هُم ) بضمير الغيبة ، إهمالا لشأنهم ، وتحقيرا لهم عن استحقاق الخطاب .وشبيه بهاتين الآيتين قوله - تعالى - : ( وَنُفِخَ فِي الصور فَصَعِقَ مَن فِي السماوات وَمَن فِي الأرض إِلاَّ مَن شَآءَ الله ثُمَّ نُفِخَ فِيهِ أخرى فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ ) وإلى هنا نجد السورة الكريمة قد حثتنا حديثا بليغا مؤثرا عن أهوال يوم القيامة ، وعن أحوال المجرمين فى هذا اليوم العسير .","15":"ثم ساق - سبحانه - بعد ذلك جانبا من قصة موسى مع فرعون ، لتكون تسلية للنبى صلى الله عليه وسلم عما أصابه من هؤلاء الجاحدين ، وتهديدا لهم حتى يقلعوا عن غيهم . . فقال - تعالى - :( هَلْ أَتَاكَ حَدِيثُ . . . ) .قال الإِمام الرازى : اعلم أن وجه المناسبة بين هذه القصة وبين ما قبلها من وجهين :الأول : أنه - تعالى - حكى عن الكفار إصرارهم على إنكار البعث ، حتى انتهوا فى ذلك الإِنكار إلى حد الاستهزاء فى قولهم : ( تِلْكَ إِذاً كَرَّةٌ خَاسِرَةٌ ) وكان ذلك يشق على الرسول صلى الله عليه وسلم فذكر - سبحانه - قصة موسى - عليه السلام - ، وبين أنه تحمل المشقة فى دعوة فرعون ، ليكون ذلك لتسلية للرسول صلى الله عليه وسلم .الثانى : أن فرعون كان أقوى من كفار قريش . . فلما تمرد على موسى ، أخذه الله - تعالى - نكال الآخرة والأولى ، فكذلك هؤلاء المشركون فى تمردهم عليك ، إن أصروا ، أخذهم الله وجعلهم نكالا . .والمقصود من الاستفهام فى قوله - تعالى - : ( هَلْ أَتَاكَ حَدِيثُ موسى . . . ) التشويق إلى الخبر ، وجعل السامع فى أشد حالات الترقب لما سيلقى إليه ، حتى يكون أكثر وعيا لما سيسمعه .والخطاب للرسول صلى الله عليه وسلم لقصد تسليته ، ويندرج فيه كل من يصلح له .والمعنى : هل وصل إلى علمك - أيها الرسول الكريم - خبر موسى - عليه السلام - مع فرعون؟ إن كان لم يصل إليك فهاك جانبا من خبره نقصه عليك ، فتنبه له ، لتزداد ثباتا على ثباتك ، وثقة فى نصر الله - تعالى - لك على ثقتك .","16":"والظرف \" إذ \" فى قوله - تعالى - : ( إِذْ نَادَاهُ رَبُّهُ بالواد المقدس طُوًى ) متعلق بلفظ \" حديث \" والجملة يدل اشتمال مما قبلها .و \" الواد \" المكان المنخفض بين جبلين ، أو بين مكانين مرتفعين . و \" المقدس \" : بمعنى المطهر . و \" طوى \" اسم للوادى . وقد جاء الحديث عنه فى آيات متعددة ، منها قوله - تعالى - : ( فَلَمَّآ أَتَاهَا نُودِيَ ياموسى . إني أَنَاْ رَبُّكَ فاخلع نَعْلَيْكَ إِنَّكَ بالواد المقدس طُوًى ) والمعنى : هل بلغك - أيها الرسول الكريم - خبر موسى ، وقت أن ناديناه وهو بالواد المقدس طوى ، الذى هو بجانب الطور الأيمن ، بالنسبة للقادم من أرض مدين التى هى فى شمال الحجاز .ويدل على ذلك قوله - تعالى - : ( فَلَمَّا قضى مُوسَى الأجل وَسَارَ بِأَهْلِهِ آنَسَ مِن جَانِبِ الطور نَاراً قَالَ لأَهْلِهِ امكثوا إني آنَسْتُ نَاراً لعلي آتِيكُمْ مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ النار لَعَلَّكُمْ تَصْطَلُونَ . فَلَمَّآ أَتَاهَا نُودِيَ مِن شَاطِىءِ الوادي الأيمن فِي البقعة المباركة مِنَ الشجرة أَن ياموسى إني أَنَا الله رَبُّ العالمين ) .","17":"وقوله - سبحانه - : ( اذهب إلى فِرْعَوْنَ . . . ) مقول لقول محذوف ، أى : ناديناه وقلن له : ( اذهب ) يا موسى إلى فرعون إنه طغى ، أى : إنه تجاوز كل حد فى الكفر والغرور والعصيان .وفرعون : لقب لكل ملك من ملوك مصر فى ذلك الزمان ، وقد قالوا إن فرعون الذى أرسل الله - تعالى - إليه موسى - عليه السلام - هو منفتاح بن رمسيس الثانى .","18":"ثم بين - سبحانه - ما قاله لموسى على سبيل الإِرشاد إلى أحكم وأفضل وسائل الدعوة إلى الحق فقال : ( فَقُلْ هَل لَّكَ إلى أَن تزكى . وَأَهْدِيَكَ إلى رَبِّكَ فتخشى ) .والمقصود بالاستفهام هنا : الحض والترغيب فى الاستجابة للحق ، كما تقول لمن تنصحه : هل كل فى كذا ، والجار والمجرور \" لك \" خب لمبتدأ محذوف ، أى : هل كل رغبة فى التزكية .أى : اذهب يا موسى إلى فرعون ، فقل له على سبيل النصح الحكيم ، والإِرشاد البليغ : هل لك يا فرعون رغبة فى أن أدلك على ما يزكيك ويطهرك من الرجس والفسوق والعصيان .وهل لك رغبة - أيضا - فى أن أرشدك إلى الطريق الذى يوصلك إلى رضى ربك ، فيترتب على وصولك إلى الطريق السوى ، الخشية منه - تعالى - والمعرفة التامة بجلاله وسلطانه .","19":"قال صاحب الكشاف : قوله : ( وَأَهْدِيَكَ إلى رَبِّكَ . . . ) أى : وأرشدك إلى معرفة الله ، أى : أنبهك عليه فتعرفه ( فتخشى ) لأن الخشية لا تكون إلا بالمعرفة . . وذكر الخشية ، لأنها ملاك الأمر ، من خشى الله أتى منه كل خير ، ومن أمن اجترأ على كل شئ . ومنه قوله صلى الله عليه وسلم : \" من خاف أدلج ، - أى : سار فى أول الليل - ومن أدلج بلغ المنزل \" .بدأ مخاطبته بالاستفهام الذى معناه العرض ، كما يقول الرجل لضيفه : هل لك أن تنزل بنا؟ وأردفه الكلام الرقيق ليستدعيه بالتلطف فى القول ، ويستنزله بالمداراة من عتوه ، كما أمر بذلك فى قوله - تعالى - ( فَقُولاَ لَهُ قَوْلاً لَّيِّناً لَّعَلَّهُ يَتَذَكَّرُ أَوْ يخشى . . . ) والحق أن هاتين الآيتين فيهما أسمى ألوان الإِرشاد إلى الدعوة إلى الحق بالحكمة والموعظة الحسنة .","20":"والفاء فى قوله - تعالى - : ( فَأَرَاهُ الآية الكبرى . فَكَذَّبَ وعصى ) للإفصاح والتفريع على كلام محذوف يفهم من المقام . والتقدير : فامتثل موسى - عليه السلام - أمر ربه ، فذهب إلى فرعون ، فدعاه إلى الحق ، فكذبه فرعون ، فما كان من موسى إلا أن أراه الآية الكبرى التى تدل على صدقه ، وهى أن ألقى أمامه عصاه فإذا هى حية تسعى ، وأن نزع يده من جيبه فإذا هى بيضاء من غير سوء .","21":"ولكن فرعون لم يستجب لدعوة موسى ، بعد أن أراه الآية الكبرى الدالة على صدقه ، بل كذب ما رآه تكذيبا شديدا ، وعصى أمر ربه عصيانا كبيرا .","22":"( ثُمَّ أَدْبَرَ يسعى ) أى : ثم أضاف إلى تكذيبه وعصيانه . إعراضه وتوليه عن الإِيمان والطاعة . وسعيه سعيا حثيثا فى إبطال أمر موسى ، وإصراره ، على تكذيب معجزته .وجاء العطف هنا بثم ، للدلالة على أنه قد تجاوز التكذيب والعصيان ، إلى ما هو أشد منهما فى الجحود والعناد ، وهو الإِعراض عن الحق والسعى الشديد فى إبطاله .","23":"ثم بين - سبحانه - ما فعله بعد ذلك فقال : ( فَحَشَرَ فنادى . فَقَالَ أَنَاْ رَبُّكُمُ الأعلى ) .والحشر : جمع الناس ، والنداء : الجهر بالصوت لإِسماع الغير ، ومفعولاهما محذوفان .أى : فجمع فرعون الناس عن طريق جنده ، وناداهم بأعلى صوته ، قائلا لهم : أنا ربكم الأعلى الذى لا رب أعلى منه ، وليس الأمر كما يقول موسى من أن لكم إلها سواى .والتعبير بالفاء فى قوله : ( فنادى ) للإِشعار بأنه بمجرد أن جمعهم دعاهم إلى الاعتراف بأنه هو رب الأرباب .","24":"وجاء نداؤه بالصيغة الدالة على الحصر ( أَنَاْ رَبُّكُمُ الأعلى ) للرد على ما قاله موسى له . من وجوب إخلاص العبادة لله - تعالى - وحده .","25":"ثم بين - سبحانه - ما ترتب على هذا الفجور الذى تلبس به فرعون ، وعلى هذا الطغيان الذى تجاوز مه كل حد ، فقال : ( فَأَخَذَهُ الله نَكَالَ الآخرة والأولى ) .والنكال : مصدر بمعنى التنكيل ، وهو العقاب الذى يجعل من رآه فى حالة تمتعه وتصرفه عما يؤدى إليه ، يقال : نَكَّلَ فلان بفلان ، إذا أوقع به عقوبة شديدة تجعله نكالا وعبرة لغيره وهو منصوب على أنه مصدر مؤكد لقوله ( فَأَخَذَهُ ) ، لأن معناه نكل به ، والتعبير بالأخذ اللإشعار بأن هذه العقوبة كانت محيطة بالمأخوذ بحيث لا يستطيع التفلت منها .والمراد بالآخرة : الدار الآخرة ، والمراد بالأولى : الحياة الدنيا .أى : أن فرعون عندما تمادى فى تكذيبه وعصيانه وطغيانه . . كانت نتيجة ذلك أن أخذه الله - تعالى - أخذ عزيز مقتدر ، بأن أنزل به فى الآخرة أشد أنواع الإِحراق ، وأنزل به فى الدنيا أفظع ألوان الإِغراق .وقدم - سبحانه - عذاب الآخرة على الأولى ، لأنه أشد وأبقى .ومنهم من يرى أن المراد بالآخرة قوله لقومه : ( أَنَاْ رَبُّكُمُ الأعلى ) ، وأن المراد بالأولى تكذيبه لموسى - عليه السلام - أى ، فعاقبه الله - تعالى - على هاتين المعصيتين وهذا العقاب الأليم ، بأن أغرقه ومن معه جميعا . .ويبدو لنا أن التفسير الأول هو الأقرب إلى ما تفيده الآية الكريمة ، إذ من المعروف أن الآخرة ، هى ما تقابل الأولى وهى دار الدنيا ، ولذا قال الإِمام ابن كثير : قوله - تعالى - : ( فَأَخَذَهُ الله نَكَالَ الآخرة والأولى ) أى : انتقم الله منه انتقاما جعله به عبرة ونكالا لأمثاله من المتمردين فى الدنيا . ويوم القيامة بئس الرفد المرفود ، كما قال - تعالى - : ( وَجَعَلْنَاهُمْ أَئِمَّةً يَدْعُونَ إِلَى النار وَيَوْمَ القيامة لاَ يُنصَرُونَ ) هذا هو الصحيح فى معنى الآية ، أن المراد بقوله : ( نَكَالَ الآخرة والأولى ) أى : الدنيا والآخرة . وقيل المراد بذلك كلمتاه الأولى والثانية . وقيل : كفره وعصيانه ، والصحيح الذى لا شك فيه الأول . .","26":"والإِشارة فى قوله - تعالى - : ( إِنَّ فِي ذَلِكَ لَعِبْرَةً لِّمَن يخشى ) ، تعود إلى حديث موسى الذى دار بينه وبين فرعون ، وما ترتب عليه من نجاة لموسى ومن إهلاك لفرعون .أى : إن فى ذلك الذى ذكرناه عما دار بين موسى وفرعون ، لعبرة وعظة ، لمن يخشى الله - تعالى - ، ويقف عند حدوده ، لا لغيره ممن لا يتوبون ولا يتذكرون ولا تخالط أنفسهم خشية الله - تعالى - .والمقصود من هذه القصة كلها ، تسلية الرسول صلى الله عليه وسلم ، وتهديد المشركين بأنهم إذا ما استمروا فى طغيانهم ، كانت عاقبتهم كعاقبة فرعون .","27":"وبعد هذا الاستطراد عن طريق ذكر جانب مما دار بين موسى وفرعون . . عادت السورة الكريمة ، كما بدأت إلى الحديث عن أهوال يوم القيامة ، وعن إمكانية وقوعه ، وعن أحوال الناس فيه . وعن أن موعد قيامه مرد علمه إلى الله - تعالى - وحده ، فقال - سبحانه - :( أَأَنتُمْ أَشَدُّ خَلْقاً أَمِ السمآء . . . ) .الخطاب فى قوله - تعالى - : ( أَأَنتُمْ أَشَدُّ خَلْقاً . . . ) لأولئك الجاحدين الجاهلين الذين استنكروا إعادتهم إلى الحياة بعد موتهم ، وقالوا : ( أَإِنَّا لَمَرْدُودُونَ فِي الحافرة ) وجاء هذا الخطاب على سبيل التقريع والتوبيخ لهم ، حيث بين لهم - سبحانه - أن إعادتهم إلى الحياة ، ليست بأصعب من خلق السموات والأرض .و ( أَشَدُّ ) أفعل تفضيل ، والمفضل عليه محذوف ، لدلالة قوله - تعالى - : ( أَمِ السمآء ) عليه .والمراد بالأشد هنا : الأصعب بالنسبة لاعتقاد المخاطبين ، إذ كل شئ فى هذا الكون خاضع لإرادة الله - تعالى - ومشيئته ( إِنَّمَآ أَمْرُهُ إِذَآ أَرَادَ شَيْئاً أَن يَقُولَ لَهُ كُن فَيَكُونُ ) والمعنى : أخلقكم - أيها الجاهلون - بعد موتكم ، وإعادتكم إلى الحياة بعد هلاككم ، أشد وأصعب فى تقديركم ، أم خلق السماء التى ترون بأعينكم عظمتها وضخامتها ، والتى أوجدها - سبحانه وبناها بقدرته .فالمقصود من الآية الكريمة لفت أنظارهم إلى أمر معلوم عندهم بالمشاهدة ، وهو أن خلق السماء أعظم وأبلغ من خلقهم ، ومن كان قادرا على الأبلغ والأعظم كان على ما هو أقل منه - وهو خلقهم وإعادتهم بعد موتهم - أقدر .وشبيه بهذه الآية قوله - تعالى - : ( لَخَلْقُ السماوات والأرض أَكْبَرُ مِنْ خَلْقِ الناس . . . ).","28":"ثم بين - سبحانه - جانبا من بديع قدرته فى خلق السماء فقال : ( رَفَعَ سَمْكَهَا فَسَوَّاهَا ) .والسَّمْك - بفتح السين - المشددة وسكون الميم - : الرفع فى الفضاء ، وجعل الشئ عاليا عن غيره .تقول : سمكت الشئ ، إذا رفعته فى الهواء ، وبناء مسموك ، أى : مرتفع ، ومنه قول الشاعر :إن الذى سمك السماء بنى لنا ... بيتا دعائمه أعز وأطولأى : أن الله - تعالى - بقدرته ، جعل مقدار ارتفاع السماء عن الأرض عظيما ، وبجانب ذلك سوى بحكمته هذه السماء ، بأن جعلها خالية من الشقوق والثقوب . . كما قال - سبحانه - : ( مَّا ترى فِي خَلْقِ الرحمن مِن تَفَاوُتٍ . . . ).","29":"وجملة ( وَأَغْطَشَ لَيْلَهَا . . . ) معطوفة على \" بناها \" والإِغطاش : الإِظلام الشديد .يقال \" غطش الليل - من باب ضرب - إذا اشتد ظلامه .أى : وجعل - بقدرته - ليل هذه السماء مظلما غاية الإِظلام : بسبب مغيب شمسها .( وَأَخْرَجَ ضُحَاهَا ) أى : وأبرز وأضاء نهارها ، إذ الضحكى فى الأصل : انتشار الشمس ، وامتداد النهار . ثم سمى به هذا الوقت ، لبروز ضوء الشمس فيه أكثر من غيره ، فهو من باب تسمية الشئ باسم أشرف أجزائه وأطيبها .وأضاف - سبحانه - الليل والضحى إلى السماء لأنهما يحدثان بسبب غروب شمسها وطلوعها .","30":"ثم انتقلت الآيات الكريمة من الاستدلال على قدرته - تعالى - عن طريق خلق السماء ، إلى الاستدلال على قدرته عن طريق خلق الأرض فقال : ( والأرض بَعْدَ ذَلِكَ دَحَاهَا ) .ولفظ \" الأرض \" منصوب على الاشتغال . واسم الإِشارة \" ذلك \" يعود إلى خلق السماء وتسويتها ورفعها وإغطاش ليلها . وقوله ( دَحَاهَا ) من الدحو بمعنى البسط ، تقول : دحوت الشئ أدحوه ، إذا بسطته . .أى : خلق - سبحانه - السماء وسواها ، وأغطش ليلها وأخرج ضحاها ، والأرض بعد كل ذلك الخلق البديع للسماء ، بسطها وأوسعها لتكون مستقرا لكم وموضعا لتقبلكم عليها . .وقد أخذ بعض العلماء من هذه الآية ، تأخر خلق الأرض عن خلق السماء . .وجمهور العلماء على أن خلق الأرض متقدم على خلق السماء ، بدليل قوله - تعالى - : ( هُوَ الذي خَلَقَ لَكُمْ مَّا فِي الأرض جَمِيعاً ثُمَّ استوى إِلَى السمآء فَسَوَّاهُنَّ سَبْعَ سَمَاوَاتٍ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ ) قالوا فى الجمع بين هذه الآية التى معنا ، وبين آية سورة البقرة ، بما روى عن ابن عباس من أنه سئل عن الجمع بين هاتين الآيتين فقال : خلق الله - تعالى - الأرض أولا غير مدحوة ، ثم خلق السماء ، ثم دحا الأرض بعد ذلك ، وجعل فيها الرواسى والأنهار وغيرهما . أى : أن أصل خلق الأرض كان قبل خلق السماء ، ودحوها بجبالها وأشجارها ، كان بعد خلق السماء .وقالوا - أيضا - فى وجه الجمع ، إن لفظ بعد فى قوله - تعالى - ( بَعْدَ ذَلِكَ ) بمعنى مع . أى : والأرض مع ذلك بسطها ومهدها لسكنى أهلها فيها . .وقدم - سبحانه - هنا خلق السماء على الأرض ، لأنه أدل على القدرة الباهرة ، لعظم السماء وانطوائها على الأعاجيب .","31":"وقوله - سبحانه - ( أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَاهَا . والجبال أَرْسَاهَا ) بدل اشتمال من قوله ( دحاها ) ، أو بيان وتفسير لدحوها ، والمرعى : مصدر ميمى أطلق على المفعول ، كالخلق بمعنى المخلوق ، أى أخرج منها ما يُرْعَى .أى : والأرض جعلها مستقرا لكم ، ومكانا لانتفاعكم ، بأن أخرج منها ماءها ، عن طريق تفجير العيون والآبار والبحار ، وأخرج منها ( مرعاها ) أى : جميع ما يقتات به الناس والدواب ، بدليل قوله - تعالى - بعد ذلك : ( مَتَاعاً لَّكُمْ وَلأَنْعَامِكُمْ ) .","32":"وكذلك من مظاهر قدرته - تعالى- ورحمته بكم ، أنه أثبت الجبال فى الأرض حتى لا تميد أو تضطرب ، فالمقصود بإرسال الجبال : تثبيتها فى الأرض .","33":"وقوله - تعالى - : ( مَتَاعاً لَّكُمْ وَلأَنْعَامِكُمْ ) بيان لوجه المنة فى خلق الأرض على هذه الطريقة البديعة .والمتاع : اسم لما يتمتع به الإِنسان من منافع الحياة الدنيا لمدة محدودة من الزمان ، وانتصب لفظ \" متاعا \" هنا بفعل مقدر من لفظه ، أى : متعناكم متاعا .والمعنى : دحونا الأرض ، وأخرجنا منها ماءها ومرعاها . . لتكون موضع منفعة لكم ، تتمتعون بخيراتها أنتم وأنعامكم ، إلى وقت معين من الزمان ، تتركونها النتهاء أعماركم .","34":"ثم بين - سبحانه - حال الأشقياء والسعداء يوم القيامة ، فقال : ( فَإِذَا جَآءَتِ الطآمة الكبرى ) . والطامة : اسم للمصيبة العظمى ، التى تَطُمُّ وتغلب وتعلو ما سواها من مصائب ، من قولهم : طمَّ الشئ يطُمُّه طَمّاً ، إذا غمره .وكل شئ كثر وعلا على غيره ، فقد طم عليه . ويقال : طم الماء الأرض إذا غمرها .وهذا الوصف ليوم القيامة ، من أوصاف التهويل والشدة ، لأن أحوالها تغمر الناس وتجعلهم لا يفكرون فى شئ سواها .وجواب الشرط محذوف ، والمجئ هنا : بمعنى الحدوث والوقوع ، أى : فإذا وقعت القيامة ، وقامت الساعة . . حدث ما لم يكن فى الحسبان من شدائد وأهوال .","35":"وقوله : ( يَوْمَ يَتَذَكَّرُ الإنسان مَا سعى ) بدل اشتمال من الجملة التى قبلها وهى قوله : ( فَإِذَا جَآءَتِ الطآمة ) لأن ما أضيف إليه لفظ \" يوم \" من الأحوال التى يشملها يوم القيامة ، وتذكر الإِنسان لسعيه فى الدنيا ، يكون بإطلاعه على أعماله التى نسيها ، ورؤيته إياها فى كتاب لا يغادر صغيرة ولا كبيرة إلا أحصاها .ى : فإذا قامت القيامة ، وتذكر الإِنسان فى هذا الوقت ما كان قد نسيه من أعمال فى دنياه ، وقع له من الخوف والفزع مالا يدخل تحت وصف . .","36":"وقوله : ( وَبُرِّزَتِ الجحيم لِمَن يرى ) معطوف على قوله ( جاءت ) أى : فإذا جاءت الطامة الكبرى ، وتذكر الإِنسان فيها ما كان قد نسيه من أعمال دنيوية ( وَبُرِّزَتِ الجحيم ) أى : وأظهرت إظهاراً واضحا لا خفاء فيه ولا لبس ( لِمَن يرى ) أى : لكل راء . كان الهول الأعظم","37":"وقوله - سبحانه - : ( فَأَمَّا مَن طغى . . . ) تفصيل لأحوال الناس فى هذا اليوم .أى : ( فَأَمَّا مَن طغى ) بأن تجاوز الحدود فى الكفر والفسوق والعصيان.","38":"( وَآثَرَ الحياة الدنيا ) بأن قدم متاعها الفانى ، على نعيم الآخرة الخالد . .","39":"( فَإِنَّ الجحيم هِيَ المأوى ) أى : فإن مصير هذا الإِنسان الشقى سيكون إلى النار الملتهبة ، لا منزل له سواها فى هذا اليوم .","40":"( وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ ) أى : خاف عظمته وجلاله ، وسلح نفسه بالإِيمان والعمل الصالح استعدادا لهذا اليوم الذى يجازى فيه كل إنسان بما يستحقه .( وَنَهَى النفس عَنِ الهوى ) أى : وزجر نفسه وكفها عن السيئات والمعاصى والميول نحو الأهوال الضالة المضلة .","41":"( فَإِنَّ الجنة هِيَ المأوى ) أى : فإن الجنة فى هذا اليوم ، ستكون هى مأواه ومنزله ومستقره . .","42":"ثم لقن الله - تعالى - نبيه صلى الله عليه وسلم الجواب الذى يرد به على المشركين ، الذين كانوا يكثرون من سؤاله عن يوم القيامة ، على سبيل الإِنكار والاستهزاء ، فقال - تعالى - : ( يَسْأَلُونَكَ عَنِ الساعة أَيَّانَ مُرْسَاهَا ) .وإيان : اسم يستفهم به عن تعيين الوقت وتحديده ، فهو ظرف زمان متضمن معنى \" متى \" ومرساها : مصدر ميمى من أرسى الشئ إذا ثبته وأقره ، ولا يكاد يستعمل هذا اللفظ إلا فى الشئ الثقيل ، كما فى قوله - تعالى - : ( والجبال أَرْسَاهَا . . . ) .ونسبة الإِرساء إلى الساعة ، باعتبار تشبيه المعانى بالأجسام و \" أيان \" خبر مقدم ، و \" مرساها \" وإرساؤها ووقوعها؟وأطلق على يوم القيامة ساعة لوقوع بغتة ، أو لسرعة ما فيه من الحساب ، أو لأنه على طوله ، زمان يسير عند الله - تعالى - .","43":"وقوله - سبحانه - : ( فِيمَ أَنتَ مِن ذِكْرَاهَا . إلى رَبِّكَ مُنتَهَاهَآ ) واقع موقع الجواب عن سؤالهم عن الساعة ، وعن وقت وقوعها .والمقصود بهذا الجواب توبيخهم على إلحاحهم فى السؤال عنها ، مع أن الأولى بهم كان الاستعداد لها بالإِيمان والعمل الصالح .و \" ما \" فى قوله ( فيم ) اسم استفهام بمعنى : أى شئ ، وهى هنا مستعملة فى التعجيب من كثرة أسئلتهم عن شئ لا يهمهم حدوثه ، وإنما الذى يهمهم - لو كانوا يعقلون - هو حسن الاستعداد له .قال الآلوسى : قوله : ( فِيمَ أَنتَ مِن ذِكْرَاهَا ) إنكار ورد لسؤال المشركين عنها . أى : فى أى شئ أنت من أن تذكر لهم وقتها ، وتعلمهم به حتى يسألونك بيانها ، كقوله - تعالى - ( يَسْأَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْهَا ) فالاستفهام للإِنكار . وفيم خبر مقدم ، وأنت مبتدأ مؤخر . وقوله ( مِن ذِكْرَاهَا ) على تقدير مضاف ، أى : ذكرى وقتها ، وهو متعلق بما تعلق به الخبر .وقيل : ( فيم ) إنكار لسؤالهم ، وما بعده استئناف تعليل للإِنكار ، وبيان لبطلان السؤال . أى فيم هذا السؤال ، ثم ابتدئ فقيل : أنت خاتم النبيين . . علامة من علاماتها .","44":"وقوله - تعالى - ( إلى رَبِّكَ مُنتَهَاهَآ ) أى : إلى ربك وحده منتهى علم قيامها ، لأنه - سبحانه - هو وحده - من دون غيره - العليم علما تاما بالوقت الذى ستقوم فيه الساعة .ومن الآيات التى وردت فى هذا المعنى قوله : ( إِنَّ الله عِندَهُ عِلْمُ الساعة . . . ) وقوله - سبحانه - ( يَسْأَلُونَكَ عَنِ الساعة أَيَّانَ مُرْسَاهَا قُلْ إِنَّمَا عِلْمُهَا عِنْدَ رَبِّي لاَ يُجَلِّيهَا لِوَقْتِهَآ إِلاَّ هُوَ . . . )","45":"وقوله - تعالى - : ( إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَاهَا ) تحديد لوظيفته صلى الله عليه وسلم أى : ليست وظيفتك - أيها الرسول الكريم - معرفة الوقت الذى تقوم فيه الساعة ، فهذا أمر مرد معرفته إلى الله وحده . . وإنما وظيفتك امتثال ما أمرت به ، من بيان اقترابها ، وتفصيل أهوالها ، ودعوة الناس إلى حسن الاستعداد لها بالإيمان والعمل الصالح . .وإذا كان الأمر كذلك فلماذا ترك هؤلاء الجاهلون ما يجب عليهم من الإِيمان والعمل الصالح ، وأخذوا يسألونك عن أشياء خارجة عن وظيفتك؟وخص - سبحانه - الإِنذار بمن يخشى قيام الساعة ، مع أن رسالته صلى الله عليه وسلم إلى الناس كافة . وإنذاره إنما هو لهم جميعا ، لأن هؤلاء الذين يخشون وقوعها ، ويعملون العمل الصالح الذى ينجيهم من أهوالها ، هم الذين ينتفعون بهذا الإِنذار .","46":"ثم ختم - سبحانه - السورة الكريمة ، ببيان حالهم عند قيام الساعة ، قيام ، فقال - تعالى - : ( كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يلبثوا إِلاَّ عَشِيَّةً أَوْ ضُحَاهَا ) .والعشية : هى الوقت الكائن من الزوال إلى الغروب .والضحى : الوقت الكائن من أوائل النهار إلى الزوال .أى : كأن هؤلاء المشركين حين يرون الساعة وقد فاجأتهم بأهوالها ، لم يلبثوا فى دنياهم أو فى قبورهم إلا وقتا يسيرا ، يشبه العشية أو الضحى بالنسبة للزمان الطويل .فالمقصود من الآية الكريمة : بيان أن الساعة آتية لا ريب فيها ، وأن المشركين عند إتيانها كأنهم ما لبثوا فى انتظارها إلا يوما أو بعض يوم . .قال صاحب الكشاف : فإن قلت : كيف صحت إضافة الضحى إلى العشية؟ قلت : لما بينهما من الملابسة لاجتماعهما فى نهار واحد .فإن قلت : فهلا قيل : إلا عشية أو ضحى وما فائدة الإِضافة؟ قلت : للدلالة على أن مدة لبثهم ، كأنها لم تبلغ يوما كاملا ، ولكن ساعة منه عشيته أو ضحاه ، فلما ترك اليوم أضافه إلى عشيته . فهو كقوله : ( لَمْ يلبثوا إِلاَّ سَاعَةً مِّن نَّهَارٍ ) ."},"80":{"1":"قد ذكر المفسرون فى سبب نزول هذه الآيات روايات ملخصها : \" أن النبى صلى الله عليه وسلم كان جالسا فى أحد الأيام ، مع جماعة من زعماء قريش يدعوهم إلى الإِسلام ، ويشرح لهم تعاليمه ، فأقبل عبد الله بن أم مكتوم - وكان كفيف البصر - فقال : أقرئنى وعلمن مما علمك الله ، يا رسول الله ، وكرر ذلك ، وهو لا يعلم أن الرسول صلى الله عليه وسلم مشغول بدعوة هؤلاء الزعماء إلى الإِسلام ، رجاء أن يسلم بسبب إسلامهم خلق كثير . .فلما أكثر عبد الله من طلبه ، أعرض عنه الرسول صلى الله عليه وسلم فنزلت هذه الآيات التى عاتب الله - تعالى - فيها نبيه صلى الله عليه وسلم على هذا الإِعراض . . فكان رسول الله صلى الله عليه وسلم بعد ذلك يكرمه ، إذا رآه ، ويقول له : \" مرحبا بمن عاتبنى فيه ربى \" ويبسط له رداءه . . \"قال الآلوسى : وعبد الله بن أم مكتوم ، هو ابن خال السيدة خديجة ، واسمه عمرو بن قيس . وأم مكتوم كنية أمه ، واسها عاتكة بنت عبد الله المخزومية ، واستخلفه صلى الله عليه وسلم على المدينة أكثر من مرة . . وهو من المهاجرين الأولين . قيل : مات بالقادسية شهيدا نوح فتح المدائن أيام عمر بن الخطاب - رضى الله عنه . .ولفظ \" عبس \" - من باب ضرب - مأخوذ من العبوس ، وهو تقطيب الوجه ، وتغير هيئته مما يدل على الغضب .وقوله ( وتولى ) مأخوذ من التولى وأصله تحول الإِنسان عن مكانه الذى هو فيه إلى مكان آخر ، والمراد به هنا الإِعراض عن السائل وعدم الإِقبال عليه .وحذف متعلق التولى ، لمعرفة ذلك من سياق الآيات ، إذ من المعروف أن إعراضه صلى الله عليه وسلم كان عن عبد الله ابن أم مكتوم الذى قاطعه خلال حديثه مع بعض زعماء قريش .","2":"وأل فى قوله - تعالى - : ( الأعمى ) للعهد . والمقصود بهذا الوصف : التعريف وليس التنقيص من قدر عبد الله بن أم مكتوم - رضى الله عنه - وكذلك فى هذا الوصف إيماء إلى أن له عذرا فى مقاطعة الرسول صلى الله عليه وسلم عند حديثه مع زعماء قريش ، فهو لم يكن يراه وهو يحادثهم ويدعوهم إلى الإِسلام .وجاء الحديث عن هذه القصة بصيغة الحكاية ، وبضمير الغيبة ، للإِشعار بأن هذه القصة ، من الأمور التى لا يحب الله - تعالى - أن يواجه بها نبيه صلى الله عليه وسلم على سبيل التكريم له ، والعطف عليه ، والرحمة به .","3":"وجملة ( وَمَا يُدْرِيكَ لَعَلَّهُ يزكى ) فى موضع الحال ، وفيها التفات من الغيبة إلى الخطاب ، و \" ما \" استفهامية مبتدأ ، وجملة \" يدريك \" خبره .والكاف مفعول أول ، وجملة الترجى سادة مسد المفعول الثانى . والضمير فى ( لعله ) يعود إلى عبد الله ابن أم مكتوم المعبر عنه بالأعمى .والمعنى : عبس صلى الله عليه وسلم وضاق صدره ، وأعرض بوجهه ، لأن جاءه الرجل الأعمى ، وجعل يخاطبه وهو مشغول بالحديث مع غيره .( وَمَا يُدْرِيكَ ) أى : وأى شئ يجعلك - أيها الرسول الكريم - داريا بحال هذا الأعمى الذى عبست فى وجهه ( لَعَلَّهُ يزكى ) أى : لعله بسبب ما يتعلمه منك يتطهر ويتزكى ، ويزداد نقاء وخشوعا لله رب العالمين .","4":"( أو ) لعله ( يذكر ) أى : يتذكر ما كان فى غفلة عنه ( فَتَنفَعَهُ الذكرى ) أى : فتنفعه الموعظة التى سمعها منك .قال الآلوسى ما ملخصه : وفى التعبير عنه صلى الله عليه وسلم بضمير الغيبة إجلال له . . كما أن فى التعبير عنه صلى الله عليه وسلم بضمير الخطاب فى قوله - تعالى - : ( وَمَا يُدْرِيكَ . . . ) إكرام له - أيضا - لما فيه من الإِيناس بعد الإِيحاش والإِقبال بعد الإِعراض . .","5":"ثم فصل - سبحانه - ما كان منه صلى الله عليه وسلم بالنسبة لهذه القصة فقال : ( أَمَّا مَنِ استغنى فَأَنتَ لَهُ تصدى وَمَا عَلَيْكَ أَلاَّ يزكى . وَأَمَّا مَن جَآءَكَ يسعى . وَهُوَ يخشى . فَأَنتَ عَنْهُ تلهى ) أى : أما من استغنى عن الإِيمان ، وعن إرشادك - أيها الرسول الكريم - واعتبر نفسه فى غنى عن هديك . .","6":"( فَأَنتَ لَهُ تصدى ) أى : فأنت تتعرض له بالقبول ، وبالإِصغاء لكلامه ، رجاء أن يسلم ، فيسلم بعده غيره .يقال : تصدَّى فلان لكذا ، إذا تعرَّض له ، وأصله تصدَّدَ من الصَّدَد ، وهو ما استقبلك وصار قبالتك . .","7":"( وَمَا عَلَيْكَ أَلاَّ يزكى ) أى : وأى شئ عليك فى أن يبقى على كفره ، بدون تطهر؟ إنه لا حرج عليك فى ذلك ، فأنت عليك البلاغ ونحن علينا الحساب و ( إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ ولكن الله يَهْدِي مَن يَشَآءُ . . . ) و \" ما \" نافية \" وعليك \" خبر مقدم ، وقوله ( أَلاَّ يزكى ) مبتدأ مؤخر .","8":"( وَأَمَّا مَن جَآءَكَ يسعى ) أى : من جاءك مسرعا فى طلب الخير والهداية والعلم ، وهو هذا الأعمى ، الذى لم يمنعه فقدانه لبصره من الحرص على التفقه فى الدين .","9":"( وَهُوَ يخشى ) أى : وهو يخشى الله ، ويخاف عقابه ، ويرجو ثوابه .","10":"( فَأَنتَ عَنْهُ تلهى ) أى : فأنت عنه تتشاغل ، وتفرغ جهدك مع هؤلاء الزعماء ، طمعا فى إيمانهم .ويلاحظ أن هذه الآيات الكريمة ، أكثر حدة فى العتاب من سابقتها ، حيث ساق - سبحانه - هذه الآيات فى صورة أشبه ما تكون بالتعجيب ممن يفعل ذلك . .","11":"ثم ساق - سبحانه - ما هو أشد فى العتاب وفى التحذير فقال : ( كَلاَّ إِنَّهَا تَذْكِرَةٌ ) .أى : كلا - أيها الرسول الكريم - ليس الأمر كما فعلت ، من إقبالك على زعماء قريش طمعا فى إسلامهم ، ومن تشاغلك وإعراضك عمن جاء يسعى وهو يخشى ..الضمير فى قوله ( إنها ) يعود إلى آيات القرآن الكريم ، أى : إن آيات القرآن الكريم لمشتملة على التذكير بالحق ، وعلى الموعظة الحكيمة التى ينبغى على كل عاقل أن يعمل بموجبها ، وأن يسير بمقتضاها .","12":"( فَمَن شَآءَ ذَكَرَهُ ) أى : فمن شاء أن يتعظ ويعتبر وينتفع بهذا التذكير فاز وربح ، ومن شاء غير ذلك خسر وضاع ، فالجملة الكريمة لتهديد الذين يعرضون عن الموعظة ، وليست للتخبير كما يتبادر من فعل المشيئة .وهى معترضة للترغيب فى حفظ هذه الآيات ، وفى العمل بما اشتملت عليه من هدايات .وجاء الضمير مذكرا فى قوله : ( فَمَن شَآءَ ذَكَرَهُ ) لأن التذكرة هنا بمعنى التذكير والاتعاظ .أى : فمن شاء التذكير والاعتبار ، تذكر واعتبر وحفظ ذلك دون أن ينساه . .","13":"وقوله : ( فَي صُحُفٍ مُّكَرَّمَةٍ ) خبر ثان لقوله ( إِنَّهَا تَذْكِرَةٌ ) وما بينهما اعتراض . .أى : إن آيات القرآن تذكرة ، مثبتة أو كائنة فى صحف عظيمة ( مكرمة ) عند الله - تعالى - لأنها تحمل آياته .","14":"هذه الصحف - أيضا - ( مرفوعة ) أى : ذات منزلة رفيعة ( مطهرة ) أى : منزهة عن أن يمسهها ما يدنسها .","15":"وهى كائنة ( بِأَيْدِي سَفَرَةٍ ) وهم الملائكة الذين جعلهم الله - تعالى - سفراء بينه وبين رسله : جمع سافر بمعنى سفير . أى : رسول وواسطة ، أو هم الملائكة الذين ينسخون ويكتبون هذه الآيات بأمره - تعالى - جمع سافر بمعنى كاتب ، يقال : سفَر فلان يَسْفِره ، إذا كتبه .","16":"( كِرَامٍ بَرَرَةٍ ) أى : هذه الآيات بأيدى سفرة من صفاتهم أنهم مكرمون ومعظمون عنده - تعالى - ، وأنهم أتقياء مطيعون الله - تعالى - كل الطاعة ، جمع بَرّ ، وهو من كان كثير الطاعة والخشوع لله - عز وجل - . .هذا والمتأمل فى هذه الآيات الكريمة يراها قد اشتملت على كثير من الآداب والأحكام ، ومن ذلك : أن شريعة الله - تعالى - تجعل التفاضل بين الناس ، أساسه الإِيمان والتقوى ، فمع أن عبد الله ابن أم مكتوم ، كان قد قاطع الرسول صلى الله عليه وسلم لم يتشاغل عنه إلا لحرصه على جذب هؤلاء الزعماء إلى الإِسلام .مع كل ذلك ، وجدنا الآيات الكريمة ، تعاتب النبى صلى الله عليه وسلم عتابا تارة فيه رقة . وتارة فيه شدة . وذلك لأن الميزان الذى أنزله الله - تعالى - للناس مع الرسل ، لكى يبنوا عليه حياتهم ، هو : ( إِنَّ أَكْرَمَكُمْ عَندَ الله أَتْقَاكُمْ ) ولقد استجاب الرسول الكريم لهذا التوجيه الحكيم ، فبنى حياته كلها بعد ذلك على هذا الميزان العادل ، ومن مظاهر ذلك : إكرامه لابن أم مكتوم ، وقوله له كلما رآه : \" أهلا بمن عاتبنى فيه ربى \" .وفعل صلى الله عليه وسلم ما يشبه ذفلك ، مع جميع المؤمنين الصادقين الذين كانوا من فقراء المسلمين ، ولم يكونوا أصحاب جاه أن نفوذ أو عشيرة قوية .لقد جعل زيد بن حارثة - وهو الغريب عن مكة والمدينة ، أميرا على الجيش الإِسلامى فى غزوة مؤتة ، وكان فى هذا الجيش عدد كبير من كبار الصحابة .وقال صلى الله عليه وسلم فى شأن سلمان الفارسى : \" سلمان منا أهل البيت \" .وقال صلى الله عليه وسلم فى شأن عمار بن ياسر ، عندما استأذن عليه فى الدخول : \" ائذنوا له . مرحبا بالطيب المطيب \" .وكان من مظاهر تكريمه لعبد الله بن مسعود ، أن جعله كأنه واحد من أهله بيته .فعن أبى موسى الأشعرى قال : قدمت أنا وأخى من اليمن ، فمكثنا حينا وما نرى ابن مسعود وأمه إلا من أهل بيت رسول الله صلى الله عليه وسلم من كثرة دخولهم على رسول الله ، ولزومهم له . .وقال صلى الله عليه وسلم لأبى بكر الصديق عندما حدث كلام بينه وبين سلمان وصهيب وبلال فى شأن أبى سفيان : يا أبا بكر لعلك أغضبتهم ، لئن كنت أغضبتهم فقد أغضبت ربك .فقد أخرج الإِمام مسلم فى صحيحه . . \" أن أبا سفيان أتى على سلمان وصهيب وبلال فى نفر ، فقالوا : ما أخذت سيوف الله من عدو الله مأخذها ، فقال أبو بكر : أتقولون هذا لشيخ قريش وسيدهم؟فأتى النبى صلى الله عليه وسلم فأخبر فقال : \" يا أبا بكر لعلك أغضبتهم . لئن كنت أغضبتهم فقد أغضب ربك \" فأتاهم فقال : يا إخوتاه أأغضبتكم؟ قالوا : لا . ويغفر الله لك يا أخى . . \"ولقد سار خلفاؤه صلى الله عليه وسلم على هذه السنة ، فكانوا يكرمون الفقراء ، فأبوا بكر - رضى الله عنه - أذن لصهيب وبلال فى الدخول عليه ، قبل أن يأذن لأبى سفيان وسهيل بن عمرو . .وعمر - رضى الله عنه - يقول فى شأن أبى بكر : \" هو سيدنا وأعتق سيدنا \" يعنى : بلال ابن رباح . .قال صاحب الكشاف عند تفسيره ، لهذه الآيات : ولقد تأدب الناس بأدب الله فى هذا تأدبا حسنا ، فقد روى عن سفيان الثورى - رحمه الله - ، أن الفقراء كانوا فى مجلسه أمراء . .","17":"ثم انتقلت السورة الكريمة بعد ذلك ، إلى الحديث عن جانب من نعم الله - تعالى - على خلقه ، وموقفهم من هذه النعم ، فقال - تعالى - :( قُتِلَ الإنسان مَآ . . . ) .قال الإِمام الرازى : اعلم أنه - تعالى - لما بدأ بذكر القصة المشتملة على ترفع صناديد قريش على فقراء المسملين ، عجب عباده المؤمنين من ذلك ، فكأنه قيل : وأى سبب فى هذا العجب والترفع؟ مع أن أوله نطفة قذرة ، وآخره جيفة مذرة ، وفيما بين الوقتين حمال عذرة ، فلا عجب أن ذكر الله - تعالى - ما يصلح أن يكون علاجا لعجبهم وما يصلح أن يكون علاجا لكفرهم ، فإن خلقه الإِنسان يستدل بها على وجود الصانع ، وعلى القول بالبعث والحشر والنشر . .والمراد بالإِنسان هنا : الإِنسان الكافر الجاحد لنعم ربه . ومعنى \" قتل \" لعن وطرد من رحمة الله - تعالى - ، ويصح أن يكون المراد به الجنس ، ويدخل فيه الكافر دخولا أوليا أى : لعن وطرد من رحمة الله - تعالى - ذلك الإِنسان الذى ما أشده كفره وجحوده لنعم الله - تعالى - .والدعاء عليه باللعن من الله - تعالى - ، المقصود به : التهديد والتحقير من شأن هذا الإِنسان الجاحد ، إذ من المعلوم أن الله - سبحانه - هو الذى يتوجه إليه الناس بالدعاء ، وليس هو - سبحانه - الذى يدعو على غيره ، إذ الدعاء فى العادة إنما يكون من العاجز ، وجل شأن الله - تعالى - عن العجز .وجملة \" ما أكفره \" تعليل لاستحقاق هذا الإِنسان الجاحد التحقير والتهديد .وهذه الآية الكريمة المتأمل فيها يراها - مع بلوغها نهاية الإِيجاز - قد بلغت - أيضا - نهاية الإِعجاز فى أسلوبها ، حيث جمعت أشد ألوان الذم والتحقير بأبلغ أسلوب وأوجزه .ولذ قال صاحب الكشاف : ( قُتِلَ الإنسان ) دعاء عليه ، وهى من أشنع دعواتهم ، لأن القتل قصارى شدائد الدنيا وفظائعها ( مَآ أَكْفَرَهُ ) تعجيب من إفراطه فى كفران نعمة الله ، ولا ترى أسلوبا أغلظ منه ولا أخشن متنا ، ولا أدل على سخط ، ولا أبعد فى المذمة ، مع تقارب طرفيه ، ولا أجمع لِلائمةٍ ، على قصر متنه . .","18":"ثم فصل - سبحانه - جانبا من نعمه ، التى تستحق من هذا الإِنسان الشكر لا الكفر فقال : ( مِنْ أَيِّ شَيءٍ خَلَقَهُ ) أى : من أى شئ خلق الله - تعالى - هذ الإِنسان الكافر الجحود ، حتى يتكبر ويتعظم عن طاعته ، وعن الإِقرار بتوحيده ، وعن الاعتراف بأن هناك بعثا وحسابا وجزاء . . ؟","19":"ثم وضح - سبحانه - كيفية خلق الإِنسان فقال : ( مِن نُّطْفَةٍ خَلَقَهُ فَقَدَّرَهُ ) أى : خلق الله - تعالى - الإِنسان من نطفة ، أى : من ماء قليل يخرج من الرجل إلى رحم المرأة - ( فقدره ) أى : فأوجد الله - تعالى - الإِنسان بعد ذلك إيجادا متقنا محكما ، حيث صير بقدرته النطفة علقة فمضغة . . ثم أنشأه خلقا آخر ثُمَّ خَلَقْنَا( فَتَبَارَكَ الله أَحْسَنُ الخالقين ) .","20":"( ثُمَّ السبيل يَسَّرَهُ ) أى : ثم بعد أن خلقه فى أحسن تقويم ، ومنحه العقل الذى يتمكن معه من التفكير السليم . يسر - سبحانه - له طريق النظر القويم ، الذى يميز به بين الحق والباطل ، والخير والشر ، والهدى والضلال .قال ابن كثير : قوله ( ثُمَّ السبيل يَسَّرَهُ ) قال العوفى عن ابن عباس : ثم يسر عليه خروجه من بطن أمه . وهكذا قال عكرمة . . واختاره ابن جرير .وقال مجاهد : هذه الآية كقوله : ( إِنَّا هَدَيْنَاهُ السبيل إِمَّا شَاكِراً وَإِمَّا كَفُوراً ) أى بيناه له ووضحناه وسهلنا عليه علما . . وهذا هو الأرجح .وجاء العطف \" بثم \" هنا ، للإِشعار بالتراخى الرتبى ، لأن تيسير معرفة طريق الخبر والشر ، أعجب وأجل على قدرة الله - تعالى - وبديع صنعه من أى شئ آخر .ولفظ \" السبيل \" منصوب على الاشتغال بفعل مقدر ، أى : ثم يسر السبيل يسره ، فالضمير فى يسره يعود إلى السبيل . أى : سهل - سبحانه - الطريق للإِنسان .","21":"( ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ ) أى : ثم أمات - سبحانه - هذا الإِنسان ، بأن سلبه الحياة ( فأقبره ) أى : فجعله ذا قبر يوارى فيه جسده تكريما له ، ولم يتركه مطروحا على وجه الأرض ، بحيث يستقذره الناس ، ويكون عرضة لاعتداء الطيور والحيوانات عليه .يقال : قبر فلان الميت يقبره - بكسر الباء وضمها - ، إذا دفنه بيده فهو قابر . ويقال : أقبره ، إذا أمر بدفنه ، أو مكن غيره من دفنه .وفى الآية الكريمة إشارة إلى أن مواراة الأجساد فى القبور من سنن الإِسلام ، أما تركها بدون دفن ، أو حرقها . . فيتنافى مع تركيم هذه الأجساد .","22":"( ثُمَّ إِذَا شَآءَ أَنشَرَهُ ) أى : ثم بعد أن خلق الله خلق الله هذا الخلق البديع ، وهداه النجدين ، وأمر بستر جسده فى القبر بعد موته . . بعد كل ذلك إذا شاء أحياه بعد الموت ، للحساب والجزاء . يقال : أنشر الله - تعالى - الموتى ونشرهم ، إذا بعثهم من قبورهم .وقال - سبحانه - ( إِذَا شَآءَ ) للإِشعار بأن هذا البعث إنما هو بإرادته ومشيئته ، وفى الوقت الذى يختاره ويريده ، مهما تعجله المتعجلون .","23":"ثم زجر - سبحانه - هذا الإِنسان زجرا شديدا لتقصيره فى أداء حق خالقه ، فقال - تعالى - : ( كَلاَّ لَمَّا يَقْضِ مَآ أَمَرَهُ ) أى : كلا ن هذا الإِنسان الجاحد المغرور . . لم يقض ولم يؤد ما أمره الله - تعالى - به من تكاليف ومن شكر لخالقه ، ومن تأمل فى آياته ، ومن طاعة لرسله . . بل استمر فى طغيانه وعناده .فالمقصود بهذه الآية الكريمة : ردع هذا الإِنسان الجاحد وزجره ، وبيان أن هذا الردع سببه إهماله لحقوق خالقه ، وعدم اهتماه بأدائها .","24":"ثم ساقت الآيات بعد ذلك ألوانا من نعمه - تعالى - على خلقه فقال : ( فَلْيَنظُرِ الإنسان إلى طَعَامِهِ ) والفاء هنا للتفريع على ما تقدم ، مع إفادتها معنى الفصيحة .أى : إذا أراد أن يقى ويؤدى ما أمره الله - تعالى - من تكاليف ، فلينظر هذا الإِنسان إلى طعامه ، وكيف أوجده - سبحانه - له ورزقه إياه ، ومكنه منه . فإن فى هذا النظر والتدبر والتفكر ، ما يعينه على طاعة خالقه ، وإخلاص العبادة له .","25":"ثم بين - سبحانه - مظاهر تهيئة هذا الطعام للإِنسان . . فقال : ( أَنَّا صَبَبْنَا المآء صَبّا ) .قال الجمل : قرأ الكوفيون ( أنا ) بالفتح . على البدل من طعامه ، فيكون فى محل جر بدل اشتمال ، بمعنى أن صب الماء سبب فى إخراج الطعام فهو مشتمل عليه .وقرأ غيرهم بكسر الهمزة على الاستئناف المبين لكيفية إحداث الطعام . .والصب : إنزال الماء بقوة وكثرة . أى : إنا أنزلنا المطر من السماء إنزالا مصحوبا بالقوة والكثرة ، لحاجتكم الشديدة إليه فى حياتكم .","26":"( ثُمَّ شَقَقْنَا الأرض شَقّاً ) أى : ثم شققنا الأرض بالنبات شقا بديعا حكيما ، بحيث تخرج النباتات من باطنها خروجها يبهج النفوس ، وتقر به العيون .","27":"( فَأَنبَتْنَا فِيهَا حَبّاً ) أى : فأنبتنا فى الأرض حبا كثيرا ، تقتاتون منه ، وتدخرونه لحين حاجتكم إليه ، والحب : يشمل الحنطة والشعير والذرة .","28":"( وَعِنَباً وَقَضْباً . وَزَيْتُوناً وَنَخْلاً . وَحَدَآئِقَ غُلْباً . وَفَاكِهَةً وَأَبّاً ) أى : وأنبتنا فى الأرض - أيضا - بقدرتنا ورحمتنا ( عنبا ) وهو ثمر الكرم المعروف بلذة طعمه .( وقضبا ) وهو كل ما يؤكل من النبات رطبا ، كالقثاء والخيار ونحوهما ، وقيل : هو العلف والرطب الذى تأكله والدواب ، وسمى قضبا ، لأنه يقضب - أى يقطع - بعد ظهوره مرة بعد أخرى .","29":"وأنبتنا فيها كذلك ( وَزَيْتُوناً وَنَخْلاً ) وهما شجرتان معروفتان بمنافعهما الجمة ، وبثمارهما المفيدة .","30":"( وَحَدَآئِقَ غُلْباً ) والحدائق جمع حديقة وهى البستان الملئ بالزورع والثمار .و ( غلبا ) جمع غلباء . أى : وأنبتنا فى الأرض حدائق عظيمة ، ذات أشجار ضخمة ، قد التف بعضها على بعض لكثرتها وقوتها . فقوله ( غلبا ) بمعنى عظاما ، وأصلها من ( الغَلَب ) - بفتحتين - ، بمعنى الغلظ ، يقال شجرة غلباء ، وهضبة غلباء . أى : عظيمة مرتفعة . ويقال : حديقة غلباء ، إذا كانت عظيمة الشجر . ويقال : رجل أغلب ، إذاكان غليظ الرقبة .وأنبتنا فيها - أيضا - بقدرتنا وفضلنا.","31":"( وَفَاكِهَةً وَأَبّاً ) . . والفاكهة : اسم للثمار التى يتناولها الإِنسان على سبيل التفكه والتلذذ ، مثل الرطب والعنب والتفاح .والأب : اسم للكلأ الذى ترعاه الأنعام ، مأخوذ من أبَّ فلان الشئ ، إذا قصده واتجه نحوه ، لحاجته إليه . . والكلأ والعشب يتجه إلأيه الإِنسان بدوابه للرعى . .قال صاحب الكشاف : والأب : المرعى ، لأنه يؤب ، أى : يؤم وينتجع . . . وعن أبى بكر الصديق - رضى الله عنه - أنه سئل عن الأب فقال : أى سماء تظلنى ، وأى أرض تقلنى ، إذا قلت فى كتاب الله مالا علم لى به . .وعن عمر - رضى الله عنه - أنه قرأ هذه الآية فقال : كل هذا قد عرفنا ، فما الأب؟ ثم رفع عصا كانت فى يده وقال : هذا لعمر الله التكلف ، وما عليك يا بن أم عمر أن لا تدرى ما الأب؟ ثم قال : اتبعوا ما تبين لكم من هذا الكتاب ، وما لا فدعوه .فإن قلت : فهذا يشبه النهى عن تتبع معانى القرآن والبحث عن مشكلاته؟ قلت : لم يذهب إلى ذلك ، ولكن القوم كانت أكبر همتهم عاكفة عن العمل ، وكان التشاغل بشئ من العلم لا يعمل به تكلفا عندهم ، فأراد أن الآية مسوقة فى الامتنان على الإِنسان بمطعمه ، واستدعاء شكره ، وقد علم من فحوى الآية ، أن الأبَّ بعض ما أنبته الله للإِنسان متاعا له أو لأنعامه فعليك؟ بما هو أهم ، من النهوض بالشكر لله - تعالى - على ما تبين لك أو لم يشكل ، مما عدد من نعمه ، ولا تتشاغل عنه بطلب معنى الأب ، ومعرفة النبات الخاص الذى هو اسم له ، واكتف بالمعرفة الجملية ، إلى أن يتبين لك فى غير هذا الوقت . .وقال بعض العلماء : والذى يتبين لى فى انتفاء علم الصديق والفاروق بمدلول لفظ الأب ، وهما من خلص العرب لأحد سببين :إما لأن اللفظ كان قد تنوسى من استعمالهم ، فأحياه القرآن لرعاية الفاصلة ، فإن الكلمة قد تشتهر فى بعض القبائل أو فى بعض الأزمان وتنسى فى بعضها ، مثل اسم السكين عند الأوس والخزرج . فقد قال أنس بن مالك : ما كنا نقول إلا المدية ، حتى سمعت قول الرسول صلى الله عليه وسلم يذكر أن سليمان قال : \" ائتونى بالسكين أقسم الطفل بينهما نصفين \" .وإما لأن كلمة الأب تطلق على أشياء كثيرة ، منها النبت الذى ترعاه الأنعام ، ومنها التبن . ومنها يابس الفاكهة ، فكان إمساك أبى بكر وعمر عن بيان معناه ، لعدم الجزم بما أراد الله منه على التعيين ، وهل الأب مما يرجع إلى قوله ( مَّتَاعاً لَّكُمْ وَلأَنْعَامِكُمْ )","32":"( مَّتَاعاً لَّكُمْ وَلأَنْعَامِكُمْ )أى : أنبت لكم تلك الزورع والثمار . . لتكون موضع انتفاع لكم ولأنعامكم إلى حين من الزمان .إذ المتاع : هو ما ينتفع به الإِنسان إلى حين ثم ينتهى ويزول ، ولفظ \" متاعا \" منصوب بفعل محذوف ، أى : فعل ذلك متاعا لكم ، أو متعكم بذلك تمتيعا لكم ولأنعامكم .أو قوله ( مَّتَاعاً لَّكُمْ ) حال من الألفاظ السابقة : العنب والقضب والزيتون والنخل .أى : حالة كون هذه المذكورات موضع انتفاع لكم ولأنعامكم .","33":"ثم ختم - سبحانه - السورة الكريمة بالحديث عن أحوال الناس فى يوم القيامة فقال - تعالى - :( فَإِذَا جَآءَتِ . . . ) .الفاء فى قوله - سبحانه - ( فَإِذَا جَآءَتِ الصآخة ) للدلالة على ترتيب ما بعدها على ما قبلها من فنون النعم . وجواب ( إذا ) محذوف يدل عليه قوله - تعالى - بعد ذلك : ( لِكُلِّ امرىء مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ ) ، ويصح أن يكون جوابه قوله : ( وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ ) .والصاخة : الصحية الشديدة التى تصُخُّ الآذان ، أى تزلزلها لشدة صوتها ، وأصل الصخ : الصك الشديد ، والمراد بها هنا : النفخة الثانية التى بعدها يبعث الناس من قبورهم . .أى : فإذا جاءت الصحية العظيمة التى بعدها يخرج الناس من قبورهم للحساب والجزاء ، كان ما كان من سعادة أقوام ، ومن شقاء آخرين .","34":"وقوله - سبحانه - : ( يَوْمَ يَفِرُّ المرء مِنْ أَخِيهِ . وَأُمِّهِ وَأَبِيهِ ) بدل مما قبله وهو قوله ( فَإِذَا جَآءَتِ الصآخة ) والفرار : الهروب من أجل التخلص من شئ مخيف .والمعنى : يوم يقوم الناس من قبورهم للحساب والجزاء يكونون فى كرب عظيم ، يجعل الواحد منهم ، يهرب من أخيه الذى هو من ألصق الناس به .","35":"ويهرب كذلك من أمه وأبيه .","36":"ومن صاحبته - وهى زوجه - وبنيه الذين هم فرع عنه .والمراد بفراره منهم : عدم اشتغاله بشئ يتعلق بهم ، وعدم التفكير فيهم وفى الالتقاء بهم ، لاشتغاله بحال نفسه اشتغالا ينسيه كل شئ سوى التفكير فى مصيره . . وذلك لشدة الهول ، وعظم الخطب .وخص - سبحانه - هؤلاء النفر بالذكر ، لأنهم أخص القرابات ، وأولاهم بالحنو والرأفة ، فالفرار منهم لا يكون إلا فى أشد حالات الخوف والفزع .قال صاحب الكشاف : \" يفر \" منهم لاشتغاله بما هو مدفوع إليه ، ولعلمه بأنهم لا يغنون عنه شيئا : وبدأ بالأخ ثم بالأبوين لأنهما أقرب منه ثم بالصاحبة والبنين ، لأنهم أقرب وأحب كأنه قال : يفر من أخيه ، بل من أبويه ، بل من صاحبته وبنيه . .","37":"وجملة : ( لِكُلِّ امرىء مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ ) مستأنفة ، واردة لبيان سبب الفرار وللمبالغة فى تهويل شأن هذا اليوم .أى : لكل واحد منهم فى هذا اليوم العظيم ، شأن وأمر يغنيه ويكفيه عن الاشتغال بأى أمر آخر سواه ، يقال : فلان أغنى فلاناً عن كذا ، إذا جعله فى غنية عنه .وقد ساق ابن كثير - رحمه الله - عند تفسيره لهذه الآية عدد من الأحاديث ، منها ما رواه النسائى عن ابن عباس قال : قال رسول الله صلى الله عليه وسلم : \" تحشرون فاة عراة غُرْلا \" - بضم فسكون - جمع أغرل ، وهو الأقلف غير المختون - قال ابن عباس : فقالت زوجته : يا رسول الله ، أو يرى بعضنا عورة بعض؟ قال : \" لكل امرئ منهم يومئذ شأن يغنيه \" . أو قال : \" ما أشغله عن النظر \" .","38":"ثم بين - سبحانه أقسام الناس فى هذا اليوم فقال : ( وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ .","39":"ضَاحِكَةٌ مُّسْتَبْشِرَةٌ ) أى : وجوه كثيرة فى هذا اليوم تكون مضيئة مشرقة ، يعلوها السرور ، والاستبشار والانشراح ، لما تراه من حسن استقبال الملائكة لهم .وقوله : ( وُجُوهٌ ) مبتدأ وإن كان نكرة ، إلا أنه صح الابتداء به لكونه فى حيز التنويع و ( مُّسْفِرَةٌ ) خبره ، وقوله ( يَوْمَئِذٍ ) متعلق به ، والإِسفار : النور والضياء .والمراد أن هذه الوجوه متهللة فرحا ، وعليها أثر النعيم .","40":"أما القسم المقابل لهذا القسم ، فقد عبر عنه - سبحانه - بقوله : ( وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ ) أى : عليها غبار ، من شدة الهم والكرب والعم الذى يعلوها .","41":"( تَرْهَقُهَا قَتَرَةٌ ) أى : تغشاها وتعلوها ظلمة وسواد ، وذلة وهوان ، من شدة ما أصابها من خزى وخسران . يقال : فلان رهقِه الكرب ، إذا اعتراه وغشيه .","42":"( أولئك ) يعنى أصحاب تلك الوجوه التى يعلوها الغبار والسواد ( هُمُ الكفرة الفجرة ) أى : الجامعون بين الكفر الذى هو فساد الاعتقاد ، وبين الفجور الذى هو فساد القول والفعل .نسأل الله - تعالى - أن يجعلنا جميعا من أصحاب الوجه المسفرة ، الضاحكة المستبشرة .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم . ."},"81":{"1":"تكرر لفظ \" إذا \" فى هذه الآيات اثنى عشرة مرة ، وجواب الشرط قوله : ( عَلِمَتْ نَفْسٌ مَّآ أَحْضَرَتْ ) . وهذا التكرار بلفظ إذا من مقاصده التشويق للجواب ، لأن السامع عندما يجد هذا الظرف وقد تكرر يكون فى ترقب وشوق لمعرفة الجواب .وعندما يسمعه يتمكن من نفسه كل التمكن .ولفظ \" الشمس مرفوع على أنه فاعل بفعل محذوف يفسره ما بعده ، أى : إذا كورت الشمس كورت ، وأصل التكوير : لف الشئ على جهة الاستدارة ، تقول : كورت العمامة ، إذا لففتها .قال صاحب الكشاف : فى التكوير وجهان : أحدهما : أن يكون من كورت العمامة إذا لففتها . أى : يلف ضوء الشمس لفا فيذهب انبساطه وانتشاره فى الآفاق ، وهو عبارة عن إزالتها والذهاب بها ، لأنها ما دامت باقية ، كان ضياؤها منبسطا غير ملفوف .وثانيهما : أن يكون لفها عبارة عن رفعها وسترها ، لأن الثواب إذا أريد رفعه ، لف وطوى ونحوه قوله - تعالى - : ( يَوْمَ نَطْوِي السمآء ) أى : إذا الشمس أزيل ضوؤها بعد انتشاره وانبساطه ، فأصبحت مظلمة بعد أن كانت مضيئة ، ومستترة بعد أن كانت بارزة .","2":"( وَإِذَا النجوم انكدرت ) أى : تناثرت وتساقطت وانقلبت هيئتها من اللمعان والظهور ، إلى الميل نحو الظلام والسواد .أى : وإذا النجوم تساقطت وانقضت . يقال : انكدر البازى ، إذا نزل على فريسته بسرعة ، وانكدر الأعداء على القوم إذا جاءوا أرسالا متتابعين فانصبوا عليهم .ويصح أن يكون المعنى : وإذا النجوم تغيرت وانطمس نورها ، وزال لمعانها ، من قولهم : كدرت الماء فانكدر ، إذا خلط به ما يجعله مائلا إلى السواد والغُبْرة .","3":"( وَإِذَا الجبال سُيِّرَتْ ) أى : اقتلعت من أماكنها فسارت فى الفضاء بقدرة الله - تعالى - . قال - تعالى - : ( وَيَوْمَ نُسَيِّرُ الجبال وَتَرَى الأرض بَارِزَةً وَحَشَرْنَاهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَداً ) وقال - سبحانه - : ( وَسُيِّرَتِ الجبال فَكَانَتْ سَرَاباً ).","4":"( وَإِذَا العشار عُطِّلَتْ ) والعشار : جمع عُشَراء وكنُفَسَاء ، وهى الناقة التى أتى على حملها عشرة أشهر . وتسمى بهذا الاسم إلى أن تضع عليها حتى فى أشد حالات الخوف .ومعنى \" عطلت \" : أهملت وتركت بدون راع يحميها ، أو يلتفت إليها ، وهذا تصوير بديع لما يصيب الناس من أهوال ، تجعلهم لا يلتفتون إلى أعز أموالهم لديهم .أى : وإذا النوق العشار - التى هى أغلى الأموال - عطلت ، أى تركت دون أن يلتفت إليها أحد . لانشغال كل إنسان بنفسه .وقيل : المراد بالعشار : السحب المحملة بالأمطار . أى : وإذا السحب الحاملة للأمطار قد عطلت عن نزول المطر منها ، وصارت خالية من الماء الذى يحيى الأرض بعد موتها .قال القرطبى ما ملخصه : ( وَإِذَا العشار عُطِّلَت ) أى : النوق الحوامل التى فى بطونها أولادها ، الواحدة عُشَراء . . وإنما خصت بالذكر ، لأنها أعز ماتكون عند العرب .. وهذا على وجه المثل . لأن فى القيامة لا تكون ناقة عشراء ، ولكن أراد به المثل ، أو هول يوم القيامة بحال ما لو كان للرجل ناقة عشراء لعطلها واشتغل بنفسه .وقيل : العشار : السحاب يعطل مما يكون فيه وهو الماء فلا يمطر ، والعرب تشبه السحاب بالحامل .وقيل : الديار تعطل فلا تسكن . . والأول أشهر ، وعليه من ناس الأكثر .","5":"( وَإِذَا الوحوش حُشِرَتْ ) أى : وإذا الحيوانات المتوحشة - كالأسد والنمر وغيرهما .( حُشِرَتْ ) أى : جمعت من أماكنها المتفرقة ، وخرجت فى ذهول ، وتلاقت دون أن يعتدى بعضها على بعض ، مخالفة بذلك ما طبعت عليه من النفور والتقاتل .قال الآلوسى قوله : ( وَإِذَا الوحوش ) جمع وحش ، وهو حيوان البر الذى ليس فى طبعه التأنس ببنى آدم . . ( حُشِرَتْ ) أى : جمعت من كل جانب . وقيل : حشرت أى : أميتت . . وقيل : حشرت : بعثت للقصاص ، فيحشر كل شئ حتى الذباب .أخرج مسلم والترمذى عن أبى هريرة فى هذه الآية قال : \" قال رسول الله صلى الله عليه وسلم : لتُؤدَّنَّ الحقوق إلى أهلها يوم القيامة ، حتى يقاد للشاة الجماء من الشاة القرناء . . \" .","6":"( وَإِذَا البحار سُجِّرَتْ ) أى : امتلأت وفاض ماؤها واختلط عذبها بملحها ، وصارت بحرا واحداً ، مأخوذ من قولهم : سجر الحوض ، إذا ملأه حتى فاض من جانبيه .ويصح أن يكون معنى \" سجرت \" : أحميت بالنار حتى تبخرت مياهها ، وظهرت النار فى مكانها ، من قولهم : سجر فلان التنور ، إذا ملأه بالحطب المعد للحرق .","7":"( وَإِذَا النفوس زُوِّجَتْ ) وقوله : ( زُوِّجَتْ ) من التزويج وهو جعل الشئ زوجا لغيره ، بعد أن كان كلاهما فرداً ، ويطلق الزوج - أيضاً - على الصنف والنوع ، كما فى قوله - تعالى - ( وَمِن كُلِّ الثمرات جَعَلَ فِيهَا زَوْجَيْنِ اثنين ) أى : وإذا النفوس اقترنت كل واحدة منها ببدنها ، أو بمن يشبهها ، أو بعملها .قال الفخر الرازى قوله : ( وَإِذَا النفوس زُوِّجَتْ ) فيه وجوه : أحدها : قرنت الأرواح بالأجساد .ثانيها : يصيرون فيها - أى : يوم القيامة - ثلاثة أصناف ، كما قال - تعالى - ( وَكُنتُمْ أَزْوَاجاً ثَلاَثَةً ) ثالثها : أنه يضم إلى كل نصف من كان من طبقته ، فيضم الطائع إلى مثله . .","8":"ثم قال - تعالى - : ( وَإِذَا الموءودة سُئِلَتْ . بِأَىِّ ذَنبٍ قُتِلَتْ ) ولفظ \" الموءودة \" من الوأد ، وهو دفن الطفلة الحية .قال صاحب الكشاف وأد يئد مقلوب من آد يؤود : إذا أثقل . قال - تعالى - ( وَلاَ يَؤُودُهُ حِفْظُهُمَا ) لأنه إثقال بالتراب .فإن قلت : ما حملهم على وأد البنات؟ قلت : الخوف من لحوق العار بهم من أجلهن ، أو الخوف من الإِملاق .فإن قلت : فما معنى سؤال الموءودة عن ذنبها الذى قتلت به؟ وهلا سئل الوائد عن موجب قتله لها؟ قلت : سؤالها وجوابها تبكيت لقاتلها ، نحو التبكيت - لقوم عيسى - فى قوله - تعالى - لعيسى :( أَأَنتَ قُلتَ لِلنَّاسِ اتخذوني وَأُمِّيَ إلهين مِن دُونِ الله ) أى : وإذا الموءودة سئلت ، على سبيل التبكيت والتقريع لمن قتلها ، بأى سبب من الأسباب قتلك قاتلك .","9":"ولا شك أنها لم ترتكب ما يوجب قتلها ، وإنما القصد من ذلك إلزام قائلها الحجة ، حتى يزداد افتضاحا على افتضاحه .وقد حكى القرآن فى كثير من الآيات ، ما كان يفعله أهل الجاهلية من قتلهم للبنات ، ومن ذلك قوله - تعالى - : ( وَإِذَا بُشِّرَ أَحَدُهُمْ بالأنثى ظَلَّ وَجْهُهُ مُسْوَدّاً وَهُوَ كَظِيمٌ . يتوارى مِنَ القوم مِن سواء مَا بُشِّرَ بِهِ أَيُمْسِكُهُ على هُونٍ أَمْ يَدُسُّهُ فِي التراب أَلاَ سَآءَ مَا يَحْكُمُونَ ) ولم يكن الوأد معمولا به عند جميع قبائل العرب ، فقريش - مثلا - لم يعرف عنها ذلك وإنما عرف فى قبائل ربيعة ، وكنده ، وتميم . ولكنهم لما كانوا جميعا راضين عن هذا الفعل ، جاء الحكم عاما فى شأن أهل الجاهلية .","10":"وقوله - سبحانه - : ( وَإِذَا الصحف نُشِرَتْ ) أى : بسطت بعد أن كانت مطوية ، وهى صحف الأعمال التى سجلتها الملائكة على أصحابها ، سواء أكانت تلك الأعمال خيرا أم شرا ، فهذه الصحائف تطوى عند الموت ، وتنشر يوم القيامة ، يوم الحساب والجزاء .قال - تعالى - : ( وَكُلَّ إِنْسَانٍ أَلْزَمْنَاهُ طَآئِرَهُ فِي عُنُقِهِ وَنُخْرِجُ لَهُ يَوْمَ القيامة كِتَاباً يَلْقَاهُ مَنْشُوراً . اقرأ كتابك كفى بِنَفْسِكَ اليوم عَلَيْكَ حَسِيباً ).","11":"( وَإِذَا السمآء كُشِطَتْ ) أى : قلعت وأزيلت ، وأصل الكشط إزالةجلدة الحيوان عنه . يقال : كشطت البعير كشطا ، إذا نزعت جلده منه . أى : وإذا السماء نزعت وأزيلت ، فلم تبق على هيئتها التى كانت عيها ، من إظلالها لما تحتها .","12":"( وَإِذَا الجحيم سُعِّرَتْ ) أى : أوقدت إيقادا شديدا للكفار ، والجحيم هى النار ذات الطبقات المتعدة من الوقود كالحطب وغيره ، وتسعيرها : إيقادها بشدة .","13":"( وَإِذَا الجنة أُزْلِفَتْ ) أى : قربت وأدنيت من المؤمنين ، كما فى قوله - تعالى - : ( وَأُزْلِفَتِ الجنة لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ ) من الزلفى بمعنى القرب ، يقال : تزلف فلان إلى فلان ، إذا تقرب منه .","14":"وقوله : ( عَلِمَتْ نَفْسٌ مَّآ أَحْضَرَتْ ) هو جواب الشرط لكل تلك الظروف السابقة . أى : إذا الشمس كورت ، وإذا النجوم انكدرت تبين لكل نفس ما عملته من خير أو شر ، ومن حسن أو قبيح . . ورأت ذلك رأى العين ، كما قال - تعالى - : ( يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَراً وَمَا عَمِلَتْ مِن سواء تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُ أَمَدَاً بَعِيداً . . . ) والمراد بالنفس عموم الأنفس ، لأن النكرة فى سياق النفى تشمل كل نفس وأسند - سبحانه - الإِحضار إلى النفوس ، لأنها هى المباشرة لأعمالها فى الدنيا ، والتى ستجد جزاءها فى الآخرة .وجعلت معرفة النفوس لجزاء أعمالها ، حاصلة عند حصول مجموع الشروط التى ذكرت فى الجمل الاثنتى عشرة ، لأن بعض الزمان والأحوال التى تضمنتها هذه الشروط مقارن لحصول علم النفوس بأعمالها ، كما فى الستة الأخيرة ، فإنها تكون عند فصل القضاء ، وبعضها يحصل قبل ذلك بقليل ، كما فى الأحوال الستة المذكورة أولا ، إلا أنه لما كان بعض هذه الأمور من مبادئ يوم القيامة ، وبعضها من روادفه ، نسب علمها بذلك إلى زمان وقوع هذه الأمور كلها تهويلا للخطب ، وتفظيعا للأمر .وإشعاراً بأن ما يسبق يوم القيامة وما يعقبه ، كل ذلك من الأهوال التى يشب لها الولدان .","15":"وبعد أن ساق - ما ساق من أحوال تدل على شدائد يوم القيامة ، أتبع ذلك ببيان أن هذا القرآن من عنده - تعالى - وأن الرسول صلى الله عليه وسلم صادق فيما يبلغه عن ربه ، فقال :( فَلاَ أُقْسِمُ . . . ) .والفاء فى قوله - تعالى - : ( فَلاَ أُقْسِمُ بالخنس . . . ) للتفريع على ما تقدم من تحقيق وقوع البعث ، وهى تعطى - أيضا - معنى الإِفصاح ، و \" لا \" مزيدة لتأكيد القسم ، وجواب القسم قوله - تعالى - ( إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ ) .و ( الخنس ) - بزنة رُكَّع - جمع خانس ، والخنوس : الاستخفاء والاستتار ، يقال خنست الظبية والبقرة ، إذا اختفت فى بيتها .","16":"و ( الجوار ) جمع جارية ، وهى التى تجرى بسرعة ، من الجرى بمعنى الإِسراع فى السير .و ( الكنس ) جمع كانس . يقال : كنس الظبى ، إذا دخل كناسه - بكسر الكاف - وهو البيت الذى يتخذه للمبيت ، وسمى بذلك لأنه يتخذه من أغصان الأشجار ، ويكنس الرمل إليه حتى يكون مختفيا عن الأعين .وهذه الصفات ، المراد بها النجوم ، لأنها بالنهار تكون مختفية عن الأنظار ، ولا تظهر إلا بالليل ، فشبهت بالظباء التى تختفى فى بيوتها ولا تظهر إلا فى أوقات معينة .أى : إذا كان الأمر كما ذكرت لكم من أن البعث حق . . فأقسم بالنجوم التى تخنس بالنهار ، أى : يغيب ضؤوها عن العيون بالنهار ، ويظهر بالليل ، والتى تجرى من مكان إلى آخر بقدرة الله - تعالى - ثم تكنس - أى : تستتر وقت غروبها - كما تتوارى الظباء فى كُنُسِها . . إن هذا القرآن لقول رسول كريم .قال ابن كثير ما ملخصه : قوله - تعالى - ( فَلاَ أُقْسِمُ بالخنس . الجوار الكنس ) : هى النجوم تخنس بالنهار ، وتظهر بالليل ، روى ذلك عن على بن أبى طالب وابن عباس ومجاهد .وقال بعض الأئمة : وإنما قيل للنجوم \" الخنس \" أى : فى حال طلوعها ، ثم هى جوار فى فلكها ، وفى حال غيبوبتها ، يقال لها \" كنس \" ، من قول العرب . أوى الظبى إلى كناسه : إذا تغيب فيه .وفى رواية عن ابن عباس : أنها الظباء ، وفى أخرى أنها بقر الوحش حين تكنس إلى الظل أو إلى بيوتها .وتوقف ابن جرير فى قوله : ( بالخنس . الجوار الكنس ) هل هى النجوم أو الظباء وبقر الوحش قال : ويحتمل أن يكون الجميع مرادا . .","17":"وقوله : ( والليل إِذَا عَسْعَسَ . والصبح إِذَا تَنَفَّسَ ) معطوف على ما قبله . وداخل فى حيز القسم .وقوله ( عسعس ) أدبر ظلامه أو أقبل ، فهذا اللفظ من الألفاظ التى تستعمل فى الشئ وضده ، إلا أن المناسب هنا يكون المراد به إقبال الظلام ، لمقابلته بالصبح إذا تنفس ، أى : أضاء وأسفر وتبلج .وقيل : العسعسة : رقة الظلام وذلك فى طرفى النهار ، فهو من المشترك المعنوى ، وليس من الأضداد ، أى : أقبل وأدبر معاً . أى : وحق النجوم التى تغيب بالنهار ، وتجرى فى حال استتارها . . وحق الليل إذا أقبل بظلامه ، والصبح إذا أقبل بضيائه .","18":"وقوله : ( والليل إِذَا عَسْعَسَ . والصبح إِذَا تَنَفَّسَ ) معطوف على ما قبله . وداخل فى حيز القسم .وقوله ( عسعس ) أدبر ظلامه أو أقبل ، فهذا اللفظ من الألفاظ التى تستعمل فى الشئ وضده ، إلا أن المناسب هنا يكون المراد به إقبال الظلام ، لمقابلته بالصبح إذا تنفس ، أى : أضاء وأسفر وتبلج .وقيل : العسعسة : رقة الظلام وذلك فى طرفى النهار ، فهو من المشترك المعنوى ، وليس من الأضداد ، أى : أقبل وأدبر معاً . أى : وحق النجوم التى تغيب بالنهار ، وتجرى فى حال استتارها . . وحق الليل إذا أقبل بظلامه ، والصبح إذا أقبل بضيائه .","19":"( إنه ) أى : القرآن الكريم ( إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ ) وهو جبريل - عليه السلام - الذى أرسله ربه إلى نبيه محمد صلى الله عليه وسلم لكى يبلغه وحيه - تعالى - .وأقسم الله - تعالى - بهذه الأشياء ، لأنها فى حركاتها المختلفة ، من ظهور وأفول ، ومن إقبال وإدبار . . تدل دلالة ظاهرة على قدرة الله - تعالى - ، وعلى بديع صنعه فى خلقه .ونسب - سبحانه - القول إلى الرسول - وهو جبريل - لأنه هو الواسطة فى تبليغ الوحى إلى النبى صلى الله عليه وسلم .ثم وصف - سبحانه - أمين وحيه جبريل بخمس صفات : أولها : قوله ( كريم ) أى : ملك شريف ، حسن الخلق ، بهى المنظر .","20":"ثانيها : ( ذِي قُوَّةٍ ) أى : صاحب قوة وبطش .كما قال - تعالى - : ( عَلَّمَهُ شَدِيدُ القوى . . . ) ثالثها : ( عِندَ ذِي العرش مَكِينٍ ) أى : إن من صفات جبريل - عليه السلام - أنه ذو مكانة رفيعة ، ومنزلة عظيمة عند الله - تعالى - .","21":"رابعها : قوله - تعالى - ( مطاع ) أى يطيعه من معه من الملائكة المقربين .وخامسها : قوله : - سبحانه - ( ثَمَّ أَمِينٍ ) و \" ثم \" بفتح الثاء - ظرف مكان للبعيد . والعامل ما قبله أو ما بعده ، والمعنى : أنه مطاع فى السموات عند ذى العرش ، أو أمين فيها ، أى : يؤدى ما كلفه الله - تعالى - به بدون أية زيادة أو نقص .قال الشوكانى : ومن قال إن المراد بالرسول محمد صلى الله عليه وسلم فالمعنى : أنه ذو قوة على تبليغ الرسالة إلى الأمة ، مطاع يطيعه من أطاع الله ، أمين على الوحى .","22":"وقوله : ( وَمَا صَاحِبُكُمْ بِمَجْنُونٍ ) : الخطاب لأهل مكة ، والمراد بصاحبهم رسول الله صلى الله عليه وسلم .والمعنى : وما محمد يا أهل مكة بمجنون ، وذكره بوصف الصحبة للإِشعار بأنهم عالمون بأمره ، وأنه ليس مما يرمونه من الجنون وغيره فى شئ ، وأنهم افتروا عليه ذلك ، عن علم منهم ، بأنه عقل الناس وأكملهم ، وهذه الجملة داخلة فى جواب القسم .فأقسم - سبحانه - بأن القرآن نزل به جبريل ، وأن محمداً صلى الله عليه وسلم ليس كما يقولون من أنه مجنون ، وأنه يأتى القرآن من جهة نفسه .فالمقصود بالآية نفى الجنون عن النبى صلى الله عليه وسلم بأكمل وجه ، وتوبيخ أعدائه الذين اتهموه بتهمة هم أول من يعلم - عن طريق مشاهدتهم لاستقامة تفكيره ، وسمو أخلاقه - أنه أكمل الناس عقلا وأقومهم سلوكا .","23":"وقوله - سبحانه - : ( وَلَقَدْ رَآهُ بالأفق المبين ) معطوف - أيضا - على قوله - تعالى - قبل ذلك : ( إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ ) فهو من جملة المقسم عليه .والمقصود بهذه الرؤية : رؤية النبى صلى الله عليه وسلم لجبريل - عليه السلام - لأول مرة ، على الهيئة التى خلقه الله عليها ، عندما كان الرسول صلى الله عليه وسلم يتعبد فى غار حراء ، وكان صلى الله عليه وسلم قد سأل جبريل أن يريه نفسه ، على الهيئة التى خلقه الله - تعالى - عليها .والأفق : هو الفضاء الواسع الذى يبدو للعين ما بين السماء والأرض .والمبين : وصف للأفق ، أى : بالأفق الواضح البين ، الذى لا تشتبه معه المرئيات .والمعنى : ووالله لقد رأى صاحبكم محمد صلى الله عليه وسلم جبريل ، بصورته التى خلقه الله عليها ، بالأفق الواضح البين ، الذى لا تلتبس فيه المرئيات ، ولا مجال فيه للأوهام والتخيلات .والمقصود من الآية الكريمة الرد على المشركين الذين كانوا إذا أخبرهم الرسول صلى الله عليه وسلم بأنه رأى جبريل . كذبوه واستهزءوا به ، وتأكيد أن هذه الرؤية كانت حقيقة واقعة ، لا مجال معها للتشكيك أو اللبس .قال الإِمام ابن كثير : وقوله - تعالى - ( وَلَقَدْ رَآهُ بالأفق المبين ) يعنى : ولقد رأى محمد جبريل الذى يأتيه بالرسالة عن الله - عز وجل - وعلى الصورة التى خلقه الله عليها ، له ستمائه جناح ( بالأفق المبين ) أى : البين ، وهى الرؤية الأولى التى كانت بالبطحاء - أى بالمكان المجاور لغار حراء . وهى المذكورة فى قوله - تعالى - : ( عَلَّمَهُ شَدِيدُ القوى . ذُو مِرَّةٍ فاستوى . وَهُوَ بالأفق الأعلى . ثُمَّ دَنَا فتدلى . فَكَانَ قَابَ قَوْسَيْنِ أَوْ أدنى . فأوحى إلى عَبْدِهِ مَآ أوحى . . . )","24":"والضمير فى قوله - تعالى - : ( وَمَا هُوَ عَلَى الغيب بِضَنِينٍ ) يعود إلى الرسول صلى الله عليه وسلم المعبر عنه قبل ذلك ( بصاحبكم ) .والغيب : ما غاب عن مدارك الناس وحواسهم ، لأن الله - تعالى - قد استأثر بعلمه .والضنين : هو البخيل بالشئ ، مأخوذ من الضن - بالكسر والفتح - بمعنى البخل .قال الآلوسى : \" وما هو \" أى : رسول الله صلى الله عليه وسلم \" على الغيب \" أى : على ما يخبر به من الوحى إليه وغيره من الغيوب \" بضنين \" من الضن - بكسر الضاد وفتحها - بمعنى البخل ، أى : ببخيل ، أى : لا يبخل بالوحى ، ولا يقصر فى التعليم والتبليغ ، ومنح كل ما هو مستعد له من العلوم ، على خلاف الكهنة فإنهم لا يطلعون غيرهم على ما يزعمون معرفته إلا بإعطائهم حلوانا .وقرأ ابن كثير والكسائى وأبو عمر ( بِضَنِينٍ ) - بالظاء - أى : وما هو على الغيب بمتهم ، من الظنة - بالكسر - بمعنى التهمة .ثم قال : ورجحت هذه القراءة ، لأنها أنسب بالمقام ، لاتهام الكفرة له صلى الله عليه وسلم بذلك ، ونفى التهمة ، أولى من نفى البخل .وهذا القول لا نوافق الآلوسى - رحمه الله - عليه ، لأن القراءة متى ثبتت عن النبى صلى الله عليه وسلم لا يجوز التفاضل بينهما . والمعنى عليها واضح ولا تعارض فيه .أى : وما محمد صلى الله عليه وسلم ببخيل بتبليغ الوحى ، بل هو مبلغ له على أكمل وجه وأتمه ، وما هو - أيضا - بمتهم فيما يبلغه عن ربه ، لأنه صلى الله عليه وسلم سيد أهل الصدق والأمانة .","25":"وقوله - سبحانه - ( وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَّجِيمٍ ) معطوف - أيضا - على قوله - تعالى - ( إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ ) والضمير هنا يعود على القرآن الكريم .أى : وليس هذا القرآن الكريم ، المنزل على سيدنا محمد صلى الله عليه وسلم بقول شيطان مرجوم مسترق للسمع . . وإنما هو كلام الله - تعالى - الذى لا يأتيه الباطل من بين يديه ولا من خلفه .وهذا رد آخر على المشركين الذين زعموا أن القرآن الكريم إنما هو من باب الكهانة ، وأن الرسول صلى الله عليه وسلم إنما هو كاهن ، تلقنه الشياطين هذا القرآن .","26":"وقوله - سبحانه - : ( فَأيْنَ تَذْهَبُونَ ) جملة معترضة بين ما سبقها .","27":"وبين قوله - تعالى - بعد ذلك ( إِنْ هُوَ إِلاَّ ذِكْرٌ لِّلْعَالَمِينَ ) ، والمقصود فيها توبيخهم وتعجيزهم عن أن يأتوا ولو بحجة واحدة يدافعون بها عن أنفسهم .والفاء لتفريع هذا التعجيز والتوبيخ ، على الحجج السابقة ، المثبتة بأن هذا القرآن من عند الله - تعالى - وليس من عند غيره .و ( أين ) اسم استفهام عن المكان ، والاستفهام هنا للتعجيز والتقريع ، وهو منصوب بقوله : ( تذهبون ) .أى : إذا كان الأمر كما ذكرنا لكم ، فأى طريق تسلكون أوضح وأبين من هذا الطريق الذى أرشدناكم إليه؟ إنه لا طريق لكم سوى هذا الطريق الذى أرشدناكم إليه .قال صاحب الكشاف : قوله ( فَأيْنَ تَذْهَبُونَ ) استضلال لهم ، كما يقال لتارك الجادة اعتسافاً أو ذهابا فى بنيات الطريق - أى : فى الطريق المتشعبة عن الطريق الأصلى - أين تذهب؟ مثلث حالهم فى تركهم الحق وعدولهم عنه إلى الباطل .( إِنْ هُوَ إِلاَّ ذِكْرٌ لِّلْعَالَمِينَ ) أى : ما هذا القرآن الكريم ، إلا تذكير وإرشاد وهدايات للبشر جميعا .","28":"وهذا الذكر العظيم إنما هو ( لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ ) أى : هو نافع لمن شاء منكم - أيها الناس - أن يستقيم على طريق الحق ، وأن يلزم الرشاد ويترك الضلال .والجملة الكريمة بدل مما قبلها ، للإِشعار بأن الذين استجابوا لهدى القرآن قد شاءوا لأنفسهم الهداية والاستقامة .فالمقصود بهذه الجملة : الثناء عليهم ، والتنويه بشأنهم .","29":"ثم ختم - سبحانه - السورة الكريمة ، ببيان أن مشيئته - تعالى - هى النافذة ، فقال : ( وَمَا تَشَآءُونَ إِلاَّ أَن يَشَآءَ الله رَبُّ العالمين ) .أى : وما تشاءون الاستقامة أو غيرها ، إلا إذا شاءها وأرادها الله - تعالى - رب العالمين ، إذ مشيئة الله - تعالى - هى النافذة ، أما مشيئتكم فلا وزن لها إلا إذا أذنت بها مشيئته - تعالى - .فالمقصود من الآية الكريمة بيان أن كل مشيئة لا قيمة لها ولا وزن . . إلا إذا أيدتها مشيئة الله - عز وجل - .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"82":{"1":"قوله - سبحانه - : ( إِذَا السمآء انفطرت ) بيان لما ستكون عليه السماء عند اقتراب قيام الساعة .ومعنى : ( انفطرت ) انشقت ، من الفطر - بفتح الفاء - بمعنى الشق ، كما قال - تعالى - فى أول سورة الانشقاق : ( إِذَا السمآء انشقت ) يقال : فطرت الشئ فانفطر ، أى : شققته فانشق . أى : إذا السماء تصدعت وتشققت فى الوقت الذى يريده الله - تعالى - لها أن تكون كذلك .","2":"( وَإِذَا الكواكب انتثرت ) أى : وإذا النجوم تهاوت وتساقطت وتفرقت ، ويقال : نثرت الشئ على الأرض ، إذا ألقيته عليها متفرقا ، فانتثار الكواكب معناه : تفرقا عن مواضعها التى كانت فيها .","3":"( وَإِذَا البحار فُجِّرَتْ ) أى : شققت جوانبها ، فزالت الحواجز التى بينها ، واختلط بعضها ببعض فصارت جميعها بحرا واحدا ، فقوله ( فُجِّرَتْ ) مأخوذ من الفجر - بفتح الفاء - وهو شق الشئ شقا واسعا ، يقال : فجر الماء فتفجر ، إذا شقه شقا واسعا ترتب عليه سيلان الماء بشدة .","4":"( وَإِذَا القبور بُعْثِرَتْ ) أى : صار باطنُها ظاهرَهَا ، وخرج ما فيها من الموتى مسرعين ، يقال : بعثر فلان متاعه ، إذا فرقه وبدده وقب بعضه على بعض .والمراد أن التراب الذى كان فيها يبعثر ويزال ، ويخرج الموتى من تلك القبور للحساب والجزاء .","5":"وقوله : ( عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ ) جواب ( إذا ) فى الآيات الأربع .أى : إذا تم ذلك ، علمت كل نفس ما قدمت من خير أو شر ، وما أخرت من سنة حسنة ، أو سنة سيئة يعمل بها بعدها .قال الجمل ما ملخصه : واعلم أن المراد من هذه الآيات أنه إذا وقعت هذه الأشياء التى هى أشراط الساعة ، فهناك يحصل الحشر والنشر ، وهى هنا أربعة : اثنان منها يتعلقان بالعلويات ، واثنان يتعلقان ، بالسفليات ، والمراد بهذه الآيات : بيان تخريب العالم ، وفناء الدنيا ، وانقطاع التكاليف . . وإنما كررت إذا لتهويل ما فى حيزها من الدواهى .وجواب ( إذا ) وما عطف عليها قوله ( عَلِمَتْ نَفْسٌ ) أى : علمت كل نفس وقت هذه المذكورات الأربعة ( مَّا قَدَّمَتْ ) من الأعمال وما أخرت منها فلم تعمله .ومعنى علم النفس بما قدمت وأخرت : العلم التفصيلى . وذلك عند نشر الصحف - كما تقدم فى سورة التكوير - أما العلم الإِجمالى فيحصل فى أول زمن الحشر ، لأن المطيع يرى آثار السعادة ، والعاصى يرى آثار الشقاوة فى أول الأمر ، وأما العلم التفصيلى فإنما يحصل عند قراءة الكتب والمحاسبة . .","6":"وبعد أن أشار - سبحانه - إلى أهوال علامات الساعة التى من شأنها أن تنبه العقول والحواس والمشاعر . . أتبع ذلك بنداء للإِنسان فقال - تعالى - : ( ياأيها الإنسان مَا غَرَّكَ بِرَبِّكَ الكريم ) والغرور : الخداع . يقال : غر فلان فلانا ، إذا خدعه وأطمعه بالباطل . والخطاب لجنس الإِنسان ، وقيل للكافر .و \" ما \" استفهامية ، والمقصود بالاستفهام : الإِنكار والتعجيب من حال هذا الإِنسان المخدوع .أى : يا أيها الإِنسان المخلوق بقدرة ربك وحده ، أى شئ غرك وخدعك وجعل جانبا من جنسك يكفر بخالقه ، ويعبد غيره ، وجانبا آخر يعصى ربه ، ويقصر فى أداء حقوقه؟قال الإِمام ابن كثير : قوله - تعالى - : ( ياأيها الإنسان مَا غَرَّكَ بِرَبِّكَ الكريم ) : هذا تهديد ، لا كما يتوهمه بعض الناس من أنه إرشاد إلى الجواب ، حيث قال : ( الكريم ) ، حتى يقول قائلهم : غره كرمه . بل المعنى فى الآية : ما غرك يا بن آدم بربك الكريم - ، أى : العظيم - حتى أقدمت على معصيته ، وقابلته بما لا يليق؟ كما جاء فى الحديث : \" يقول الله يوم القيامة : يا بن آدم ماذا أجبت المرسلين؟ \" . .وهذا الذى تخيله هذا القائل ليس تحته طائل ، لأنه إنما أتى باسمه الكريم لينبه على أنه لا ينبغى أن يقابل الكريم بالأفعال القبيحة ، وأعمال السوء . .والمقصود بالنداء هنا : التنبيه إلى ما سيأتى بعده من توجيهات ، وليس المقصود به طلب الإِقبال على شئ معين .وإيثار تعريف الله - تعالى - بصفة الرب ، لما فى معنى الرب من التربية والرعاية والملكيمة ، والإِيجاد من العدم . . ففى هذا الوصف تذكير للإِنسان بنعم خالقه الذى أنشأه من العدم ، وتعهده بالرعاية والتربية .وكذلك الوصف بالكريم ، فيه - أيضاً - تذكير لهذا الإِنسان بكرم ربه عليه ، إذ مقتضى هذا الكرم منه - تعالى - ، أن يقابل المخلوق ذلك بالشكر والطاعة .","7":"وقوله - سبحانه - : ( الذي خَلَقَكَ فَسَوَّاكَ فَعَدَلَكَ . في أَىِّ صُورَةٍ مَّا شَآءَ رَكَّبَكَ ) صفات أخرى للرب - عز وجل - الكريم المنان .والخلق : هو الإِيجاد على مقدار معين مقصود . والتسوية : جعل الشئ سويا ، أى : قويما سليما خاليا من الاضطراب والاختلال .وقوله : ( فَعَدَلَكَ ) قرأها بعضهم بفتح الدال مع التخفيف ، وقرأها آخرون بفتحها مع التشديد ، وهما متقاربان ، إلا أن التشديد يفيد المبالغة فى التعديل ، الذى هو جعل البنية معتدلة ، متناسبة الأعضاء ، فالتسوية ترجع إلى عدم النقصان فى الأعضاء ، والتعديل يرجع إلى عدم التخالف فيها وهذا ، باعتبار الأصل فى خلق الإِنسان ، فلا عبرة بوجود ما يخالف ذلك فى قلة من أفراد الإِنسان .والمعنى : يأيها الإِنسان ، أى شئ خدعك وجرأك على معصية ربك الكريم . . الذى من مظاهر كرمه أنه ( خَلَقَكَ فَسَوَّاكَ ) بأن جعل أعضاءك سوية سليمة . مهيأة لاكتساب منافعها على حسب ما تقتضيه حكمة خالقك ( فعدلك ) أى : فعدل أعضاؤك بأن جعلها متناسقة متوازنة بعضها مع بعض ، فلم يجعل - مثلا - إحدى يديك طويلة والأخرى قصيرة ، ولم ثيجعل - مثلا - جانباً من جسدك أبيض ، والأخر أسود .ومن مظاهر قدرته وكرمه - أيضاً - أنه - سبحانه - ركبك ووضعك فى أى صورة من الصور المتنوعة التى اقتضتها مشيئته وحكمته .","8":"فقوله : ( في أَىِّ صُورَةٍ ) متعلق بركبك . و \" ما \" مزيدة ، و \" شاء \" صفة لصورة ولم يعطف \" ركبك \" على ما قبله بالفاء ، كما عطف ما قبله بها ، لأنه بيان لقوله ( فَعَدَلَكَ ) . والتقدير : فعلدك بأن ركبك فى أى صورة من الصور التى شاءها لك ، وهى صورة فيها ما فيها من العجائب والأسرار ، فضلا عن أنها أحسن صورة وأكملها ، كما قال - تعالى - : ( لَقَدْ خَلَقْنَا الإنسان في أَحْسَنِ تَقْوِيمٍ ) فالمقصود من الآيات الكريمة ، تذكير الإِنسان بفضل ربه - تعالى - عليه ، وحضه على طاعته وشكره ، وتوبيخه على تقصيره وجحوده ، وتهديده بسوء المصير إذا ما استمر فى غفلته وغروره .قال بعض العلماء : إن خلق الإِنسان على هذه الصورة الجميلة السوية المعتدلة ، الكاملة الشكل والوظيفة . أمر يستحق التدبر الطويل ، والشكر العميق ، والأدب الجم لربه الكريم الذى أكرمه بهذه الخلقة .وهناك مؤلفات كاملة فى وصف كمال التكوين الإِنسان العضوى ودقته وإحكامه .كاكتمال التكوين الجسدى ، والعضلى ، والجلدى ، والهضمى ، والدموى والعظمى ، والتنفسى ، والتناسلى ، والعصبى . . للإِنسان .وإن جزءا من أذن الإِنسان \" الأذن الوسطى \" لهو سلسلة من نحو أربعة آلاف جزئية دقيقة معقدة ، متدرجة بنظام بالغ الدقة فى الحجم والشكل .ومركز حاسة الإِبصار فى العين التى تحتوى على مائة وثلاثين مليونا من مستقبلات الضوء .وهى أطراف الأعصاب ، ويقوم بحمايتها الجفن ذو الأهداب الذى يقيها ليلا ونهارا . .","9":"ثم يكشف القرآن بعد ذلك عن علة الغرور والغفلة - وهى التكذيب بيوم الحساب - ويقرر أن كل عمل يعمله الإِنسان هو مسجل عليه فيقول : ( كَلاَّ بَلْ تُكَذِّبُونَ بالدين . وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ . كِرَاماً كَاتِبِينَ . يَعْلَمُونَ مَا تَفْعَلُونَ ) .و \" كلا \" حرف ردع وزجر ، وهى هنا للردع والزجر عن الاغترار بكرم الله - تعالى - وعن جعله ذريعة إلى الكفر والفسوق والعصيان .وقوله : ( كَلاَّ بَلْ تُكَذِّبُونَ بالدين ) إبطال لوجود ما يدعو إلى غرورهم لو كانوا يعقلون .أى : كلا ليس هناك شئ يقتضى غروركم بالله - تعالى - ويجرؤكم على عصيانه لو كتم تتفكرون وتتدبرون . . ولكن تكذيبهم بالبعث والحساب والجزاء هو الذى حملكم على الكفر والفسوق والعصيان .قال الآلوسى ما ملخصه : قوله ( كلا ) ردع عن الاغترار بكرم الله - تعالى - وقوله : ( كَلاَّ بَلْ تُكَذِّبُونَ بالدين ) إضراب عن جملة مقدرة ، ينساق إليها الكلام ، كأنه قيل بعد الردع بطريق الاعتراض ، وأنتم لا ترتدعون عن ذلك ، بل تجترئحون على أعظم منه ، حيث تكذبون بالجزاء والبعث رأسا ، أو بدين الإِسلام ، اللذين هما من جملة أحكامه ، فلا تصدقون سؤالا ولا جوابا ، ولا ثوابا ولا عقابا ، وفيه ترق من الأهوان إلى الأعظم .وعن الراغب : \" بل \" هنا لتصحيح الثانى وإبطال الأول . كأنه قيل : ليس هنا مقتض لغرورهم ، ولكن تكذيبهم بالبعث حملهم على ما ارتكبوه .وقيل تقدير الكلام : كلا إنكم لا تستقيمون على ما توجبه نعمى إليكم ، وإرشادى لكم ، بل تكذبون بالدين . .","10":"وقوله : ( وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ ) عطف على جملة ( كَلاَّ بَلْ تُكَذِّبُونَ بالدين ) لتأكيد ثبوت الجزاء على الأعمال ، وتسجيل هذه الأعمال تسجيلا تاما .وقوله ( لَحَافِظِينَ ) صفة لموصوف محذوف . أى : وإن عليكم لملائكه يحفظون أعمالكم عليكم ، ويسجلونها دون أن يضيعوا منها شيئا .","11":"وقوله : ( كِرَاماً كَاتِبِينَ . يَعْلَمُونَ مَا تَفْعَلُونَ ) صفات أخرى لهؤلاء الملائكة .أى : وإن عليكم ملائكة من صفاتهم أنهم يحفظون أعمالكم ، ويسجلونها عليكم ، وأنهم لهم عند الله - تعالى - الكرامة والمنزلة الحسنة ، وأنهم يكتبون أعمالكم كلها .","12":"وأنهم يعلمون أفعالكم التى تفعلونها سواء أكانت قليلة أم كثيرة ، صغيرة أم كبيرة .فالمقصود بهذه الآيات الكريمة : بيان أن البعث حق ، وأن الحساب حق ، وأن الجزاء حق ، وأن أعمال الإِنسان عليه تسجيلا تاما ، بواسطة ملائكة لا يعصون الله ما أمرهم ويفعلون ما يؤمرون .أما كيفية هذه الكتابة من الملائكة لأعمال الإِنسان ، وعلى أى شئ تكون هذه الكتابة ، ومتى تكون ههذ الكتابة . . فمن الأمور التى يجب الإيمان بها كما وردت ، مع تفويض كنهها وكيفيتها ودقتها إلى الله - تعالى - لأنه لم يرد حديث صحيح عن المعصوم - صلى الله عليه وسلم يعتمد عليه فى بيان ذلك .","13":"ثم بين - سبحانه - النتائج المترتبة على كتابة الملائكة لأفعال الإِنسان فقال : ( إِنَّ الأبرار لَفِي نَعِيمٍ . وَإِنَّ الفجار لَفِي جَحِيمٍ . يَصْلَوْنَهَا يَوْمَ الدين . وَمَا هُمْ عَنْهَا بِغَآئِبِينَ ) .والأبرار : جمع بر - بفتح الباء - ، وهو الإِنسان التقى الموفى بعهد الله - تعالى - .- أى : إن المؤمنين الصادقين الذين وفوا بما عاهدوا الله عليه ، لفى نعيم دائم ، وهناء مقيم ، وإن الفجار الذين نقضوا عهودهم مع الله ، وفسقوا عن أمره ، لفى نار متأججة بعضها فوق بعض ، هؤلاء الفجار الذين شقوا عصا الطاعة .","14":"والفجار : جمع فاجر ، وهو الإِنسان الكثير الفجور ، أى : الخروج عن طاعة الله - تعالى - أى : إن المؤمنين الصادقين الذين وفوا بما عاهدوا الله عليه ، لفى نعيم دائم ، وهناء مقيم ، وإن الفجار الذين نقضوا عهودهم مع الله ، وفسقوا عن أمره ، لفى نار متأججة بعضها فوق بعض ، هؤلاء الفجار الذين شقوا عصا الطاعة .","15":"( يَصْلَوْنَهَا ) أى : يدخلون الجحيم ويقاسون حرها ( يَوْمَ الدين ) أى : يوم الجزاء والحساب .","16":"( وَمَا هُمْ عَنْهَا بِغَآئِبِينَ ) أى : وما هم عن المنار بمبعدين ، بل هم ملازمون لها ملازمة تامة .","17":"ثم فخم - سبحانه - وعظم من شأن يوم الجزاء فقال : ( وَمَآ أَدْرَاكَ مَا يَوْمُ الدين . ثُمَّ مَآ أَدْرَاكَ مَا يَوْمُ الدين ) .و \" ما \" اسم استفهام مبتدأ . وجملة \" أدراك \" خبره ، والكاف مفعول أول .وجملة ( مَا يَوْمُ الدين ) المكونة من مبتدأ وخبر سدت مسد المفعول الثانى لأدراك والتكرار للتهويل والتعظيم ليوم الدين ، كما فى قوله - تعالى - ( الحاقة . مَا الحآقة . وَمَآ أَدْرَاكَ مَا الحاقة ) أى : وأى شئ أدراك عظم وشدة يوم الحساب والجزاء ، ثم أى شئ أدراك بذلك؟إننا نحن وحدنا الذين ندرك شدة هوله .. وقد أخبرناك بجانب مما يحدث فيه من شدائد لتنذر الناس ، حتى يستعدوا له بالإِيمان والعمل الصالح .","18":"ثم فخم - سبحانه - وعظم من شأن يوم الجزاء فقال : ( وَمَآ أَدْرَاكَ مَا يَوْمُ الدين . ثُمَّ مَآ أَدْرَاكَ مَا يَوْمُ الدين ) .و \" ما \" اسم استفهام مبتدأ . وجملة \" أدراك \" خبره ، والكاف مفعول أول .وجملة ( مَا يَوْمُ الدين ) المكونة من مبتدأ وخبر سدت مسد المفعول الثانى لأدراك والتكرار للتهويل والتعظيم ليوم الدين ، كما فى قوله - تعالى - ( الحاقة . مَا الحآقة . وَمَآ أَدْرَاكَ مَا الحاقة ) أى : وأى شئ أدراك عظم وشدة يوم الحساب والجزاء ، ثم أى شئ أدراك بذلك؟إننا نحن وحدنا الذين ندرك شدة هوله .. وقد أخبرناك بجانب مما يحدث فيه من شدائد لتنذر الناس ، حتى يستعدوا له بالإِيمان والعمل الصالح .","19":"ثم فصل - سبحانه - جانبا من أهواله فقال : ( يَوْمَ لاَ تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئاً والأمر يَوْمَئِذٍ لِلَّهِ ) أى : يوم الدين والجزاء هو اليوم الذى لا تملك فيه نفس لغيرها شيئا من النفع . وإنما الذى ينفع فيه هو الإِيمان والعمل الصالح ، والأمر فيه لله - تعالى - وحده ، ولا سلطان ولا تصرف لأحد سواه .وقوله : ( يَوْمَ لاَ تَمْلِكُ . . . ) بيان ليوم الدين . وقد قرأ بعض القراء السبعة ( يوم ) بالنصب على أنه منصوب بفعل محذوف . أى : اذكر يوم لا تملك نفس لنفس شيئا .وقرأ البعض الآخر بالرفع على أنه خبر لمبتدأ محذوف . أى : هو يوم لا تملك نفس لنفس شيئا . . أو على أنه بدل من \" يوم الدين \" .وهكذا اختتمت السورة الكريمة كما بدئت بالتهويل من شأن يوم القيامة ، ليزداد العقلاء استعداداً له ، عن طريق الإِيمان والعمل الصالح الذى يرضى الله - تعالى - .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"83":{"1":"الويل : لفظ دال على الهلاك أو الشر ، وهو اسم لا فعل له من لفظه . . وقيل : هو اسم واد فى جهنم .و ( المطففين ) جمع مطفف ، من الطفيف ، وهو الشئ التافه الحقير ، لأن ما يغتاله المطفف من غيره شئ قليل . والتطفيف : الإِنقاص فى المكيال أو الميزان عن الحدود المطلوبة .قال الإِمام ابن جرير : وأصل التطفيف ، من الشئ الطفيف ، وهو القليل النزر . والمطفف : المقلل صاحب الحق عَمَّا له من الوفاء والتمام فى الوكيل أو وزن .","2":"ومنه قيل للقوم الذين يكونون سواء فى حسبه أو عدد : هم سواء كطف الصاع . يعنى بذلك كقرب الممتلئ منه ناقص عن الملء . .وقوله : ( اكتالوا ) من الاكتيال وهو افتعال من الكيل . والمراد به : أخذ مالهم من مكيل من غيرهم بحكم الشراء .","3":"ومعنى : ( كَالُوهُمْ أَوْ وَّزَنُوهُمْ ) : كالوهم أو وزنوا لهم ، فحذفت اللام ، فتعدى الفعل إلى المفعول ، فهو من باب الحذف والإِيصال .فالواوان فى ( كَالُوهُمْ أَوْ وَّزَنُوهُمْ ) يعودان إلى الاسم الموصول فى قوله : ( الذين إِذَا اكتالوا ) والضميران المنفصلان \" هم \" ، يعودان إلى الناس .قال صاحب الكشاف : والضمير فى ( كَالُوهُمْ أَوْ وَّزَنُوهُمْ ) ضمير منصوب راجع إلأى الناس . وفيه وجهان : أن يراد : كالوا لهم ، أو وزنوا لهم فحذف الجار ، وأوصل الفعل ، كما فى قول الشاعر :ولقد جنيتك أكمؤا وعساقلا ... ولقد نهيتك عن بنات الأوبربمعنى جنيت لك . وأن يكون على حذف مضاف ، وإقامة المضاف إليه مقامه ، والمضاف هو المكيل أو الموزون . .والمعنى : هلاك شديد ، وعذاب أليم ، للمطففين ، وهم الذين يبخسون حقوق الناس فى حالتى الكيل والوزن وما يشبههما ، ومن مظاهر ذلك أنهم إذا اشتروا من الناس شيئا حرصوا على أن يأخذوا حقوقهم منهم كاملة غير منقوصة ، وإذا باعوا لهم شيئا ، عن طريق الكيل أو الوزن أو ما يشبههما ( يُخْسِرُونَ ) أى : ينقصون فى الكيل أو الوزن .يقال : خسَر فلان الميزان وأخْسَره ، إذا نقصه ، ولم يتممه كما يقتضيه العدل والقسط .وافتتحت السورة الكريمة بلفظ \" الويل \" للإِشعار بالتهديد والتشديد ، والوعيد الأليم لمن يفعل ذلك . وقوله ( ويل ) مبتدأ ، وهو نكرة ، وسوغ الابتداء به كونه دعاء . وخبره \" للمطففين \" .وقال - سبحانه - ( إِذَا اكتالوا عَلَى الناس ) ولم يقل : من الناس . للإِشارة إلى ما فى عملهم المنكر من الاستيلاء والقهر والظلم .وإلى هذا المعنى أشار صاحب الكشاف بقوله : لما كان اكتيالهم من الناس اكتيالا يضرهم ، ويتحامل فيه عليهم ، أبدل \" على \" مكان \" من \" للدلالة على ذلك .ويجوز أن يتعلق \" على \" بيستوفون ، ويقدم المفعول على الفعل لإِفادة الخصوصية . أى : يستوفون على الناس خاصة ، فأما أنفسهم فيستوفون لها .وقال الفراء : \" من \" و \" على \" يعتقبان فى هذا الموضوع ، لأنه حق عليه ، فإذا قال : اكتلت عليك ، فكأنه قال : أخذت ما عليك ، وإذا قال : اكتلت منك ، فكقوله : استوفيت منك ..والتعبير بقوله : ( يستوفون ) و ( يخسرون ) يدل على حرصهم الشديد فيما يتعلق بحقوقهم ، وإهمالهم الشنيع لحقوق غيرهم ، إذ استيفاء الشئ ، أخذه وافيا تاما ، فالسين والتاء فيه للمبالغة .وأما ( يخسرون ) فمعناه إيقاع الخسارة على الغير فى حالتى الكيل والوزن وما يشبههما .","4":"ثم أتبع - سبحانه - هذا التهديد للمطففين . بما يجعل الناس يتعجبون من أحوالهم ، فقال - تعالى - .( أَلا يَظُنُّ أولئك أَنَّهُمْ مَّبْعُوثُونَ . لِيَوْمٍ عَظِيمٍ . يَوْمَ يَقُومُ الناس لِرَبِّ العالمين ) .والهمزة للاستفهام التعجيبى من أحوالهم ، والجملة مستأنفة مسوقة لتفظيع ما فعلوه من بخس الناس أشياءهم . وأدخلت همزة الاستفهام على \" لا \" النافية لزيادة التوبيخ والإِنكار ، حتى لكأن سوء عاقبة التطفيف لا تخطر لهم على بال .والظن هنا مستعمل فى معناه الحقيقى ، وهو اعتقاد الشئ اعتقادا راجحا .وقال - سبحانه - : ( أَلا يَظُنُّ أولئك . . ) ولم يقل : ألا يظنون ، لقصد تمييزهم والتشهير بهم ، زيادة فى ذمهم ، وفى تقبيح أفعالهم .أى : أبلغت الجرأة بهؤلاء المطففين ، أنهم صاروا من بلادة الحس ، ومن فقدان الشعور ، لا يخشون الحساب يوم القيامة ، ولا يخافون العذاب الشديد الذى سينزل بهم ، يوم يقوم الناس من قبورهم استجابة لأمر رب العالمين ، حيث يتلقون جزاءه العادل ، وحكمه النافذ .ووصف - سبحانه - اليوم بالعظم . باعتبار عظم ما يقع فيه من أهوال .وقوله : ( يَوْمَ يَقُومُ الناس لِرَبِّ العالمين ) بدل مما قبله . واللام فى قوله ( لرب ) للتعليل . أى : يقومون لأجل ربوبيته - تعالى - وتلقى حكمه الذى لا يستطيعون الفرار منه . وفى هذا الوصف ما فيه استحضار جلاله - وعظمته - سبحانه - .قال القرطبى : وفى هذا الإِنكار والتعجيب ، وكلمة الظن .","5":"ووصف اليوم بالعظيم .","6":"وقيام الناس فيه الله خاضعين ، ووصف ذاته برب العالمين ، بيان بليغ لعظم الذنب ، وتفاقم الإِثم فى التطفيف ، وفيما كان مثل حاله من الحيف وترك القيام بالقسط والعمل على التسوية والعدل ، فى كل أخذ وإعطاء ، بل فى كل قول وعمل . .هذا ، وقد جاء الأمر بإيفاء الكيل والميزان ، والنهى عن تطفيفهما ، فى آيات كثيرة ، منها قوله - تعالى - : ( وإلى مَدْيَنَ أَخَاهُمْ شُعَيْباً قَالَ ياقوم اعبدوا الله مَا لَكُمْ مِّنْ إله غَيْرُهُ وَلاَ تَنقُصُواْ المكيال والميزان إني أَرَاكُمْ بِخَيْرٍ وإني أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ ) ومنها قوله - سبحانه - : ( وَأَوْفُواْ الكيل والميزان بالقسط لاَ نُكَلِّفُ نَفْساً إِلاَّ وُسْعَهَا ) قال بعض العلماء ما ملخصه : والتصدى لشأن المطففين بهذا الأسلوب فى سورة مكية ، أمر يلفت النظر ، فالسورة المكية عادة توجه اهتمامها إلى أصول العقائد .ومن ثم فالتصدى لهذا الأمر بذاته ، يدل أولا على أن الإِسلام ، كان يواجه فى البيئة المكية ، حالة صارخة من هذا التطفيف يزاولها الكبراء .. الذين يملكون إكراه الناس على ما يريدون فهم \" يكتالون على الناس \" لا من الناس . . فكأن لهم سلطانا على الناس .ويدل - ثانيا - على طبيعة هذا الدين ، وشمول منهجه للحياة الواقعية ، وشئونها العملية ، وإقامتها على الأساس الأخلاقى الأصيل فى طبيعة هذا المنهج الإِلهى القويم . .","7":"ثم زجر - سبحانه - هؤلاء الفاسقين عن أمره زجرا شديدا ، وتوعدهم بالعذاب الشديد ، فقال - تعالى - : ( كَلاَّ إِنَّ كِتَابَ الفجار لَفِي سِجِّينٍ ) .وقوله : ( كلا ) حرف ردع وزجر ، وما بعده كلام مستأنف ، وقد تكرر فى الآيات التى معنا ثلاث مرات ، والمراد به هنا : ردعهم وزجرهم عما كانوا فيه من الشرك ، والتطفيف فى الكيل والميزان .والفجار : جمع فاجر ، وهو مأخوذ من الفجور ، وهو شق الشئ شقا واسعا ، وسمى الفجار بذلك مبالغة فى هتكهم لحرمات الله ، وشقهم لستر الشريعة ، بدون خوف أو وجل . يقال : فجر فلان فجورا فهو فاجر ، وهم فجار وفجرة ، إذا تجاوزوا كل حد أمر الله - تعالى - بالوقوف عنده . والمراد بالكتاب المكتوب . أى : صحيفة الأعمال .والسجِّين : اختلفوا فى معناه على أقوال منها : أنه علم أو وصف لواد فى جهنم ، صيغ بزنة فِعِّيل - بكسر الفاء مع تشديد العين المكسورة - ، مأخوذ من السَّجن بمعنى الحبس . يقال : سجن الحاكم فلانا يسجنه - بضم الجيم - سجنا ، إذا حبسه .قال ابن كثير : قوله : ( كَلاَّ إِنَّ كِتَابَ الفجار لَفِي سِجِّينٍ ) أى : إن مصيرهم ومأواهم لفى سجين - فعيل من السَّجن ، وهو الضيق - ، كما يقال : فلان فسيق وشريب وخمير وسكير ونحو ذلك ، ولهذا عظم أمره فقال : ( وَمَآ أَدْرَاكَ مَا سِجِّينٌ ).","8":"( وَمَآ أَدْرَاكَ مَا سِجِّينٌ ).؟ أى : هو أمر عظيم ، وسجن مقيم ، وعذاب أليم .ثم قد قال قائلون : هو تحت الأرض السابعة . . وقيل : بئر فى جهنم .والصحيح أن \" سجينا \" مأخوذ من السَّجن ، وهو الضيق ، فإن المخلوقات كل ما تسافل منها ضاق ، وكل ما تعالى منها اتسع . . ولما كان مصير الفجار إلى جهنم ، وهى أسفل سافلين .قال - سبحانه - : ( كَلاَّ إِنَّ كِتَابَ الفجار لَفِي سِجِّينٍ ) وهو يجمع الضيق والسفول . .أى : كلا ، ليس الأمر كما يزعم هؤلاء المشركون من أ ، ه لا بعث ولا جزاء ، بل الحق أن البعث أمر واقع ، ماله من دافع ، وأن ما عمله هؤلاء الفجار من كفر ومن تطفيف فى الكيل والميزان ، لمكتوب فى صحائف أعمالهم ، ومسجل عليهم فى ديوان الشر الذى يوصلهم إلى قاع جهنم .وقوله : ( وَمَآ أَدْرَاكَ مَا سِجِّينٌ ) تهويل وتفظيع لهذا الشئ الضيق الذى يؤدى إلى القذف بهم فى أعماق جهنم .وقوله : ( كِتَابٌ مَّرْقُومٌ ) خبر لمبتدأ محذوف يعود إلى \" كتاب الفجار \" والمرقوم : المكتوب كتابة واضحة بينة تشبه الخط . الظاهر فى الثوب المنسوج .يقال : رقم فلان الكتاب ، إذا جعل له رقما ، أى : علامة يعرف بها .أى : وهو - أى : كتاب الفجار - كتاب بين الكتابة ، يفهم صاحبه ما فيه فهما واضحا لا خفاء معه ولا التباس . فقوله : ( كِتَابٌ مَّرْقُومٌ ) بيان وتفسير لكتاب الفجار ، وهو ديوان الشر الجامع لأعمالهم السيئة .","9":"ومنهم من جعل قوله - تعالى - : ( كِتَابٌ مَّرْقُومٌ ) ليس تفسيرا لكتاب الفجار ، وإنما هو تفسير لقوله ( سجين ) .قال الشوكانى ما ملخصه : وسجين هو ما فسره به - سبحانه - من قوله ( وَمَآ أَدْرَاكَ مَا سِجِّينٌ . كِتَابٌ مَّرْقُومٌ ) فأخبر بهذا أنه كتاب مرقوم ، أى : مسطور .ومنهم من جعله بيانا وتفسيرا لكتاب المذكور فى قوله ( إِنَّ كِتَابَ الفجار ) على تقدير : هو كتاب مرقوم ، أى : قد بينت حروفه .والأَوْلَى ما ذكرناه أولا ، ويكون المعنى : إن كتاب الفجار الذين من جملتهم المطففون . . لفى ذلك الكتاب المدون للقبائح ، المختص بالشر ، وهو سجين ، ثم ذكر ما يدل على تهويله ، فقال : ( وَمَآ أَدْرَاكَ مَا سِجِّينٌ ) ثم بينه بقوله : ( كِتَابٌ مَّرْقُومٌ ) .وعلى أية حال ، فالمقصود بيان المصير السئ الذى ينتظر هؤلاء الفجار ، حيث سجلت عليهم أعمالهم فى ديوان الشر الذى يجمع أعمالهم القبيحة ، والتى ستؤدى بهم إلى السجن الدائم ، وإلى العذاب المقيم .","10":"وقوله - سبحانه - : ( وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ ) وعيد وتهديد لأولئك المنكرين للبعث ، والذين من صفاتهم تطفيف الكيل والميزان . أى : هلاك عظيم ، وعذاب أليم ، وسجن دائم فى قاع جهنم ، لأولئك المكذبين ، للبعث والحساب والجزاء .","11":"ثم فصل - سبحانه - هذا التكذيب فقال : ( الذين يُكَذِّبُونَ بِيَوْمِ الدين ) أى : يكذبون بيوم القيامة وما فيه من ثواب وعقاب .","12":"( وَمَا يُكَذِّبُ بِهِ ) أى : بيوم الدين ( إِلاَّ كُلُّ مُعْتَدٍ أَثِيمٍ ) أى : وما يكذب بهذا اليوم إلا كل إنسان متجاوز الحدود المشروعة ، ومبالغ فى ارتكاب الآثام والقبائح .","13":"هذا المكذب بيوم القيامة من صفاته - أيضا - أنه ( إِذَا تتلى عَلَيْهِ آيَاتُنَا قَالَ أَسَاطِيرُ الأولين ) .أى : إذا تقرأ على هذا الكتاب آياتنا الدالة على وحدانيتنا وقدرتنا وصدق رسولنا . . قال هذه الآيات هى من أساطير الأقوام الأولين وترهاتهم وقصصهم المخترعة التى لا أصل لها .فأنت ترى أن هؤلاء المكذبين ، قد وصفهم الله -تعالى - بثلاث صفات هى : الاعتداء على الحق . والمبالغة فى ارتكاب الآثام ، والجرأة فى الافتراء والكذب ، حيث وصفوا القرآن بأنه ليس من عند الله - تعالى - .","14":"ثم بين - سبحانه - الأسباب التى حملتهم على أن يقولوا فى القرآن ما قالوا ، فقال : ( كَلاَّ بَلْ رَانَ على قُلُوبِهِمْ مَّا كَانُواْ يَكْسِبُونِ ) .وقوله : ( بَلْ رَانَ ) قرأه الجمهور بإدغام اللام فى الراء بعد قلبها راء لتقارب مخرجيهما ، وقرأه عاصم بالوقف الخفيف على لام بل والابتداء بكلمة ران بدون إدغام .وقوله : ( كَلاَّ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ ) بيان لسوء مصيرهم يوم القيامة .وكلا هنا تأكيد لسابقتها لزيادة الردع والزجر ، ويصح أن تكون كلا هنا بمعنى حقا .أى : حقا إن هؤلاء الفجار سيكونون يوم القيامة فى حالة احتجاب وامتناع عن رؤية الله - تعالى - وعن رضاه .","15":"قال الآلوسى : \" كلا \" ردع وزجر عن الكسب الرائن ، أو بمعنى حقا \" إنهم \" . أى : هؤلاء المكذبين ( عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُون ) لا يرونه - سبحانه - وهو - وعز وجل - حاضر ناظر لهم ، بخلاف المؤمنين ، فالحجاب : مجاز عن عدم الرؤية ، لأن المحجوب لا يرى ما حجب ، و الحجب المنع ، والكلام على حذف مضاف . أى : عن رؤية ربهم لممنوعن فلا يرونه - سبحانه - .واحتج مالك - رحمه الله - بهذه الآية ، على رؤية المؤمنين له - تعالى - ، من جهة دليل الخطاب ، وإلا فلو حجب الكل لما أغنى هذا التخصيص .وقال الشافعى - رحمه الله - : لما حجب - سبحانه - قوما بالسخط دل على أن قوما يرونه بالرضا . .","16":"وقوله - سبحانه - : ( ثُمَّ إِنَّهُمْ لَصَالُواْ الجحيم . ثُمَّ يُقَالُ هذا الذي كُنتُمْ بِهِ تُكَذِّبُونَ ) .بيان للون آخر من سوء مصيرهم .أى : أن هؤلاء المكذبين سيكونون يوم القيامة محجوبين عن رؤية الله - تعالى - لسخطه عليهم ، وممنوعين من رحمته ، ثم إنهم بعد ذلك لداخلون فى أشد طبقات النار حرا . . ثم يقال لهم بواسطة خزنة جهنم على سبيل التقريع والتأنيب .","17":"هذا هو العذاب الذى كنتم به تكذبون فى الدنيا ، وتقولون لمن يحذركم منه : ( وَيَقُولُونَ متى هذا الوعد إِن كُنتُمْ صَادِقِينَ ) فأنت ترى أن هذه الآيات الكريمة قد اشتملت على أشد ألوان الإِهانة؛ لأنها أخبرت أن هؤلاء المكذبين : محجوبون عن ربهم ، وأنهم مقاسون حر جهنم ، وأنهم لا يقابلون من خزنتها إلا بالتيئيس من الخروج منها ، وبالتأنيب والتقريع .","18":"وكعادة القرآن الكريم فى قرن الترهيب بالترغيب ، والعكس ، ساقت السورة الكريمة بعد ذلك ، ما أعده - سبحانه - للأبرار من خير وفير ، ومن نعيم مقيم ، فقال - تعالى - :( كَلاَّ إِنَّ كِتَابَ الأبرار . . . ) .قوله : ( كلا ) هنا ، تكرير للردع والزجر اسابق فى قوله - تعالى - قبل ذلك : ( إِنَّ كِتَابَ الفجار لَفِي سِجِّينٍ ) لبيان ما يقابل ذلك من أن كتاب الأبرار فى عليين .ولفظ \" عليين \" جمع عِلِّى - بكسر العين وتشديد اللام المكسورة - من العلو . ويرى بعضهم أن هذا اللفظ مفرد ، وأنه اسم للديوان الذى تكتب فيه أعمال الأبرار .قال صاحب الكشاف : وكتاب الأبرار : ما كتب من أعمالهم وعليون : علم لديوان الخير ، الذى دون فيه كل ما عملته الملائكة وصلحاء الثقلين . منقول من جمع \" عِلِّى \" بزنة فِعِّيل - بكسر الفاء والعين المشددة - من العلو ، كسِجِّين من السجن . سمى بذلك إما لأنه سبب الارتفاع إلى أعلى الدرجات فى الجنة ، وإما لأنه مرفوع فى السماء السابعة . . تكريما له وتعظيما . .أى : حقا إن ما كتبته الملائكة من أعمال صالحة للأتقياء الأبرار ، لمثبت فى ديوان الخير ، الكائن فى أعلى مكان وأشرفه .","19":"وقوله - سبحانه - : ( وَمَآ أَدْرَاكَ مَا عِلِّيُّونَ ) تفخيم لشأن هذا الديوان ، وتنويه عظيم بشرفه .","20":"وقوله : ( كِتَابٌ مَّرْقُومٌ ) تفسير لما كتب لهؤلاء الأبرار من خير وبركة ، أى : كتاب الأبرار كتاب واضح بين ، يقرؤه أصحابه بسهولة ويسر ، فتنشرح صدورهم ، وتقر عيونهم .","21":"وقوله - تعالى - ( يَشْهَدُهُ المقربون ) أى : يطلع عليه الملائكة المقربون من الله - تعالى- ، ليكون هذا الاطلاع شهادة لهؤلاء الأبرار ، بأنهم محل رضا الله - تعالى - وتكريمه وثوابه .","22":"ثم بين - سبحانه - حالهم فى الجنة ، بعد بيان ما اشتمل عليه كتابهم من خير وبر فقال - تعالى - : ( إِنَّ الأبرار لَفِي نَعِيمٍ ) أى : لفى نعيم دائم ، لا يحول ولا يزول .","23":"( عَلَى الأرآئك يَنظُرُونَ ) والأرائك : جمع أريكة - بزنة سفينة - وهى اسم للسرير الذى يكون مفروشا فرشا أنيقا جميلا .أى : هم فى نعيم دائم لا يقادر قدره ، وهم - أيضا - يجلسون على السرر المهيأة لجلوسهم تهيئة حسنة ، ينظرون إلى كل ما يدخل البهجة والسرور على نفوسهم .وحذف مفعول \" ينظرون \" لقصد التعميم . أى : ينظرون إلى كل ما يبهج نفوسهم .","24":"( تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النعيم ) أى : تعرف فى وجوههم - أيها الناظر إليهم - البهجة والحسن ، وصلاح البال ، وهناءة العيش .وإضافة النضرة - وهى الجمال الواضح - إلى النعيم - الذى هو بمعنى التنعم والترفه - من إضافة المسبب إلى السبب . وهذه الجملة الكريمة صفة ثالثة من صفات هؤلاء الأبرار .","25":"ثم تأتى الصفة الرابعة المتمثلة فى قوله - تعالى - : ( يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ ) .والرحيق : اسم للخمر الطيبة الصافية الخالية من كل ما يكدر أو يذهب العقل .والمختوم : أى المسدود الذى لم تمسه يد قبل أيدى هؤلاء الأبرار .","26":"وقوله : ( خِتَامُهُ مِسْكٌ ) وقرأ الكسائى ( خاتمه ) والخاتم والختام يتقاربان فى المعنى إلا أن الخاتم الاسم ، والختام المصدر . .واسم الإِشارة فى قوله - تعالى - : ( وَفِي ذَلِكَ فَلْيَتَنَافَسِ المتنافسون ) يعود للرحيق المختوم ، الدال على صلاح بالهم ، وحسن أحوالهم .وأصل التنافس : التغالب فى الشئ النفيس ، وهو الذى تحرص عليه النفوس ، بحيث يبتغيه ويطلبه كل إنسان لنفسه خاصة . يقال : نفس فلان على فلان بهذا الشئ - كفرح - إذا بخل به عليه . أى : ومن أجل الحصول على ذلك الرحيق المختوم ، والنعيم المقيم . . فليرغب الراغبون ، وليتسابق المتسابقون ، وليتنافس المتنافسون فى وجوه الخير . عن طريق المسارعة فى تقديم الأعمال التى ترضى الله - تعالى - .فالمقصود من الآية الكريمة : تحريض الناس وحضهم على تقديم العمل الصالح ، الذى يوصلهم يوم القيامة إلى أعلى الدرجات .","27":"وقوله - سبحانه - : ( وَمِزَاجُهُ مِن تَسْنِيمٍ . عَيْناً يَشْرَبُ بِهَا المقربون ) صفة ثالثة من صفات هذا الرحيق .والمزاج : ما يمزج به الشئ ، ويطلق على الممزوج بالشئ - كما هنا - فهو من إطلاق المصدر على المفعول .والتسنيم : علم لعين فى الجنة مسماة بهذا الاسم ، وهذا اللفظ مصدر سنمه إذا رفعه . يقال : سنم فلان الطعام . إذا جعله كهيئة السنام فى ارتفاعه .قالوا : وسميت هذه العين بهذا الاسم ، لأنها تنبع من مكان مرتفع ، أو لعلو مكانتها .","28":"وقوله : ( عينا ) منصوب على المدح .أى : ومزاج هذا الرحيق وخليطه كائن من ماء لعين فى الجنة ، مرتفعة المكان والمكانة ، هذه العين يشرب منها المقربون إلى الله - تعالى- شرابهم .قال الآلوسى : والباء فى قوله ( بها ) إما زائدة . أى يشربها . أو بمعنى من . أى : يشرب منها ، أو على تضمين يشرب معنى يروى . أى : يشرب راوين بها . أى يروى بها المقربون . .وإلى هنا نجدد أن هذه الآيات الكريمة قد بشرت الأبرار ببشارات متعددة ، بشرتهم بأن صحائف أعمالهم فى أعلى عليين ، وبأنهم فى تعيم مقيم ، وبأنهم ينظرون إلى كل ما يشرح صدورهم ، وبأن الناظر إليهم يرى آثار النعمة والرفاهية على وجوههم ، وبأن شرابهم من خمر طيبة لذيذة الطعم والرائحة .","29":"ثم حكى - سبحانه - جانبا من الرذائل التى كان يفعلها المشركون مع المؤمنين ، وبشر المؤمنين بأن العاقبة الطيبة ستكون لهم . . فقال - تعالى - :( إِنَّ الذين أَجْرَمُواْ . . . ) .قد ذكر المفسرون فى سبب نزول هذه الآيات ، أن بعض المشركين - كأبى جهل والعاص بن وائل - كانوا يستهزئون من فقراء المسلمين كصهيب وعمار بن ياسر .وقوله - سبحانه - ( أَجْرَمُواْ ) من الإِجرام ، وهو ارتكاب الجرم . ويطلق على الإِثم العظيم . والذنب الكبير ، والمراد بإجرامهم هنا : كفرهم بالله - تعالى - واستهزائهم بالمؤمنين . أى : إن الذين ارتكبوا فى دنياهم أقبح الجرائم وأشنعها ، وهم زعماء المشركين ( كَانُواْ ) فى الدنيا ( مِنَ الذين آمَنُواْ يَضْحَكُونَ ) أى : كانوا فى حياتهم يتهكمون بالمؤمنين ، ويسخرون منهم ، ويعتبرونهم الأراذل الذين يجب الابتعاد عنهم .","30":"( وَإِذَا مَرُّواْ بِهِمْ يَتَغَامَزُونَ ) أى : وإذا مر هؤلاء المجرمون بالمؤمنين سخروا منهم ، وتغامزوا فيما بينهم على سبيل الاستهزاء بفقراء المؤمنين .والتغامز : تفاعل من الغمز وهو الإِشارة بالجفون والحواجب على سبيل الطعن والتهكم .أى : يغمز أحدهم الآخر لينبه إلى ما عليه فقراء المسلمين من شظف العيش ، ومن غير ذلك من الأحوال التى لا يرضاها المشركون لجهلهم وغرورهم وبلادة حسهم .","31":"( وَإِذَا انقلبوا إلى أَهْلِهِمُ انقلبوا فَكِهِينَ ) أى : وإذا رجع هؤلاء المجرمون إلى أهلهم من مجالسهم التى كانوا فيها . . رجعوا متلذذين باستخفافهم بالمؤمنين . والسخرية منهم .فهم لإِيغالهم فى الكفر والفسوق والعصيان ، لا يكتفون بالغمز واللمز عندما يرون المؤمنين ، بل يجعلونهم عند عودتهم إلى أهليهم ، مادة تفكههم وضحكهم .فقوله : ( فَكِهِينَ ) جمع فكه ، صفة مشبهة ، وهى قراءة حفص عن عاصم .وقرأ الجمهور ( فاكهين ) اسم فاعل : من فكه - بزنة - فرح - إذا مزح فى كلامه ليضحك أو يضحك غيره .وحذف متعلق \" فكهين \" للعلم به . أى : رجعوا فكهين بسبب حديثهم عن المؤمنين .","32":"وقوله : ( وَإِذَا رَأَوْهُمْ قالوا إِنَّ هؤلاء لَضَالُّونَ ) أى : أن هؤلاء الذين أجرموا ، لا يكتفون بغمز المؤمنين ولمزهم وجعلهم مادة السخرية فى أحاديثهم مع أهليهم .بل إنهم تجاوزوا ذلك ، فهم عندما يرون المؤمنين يقولون عنهم : هؤلاء هم الضالون ، لأنهم تركوا دين آبائهم وأجدادهم ، ودخلوا فى دين آخر .فمرادهم بالضلال : فساد الرأى . وعدم البقاء على دينهم القديم .وهكذا الأشرار يرون أن أهل الحق والتقى فى ضلال .","33":"وجملة : ( وَمَآ أُرْسِلُواْ عَلَيْهِمْ حَافِظِينَ ) جملة حالية من الضمير فى ( قالوا ) .أى : قالوا إن هؤلاء المؤمنين الضالون ، والحال أن هؤلاء المشركين ما أرسلهم الله - تعالى - ليكونوا وكلاء عنه ، حتى يحكموا على هذا الفريق بالضلال . وعلى غيره بالرشاد .فالمقصود بالآية الكريمة : تأنيب الذين أجرموا وتوبيخهم على تصرفاتهم ، لأن الحكم على الغير بالهداية والضلال . هم ليسوا أهلا له إطلاقا؛ لأن الله - تعالى - لم يكلفهم بذلك ، وإنما كلفهم بإتباع الرسول الذى أرسله - سبحانه - لهدايتهم .فحكمهم على المؤمنين بالضلال يدل على نهاية الغرور والجهل .","34":"ثم ببشر الله - تعالى - المؤمنين بما سيكونون عليه يوم القيامة من نعيم فقال : ( فاليوم الذين آمَنُواْ مِنَ الكفار يَضْحَكُونَ . عَلَى الأرآئك يَنظُرُونَ )والفاء فى قوله ( فاليوم ) للسببية ، والمراد باليوم : يوم الجزاء والحساب .أى : فبسبب استهزاء الذين أجرموا من المؤمنين فى الدنيا ، كافأ الله - تعالى - المؤمنين على صبرهم ، بأن جعلهم يوم القيامة يضحكون من الكفار حين يرونهم أذلاء مهانين ، كما كان الكفار يضحكون من المؤمنين فى الدنيا .فالمقصود من الآية الكريمة تسلرية المؤمنين ، وتبشيرهم بأنهم سيأخذون بثأرهم من المشركين عما قريب . . وأنهم - أى : المؤمنين - سيكونون يوم القيامة على سرر قد فرشت بأجمل الفراش .","35":"وأنهم لا ينظرون إلا إلى ما يسرهم ويبهج نفوسهم .","36":"ثم ختم - سبحانه - السورة الكريمة بقوله : ( هَلْ ثُوِّبَ الكفار مَا كَانُواْ يَفْعَلُونَ ) .والاستفهام للتقرير . وقوله : ( ثوب ) من التثويب والإِثابة ، أى المجازاة .يقال : ثوب فلان فلانا وأثابه ، بمعنى جازاه المجازاة اللائقة به .والمعنى : لقد جوزى الكفار بالجزاء المناسب لتهكمهم بالمؤمنين فى الدنيا ، فقد أنزلنا بهم ما يستحقونه من عقاب أليم ، جزاء وفاقا .وجاء الجزاء بأسلوب الاستفهام ، لتأكيد هذا الجزاء ، حتى لكأن المخاطب هو الذى نطق بهذا الجزاء العادل الذى استحقه الكافرون . ولبيان أن عدالة الله - تعالى - تقتص من المعتدين مهما طالت بهم الحياة .والتعبير بثوب - مع أنه أكثر ما يستعمل فى الخير - إنما هو من باب التهكم بهم ، كما فى قوله - تعالى - : ( فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ ) نسأل الله - تعالى - أن يجعلنا من عباده المؤمنين الصادقين .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"84":{"1":"قوله : ( انشقت ) من الانشقاق بمعنى الانفطار والتصدع ، بحيث تتغير هيئتها . ويختل نظامها . كما قال - تعالى - : ( يَوْمَ تُبَدَّلُ الأرض غَيْرَ الأرض والسماوات وَبَرَزُواْ للَّهِ الواحد الْقَهَّارِ ) وانشقاق السماء قد ورد فى آيات متعددة منها قوله - تعالى - : ( وَيَوْمَ تَشَقَّقُ السمآء بالغمام ) وقوله - سبحانه - : ( فَإِذَا انشقت السمآء فَكَانَتْ وَرْدَةً كالدهان )","2":"ومعنى \" أذنت \" : استمعت . يقال : أذن له ، بمعنى استمع له بإصغاء تام - وبابه طرب - وفى الحديث الصحيح : \" ما أذن الله لشئ إذنه لنبى يتغنى القرآن \" ، وقال الشاعر :صمٍّ إذا سمعوا خيرا ذكرتُ به ... وإن ذُكِرْتُ بسوء عندهم أذنواوجملة \" وحقت \" معترضة بين المعطوف والمعطوف عليه . أى : إذا السماء تصدعت واختل نظامها ، واستمعت لأمر ربها استماعاً تاما ، وانقادت لحكمة انقياد العبد لسيده ، وجعلت حقيقة وجديرة بالانقياد والاستماع والطاعة فى جميع الأحوال .","3":"( وَإِذَا الأرض مُدَّتْ ) أى : بسطت وتساوت بحيث صارت فى مستوى واحد ، بدون ارتفاع فى جانب أو انخفاض فى آخر ، كما قال - تعالى - : ( لاَّ ترى فِيهَا عِوَجاً ولا أَمْتاً )","4":"( وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ ) أى : وطرحت ما بداخلها من أجساد ومن كنوز ، ومن غيرهما ، وخلت من ذلك خلوا تاما .","5":"( وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ ) أى : وطرحت ما بداخلها من أجساد ومن كنوز ، ومن غيرهما ، وخلت من ذلك خلوا تاما .","6":"ثم وجه - سبحانه بعد ذلك نداء للإِنسان ، دعاه فيه إلى طاعته وإخلاص العبادة له ، فقال : ( ياأيها الإنسان إِنَّكَ كَادِحٌ إلى رَبِّكَ كَدْحاً فَمُلاَقِيهِ ) والمراد بالإِنسان هنا : جنسه .وأصل الكدح فى كلام العرب : السعى فى سبيل الحصول على الشئ بجد واجتهاد وعناء .مأخوذ من كدح فلان جلده ، إذا خدشه ، ومنه قول الشاعر :وما الدهر إلا تارتان فمنهما ... أموت ، وأخرى أبتغى العيش أكدحُوقول الآخر :ومضت بشاشة كل عيش صالح ... وبقيت أكدح للحياة وأَنْصِبُأى : وبقيت أسعى سعيا حثيثا للحياة ، وأتعب من أجل الحصول على مطالبى فيها .والضمير فى قوله : ( فَمُلاَقِيهِ ) يعود إلى الله - تعالى - ، ويصح أن يعود للكدح ، بمعنى ملاق جزاء هذا الكدح .والمعنى : يأيها الإِنسان إنك اباذل فى حياتك جهدا كبيرا من أجل مطالب نفسك .وإنك بعد هذا الكدح والعناء . . مصيرك فى النهاية إلى لقاء ربك ، حيث يحاسبك على عملك وكدحك . . فقدم فى دنياك الكدح المشروع ، والعمل الصالح .والسعى الحثيث فى طاعته - تعالى - ، لكى تنال ثواب ربك ورضاه .قال ابن كثير : وقوله : ( ياأيها الإنسان إِنَّكَ كَادِحٌ إلى رَبِّكَ كَدْحاً ) أى : ساع إلى ربك سعيا ، وعامل عملا ( فَمُلاَقِيهِ ) ثم إنك ستلقى ما عملت من خير أو شر .ويشهد لذلك ما رواه أبو داود الطيالسى . . عن جابر قال : قال رسول الله صلى الله عليه وسلم : \" قال جبريل : يا محمد ، عش ما شئت فإنك ميت ، وأحبب ما شئت فإنك مفارقه ، واعمل ما شئت فإنك ملاقيه \" .ومن الناس من يعيد الضمير على قوله ( رَبِّكَ ) أى : فملاق ربك فيجازيك بعملك ، ويكافئك على سعيك ، وعلى هذا فكلا القولين متلازم .","7":"ثم فصل - سبحانه - بعد ذلك عاقبة هذا الكدح ، والسعى المتواصل . . فقال - تعالى - : ( فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ . فَسَوْفَ يُحَاسَبُ حِسَاباً يَسِيراً . وَيَنقَلِبُ إلى أَهْلِهِ مَسْرُوراً ) .والمراد بالكتاب هنا : صحيفة العمل التى سجلت فيها حسنات الإِنسان وسيئاته .","8":"والمراد بالحساب اليسير : عرض الأعمال ، مع التجاوز عن الهفوات ، بفضل الله - تعالى - : أى : الناس جميعا يكدحون فى هذه الحياة ، ثم يعودون إلى خالقهم للحساب والجزاء ، فأما من أعطى كتابه بيمينه ، وهم المؤمنون الصادقون فسوف يحاسب من ربه - تعالى - حسابا يسيرا سهلا ، بأن تعرض أعماله على خالقه - تعالى - ثم يكون التجاوز عن المعاصى والثواب على الطاعة ، بدون مناقشة أو مطالبة بعذر أو حجة .","9":"ثم ينقلب هذا الإِنسان بعد ذلك إلى أهله وعشيرته ، مبتهجا مسرورا ، بسبب فضل الله - تعالى - عليه ، ورحمته به .وعبر - سبحانه - عن فوز هذا الإِنسان : بأنه يؤتى كتابه بيمينه ، للإِشعار بأنه من أهل السعادة والتقوى ، فقد جرت العادة أن اليد اليمنى إنما تتناول بها الأشياء الزكية الحسنة . والباء فى قوله ( بيمينه ) للملابسة أو المصاحبة ، أو بمعنى فى .قال الآلوسى : والحساب اليسير : هو السهل الذى لا مناقشة فيه . وفسره صلى الله عليه وسلم بالعرض وبالنظر فى الكتاب ، مع التجاوز ، أخرج الشيخان عن عائشة أن النبى صلى الله عليه وسلم قال : \" ليس أحد يحاسب إلا هلك \" قلت يا رسول الله ، جعلنى الله فداك ، أليس الله - تعالى - يقول ( فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ .فَسَوْفَ يُحَاسَبُ حِسَاباً يَسِيراً ) ، قال : ذلك العرض يعرضون ومن نوقش الحساب هلك \" .وأخرج الإِمام أحمد عن عائشة - أيضا - قالت : \" سمعت رسول الله صلى الله عليه وسلم يقول فى بعض صلاته : \" اللهم حاسبنى حسابا يسيرا \" فلما انصرف قلت له : يا رسول الله ، ما الحساب اليسير؟ قال : \" أن ينظر فى كتابه فيتجاوز له عنه \" \" .","10":"ثم بين - سبحانه - حال الأشقياء ، بعد بيانه لحال السعداء فقال : ( وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَآءَ ظَهْرِهِ . فَسَوْفَ يَدْعُواْ ثُبُوراً . ويصلى سَعِيراً ) . أى : وأما من أعطى صحيفة أعماله - لسوادها وقبح أعمالها - بشماله من وراء ظهره وهو الكافر - والعياذ بالله - قيل تغل يمناه إلى عنقه ، وتجعل شماله وراء ظهره ، على سبيل الإِهانة والإذلال له .","11":"( فَسَوْفَ يَدْعُواْ ثُبُوراً ) أى : فسوف يطلب الهلاك ، بأن ينادى عليه بحسرة وندامة ويقول : أيها الموت أقبل فهذا أوانك ، لتنقذنى مما أنا فيه من سوء .وفى طلبه للهلاك ، وتفضيله على ما هو فيه ، دليل على أن هذا الشقى - والعياذ بالله - قد وصل به الحال السيئ إلى أقصى مداه ، حتى لقد أصبح الهلاك نهاية أمانية ، كما قال الشاعر :كفى بك داء أن ترى الموت شافيا ... وحسب المنايا أن يكن أمانيافالمراد بالدعاء فى قوله ( يَدْعُواْ ثُبُوراً ) النداء . والثبور : الهلاك ، بأن يقول : يا ثبوراه أقبل فهذا أوان إقبالك .","12":"وقوله - تعالى - ( ويصلى سَعِيراً ) بيان للعذاب الذى يحل به . أى : ويدخل النار الشديدة الاشتعال فيتقلب فيها ، ويقاسى حرها .","13":"وقوله - سبحانه - ( إِنَّهُ كَانَ في أَهْلِهِ مَسْرُوراً . إِنَّهُ ظَنَّ أَن لَّن يَحُورَ ) تعليل لما أصابه من سوء . أى : إن هذا الشقى كان فى الدنيا فرحا بطرا بين أهله ، لا يفكر فى عاقبة ، ولا يعمل حسابا لغير ملذاته وشهواته ، وإنه فوق ذلك ( ظن ) أى : أيقن أنه لن يرجع إلى ربه يوم القيامة ، ليحاسبه على أعماله ، ويجازيه بما يستحقه من جزاء .","14":"قال القرطبى : قوله ( إِنَّهُ ظَنَّ أَن لَّن يَحُورَ ) أى : لن يرجع حيا مبعوثا فيحاسب . ثم يثاب أو يعاقب . يقال : حار فلان يحور إذا رجع ، ومنه قول لبيد :وما المرء إلا كالشهاب وضوئه ... يحور رمادا بعد إذ هو ساطعفالحور فى كلام العرب : ومنه قوله صلى الله عليه وسلم \" اللهم إنى أعوذ بك من الحَوْر بعد الكَوْر \" يعنى : من الرجوع إلى النقصان بعد الزيادة . .","15":"وقوله - سبحانه - ( بلى إِنَّ رَبَّهُ كَانَ بِهِ بَصِيراً ) إيجاب لما نفاه ، وإثبات لما استبعده ، وجملة \" إن ربه \" بمنزلة التعليل لما أفادته بلى من إبطال لما نفاه .أى : ليس الأمر كما زعم من أنه لن يبعث ولن يرجع إلى ربه . . بل الحق الذى لا يشوبه باطل ، أن هذا الشقى سيرجع إلى ربه يوم البعث والنشور ، ليجازيه على أعماله ، لأنه - سبحانه - كان - وما زال - عليما بأحوال هذا الشقى وغيره ، إذ لا يخفى عليه - سبحانه - شئ فى الأرض ولا فى السماء .فالمراد بالبصر هنا : العلم التام بأحوال الخلق .","16":"ثم أقسم - سبحانه - ببعض مخلوقاته ، على أن مشيئته نافذة ، وقضاءه لا يرد ، وحكمه لا يتخلف . فقال : ( فَلاَ أُقْسِمُ بالشفق . والليل وَمَا وَسَقَ . والقمر إِذَا اتسق . لَتَرْكَبُنَّ طَبَقاً عَن طَبقٍ ) .والفاء فى قوله ( فَلاَ أُقْسِمُ ) واقعة فى جواب شرط مقدر ، وهى التى يعبر عنها بالفصيحة ، و \" لا \" مزيدة لتأكيد القسم ، وجوابه \" لتركبن \" .والشفق : الحمرة التى تظهر فى الأفق الغربى بعد غروب الشمس ، وهو ضياء من شعاعها ، وسمى شفقا لرقته ، ومنه الشفقة لرقة القلب .أى : أقسم بالحمرة التى تظهر فى الأفق العربى ، بعد غروب الشمس ، وبالليل وما يضمه تحت جناحه من مخلوقات وعجائب لا يعلمها إلا الله - تعالى - وبالقمر إذا ما اجتمع نوره ، وأكتمل ضاؤه ، وصار بدرا متلألئاً .وفى القسم بهذه الأشياء ، دليل واضح على قدرة الله - تعالى - الباهرة ، لأن هذه الأشياء تتغير من حال إلى حال ، ومن هيئة إلى هيئة . . فالشفق حالة تأتى فى أعقاب غروب الشمس ، والليل يأتى بعد النهار ، والقمر يكتمل بعد نقصان . . وكل هذه الحالات الطارئة ، دلائل على قدرة الله - تعالى - .","17":"والوسق : جمع الأشياء ، وضم بعضها إلى بعض . يقال : وسَق الشئَ يسِقُه - كضرب - إذا جمعه فاجتمع ، ومنه قولهم : إبل مستوسقة ، أى : مجتمعة ، وأمر متسق . أى : مجتمع على ما يسر صاحبه ويرضيه .أى : أقسم بالحمرة التى تظهر فى الأفق العربى ، بعد غروب الشمس ، وبالليل وما يضمه تحت جناحه من مخلوقات وعجائب لا يعلمها إلا الله - تعالى - وبالقمر إذا ما اجتمع نوره ، وأكتمل ضاؤه ، وصار بدرا متلألئاً .وفى القسم بهذه الأشياء ، دليل واضح على قدرة الله - تعالى - الباهرة ، لأن هذه الأشياء تتغير من حال إلى حال ، ومن هيئة إلى هيئة . . فالشفق حالة تأتى فى أعقاب غروب الشمس ، والليل يأتى بعد النهار ، والقمر يكتمل بعد نقصان . . وكل هذه الحالات الطارئة ، دلائل على قدرة الله - تعالى - .","18":"واتساق القمر : اجتماع ضيائه ونوره ، وهو افتعال من الوسق . وهو الجمع والضم ، وذلك يكون فى الليلة الرابعة عشرة من الشهر .أى : أقسم بالحمرة التى تظهر فى الأفق العربى ، بعد غروب الشمس ، وبالليل وما يضمه تحت جناحه من مخلوقات وعجائب لا يعلمها إلا الله - تعالى - وبالقمر إذا ما اجتمع نوره ، وأكتمل ضاؤه ، وصار بدرا متلألئاً .وفى القسم بهذه الأشياء ، دليل واضح على قدرة الله - تعالى - الباهرة ، لأن هذه الأشياء تتغير من حال إلى حال ، ومن هيئة إلى هيئة . . فالشفق حالة تأتى فى أعقاب غروب الشمس ، والليل يأتى بعد النهار ، والقمر يكتمل بعد نقصان . . وكل هذه الحالات الطارئة ، دلائل على قدرة الله - تعالى - .","19":"وقوله - سبحانه - ( لَتَرْكَبُنَّ طَبَقاً عَن طَبقٍ ) جواب القسم - كما سبق أن أشرنا - .والمراد بالركوب : الملاقاة والمعاناة ، والخطاب للناس ، والطبق جمع طبقة ، وهى الشئ المساوى لشئ آخر ، والمراد بها هنا : الحالة أو المرتبة ، وعن بمعنى بعد .أى : وحق الشفق ، والمراد بها هنا : الحالة أو المرتبة ، وعن بمعنى بعد .أى : وحق الشفق ، والليل وما وسق ، والقمر إذا اتسق . . لتلاقن - أيها الناس - أحوالا بعد أحوال ، هى طبقات ومراتب فى الشدة ، بعضها أصعب من بعض ، وهى الموت ، وما يكون بعده من حساب وجزاء يوم القيامة .قال الآلوسى ما ملخصه : قوله : ( لَتَرْكَبُنَّ طَبَقاً عَن طَبقٍ ) خطاب لجنس الإِنسان المنادى أولا ، باعتبار شموله لأفراده ، والمراد بالركوب : الملاقاة ، والطبق فى الأصل ما طابق غيره مطلقا .وخص فى العرف بالحال المطابقة لغيرها . . و \" عن \" للمجاوزة ، أو بمعنى \" بعد \" والجار والمجرور متعلق بمحذوف صفة أو حالا من فاعل لتركبن ، والظاهر أن \" طبقا \" منصوب على المفعولية ، أى : لتلاقن حالا كائنة بعد حال ، كل واحدة مطابقة لأختها فى الشدة والهول . . منها ما هو فى الدنيا ، ومنها ما هو فى الآخرة .وقرأ الأخوان - حمزة الكسوائى - وابن كثير ( لتركبن ) بفتح الباء - على أنه خطاب للإِنسان - أيضا - ، ولكن باعتبار اللفظ ، لا باعتبار الشمول .وأخرج البخارى عن ابن عباس أنه خطاب للنبى صلى الله عليه وسلم ، أى : لتركبن - أيها الرسول الكريم - أحوال شريفة بعد أخرى من مراتب القرب . أو مراتب من الشدة بعد مراتب من الشدة ، ثم تكون العاقبة لك . .","20":"والفاء فى قوله - تعالى - بعد ذلك : ( فَمَا لَهُمْ لاَ يُؤْمِنُونَ . وَإِذَا قُرِىءَ عَلَيْهِمُ القرآن لاَ يَسْجُدُونَ ) . لترتيب ما بعدها من الإِنكار والتعجيب على ما قبلها ، و \" ما \" للاستفهام ومن أن المستحق للعبادة هو الله - تعالى - وحده . . فأى شئ يمنع هؤلاء الكافرين من الإِيمان ، مع أن كل الدلائل والبراهين تدعوهم إلى الإِيمان .فالمقصود من الآيتين الكريمتين تعجيب الناس من حال هؤلاء الكافرين الذين قامت أمامهم جميع الأدلة على صدق اللرسول صلى الله عليه وسلم فيما يبلغه عن ربه ، ومع ذلك فهم مصرون على كفرهم وجحودهم وعنادهم .قال الآلوسى : وقد صح عنه صلى الله عليه وسلم أنه سجد عند قراءة هذه الآية ، فقد أخرج مسلم وأبو داود والترمذى . . عن أبى هريرة قال : سجدنا مع رسول الله صلى الله عليه وسلم فى ( إِذَا السمآء انشقت ) وفى ( اقرأ باسم رَبِّكَ . . ) وهى سنة عند الشافعى ، وواجبة عند أبى حنيفة . .أما الإِمام مالك فالرواية الراجحة فى مذهبه ، أن هذه الآية ليست من آيات سجود التلاوة .","21":"وأى : مانع منعهم من السجود والخضوع لله - عند ما يقرأ عليهم القرآن الكريم ، الذى أنزلناه عليك لإِخراجهم من الظلمات إلى النور .فالمقصود من الآيتين الكريمتين تعجيب الناس من حال هؤلاء الكافرين الذين قامت أمامهم جميع الأدلة على صدق اللرسول صلى الله عليه وسلم فيما يبلغه عن ربه ، ومع ذلك فهم مصرون على كفرهم وجحودهم وعنادهم .قال الآلوسى : وقد صح عنه صلى الله عليه وسلم أنه سجد عند قراءة هذه الآية ، فقد أخرج مسلم وأبو داود والترمذى . . عن أبى هريرة قال : سجدنا مع رسول الله صلى الله عليه وسلم فى ( إِذَا السمآء انشقت ) وفى ( اقرأ باسم رَبِّكَ . . ) وهى سنة عند الشافعى ، وواجبة عند أبى حنيفة . .أما الإِمام مالك فالرواية الراجحة فى مذهبه ، أن هذه الآية ليست من آيات سجود التلاوة .","22":"وقوله - سبحانه - : ( بَلِ الذين كَفَرُواْ يُكَذِّبُونَ ) إضرب انتقالى ، من التعجيب من عدم إيمانهم مع ظهور كل الأدلة على وجوب الإِيمان ، إلى الإِخبار عنهم بأنهم مستمرون على كفرهم ، أى : ليس هناك أى مانع الكافرين من الإِيمان ، بعد أن قامت جميع الشواهد على صدق الرسول صلى الله عليه وسلم ، بل الحق أن هؤلاء الكافرين إنما استمروا على كفرهم بسبب عنادهم وحسدهم للرسول صلى الله عليه وسلم على ما آتاه الله - تعالى - من فضله ، وتكذيبهم للحق عناداً وجحوداً .","23":"وقوله - سبحانه - : ( والله أَعْلَمُ بِمَا يُوعُونَ ) كلام معترض بين سابقه ولا حقه ، والمقصود به التهديد والوعيد .ومعنى \" يوعون \" يضمرون ويخفون ويسرون ، وأصل الإِيعاء حفظ الأمتعة فى الوعاء ، يقال : أوعى فلان الزاد والمتاع ، إذا جعله فى الوعاء ، والمراد به هنا : الإِضمار والإِخفاء ، كما فى قوله الشاعر :والشر أخبث ما أوعيت من زاد ... أى : والله - تعالى - أعلم من كل أحد ، بما يضمره هؤلاء الكافرون ، وبما يخفونه فى صدورهم من تكذيب للحق ، ومن جحود للقرآن الكريم ، ومن معاداة للمؤمنين .","24":"وقوله : ( فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ ) تفريع على قوله : ( بَلِ الذين كَفَرُواْ يُكَذِّبُونَ ) .والتبشير : الإِخبار بام يسر ، والمراد به هنا التهكم بهم ، بدليل توعدهم بالعذاب الأليم .","25":"والاستثناء فى قوله - تعالى - : ( إِلاَّ الذين آمَنُواْ وَعَمِلُواْ الصالحات لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ ) استثناء منقطع . أى : هذا هو حال الكافرين ، لكن الذين آمنوا إيمانا حقا ، وقدموا فى دنياهم الأعمال الصالحة ، فلهم فى الآخرة أجر غير مقطوع ، فقوله ( ممنون ) مِنْ مَنَّ : إذا قطع يقال : مننت الحبل إذا قطعته ، أو لهم أجر خالص من شوائب الامتنان ، وهو أن يعطى الإِنسان غيره عطاء ، ثم يتباهى عليه به .نسأ الله - تعالى - أن يجعلنا من عباده المؤمنين الصادقين .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"85":{"1":"قوله - تعالى - ( أَيْنَمَا تَكُونُواْ يُدْرِككُّمُ الموت وَلَوْ كُنتُمْ فِي بُرُوجٍ مُّشَيَّدَةٍ ) أى : ولو كنتم فى قصور عظيمة محصنة .والمراد بها هنا : المنازل الخاصة بالكواكب السيارة ، ومداراتها الفلكية الهائلة ، وهى اثنا عشر منزلا : الحمل ، والثور ، والجوزاء ، والسرطان ، والأسد ، والسنبلة ، والميزان ، والعقرب ، والقوس ، والجدى ، والدول ، والحوت .وسميت بالبروج ، لأنها بالنسبة لهذه الكواكب كالمنازل لساكنيها .قال القرطبى : قوله : ( والسمآء ذَاتِ البروج ) : قسم أقسم الله - عز وجل - به . وفى البروج أربعة أقوال : أحدها : ذات النجوم . والثانى : ذات القصور . . الثالث : ذات الخَلْق الحسن . الرابع : ذات المنازل . . وهى اثنا عشر منزلا . .","2":"وقوله : ( واليوم الموعود ) المقصود به : يوم القيامة ، لأن الله - تعالى - وعد الخلق به ، ليجازى فيه الذين أساءوا بما عملوا ، ويجازى الذين أحسنوا بالحسنى .","3":"وقوله : ( وَشَاهِدٍ وَمَشْهُودٍ ) قسم ثالث ببعض مخلوقاته - تعالى - . والشاهد اسم فاعل من المشاهدة بمعنى الرؤية ، فالشاهد هو الرائى ، أو المشهود عليه بأنه حق .فالمراد بالشاهد : من يحضر ذلك اليوم من الخلائق المبعوثين ، وما يراه فيه من عجائب وأهوال ، من المشاهدة بمعنى الرؤية والحضور ، أو من يشهد فى ذلك اليوم على غيره ، من الشهادة على الخصم .وقد ذكر المفسرون فى معنى هذين اللفظين ، ما يقرب من عشرين وجها .قال صاحب الكشاف وقوله : ( وَشَاهِدٍ وَمَشْهُودٍ ) يعنى : وشاهد فى ذلك اليوم ومشهود فيه . والمراد بالشاهد : من يشهد فيه من الخلائق كلهم . وبالمشهود : ما فى ذلك اليوم من عجائبه . ثم قال : وقد اضطربت أقوال المفسرين فيما ، فقيل : الشاهد والمشهود : محمد صلى الله عليه وسلم ويوم القيامة . وقيل : عيسى وأمته . وقيل : أمة محمد صلى الله عليه وسلم وسائر الأمم . وقيل : يوم التروية ويوم عرفة . وقيل : يوم عرفة ويوم الجمعة . وقيل : الحجر الأسود ، والحجيج . وقيل : الأيام والليالى . وقيل : الحفظة وبنو آدم . .ويبدو لنا أن أقرب الأقوال والصواب : أن المراد بالشاهد هنا : الحاضر فى ذلك اليوم العظيم وهو يوم القيامة ، والرائى لأهواله وعجائبه .وأن المراد بالمشهود : ما يشاهد فى ذلك اليوم من أحوال يشيب لها الولدان .وقال - سبحانه - ( وَشَاهِدٍ وَمَشْهُودٍ ) بالتنكير ، لتهويل أمرهما ، وتفخيم شأنهما .","4":"وقوله - تعالى - ( قُتِلَ أَصْحَابُ الأخدود ) جواب القسم بتقدير اللام وقد .أى : وحق السماء ذات البروج ، وحق اليوم الموعود ، وحق الشاهد والمشهود ، لقد قتل ولعن أصحاب الأخدود ، وطردوا من رحمة الله بسبب كفرهم وبغيهم .والأخدود : وهو الحفرة العظيمة المستطيلة فى الأرض ، كالخندق ، وجمعه أخاديد ، ومنه الخد لمجارى الدمع ، والمخدة : لأن الخد يوضع عليها .ويقال : تخدد وجه الرجل ، إذا صارت فيه التجاعيد . . ومنه قول الشاعر :ووجه كأن الشمس ألقت رداءها ... عليه ، نقى اللون لم يتخددوقيل : إن جواب القسم محذوف ، دل عليه قوله - تعالى - : ( قُتِلَ أَصْحَابُ الأخدود ) كأنه قيل : أقسم بهذه الأشياء إن كفار مكة لملعونون كما لعن أصحاب الأخدود .وأصحاب الأخدود : هم قوم من الكفار السابقين ، حفروا حفرا مستطيلة فى الأرض ، ثم أضرموها بالنار ، ثم ألقوا فيها المؤمنين ، الذين خالفوهم فى كفرهم ، وأبوا إلا إخلاص العبادة لله - تعالى - وحده .","5":"وقوله - سبحانه - : ( النار ذَاتِ الوقود ) بدل اشتمال مما قبله وهو الأخدود .والوقود : اسم لما توقد به النار كالحطب ونحوه . وذات الوقود : صفة للنار .أى : قتل وطرد من رحمة الله أصحاب الأخدود ، الذين أشعلوا فيه النيران ذات اللهب الشديد ، لكى يلقوا المؤمنين فيها .","6":"والظرف فى قوله - تعالى - ( إِذْ هُمْ عَلَيْهَا قُعُودٌ ) متعلق بقوله - تعالى - : ( قتل ) أى : لعنوا وطردوا من رحمة الله ، حين قعدوا على الأخدود ، ليشرفوا على من يعذبونهم من المؤمنين .فالضمير \" هم \" يعود على أولئك الطغاة الذين كانوا يعذبون المؤمنين ويجلسون على حافات الأخدود ليروهم وهم وهم يحرقون بالنار ، أو ليأمروا أتباعهم وزبانيتهم بالجد فى التعذيب حتى لا يتهاونوا فى ذلك .و ( على ) للاستعلاء المجازى : إذ من المعلوم أنهم لا يقعدون فوق النار ، وإنما هم يقعدون حولها ، لإِلقاء المؤمنين فيها .","7":"وجملة ( وَهُمْ على مَا يَفْعَلُونَ بالمؤمنين شُهُودٌ ) فى موضع الحال من الضمير فى قوله : ( إِذْ هُمْ عَلَيْهَا قُعُودٌ ) . أى : أن هؤلاء الطغاة الظالمين ، لم يكتفوا بإشعال النار ، والقعود حولها وهم يعذبون المؤمنين ، بل أضافوا إلى ذلك ، أنهم يشهدون تعذيبهم ، ويرونه بأعينهم على سبيل التشفى منهم ، فقوله ( شهود ) بمعنى حضور ، أو بمعنى يشهد بعضهم لبعض أمام ملكهم الظالم ، بأنهم ما قصروا فى تعذيب المؤمنين ، وهذا الفعل منهم . يدل على نهاية القسوة والظلم ، وعلى خلو قلوبهم من أى رحمة أو شفقة .قال الآلوسى : وقوله : ( وَهُمْ على مَا يَفْعَلُونَ بالمؤمنين شُهُودٌ ) أى : يشهد بعضهم لبعض عند الملك ، بأن أحدا لم يقصر فيما أمر به ، أو يشهدون عنده على حسن ما يفعلون . . أو يشهد بعضهم على بعض بذلك الفعل الشنيع يوم القيامة ، أو يشهدون على أنفسهم بذلك ، كما قال - تعالى - : ( يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِمَا كَانُواْ يَعْمَلُونَ ) .وقيل : \" على \" بمعنى مع . أى : وهم مع ما يفعلون بالمؤمنين من العذاب حضور ، لا يرقون لهم ، لغاية قسوة قلوبهم . .","8":"ثم بين - سبحانه - الأسباب التى حملت هؤلاء الطغاة على إحراق المؤمنين فقال : ( وَمَا نَقَمُواْ مِنْهُمْ إِلاَّ أَن يُؤْمِنُواْ بالله العزيز الحميد . الذي لَهُ مُلْكُ السماوات والأرض والله عَلَى كُلِّ شَيْءٍ شَهِيدٌ ) .والنقمة هنا بمعنى الإِنكار والكراهية . يقال : نقَم فلان هذا الشئ ، - من باب ضرب - إذا كرهه وأنكره .أى : أن هؤلاء الكافرين ما كرهوا المؤمنين ، وما أنزلوا بهم ما أنزلوا من عذاب ، إلا لشئ واحد ، وهو أن المؤمنين أخلصوا عبادتهم لله - تعالى - صاحب العزة التامة ، والحمد المطلق ، والذى له ملك جميع ما فى السموات والأرض ، وهو - سبحانه - على كل شئ شهيد ورقيب ، لا يخفى عليه أمر من أمور عباده ، أو حال من أحوالهم .فالمقصود من هاتين الآيتين الكريمتين ، التعجيب من حال هؤلاء المجرمين ، حيث عذبوا المؤمنين ، لا لشئ إلا من أجل إيمانهم بخالقهم ، وكأن الإِيمان فى نظرهم جريمة تستحق الإِحراق بالنار .وهكذا النفوس عندما يستحوذ عليها الشيطان ، تتحول الحسنات فى نظرها إلى سيئات وقديما قال المنكوسون من قوم لوط - عليه السلام - ( أخرجوا آلَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهمْ أُنَاسٌ يَتَطَهَّرُونَ ) والاستثناء فى قوله : ( إِلاَّ أَن يُؤْمِنُواْ بالله . . . ) استثناء مفصح عن براءة المؤمنين مما يعاب وينكر ، فهو من باب تأكيد المدح بما يشبه الذم كما فى قول القائل :ولا عيب فيهم غير أن سيوفهم ... بهن فلول من قراع الكتائبوشبيه بهذه الآية قوله - تعالى - : ( قُلْ ياأهل الكتاب هَلْ تَنقِمُونَ مِنَّآ إِلاَّ أَنْ آمَنَّا بالله وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَاسِقُونَ ) قال الإِمام ابن كثير : وقد اختلفوا فى أهل هذه القصة من هم؟ فعن على ابن أبى طالب : أنهم أهل فارس حين أراد ملكهم تحليل زواج المحارم ، فامتنع عليه علماؤهم ، فعمد إلى حفر أخدود ، فقذف فيه من أنكر عليه منهم .وعنه أنهم كانوا قوما من اليمن ، اقتتل مؤمنوهم ومشركوهم ، فتغلب مؤمنوهم على كفارهم ، ثم اقتتلوا فغلب الكفار المؤمنين ، فخذا لهم الأخاديد ، وأحرقوهم فيها .ثم ذكر - رحمه الله - بعد ذلك جملة من الآثار فى هذا المعنى فارجع إليها إن شئت .وعلى أية حال فالمقصود بهذه الآيات الكريمة ، تثبيت المؤمنين على ما هم عليه من الإِيمان وتسليتهم عما أصابهم من أعدائهم ، وإعلامهم بأن ما نزل بهم من أذى ، قد نزل ما هو أكبر منه بالمؤمنين السابقين ، فعليهم أن يصبروا كما صبر أسلافهم ، وقد اقتضت سنته - تعالى - أن يجعل العاقبة للمتقين .","9":"ثم بين - سبحانه - الأسباب التى حملت هؤلاء الطغاة على إحراق المؤمنين فقال : ( وَمَا نَقَمُواْ مِنْهُمْ إِلاَّ أَن يُؤْمِنُواْ بالله العزيز الحميد . الذي لَهُ مُلْكُ السماوات والأرض والله عَلَى كُلِّ شَيْءٍ شَهِيدٌ ) .والنقمة هنا بمعنى الإِنكار والكراهية . يقال : نقَم فلان هذا الشئ ، - من باب ضرب - إذا كرهه وأنكره .أى : أن هؤلاء الكافرين ما كرهوا المؤمنين ، وما أنزلوا بهم ما أنزلوا من عذاب ، إلا لشئ واحد ، وهو أن المؤمنين أخلصوا عبادتهم لله - تعالى - صاحب العزة التامة ، والحمد المطلق ، والذى له ملك جميع ما فى السموات والأرض ، وهو - سبحانه - على كل شئ شهيد ورقيب ، لا يخفى عليه أمر من أمور عباده ، أو حال من أحوالهم .فالمقصود من هاتين الآيتين الكريمتين ، التعجيب من حال هؤلاء المجرمين ، حيث عذبوا المؤمنين ، لا لشئ إلا من أجل إيمانهم بخالقهم ، وكأن الإِيمان فى نظرهم جريمة تستحق الإِحراق بالنار .وهكذا النفوس عندما يستحوذ عليها الشيطان ، تتحول الحسنات فى نظرها إلى سيئات وقديما قال المنكوسون من قوم لوط - عليه السلام - ( أخرجوا آلَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهمْ أُنَاسٌ يَتَطَهَّرُونَ ) والاستثناء فى قوله : ( إِلاَّ أَن يُؤْمِنُواْ بالله . . . ) استثناء مفصح عن براءة المؤمنين مما يعاب وينكر ، فهو من باب تأكيد المدح بما يشبه الذم كما فى قول القائل :ولا عيب فيهم غير أن سيوفهم ... بهن فلول من قراع الكتائبوشبيه بهذه الآية قوله - تعالى - : ( قُلْ ياأهل الكتاب هَلْ تَنقِمُونَ مِنَّآ إِلاَّ أَنْ آمَنَّا بالله وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَاسِقُونَ ) قال الإِمام ابن كثير : وقد اختلفوا فى أهل هذه القصة من هم؟ فعن على ابن أبى طالب : أنهم أهل فارس حين أراد ملكهم تحليل زواج المحارم ، فامتنع عليه علماؤهم ، فعمد إلى حفر أخدود ، فقذف فيه من أنكر عليه منهم .وعنه أنهم كانوا قوما من اليمن ، اقتتل مؤمنوهم ومشركوهم ، فتغلب مؤمنوهم على كفارهم ، ثم اقتتلوا فغلب الكفار المؤمنين ، فخذا لهم الأخاديد ، وأحرقوهم فيها .ثم ذكر - رحمه الله - بعد ذلك جملة من الآثار فى هذا المعنى فارجع إليها إن شئت .وعلى أية حال فالمقصود بهذه الآيات الكريمة ، تثبيت المؤمنين على ما هم عليه من الإِيمان وتسليتهم عما أصابهم من أعدائهم ، وإعلامهم بأن ما نزل بهم من أذى ، قد نزل ما هو أكبر منه بالمؤمنين السابقين ، فعليهم أن يصبروا كما صبر أسلافهم ، وقد اقتضت سنته - تعالى - أن يجعل العاقبة للمتقين .","10":"ثم هدد - سبحانه - كفار قريش بسوء المصير ، إذا ما استمروا فى إيذائهم للمؤمنين ، فقال - تعالى - : ( إِنَّ الذين فَتَنُواْ المؤمنين والمؤمنات ثُمَّ لَمْ يَتُوبُواْ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الحريق ) .وقوله : ( فتنوا ) من الفتن ، بمعنى الاختبار والامتحان . تقول : فتنت الذهب بالنار ، أى : أدخلته فى النار لتعلم جودته من رداءته ، والمراد به هنا : والتحريق بالنار .أى : إن الظالمين الذين عذبوا المؤمنين والمؤمنات ، وأحرقوهم بالنار ثم لم يتوبوا إلى الله - تعالى - من ذنوبهم ، ويرجعوا عن تعذيبهم للمؤمنين والمؤمنات ، فلهم فى الآخرة عذاب جهنم ، بسبب إصرارهم على كفرهم وعدوانهم ، ولهم نار أخرى زائدة على غيرها فى الإِحراق .والمراد بالذين فتنوا المؤمنين والمؤمنات : كفار قريش ، كأبى جهل وأمية ابن خلف . وغيرهما ، فقد عذبوا بلالا ، وعمار بن ياسر ، وأباه وأمه سمية .ويؤيد أن المراد بالذين فتنوا المؤمنين والمؤمنات كفار قريش ، قوله - تعالى - : ( ثُمَّ لَمْ يَتُوبُواْ ) لأن هذه الجملة تحريض على التوبة ، وترغيب فيها للكافرين المعاصرين للنبى صلى الله عليه وسلم .ويصح أن يراد بهم جميع من عذبوا المؤمنين والمؤمنات ، ويدخل فيه أصحاب الأخدود ، وكفار قريش دخولا أوليا .وجمع - سبحانه - بين عذاب جهنم لهم ، وبين عذاب الحريق ، لبيان أن العذاب لهم مضاعف ، بسبب طغيانهم وشركهم .","11":"ثم بين - سبحانه - بعد ذلك ما أعده للمؤمنين والمؤمنات من ثواب وعطاه كريم فقال : ( إِنَّ الذين آمَنُواْ وَعَمِلُواْ ) الأعمال ( الصالحات لَهُمْ ) أى : عند ربهم ( جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الأنهار ) أى تجرى من تحت أشجارها وبساتينها الأنهار ( ذَلِكَ ) العطاء هو ( الفوز الكبير ) الذى لا فوز يضارعه أو يقاربه .","12":"ثم ساق - سبحانه - بعد ذلك ، ما يدل على نفاذ قدرته ومشيئته ، حتى يزداد المؤمنون ثباتا على ثباتهم ، وصبرا على صبرهم فقال : ( إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ ) .والبطش : هو الأخذ بقوة وسرعة وعنف . أى : إن بطش ربك - أيها الرسول الكريم - بالظالمين والطغاة لبالغ نهاية القوة والعنف : فمر أصحابك فليصبروا على الأذى ، فإن العاقبة الحسنة ستكون لهم وحدهم .","13":"( إِنَّهُ هُوَ يُبْدِىءُ وَيُعِيدُ ) أى : إنه وحده هو الذى يخلق الخلق أولا فى الدنيا ، ثم يعيدهم إلى الحياة بعد موتهم للحساب والجزاء ، وهو - سبحانه - وحده الذى يبدئ البطش بالكفار فى الدنيا ثم يعيده عليهم فى الآخرة بصورة أشد وأبقى .وحذف - سبحانه - المفعول فى الفعلين ، لقصد العموم ، ليشمل كل ما من شأنه أن يبدأ وأن يعاد من الخلق أو من العذاب أو من غيرهما .","14":"( وَهُوَ الغفور الودود ) أى : وهو - سبحانه - الواسع المغفرة لمن تاب وآمن ، وهو الكثير المحبة والود لمن أطاعه واتبع هداه .","15":"( ذُو العرش المجيد ) أى : وهو - عز وجل - صاحب العرش العظيم ، الذى لا يعرف كنهه إلا هو - سبحانه - ، وهو ( المجيد ) أى : العظيم فى ذاته وصفاته .","16":"( فَعَّالٌ لِّمَا يُرِيدُ ) أى : وهو - تعالى - الذى يفعل كل شئ يريده . دون أن يعترض عليه أحد ، بل فعله هو النافذ ، وأمره هو السارى والمطاع .وجاءت كلمة \" فعال \" بصيغة المبالغة ، للدلالة على أن ما يريده ويفعله - مع كثرته - هو فى غاية النفاذ والسرعة ، كما قال - تعالى - : ( إِنَّمَآ أَمْرُهُ إِذَآ أَرَادَ شَيْئاً أَن يَقُولَ لَهُ كُن فَيَكُونُ ) فهذه الصفة من الصفات الجامعة لعظمته الذاتية ، وعظمة نعمه ومننه وعطاياه .","17":"ثم ساق - سبحانه - بعد ذلك ، ما يدل على شدة بطشه ، ونفاذ أمره فقال : ( هَلُ أَتَاكَ حَدِيثُ الجنود .فِرْعَوْنَ وَثَمُودَ ) .والاستفهام هنا : للتقرير والتهويل . والمراد بالجنود : الجموع الكثيرة التى عتت عن أمر ربها ، فأخذها - سبحانه - أخذ عزيز مقتدر .","18":"وقوله : ( فِرْعَوْنَ وَثَمُودَ ) بدل من الجنود .والمراد بفرعون وثمود : ملؤهما وقومهما الذين آثروا الغى على الرشد ، والضلالة على الهداية ، والباطل على الحق . أى : لقد بلغك - أيها الرسول الكريم - حديث فرعون الذى طغى وبغى ، واتبعه قومه فى طغيانه وبغيه ، وحيديث قوم صالح - عليه السلام - وهم الذين كذبوا نبيهم . وآذوه ، وعقروا الناقة التى نهاهم عن أن يمسوها بسوء .وكيف أنه - سبحانه - قد دمر الجميع تدميرا شديدا ، جزاء كفرهم وبغيهم .وخص - سبحانه - جند فرعون وثمود بالذكر ، لأنهم كانوا أشد من غيرهم بغيا وظلما ، ولأنهم كانت قصصهم معروفة لأهل مكة أكثر من غيرهم .","19":"وقوله : ( فِرْعَوْنَ وَثَمُودَ ) بدل من الجنود .والمراد بفرعون وثمود : ملؤهما وقومهما الذين آثروا الغى على الرشد ، والضلالة على الهداية ، والباطل على الحق . أى : لقد بلغك - أيها الرسول الكريم - حديث فرعون الذى طغى وبغى ، واتبعه قومه فى طغيانه وبغيه ، وحيديث قوم صالح - عليه السلام - وهم الذين كذبوا نبيهم . وآذوه ، وعقروا الناقة التى نهاهم عن أن يمسوها بسوء .وكيف أنه - سبحانه - قد دمر الجميع تدميرا شديدا ، جزاء كفرهم وبغيهم .وخص - سبحانه - جند فرعون وثمود بالذكر ، لأنهم كانوا أشد من غيرهم بغيا وظلما ، ولأنهم كانت قصصهم معروفة لأهل مكة أكثر من غيرهم .","20":"وقوله : ( فِرْعَوْنَ وَثَمُودَ ) بدل من الجنود .والمراد بفرعون وثمود : ملؤهما وقومهما الذين آثروا الغى على الرشد ، والضلالة على الهداية ، والباطل على الحق . أى : لقد بلغك - أيها الرسول الكريم - حديث فرعون الذى طغى وبغى ، واتبعه قومه فى طغيانه وبغيه ، وحيديث قوم صالح - عليه السلام - وهم الذين كذبوا نبيهم . وآذوه ، وعقروا الناقة التى نهاهم عن أن يمسوها بسوء .وكيف أنه - سبحانه - قد دمر الجميع تدميرا شديدا ، جزاء كفرهم وبغيهم .وخص - سبحانه - جند فرعون وثمود بالذكر ، لأنهم كانوا أشد من غيرهم بغيا وظلما ، ولأنهم كانت قصصهم معروفة لأهل مكة أكثر من غيرهم .","21":"وقوله - سبحانه - : ( بَلْ هُوَ قُرْآنٌ مَّجِيدٌ . فِي لَوْحٍ مَّحْفُوظٍ ) إضراب انتقالى آخر ، من بيان شدة تكذيبهم للحق ، إلى بيان القرآن الكريم هو كتاب الله الذى لا يأتيه الباطل من بين يديه ولا من خلفه .أى : ليس الأمر كما قال هؤلاء المشركون فى القرآن من أنه أساطير الأولين . . بل الحق أن هذا القرآن هو كلام الله - تعالى - البالغ النهاية فى الشرف والرفعة والعظمة .","22":"وأنه كائن فى لوح محفوظ من التغيير والتبديل ، ومن وصول الشياطين إليه . ونحن نؤمن بأن القرآن الكريم كائن فى لوح محفوظ ، إلا أننا نفوض معرفة حقيقة هذا اللوح وكيفيته إلى علمه - تعالى - ، لأنه من أمر الغيب الذى تفرد الله - تعالى - بعلمه . . وما قيل فى وصف هذا اللوح لم يرد به حديث صحيح يعتمد عليه .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"86":{"1":"الطارق : اسم فاعل من الطروق . والمراد به هنا : النجم الذى يظهر ليلا فى السماء .قال القرطبى ما ملخصه : الطارق : النجم ، اسم جنس سمى بذلك لأنه يطرق ليلا ، ومنه الحديث : نهى النبى صلى الله عليه وسلم أن يطرق المسافر أهله ليلا . . والعرب تسمى كل قاصد فى الليل طارقا . يقال : طرق فلان ، إذا جاء ليلا . . وأصل الطرق : الدق ، ومنه سميت المطرقة ، فسمى قاصد الليل طارقا ، لاحتياجه فى الوصول إلى الدق .وفى الحديث : \" أعوذ بك من طوارق الليل والنهار ، إلا طارقا يطرق بخير يا رحمن . . \" .","2":"وقوله - تعالى - : ( وَمَآ أَدْرَاكَ مَا الطارق ) تنويه بشأنه إثر تفخيمه بالإِقسام به ، فالاستفهام مستعمل فى تعظيم أمره .وقد جاء التعبير بقوله - تعالى - : ( وَمَآ أَدْرَاكَ . . . ) ثلاث عشرة مرة فى القرآن الكريم ، كلها جاء الخبر بعدها - كما هنا - ، وكما فى قوله - تعالى - ( وَمَآ أَدْرَاكَ مَا سَقَرُ . لاَ تُبْقِي وَلاَ تَذَرُ . لَوَّاحَةٌ لِّلْبَشَرِ ) وكما فى قوله - سبحانه - : ( وَمَآ أَدْرَاكَ مَا يَوْمُ الدين . ثُمَّ مَآ أَدْرَاكَ مَا يَوْمُ الدين . يَوْمَ لاَ تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئاً . . . ) إلا واحدة لم يأت الخبر بعدها ، وهى قوله - تعالى - : ( الحاقة . مَا الحآقة . وَمَآ أَدْرَاكَ مَا الحاقة . . ) أما التعبير بقوله - تعالى - : ( وَمَا يُدْرِيكَ لَعَلَّ الساعة تَكُونُ قَرِيباً ) ( وَمَا يُدْرِيكَ لَعَلَّ الساعة قَرِيبٌ ) ( وَمَا يُدْرِيكَ لَعَلَّهُ يزكى ) قال القرطبى : قال سفيان : كل ما فى القرآن وما أدراك فقد أخبر به ، وكل شئ قال فيه : وما يدريك ، لم يخبر به .","3":"وقوله ( النجم الثاقب ) بيان وتفسير للطارق ، والثاقب . أى : المضئ الذى يثقب الظلام ويخرقه بنوره فينفذ فيه ويبدده .والجملة الكريمة مستأنفة ، وهى جواب عن سؤال مقدر نشأ مما قبله ، كأنه قيل : وما هو الطارق؟ فكان الجواب : هو النجم الثاقب .","4":"وقوله - سبحانه - : ( إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ ) جواب القسم وما بينهما كلام معترض لتفخيم شأن المقسم به . . والحافظ : هو الذى يحفظ ما كلف بحفظه ، لمقصد معين . أى : وحق السماء البديعة الصنع ، وحق النم الذى يطلع فيها فيبدد ظلام الليل ، ما كل نفس من الأنفس إلا وعليها من الملائكة من يحفظ عملها ويسجله ، سواء أكان هذا العمل خيرا أم شرا .قال الإِمام الشوكانى ما ملخصه : قرأ الجمهور بتخفيف الميم فى قوله : لما ، فتكون \" إن \" مخففة من الثقيلة ، فيها ضمير الشأن المقدر ، وهو اسمها ، واللام هى الفارقة - بين \" إن \" النافية ، و \" إن \" المخففة من الثقيلة - وما مزيدة . أى : إن الشأن كل نفس لعليها حافظ .وقرأ ابن عامر وعاصم وحمزة بتشديد الميم فى قوله ( لما ) فتكون \" إن \" نافية ، و \" لما \" بمعنى إلا .أى : ما كل نفس إلا عليها حافظ .والحافظ : هم الحفظة من الملائكة الذين يحفظون عليها عملها وقولها وفعلها . وقيل : الحافظ هو الله - تعالى - وقيل : هو العقل يرشدهم إلى المصالح .والأول أولى لقوله - تعالى - : ( وَيُرْسِلُ عَلَيْكُم حَفَظَةً ) وقوله : ( وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ ) وحفظ الملائكة إنما هو من حفظه - تعالى - . لأنهم لا يحفظون إلا بأمره - عز وجل - .والمقصود من الآية الكريمة : تحقيق تسجيل أعمال الإِنسان عليه ، وأنه سيحاسب عليها وسيجازى عليها بما يستحقه من ثواب أو عقاب .","5":"وبعد أن بين - سبحانه - أن كل نفس عليها حافظ يسجل عليها أعمالها ، أتبع ذلك بأمر الإِنسان بالتفكر فيما ينفعه ، بأن يعتبر بأول نشأته ، وليعلم أن من خلقه من ماء مهين ، قادر على إعادته إلى الحياة مرة أخرى ، فقال - تعالى - : ( فَلْيَنظُرِ الإنسان مِمَّ خُلِقَ . خُلِقَ مِن مَّآءٍ دَافِقٍ . يَخْرُجُ مِن بَيْنِ الصلب والترآئب . . . ) .والفاء فى قوله ( فَلْيَنظُرِ . . . ) للتفريع على ما تقدم ، وهى بمعنى الفصيحة .أى : إذا كان الأمر كما ذكرت لكم - أيها الناس - ، من أن كل نفس عليها حافظ يسجل عليها أقوالها وأفعالها . . فلينظر الإِنسان منكم نظر تأمل وتدبر واعتبار ، وليسأل نفسه من أى شئ عليها أقوالها وأفعالها . . فلينظر الإِنسان منكم نظر تأمل وتدبر واعتبار ، وليسأل نفسه من أى شئ خلق؟ لقد خلقه الله - تعالى - بقدرته ، من ماء متدفق ، يخرج بقوة وسرعة من الرجل ، ليصب فى رحم الأنثى .وهذا الماء الدافق من صفاته أنه يخرج من بين صلب الرجل ، ومن بين ترائب المرأة ، حيث يختلط الماءان ، ويتكون منهما الإِنسان فى مراحله المختلفة بقدرة الله - تعالى - .قال صاحب الكشاف : فإن قلت : ما وجه اتصال قوله : ( فلينظر ) بما قبله؟قلت : وجه اتصاله به أنه لما ذكر أن على كل نفس حافظا ، أتبعه بتوصية الإِنسان بالنظر فى أول أمره . ونشأته الأولى ، حتى يعلم أن من أنشأه قادر على إعادته وجزائه ، فيعمل ليوم الإِعادة والجزاء ، ولا يملى على حافظه إلا ما يسره فى عاقبته .\" مم خلق \" استفهام جوابه : ( خُلِقَ مِن مَّآءٍ دَافِقٍ ) ، والدفق : صَبٌّ فيه دفع .ومعنى \" دافق \" النسبة إلى الدفق الذى هو مصدر دفق ، كالابن والتامر . أو الإِسناد المجازى ، والدفق فى الحقيقة لصاحبه .ولم يقل ماءين لامتزاجهما فى الرحم ، واتحادهما حين ابتدئ فى خلقه . .وقال بعض العلماء : قوله : ( خُلِقَ مِن مَّآءٍ دَافِقٍ ) أى : من ماء ذى دفق . . وكل من منى الرجل . ومنى المرأة ، اللذين يتخلق منهما الجنين ، ذو وفق فى الرحم .","6":"وقوله : ( خُلِقَ مِن مَّآءٍ دَافِقٍ ) جواب الاستفهام فى قوله - سبحانه - ( مِمَّ خُلِقَ ) والمقصود بالاستفهام هنا : الحث والحض على التفكر والتدبر .أى : إذا كان الأمر كما ذكرت لكم - أيها الناس - ، من أن كل نفس عليها حافظ يسجل عليها أقوالها وأفعالها . . فلينظر الإِنسان منكم نظر تأمل وتدبر واعتبار ، وليسأل نفسه من أى شئ عليها أقوالها وأفعالها . . فلينظر الإِنسان منكم نظر تأمل وتدبر واعتبار ، وليسأل نفسه من أى شئ خلق؟ لقد خلقه الله - تعالى - بقدرته ، من ماء متدفق ، يخرج بقوة وسرعة من الرجل ، ليصب فى رحم الأنثى .وهذا الماء الدافق من صفاته أنه يخرج من بين صلب الرجل ، ومن بين ترائب المرأة ، حيث يختلط الماءان ، ويتكون منهما الإِنسان فى مراحله المختلفة بقدرة الله - تعالى - .قال صاحب الكشاف : فإن قلت : ما وجه اتصال قوله : ( فلينظر ) بما قبله؟قلت : وجه اتصاله به أنه لما ذكر أن على كل نفس حافظا ، أتبعه بتوصية الإِنسان بالنظر فى أول أمره . ونشأته الأولى ، حتى يعلم أن من أنشأه قادر على إعادته وجزائه ، فيعمل ليوم الإِعادة والجزاء ، ولا يملى على حافظه إلا ما يسره فى عاقبته .\" مم خلق \" استفهام جوابه : ( خُلِقَ مِن مَّآءٍ دَافِقٍ ) ، والدفق : صَبٌّ فيه دفع .ومعنى \" دافق \" النسبة إلى الدفق الذى هو مصدر دفق ، كالابن والتامر . أو الإِسناد المجازى ، والدفق فى الحقيقة لصاحبه .ولم يقل ماءين لامتزاجهما فى الرحم ، واتحادهما حين ابتدئ فى خلقه . .وقال بعض العلماء : قوله : ( خُلِقَ مِن مَّآءٍ دَافِقٍ ) أى : من ماء ذى دفق . . وكل من منى الرجل . ومنى المرأة ، اللذين يتخلق منهما الجنين ، ذو وفق فى الرحم .","7":"و \" دافق \" اسم فاعل من الدفق ، وهو الصب للشئ بقوة وسرعة ، يقال : تدفق الماء إذا سال باندفاع وسرعة . والمراد به هنا : الماء الذى تخرج من الرجل ويصب فى رحم المرأة .والصلب : يطلق على فقار الظهر بالنسبة للرجل ، والترائب : جمع تربية ، وهى العظام التى تكون فى أعلى صدر المرأة ، ويعبرون عنها بقولهم موضع القلادة من المرأة .أى : إذا كان الأمر كما ذكرت لكم - أيها الناس - ، من أن كل نفس عليها حافظ يسجل عليها أقوالها وأفعالها . . فلينظر الإِنسان منكم نظر تأمل وتدبر واعتبار ، وليسأل نفسه من أى شئ عليها أقوالها وأفعالها . . فلينظر الإِنسان منكم نظر تأمل وتدبر واعتبار ، وليسأل نفسه من أى شئ خلق؟ لقد خلقه الله - تعالى - بقدرته ، من ماء متدفق ، يخرج بقوة وسرعة من الرجل ، ليصب فى رحم الأنثى .وهذا الماء الدافق من صفاته أنه يخرج من بين صلب الرجل ، ومن بين ترائب المرأة ، حيث يختلط الماءان ، ويتكون منهما الإِنسان فى مراحله المختلفة بقدرة الله - تعالى - .قال صاحب الكشاف : فإن قلت : ما وجه اتصال قوله : ( فلينظر ) بما قبله؟قلت : وجه اتصاله به أنه لما ذكر أن على كل نفس حافظا ، أتبعه بتوصية الإِنسان بالنظر فى أول أمره . ونشأته الأولى ، حتى يعلم أن من أنشأه قادر على إعادته وجزائه ، فيعمل ليوم الإِعادة والجزاء ، ولا يملى على حافظه إلا ما يسره فى عاقبته .\" مم خلق \" استفهام جوابه : ( خُلِقَ مِن مَّآءٍ دَافِقٍ ) ، والدفق : صَبٌّ فيه دفع .ومعنى \" دافق \" النسبة إلى الدفق الذى هو مصدر دفق ، كالابن والتامر . أو الإِسناد المجازى ، والدفق فى الحقيقة لصاحبه .ولم يقل ماءين لامتزاجهما فى الرحم ، واتحادهما حين ابتدئ فى خلقه . .وقال بعض العلماء : قوله : ( خُلِقَ مِن مَّآءٍ دَافِقٍ ) أى : من ماء ذى دفق . . وكل من منى الرجل . ومنى المرأة ، اللذين يتخلق منهما الجنين ، ذو وفق فى الرحم .","8":"( يَخْرُجُ مِن بَيْنِ الصلب والترآئب ) أى : يخرج هذا الماء الدافق ، من بين صلب كل واحد منهما ، وترائب كل منهما . أى : أن أعضاء وقوى كل منهما ، تتعاون فى تكوين ما هو مبدأ لتوالد الإِنسان : ماء الرجل وهو المنى ، ومادة المرأة وهى البويضة المصحوبة بالسائل ، المنصبان بدفع وسيلان سريع إلى الرحم عند الاتصال الجنسى . ويسمى الفقهاء هذه المادة منيا وماء . .وقال فضيلة الشيخ ابن عاشور : وأطنب - سبحانه - فى وصف هذا الماء الدافق ، لإِدماج التعليم والعبرة بدقائق التكوين ، ليستيقظ الجاهل الكافر ، ويزداد المؤمن علما ويقينا .ووصف بأنه ( يَخْرُجُ مِن بَيْنِ الصلب والترآئب ) ، لأن الناس لا يتفطنون لذلك . . وهذا من الإِعجاز العلمى فى القرآن ، الذى لم يكن علم به للذين نزل بينهم ، وهو إشارة مجملة ، وقد بينها حديث مسلم عن أم سلمة وعائشة : \" أن رسول الله صلى الله عليه وسلم سئل عن احتلام المرأة فقال : \" تغتسل إذا أبصرت الماء . فقيل له : أترى المرأة ذلك؟ فقال : وهل يكون الشبه إلا من قِبَل ذلك ، إذا علا ماءُ المرأة ماءَ الرجل ، أشبه الولد أخواله ، وإذا علا ماءُ الرجل ماءها ، أشبه عمامه \" \" .وقال صاحب الظلال : ولقد كان هذا سرا مكنونا فى علم الله لا يعلمه البشر ، حتى كان نصف القرن الأخير ، حيث اطعل العلم الحديث على هذه الحقيقة بطريقته ، وعرف أنه فى عظام الظهر الفقارية ، يتكون ماء الرجل . وفى عظام الصدر العلوية يتكون ماء المرأة ، حيث يلتقيان فى قرار مكين . فينشأ منهما الإِنسان . .","9":"وقوله - سبحانه - : ( إِنَّهُ على رَجْعِهِ لَقَادِرٌ . يَوْمَ تبلى السرآئر . فَمَا لَهُ مِن قُوَّةٍ وَلاَ نَاصِر ) . بيان لكمال قدرته - تعالى- وأنه كما أنشأ الإِنسان من ماء مهين ، قادر على إعادته إلى الحياة بعد موته . والضمير فى قوله : ( إنه ) يعود إلى الله - عز وجل - لأن الخالق للإِنسان من ماء دافق هو الله - تعالى - .والضمير فى قوله \" رجعه \" يعود إلى الإِنسان المخلوق .","10":"وقوله : ( تبلى ) من البلاء بمعنى الاختبار والامتحان . ومنه قوله - تعالى - ( إِنَّ هذا لَهُوَ البلاء المبين ) والمراد بقوله ( تبلى ) هنا : الكشف والظهور .و ( السرائر ) جمع سريرة ، وهى ما أسره الإِنسان من أقوال وأفعال ، والظرف \" يوم \" متعلق بقوله : ( رجعه ) .أى : إن الله - تعالى - الذى قدر على خلق الإِنسان من ماء دافق .يخرج من بين الصلب والترائب . . لقادر - أيضا - على إعادة خلق هذا الإِنسان بعد موته ، وعلى بعثه من قبره للحساب والجزاء ، يوم القيامة ، يوم تكشف المكنونات ، وتبدو ظاهرة للعيان ، وترفع الحجب عما كان يخفيه الإِنسان فى دنياه من عقائد ونيات وغيرهما .","11":"وفى هذا اليوم لا يكون للإِنسان من قوة تحميه من الحساب والجزاء ، ولا يكون له من ناصر ينصره من بأس الله - تعالى - أو من مدافع يدافع عنه .","12":"ثم أقسم - سبحانه - مرة أخرى بالسماء على أن القرآن من عنده - تعالى - فقال : ( والسمآء ذَاتِ الرجع . والأرض ذَاتِ الصدع . إِنَّهُ لَقَوْلٌ فَصْلٌ . وَمَا هوَ بالهزل ) .والرجع : المطر . وسمى بذلك لأنه يجئ ويرجع ويتكرر ، وقيل : الرجع هنا : الشمس والقمر والنجوم ، يرجعن فى السماء حيث تطلع من ناحية ، وتغيب فى الأخرى .وقيل : المراد بالرجع : الملائكة ، لأنهم يرجعون إليها حاملين أعمال العباد .","13":"والصدع : الشق والانفطار ، يقال : تصدع الشئ ، إذا تشقق . . والمراد به هنا : ما تتشقق عنه الأرض من نبات . كما قال - تعالى - : ( أَنَّا صَبَبْنَا المآء صَبّاً . ثُمَّ شَقَقْنَا الأرض شَقّاً . فَأَنبَتْنَا فِيهَا حَبّاً . وَعِنَباً وَقَضْباً ) أى : وحق السماء صاحبة المطر الذى ينزل من جهتها مرة فأخرى ، لنفع العباد والحيوان والنبات . . وحق الأرض ذات النبات البازغ من شقوقها .","14":"( إنه ) أى : هذا القرآن ( لَقَوْلٌ فَصْلٌ ) أى : لقول فاصل بين الحق والباطل ، والهدى والضلال . والغى والرشاد . . وقد بلغ النهاية فى ذلك حتى لكأنه نفس الفصل .","15":"( وَمَا هوَ بالهزل ) أى : وأن هذا القرآن ، ليس فيه شائبة من شوائب الهزل أو اللعب أو المزاح . بل هو جد كله ، فيجب على كل عاقل ، أن يتبع هداه ، وأن يستجيب لأمره ونهيه .وفى هذه الآيات الكريمة رد بليغ ، على أولئك المشركين الجاهلين ، الذين وصفوا القرآن ، بأنه نزل على الرسول صلى الله عليه وسلم ليهزل به ، لأنه يخبرهم بأن الأموات سيعادون إلى الحياة مرة أخرى ، وذلك أمر تستبعده نفوسهم المطموسة .وفى قوله - تعالى - : ( والسمآء ذَاتِ الرجع . والأرض ذَاتِ الصدع ) مقابلة لطيفة ، حيث وصف - سبحانه - السماء والأرض بما ينسابهما ، وبما يشير إلى أن البعث حق ، لأنه كما ينزل المطر من السماء فيحيى الأرض بعد موتها . كذلك يحيى الله - تعالى - بقدرته الأجساد بعد موتها ، وعاد الضمير فى قوله ( إنه ) إلى القرآن - مع أنه لم يسبق له ذكر - لأنه معلوم من المقام .","16":"ثم ختم - سبحانه - السورة الكريمة ، بتسلية الرسول صلى الله عليه وسلم وبتبشيره بحسن العاقبة فقال - تعالى - : ( إِنَّهُمْ يَكِيدُونَ كَيْداً . وَأَكِيدُ كَيْداً . فَمَهِّلِ الكافرين أَمْهِلْهُمْ رُوَيْداً ) وقوله : ( رُوَيْداً ) تصغير \" رُودِ \" بزنة عود - من قولهم : فلان يمشى على ورد ، أى : على مهل ، وأصله من رادت الريح ترود ، إذا تحركت حركة ضعيفة .والكيد : العمل على إلحاق الضرر بالغير بطريقة خفية ، فهو نوع من المكر .والمراد به بالنسبة لهؤلاء المشركين : تكذيبهم الرسول صلى الله عليه وسلم ، ولما جاء به من عند ربه ، فكيدهم مستعمل فى حقيقته .والمراد بالنسةب لله - تعالى - : إمهالهم واستدراجهم ، حتى يأخذهم أخذ عزيز مقتدر ، فى الوقت الذى يختاره ويشاؤه .أى : إن هؤلاء المشركين يحيكون المكايد لإِبطال أمرك - أيها الرسول الكريم - ، وإنى أقابل كيدهم ومكرهم بما يناسبه من استدراج من حيث لا يعلمون ، ثم آخذهم أخذ عزيز مقتدر ، فتمهل - أيها الرسول الكريم - مع هؤلاء المشركين ، ولا تستعجل عقابهم . وانتظر تدبيرى فيهم ، وأمهلهم وأنظرهم \" رويدا \" أى : إمهالا قريبا أو قليلا ، فإن كل آت قريب ، وقد حقق - سبحانه - لنبيه وعده بأن جعل العاقبة له ولأتباعه .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم .","17":"ثم ختم - سبحانه - السورة الكريمة ، بتسلية الرسول صلى الله عليه وسلم وبتبشيره بحسن العاقبة فقال - تعالى - : ( إِنَّهُمْ يَكِيدُونَ كَيْداً . وَأَكِيدُ كَيْداً . فَمَهِّلِ الكافرين أَمْهِلْهُمْ رُوَيْداً ) وقوله : ( رُوَيْداً ) تصغير \" رُودِ \" بزنة عود - من قولهم : فلان يمشى على ورد ، أى : على مهل ، وأصله من رادت الريح ترود ، إذا تحركت حركة ضعيفة .والكيد : العمل على إلحاق الضرر بالغير بطريقة خفية ، فهو نوع من المكر .والمراد به بالنسبة لهؤلاء المشركين : تكذيبهم الرسول صلى الله عليه وسلم ، ولما جاء به من عند ربه ، فكيدهم مستعمل فى حقيقته .والمراد بالنسةب لله - تعالى - : إمهالهم واستدراجهم ، حتى يأخذهم أخذ عزيز مقتدر ، فى الوقت الذى يختاره ويشاؤه .أى : إن هؤلاء المشركين يحيكون المكايد لإِبطال أمرك - أيها الرسول الكريم - ، وإنى أقابل كيدهم ومكرهم بما يناسبه من استدراج من حيث لا يعلمون ، ثم آخذهم أخذ عزيز مقتدر ، فتمهل - أيها الرسول الكريم - مع هؤلاء المشركين ، ولا تستعجل عقابهم . وانتظر تدبيرى فيهم ، وأمهلهم وأنظرهم \" رويدا \" أى : إمهالا قريبا أو قليلا ، فإن كل آت قريب ، وقد حقق - سبحانه - لنبيه وعده بأن جعل العاقبة له ولأتباعه .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"87":{"1":"افتتحت السورة الكريمة ، بأمر النبى صلى الله عليه وسلم بالمداومة على تنزيه الله - تعالى - عن كل نقص ، ويدخل فى هذا الأمر ، كل من يصلح للخطاب . والاسم لمراد به الجنس ، فيشمل جميع أسمائه - تعالى - .أى : نزه - أيها الرسول الكريم - أسماء ربك الأعلى عن كل ما لا يليق بها ، فلا تطلقها على غيره - تعالى - إذا كان خاصة به ، كلفظ الجلالة ، وكلفظ الرحمن ، ولا تذكرها فى موضع لا يتناسب مع جلالها وعظمتها ، ولا تحرفها عن المعانى التى وضعت لها كما يفعل الزائغون . فقد قال - تعالى - : ( وَللَّهِ الأسمآء الحسنى فادعوه بِهَا وَذَرُواْ الذين يُلْحِدُونَ في أَسْمَآئِهِ سَيُجْزَوْنَ مَا كَانُواْ يَعْمَلُونَ ) ونزه ربك الأعلى ، عن الشريك ، وعن الوالد ، وعن الولد ، وعن الشبيه . . وعن كل ما لا يليق به .قال الجمل : أى : نزه ربك عن كل ما لا يليق به ، فى ذاته ، وصفاته ، وأسمائه ، وأفعاله ، وأحكامه . أما فى ذاته : فأن تعتقد أنها ليست من الجواهر والأعراض . وأما فى صفاته : فإن تعتقد أنها لسيت محدثة ولا متناهية ولا ناقصة . وأما فى أفعاله : فأن تعتقد أنه - سبحانه - مطلق لا اعتراض لأحد عليه فى أمر من الأمور . وأما فى أسمائه : فأن لا تذكره - سبحانه - إلا بالأسماء التى لا توهم نقصا بوجه من الوجوه . . وأما فى أحكامه : فإن تعلم أنه ما كلفنا لنفع يعود عليه ، بل لمحض المالكية . .أخرج الإِمام أحمد عن عامر بن عقبة الجهنى قال : \" لما نزلت : ( فَسَبِّحْ باسم رَبِّكَ العظيم ) قال لنا رسول الله صلى الله عليه وسلم : \" اجعلوها فى ركوعكم \" فلما نزلت : ( سَبِّحِ اسم رَبِّكَ الأعلى ) قال : \" اجعلوها فى سجودكم \" \" .","2":"ثم وصف - سبحانه - ذاته بعد وصفه بالأعلى بصفات كريمة أخرى فقال : ( الذي خَلَقَ فسوى ) أى : خلق كل شئ فسوى خلقه تسوية ، ولم يأت به متفاوتا غير ملتئم ، ولكن على إحكام واتساق ، ودلالة على أنه صادر عن عالم ، وأنه صنعه حكيم . .","3":"( والذي قَدَّرَ فهدى ) والتقدير : وضع الأشياء فى مواضعها الصحيحة ، بمقدار معين ، وبكيفية معينة . . تقتضيها الحكمة ، ويقرها العقل السليم .وقوله : ( فهدى ) من الهداية . بمعنى الإِرشاد والدالالة على طريق الخبر والبر . أى : وهو - سبحانه - الذى جعل الأشياء على مقادير مخصوصة فى أجناسها ، وفى أنواعها ، وفى أفرادها . وفى صفاتها وأفعالها . . وهدى كل مخلوق إلى ما ينبغى له طبعا واختيارا ، ووجهه إلى الوظيفة التى خلقه من أجلها ، بأن أوجد فيه العقل والميول والإِلهامات والغرائز والدوافع التى تعينه على أداء تلك الوظيفة .وحذف - سبحانه - المفعول فى قوله : ( الذي خَلَقَ فسوى .والذي قَدَّرَ فهدى ) للعموم ، لأن هذه الأفعال تشمل جميع مخلوقاته - عز وجل - .قال الآلوسى : ( والذي قَدَّرَ . . ) أى : جعل الأشياء على مقادير مخصوصة . . ( فهدى ) أى : فوجه كل واحد منها إلى ما يصدر عنه ، وينبغى له . . فلو تتبعت أحوال النباتات والحيوانا ، لرأيت فى كل منهما ما تحار فيه العقول ، وتضيق عنه دفاتر النقول .وأما فنون هداياته - سبحانه - للإِنسان على الخصوص ، ففوق ذلك بمراحل . . وهيهات أن يحيط بها فلك العبارة والتحرير ، ولا يعلمها إلا اللطيف الخبير .أتزعم أنك جرم صغير ... وفيك انطوى العالم الأكبروقد فصل بعض العلماء الحديث عن مظاهر تقديره وهدايته - سبحانه - فقال : قوله - تعالى - : ( الذي خَلَقَ فسوى . والذي قَدَّرَ فهدى ) أى : الذى خلق كل شئ فسواه ، فأكمل صنعته ، وبلغ به غاية الكمال الذى يناسبه ، والذى قدر لكل مخلوق وظيفته وطريقته وغايته ، فهداه إلى ما خلقه لأجله ، وألهمه غاية وجوده ، وقدر له ما يصلحه مدة بقائه ، وهداه إليه . وهذه الحقيقة الكبرى ماثلة فى كل شئ فى هذا الوجود ، ويشهد بها كل شئ فى رحاب هذا الكون ، من الكبير إلى الصغير .فالطيور لها غريزة العودة إلى الوطن . . دون أن تضل عنه مهما بعد ، والنحلة تهتدى إلى خليتها ، مهما طمست الريح فى هبوبها على الأعشاب والأشجار كل دليل يرى . .وسمك \" السلمون \" الصغير ، يمضى سنوات فى البحر ، ثم يعود إلى نهره الخاص به . .","4":"وقوله - سبحانه - : ( والذي أَخْرَجَ المرعى . فَجَعَلَهُ غُثَآءً أحوى ) بيان لمظهر آخر من مظاهر قدرته - تعالى - ، التى لا يعجزها شئ .والمرعى : النبات الذى ترعاه الحيوانات ، وهو اسم مكان للأرض الذى يوجد فيها النبات .أى : وهو - سبحانه - وحده ، الذى أنبت النبات الذى ترعاه الدواب ، حالة كون هذا النبات أخضر رطبا . ثم يحوله بقدرته - تعالى - بعد حين إلى نبات يابس جاف .وهذا من أكبر الأدلة المشاهدة ، على أنه - تعالى - يتصرف فى خلقه كما يشاء ، فهو القادر على تحويل الزرع الأخضر إلى زرع يابس جاف ، كما أنه قادر على إحياء الإِنسان بعد موته .فالمقصود من هذه الآيات الكريمة ، الإِرشاد إلى كمال قدرته ، وتنوع نعمه - سبحانه - ، حتى يزداد المؤمنون إيمانا على إيمانهم ، وحتى يعود الكافرون إلى رشدهم بعد هذا البيان الواضح الحكيم .","5":"والغثاء : هو اليابس الجاف من النبات الذى ترعاه المواشى .والأحوى : أى : المائل إلى السواد ، مأخوذ من الحُوَّة - بضم الحاء مع تشديد الواو المفتوحة - وهى لون يكون بين السواد والخضرة أو الحمرة . ووصف الغثاء بأنه أحوى ، لأنه إذا طال عليه الزمن ، وأصابته المياه ، اسود وتعفن فصار أحوى .أى : وهو - سبحانه - وحده ، الذى أنبت النبات الذى ترعاه الدواب ، حالة كون هذا النبات أخضر رطبا . ثم يحوله بقدرته - تعالى - بعد حين إلى نبات يابس جاف .وهذا من أكبر الأدلة المشاهدة ، على أنه - تعالى - يتصرف فى خلقه كما يشاء ، فهو القادر على تحويل الزرع الأخضر إلى زرع يابس جاف ، كما أنه قادر على إحياء الإِنسان بعد موته .فالمقصود من هذه الآيات الكريمة ، الإِرشاد إلى كمال قدرته ، وتنوع نعمه - سبحانه - ، حتى يزداد المؤمنون إيمانا على إيمانهم ، وحتى يعود الكافرون إلى رشدهم بعد هذا البيان الواضح الحكيم .","6":"ثم بين - سبحانه - جانبا من مظاهر فضله على نبيه صلى الله عليه وسلم فقال : ( سَنُقْرِئُكَ فَلاَ تنسى .إِلاَّ مَا شَآءَ الله إِنَّهُ يَعْلَمُ الجهر وَمَا يخفى ) .والنسيان : زوال ما كان موجودا فى حافظة الإِنسان . والاستثناء مفرغ من أعم المفاعيل . ومفعول المشيئة محذوف . جريا على غالب استعماله فى كلام العرب . .أى : سنقرئك - أيها الرسول الكريم - القرآن على لسان أمين وحينا جبريل - عليه السلام - وسنجعلك حافظا وواعيا لما سيقرؤه جبريل عليك ، بحيث لا تنساه فى وقت من الأوقات ، أو فى حال من الأحوال ، إلا فى الوقت أو فى الحال الذى يشاء الله - تعالى - أن ينسيك شيئا من ذلك . فإنك ستنساه بأمره - تعالى - لأنه وحده - عز وجل - وهو العليم بما كان ظاهرا من الأشياء ، وبما كان خافيا منها .فالمقصود من هاتين الآيتين : وعد الله - تعالى - لنبيه صلى الله عليه وسلم ببيان أنه - سبحانه - كما أنه قادر على أن يقرئ الرسول صلى الله عليه وسلم قراءة لا ينساها ، فهو أيضا قادر على أن يزل من صدره ما يشاء إزلته ، عن طريق النسيان لما حفظه .فالمراد بهذا الاستثناء : بيان أنه - تعالى - لو أراد أن يصير الرسول صلى الله عليه وسلم ناسيا للقرآن لقدر على ذلك ، كما قال - سبحانه - ( وَلَئِن شِئْنَا لَنَذْهَبَنَّ بالذي أَوْحَيْنَا إِلَيْكَ . . . ) إذ هو - تعالى - على كل شئ قدير ، ولكنه لم يشأ ذلك فضلا منه وكرما .قال الإِمام الشوكانى ما ملخصه : قوله : ( سَنُقْرِئُكَ فَلاَ تنسى ) أى : سنجعلك قارئا بأن نلهمك القراءة . فلا تنسى ما تقرؤه ، والجملة مستأنفة لبيان هدايته صلى الله عليه وسلم الخاصة ، بعد بيان الهداية العامة ، وهى هدايته صلى الله عليه وسلم لحفظ القرآن .","7":"وقوله : ( إِلاَّ مَا شَآءَ الله ) استثناء مفرغ من أعم المفاعيل ، أى : لا تنسى مما تقرؤه شيئا من الأشياء ، إلا ما شاء الله أن تنساه ، وهو لم يشأ - سبحانه - أن ينسى النبى صلى الله عليه وسلم شيئا كقوله - تعالى - ( خَالِدِينَ فِيهَا مَا دَامَتِ السماوات والأرض إِلاَّ مَا شَآءَ رَبُّكَ ) وقيل : \" لا \" فى قوله ( فَلاَ تنسى ) للنهى ، والألف مزيدة لرعاية الفاصلة ، كما فى قوله - تعالى - : ( فَأَضَلُّونَا السبيلا ) يعنى : فلا تغفل عن قراءته .وقال الإِمام الرازى : وهاتان الآيتان تدلان على المعجزة من وجهين :أحدهما : أن رسول صلى الله عليه وسلم كان أميا ، فحفظه لهذا الكتاب المطول عن غير دراسة ، ولا تكرار ، ولا كتبة ، خارق للعبادة فيكون معجزا . وثانيهما : أن هذه السورة من أوائل ما نزل بمكة . فهذا إخبار عن أمر عجيب غريب مخالف للعادة . سيقع فى المستقبل ، وقد وقع ، فكان هذا إخبارا عن الغيب ، فيكون معجزا . .","8":"وقوله - سبحانه - : ( وَنُيَسِّرُكَ لليسرى ) معطوف على قوله ( سَنُقْرِئُكَ ) وجملة : ( إِنَّهُ يَعْلَمُ الجهر وَمَا يخفى ) معترضة .والتيسير بمعنى التسهيل والتخفيف ، وهو جعل العمل يسيرا على عامله بأن يهيئ الله - تعالى - للعامل الأسباب التى تهون له العسير ، وتقرب له البعيد .واليسرى : مؤنث الأيسر ، بمعنى الأسهل ، والموصوف محذوف .والمعنى : سنجعلك - أيها الرسول الكريم - صاحب ذاكرة قوية تحفظ القرآن ولا تنساه . وسنوفقك توفيقا دائما للطريقة اليسرى فى كل باب من أبواب الدين : علما وعملا ، واهتداء وهداية - وسنرزقك الأمور الحسنة التى تجعلك تعيش سعيدا فى دنياك ، وظافرا برضواننا فى أخراك .ولقد أنجز الله - تعالى - لنبيه صلى الله عليه وسلم وعده ، حيث أعطاه شريعة سمحة ، ومنحه أخلاقا كريمة ، من مظاهرها أنه صلى الله عليه وسلم ما خير بين الأمرين إلا اختار أيسرهما ، ودعا أتباعه إلى الأخذ بمبدأ التيسير ، فقال : \" يسروا ولا تعسروا ، وبشروا ولا تنفروا . . \" .فهاتان بشارتان عظيمتان للرسول صلى الله عليه وسلم أولاهما : تتمثل فى إلهامه الذاكرة الواعية الحافظة لما يوحى إليه . وثانيتهما : توفيقه صلى الله عليه وسلم إلى الشريعة اليسرى ، وإلى الأخلاق الكريمة وإلى الأخذ بما هو أرفق وأيسر فى كل أحواله .","9":"ثم أمره - تعالى - بدوام التذكير بدعوة الحق بدون إبطاء أو يأس فقال : ( فَذَكِّرْ إِن نَّفَعَتِ الذكرى سَيَذَّكَّرُ مَن يخشى . وَيَتَجَنَّبُهَا الأشقى . الذى يَصْلَى النار الكبرى . ثُمَّ لاَ يَمُوتُ فِيهَا وَلاَ يَحْيَا ) .والفاء فى قوله ( فذكر ) للتفريع على ما تقدم ، والأمر مستعمل هنا فى طلب المداومة على التذكير بدعوة الحق التى أرسله - سبحانه - بها ، والذكرى : بمعنى التذكير .والمعنى : إذا كان الأمر كما أخبرناك - أيها الرسول الكريم - فداوم على تذكير الناس بالهدى ودين الحق ، واتبع فى ذلك الحكمة والموعظة الحسنة والمجادلة بالتى هى أحسن اهتم فى تذكيرك بمن تتوقع منهم قبول دعوتك ، وأعرض عن الجاحدين والمعاندين والجاهلين .قال صاحب الكشاف : فإن قلت : كان الرسول صلى الله عليه وسلم مأمورا بالذكرى نفعت أو لم تنفع . . فما معنى اشتراط النفع؟ . .قلت : هو على وجهين : أحدهما . أن رسول الله صلى الله عليه وسلم قد استفرغ مجهوده فى تذكيرهم ، وما كانوا يزيدون على زيادة الذكرى إلا عتوا وطغيانا ، وكان النبى صلى الله عليه وسلم يتلظى حسرة وتلهفا ، ويزداد جدا فى تذكيرهم ، وحرصا عليه ، فقيل له : ( وَمَآ أَنتَ عَلَيْهِمْ بِجَبَّارٍ فَذَكِّرْ بالقرآن مَن يَخَافُ وَعِيدِ ) وذلك بعد إلزام الحجة بتكرير التذكير .والثانى : أن يكون ظاهره شرطا ، ومعناه ذَمّاً للمذكِّرين - بتشديد الكاف المفتوحة - وإخبارا عن حالهم ، واستبعادا لتأثير الذكرى فيهم ، وتسجيلا عليهم بالطبع على قلوبهم ، كما تقول للواعظ : عظ المكاسين إن سمعوا منك ، قاصدا بهذا الشرط ، استبعاد ذلك ، وأنه لن يكون . .وقال الإِمام الرازى ما ملخصه : جاء التعليق بالشرط فى قوله - تعالى - : ( فَذَكِّرْ إِن نَّفَعَتِ الذكرى ) مع أنه صلى الله عليه وسلم مطلوب منه أن يذكر الناس جميعا ، نفعتهم الذكرى أم لم تنفعهم - للتنبيه على أشرف الحالين ، وهو وجود النفع الذى من أجله شرعت الذكرى ، كقوله - تعالى - :( سَرَابِيلَ تَقِيكُمُ الحر ) وللإِشعار بأن المراد من الشرط : البعث على الانتفاع بالذكرى ، كما يقول الإِنسان لغيره بعد أن بين له الحق ، قد أوضحت لك الأمر إن كنت تعقل ، فيكون مراده الحض على القبول . .ويبدو لنا أن المقصود بالآية الكريمة ، تحريض النبى صلى الله عليه وسلم على المداومة على دعوة الناس إلى قبول الحق الذى جاء به ، فإن هذا التذكير إن لم ينفع الناس جميعا ، فسينفع بعضهم ، فقد اقتضت سنة الله - تعالى - أن لا تخلو الأرض ممن يستمع إلى الحق ، ويستجيب له .","10":"ويدل على هذا المعنى قوله - تعالى - بعد ذلك : ( سَيَذَّكَّرُ مَن يخشى ) أى : سينتفع بتذكيرك - أيها الرسول الكريم - من يخشى الله - تعالى - ويخاف عذابه ، ويرجو ثوابه .","11":"( وَيَتَجَنَّبُهَا الأشقى ) أى : ويتجنب الذكرى ، ويبتعد عن الموعظة ، ويتجافى عن النصيحة ، الإِنسان الشديد الشقاوة والتعاسة ، الذى أبى إلا الإِصرار على كفره وعناده ، وخلا من خشية الله - تعالى - . والمراد بالأشقى : الجنس ، أى : يبتعد عن الانتفاع بالتذكير جميع الأشقياء وهم الكافرون .وقيل : المراد به الكافر المتوغل فى كفره كأبى جهل والوليد بن المغيرة وأشباههما .","12":"وقوله : ( الذى يَصْلَى النار الكبرى ) صفة للأشقى . أى : سيبتعد عن الانتفاع بتذكيرك - أيها الرسول الكريم - الكافر لمصر على كفره ، الذى من صفاته أنه سيصلى وسيلقى فى أشد طبقات النار سعيرا وحريقا ، وهى الطبقة السفلى منها .","13":"فوصف النار بالكبرى ، من قبيل التهويل والإنذار للمصرين على كفرهم ( ثُمَّ لاَ يَمُوتُ فِيهَا وَلاَ يَحْيَا ) أى : ثم إن هذا الشقى بعد أن يلقى به فى النار الكبرى ، ( ثُمَّ لاَ يَمُوتُ فِيهَا ) فيستريح من العذاب ( وَلاَ يَحْيَا ) حياة طيبة فيها شئ من الراحة ، بل يبقى هكذا ( وَيَأْتِيهِ الموت مِن كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍ ) وشبيه بهذه الآية قوله - تعالى - : ( والذين كَفَرُواْ لَهُمْ نَارُ جَهَنَّمَ لاَ يقضى عَلَيْهِمْ فَيَمُوتُواْ وَلاَ يُخَفَّفُ عَنْهُمْ مِّنْ عَذَابِهَا كَذَلِكَ نَجْزِي كُلَّ كَفُورٍ ) وبعد هذا البيان الذى يهز القلوب . . عن سوء عاقبة الأشقياء ز","14":"ساق - سبحانه - ما يدخل البهجة والسرور على النفوس ، عن طريق بيان حسن عاقبة السعداء ، فقال : ( قَدْ أَفْلَحَ مَن تزكى . وَذَكَرَ اسم رَبِّهِ فصلى ) .أى : قد أفلح وفاز وانتفع بالتذكير ، من حاول تزكية نفسه وتطهيرها من كل سوء .ومن ذكر اسم ربه بقلبه ولسانه ، فصلى الصلوات الخمس التى فرضها الله - تعالى - عليه . وأضاف إليها ما استطاع من نوافل وسنن .وعبر - سبحانه - بقوله : ( قَدْ أَفْلَحَ ) ليجمع فى هذا التعبير البليغ ، كل معانى الخير والنفع ، لأن الفلاح معناه : وصول المرء إلى ما يطمح إليه من فوز ونفع .وجاء التبعير بالماضى المسبوق بقد ، للدلالة على تحقيق هذا الفلاح بفضل الله - تعالى - ورحمته .","15":"وقد اشتملت هاتان الآيتان على الطهارة من العقائد الباطلة ( تزكى ) وعلى استحضار معرفة الله - تعالى - ( وَذَكَرَ اسم رَبِّهِ ) وعلى أداء التكاليف الشرعية التى على رأسها الصلاة ( فصلى ) .وهذه المعانى هى التى وصلت صاحبها إلى الفلاح الذى ليس بعده فلاح .","16":"وقوله - تعالى - : ( بَلْ تُؤْثِرُونَ الحياة الدنيا . والآخرة خَيْرٌ وأبقى ) الإضراب فيه عن كلام مقدر يفهم من السياق .والمعنى : لقد بينت لكم ما يؤدى إلى فلاحكم وفوزكم . . يا بنى آدم - كثير منكم لم يستجيب لما بينته له ، لأن الدنيا ومتعها زائلة ، أما الآخرة فخيرها باق لا يزول .والخطاب لجميع الناس ، ويدخل فيه الكافرون دخولا أوليا ، وعليه يكون المراد بإيثار الحياة الدنيا بالنسبة للمؤمنين ، ما لا يخلو منه غالب الناس ، من اشتغالهم فى كثير من الأحيان بمنافع الدنيا ، وتقصيرهم فيما يتعلق بآخرتهم .ويرى كثير من العلماء : أن الخطاب للكافرين على سبيل الالتفات ، ويؤيد أن الخطاب للكافرين قراءة أبى عمرو بالياء على طريقة الغيبة .أى : بل إن الكافرين يؤثرون الحياة الدنيا على الآخرة ، مع أن الآخرة خير وأبقى .","17":"وقوله - تعالى - : ( بَلْ تُؤْثِرُونَ الحياة الدنيا . والآخرة خَيْرٌ وأبقى ) الإضراب فيه عن كلام مقدر يفهم من السياق .والمعنى : لقد بينت لكم ما يؤدى إلى فلاحكم وفوزكم . . يا بنى آدم - كثير منكم لم يستجيب لما بينته له ، لأن الدنيا ومتعها زائلة ، أما الآخرة فخيرها باق لا يزول .والخطاب لجميع الناس ، ويدخل فيه الكافرون دخولا أوليا ، وعليه يكون المراد بإيثار الحياة الدنيا بالنسبة للمؤمنين ، ما لا يخلو منه غالب الناس ، من اشتغالهم فى كثير من الأحيان بمنافع الدنيا ، وتقصيرهم فيما يتعلق بآخرتهم .ويرى كثير من العلماء : أن الخطاب للكافرين على سبيل الالتفات ، ويؤيد أن الخطاب للكافرين قراءة أبى عمرو بالياء على طريقة الغيبة .أى : بل إن الكافرين يؤثرون الحياة الدنيا على الآخرة ، مع أن الآخرة خير وأبقى .","18":"ثم ختم - سبحانه - السورة بقوله : ( إِنَّ هذا لَفِي الصحف الأولى . صُحُفِ إِبْرَاهِيمَ وموسى ) أى : إن هذا الذى ذكرناه من فلاح من تزكى ، ومن إيثاركم الحياة الدنيا على الآخرة ، لكائن وثابت ومذكور فى الصحف الأولى ، التى هى صحف إبراهيم وموسى ، التى أنزلها - سبحانه - على هذين النبيين الكريمين ، ليعلما الناس ما اشتملت عليه من آداب وأحكام ومواعظ . وفى إبهام هذه الصحف ، ووصفها بالقدم ، ثم بيان أنها لنبيين كريمين من أولى العزم من الرسل ، تنويه بشأنها ، وإعلاء من قدرها .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم .","19":"ثم ختم - سبحانه - السورة بقوله : ( إِنَّ هذا لَفِي الصحف الأولى . صُحُفِ إِبْرَاهِيمَ وموسى ) أى : إن هذا الذى ذكرناه من فلاح من تزكى ، ومن إيثاركم الحياة الدنيا على الآخرة ، لكائن وثابت ومذكور فى الصحف الأولى ، التى هى صحف إبراهيم وموسى ، التى أنزلها - سبحانه - على هذين النبيين الكريمين ، ليعلما الناس ما اشتملت عليه من آداب وأحكام ومواعظ . وفى إبهام هذه الصحف ، ووصفها بالقدم ، ثم بيان أنها لنبيين كريمين من أولى العزم من الرسل ، تنويه بشأنها ، وإعلاء من قدرها .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"88":{"1":"الاستفهام فى قوله - تعالى - : ( هَلْ أَتَاكَ حَدِيثُ الغاشية ) للتحقيق والتقرير ، أو المقصود به التعجيب من حديث القيامة ، والتشويق إلى الاستماع إليه .والغاشية : لفظ مشتق من الغشيان ، وهو تغطية الشئ لغيره ، يقال : غشيه الأمر ، إذا غطاه ، والمقصود بالغاشية يوم القيامة ، ووصف يوم القيامة بذلك ، لأنه يغشى الناس بأهواله وشدائده ، ويغطى عقولهم عن التفكير فى أى شئ سواه .والمعنى : هل بلغك - أيها الرسول الكريم أو أيها المخاطب - حديث يوم القيامة ، الذى يغشى الناس بأحواله المفزعة ، ويعمهم بشدائده . . إن كان لم يأتك فهذا خبره ، وتلك هى أقسام الناس فيه .وافتتاح السورة بهذا الافتتاح - بجانب ما فيه من تشويق - يدل على أهمية هذا الخبر ، وأنه من الأخبار التى ينبغى الاستعداد لما اشتملت عليه من معانى لا يصح التغافل عنها .","2":"ثم فصل - سبحانه - أحوال الناس فى هذا اليوم فقال : ( وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ ) .قال الشوكانى : الجملة مستأنفة من كون ثَمَّ وجوه فى ذلك اليوم متصفة بهذهالصفة المذكورة ، و \" وجوه \" مرتفع على الابتداء - وإن كانت نكرة مرتفع على الابتداء - وإن كانت نكرة - لوقوعه فى مقام التفصيل . . والتنوين فى \" يومئذ \" عوض عن المضاف إليه . أى : يوم غشيان الغاشية .والخاشعة : الذليلة الخاضعة ، وكل متضائل ساكن يقال له خاشع . .والمراد بالوجوه : أصحابها ، من باب التعبير عن الكل بالبعض ، وخصت الوجوه بالذكر ، لأنها أشرف أعضاء الإِنسان ، ولأنها هى التى تظهر عليها الآثار المختلفة من حزن أو فرح . أى : وجوه فى يوم قيام الساعة ، تكون خاشعة ذليلة ، تبدو عليها آثار الهوان والانتكاس والخزى ، كما قال - تعالى - : ( وَتَرَاهُمْ يُعْرَضُونَ عَلَيْهَا خَاشِعِينَ مِنَ الذل . . . ).","3":"وهذه الوجوه - أيضا - من صفاتها أنها ( عَامِلَةٌ نَّاصِبَةٌ ) أى : مكلفة بالعمل الشاق المرهق الذى تَنْصَبُ له الوجوه فى هذا اليوم ، وتتعب تعبا ما عليه من مزيد ، كجر السلاسل ، وحمل الأغلال ، والخوض فى النار .فقوله : ( عاملة ) اسم فاعل من العمل ، والمراد به هنا : العمل الشاق المهين .وقوله : ( ناصبة ) من النَّصب ، بمعنى : التعب والإِعياء يقال : نَصِب فلان بكسر الصاد - كفرح - ينصب نصبا ، إذا تعب فى عمله تعبا شديدا .وفى هذه الصفات زيادة توبيخ لأهل النار ، لأنهم لما تركوا فى الدنيا الخشوع لله - تعالى - والعمل الصالح ، وآثروا متع الدنيا على ثواب الآخرة . . كان جزاؤهم يوم القيامة ، الإِذلال ، والعمل الشاق المهين الذى لا تعقبه راحة .","4":"ثم أخبر - سبحانه - عن هذه الوجوه الشقية بأخبار أخرى فقال : ( تصلى نَاراً حَامِيَةً ) أى : أن هذه الوجوه تشوى بالنار الحامية يوم القيامة . يقال : صَلِىَ فلان النار فهو يصلاها ، إذا لفحته بحرها لفحا شديدا .","5":"( تسقى مِنْ عَيْنٍ آنِيَةٍ ) أى : هذه الوجوه يسقى أصحابها من عين قد بلغت النهاية فى الحرارة والغليان ، إذ الشئ الآنى ، هو الذى بلغ النهاية فى الحرارة ، يقال : أَنَى الماء يَأْنَى - كرمى يرمى - ، إذا بلغ الغاية فى الغليان ، ومنه قوله - تعالى - ( يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ ) قال الإِمام ابن جرير : قوله : ( تسقى مِنْ عَيْنٍ آنِيَةٍ ) أى : تسقى أصحاب هذه الوجوه من شراب عين قد أَنَى حرها ، فبلغ غايته فى شدة الحر ، وبنحو الذى قلنا فى ذلك قال أهل التأويل . . فعن ابن عباس : هى التى قد طال أنيْهُا - أى : حرها - .وقال بعضهم : عنى بقوله : ( مِنْ عَيْنٍ آنِيَةٍ ) أى : من عين حاضرة - أى : حاضرة لعذابهم .","6":"وقوله - تعالى - : ( لَّيْسَ لَهُمْ طَعَامٌ إِلاَّ مِن ضَرِيعٍ . لاَّ يُسْمِنُ وَلاَ يُغْنِي مِن جُوعٍ )والضريع : هو شجر فى النار يشبه الشوك ، فيه ما فيه من المرارة والحرارة وقبح الرائحة .","7":"وقوله : ( يسمن ) من السِّمَن - بكسر السين وفتح الميم - وهو وفرة اللحم والشحم فى الحيوان وغيره . يقال : فلان أسمنه الطعام ، إذا عاد عليه بالسمن .وقوله : ( يغنى ) من الإِغناء ودفع الحاجة ، يقال : أغنانى هذا الشئ عن غيره ، إذا كفاه واستغنى به عن سواه . أى : أن أصحاب هذه الوجوه التعيسة بجانب شرابهم من الماء البالغ النهاية فى الحرارة ، لهم - أيضا - طعام من أقبح الطعام وأردئه وأشنعه وأشده مرارة . . هذا الطعام لا يأتى بسمن ، ولا يغنى من جوع ، بل إن آكله ليزدرده رغما عنه .فأنت ترى أن الله - تعالى - قد أخبر عن أصحاب هذه الوجوه الشقية بجملة من الأخبار المحزنة المؤلمة ، التى منها ما يتعلق بهيئاتهم ، ومنها ما يتعلق بأحوالهم ، ومنها ما يتعلق بشرابهم ، ومنها ما يتعلق بطعامهم .ووصف - سبحانه - طعامهم بأنه لا يسمن ولا يغنى من جوع ، لزيادة تقبيح هذا الطعام ، وأنه شر محض ، لا مكان لأية فائدة معه .قال صاحب الكشاف : الضريع : اليابس من نبات الشبرق ، وهو جنس من الشوك ، ترعاه الإِبل ما دام رطبا ، فإذا يبس تحامته الإِبل وهو سم قاتل . .فإن قلت : كيف قيل : ( لَّيْسَ لَهُمْ طَعَامٌ إِلاَّ مِن ضَرِيعٍ ) وفى الحاقة ( وَلاَ طَعَامٌ إِلاَّ مِنْ غِسْلِينٍ ) قلت : العذاب ألوان ، والمعذبون طبقات ، فمنهم : أكله الزقوم ، ومنهم أكلة الغسلين ، ومنهم أكلة الضريع .والضريع : منفعتا الغذاء منفيتان عنه : وهما إماطة الجوع ، وإفادة القوة والسمن فى البدن . أو أريد : أن لا طعام لهم أصلا ، لأن الضريع ليس بطعام للبهائم ، فضلا عن الإِنس ، لأن الطعام ما أشبه أو أسمن ، وهما منه بمعزل ، كما تقول : ليس لفلان ظل إلى الشمس . نريد : نفى الظل على التوكيد . .وبعد هذا الحديث المؤثر عن الكافرين وسوء عاقبتهم ..","8":"جاء الحديث عن المؤمنين ونعيمهم ، فقال - تعالى - : ( وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ . لِّسَعْيِهَا رَاضِيَةٌ . فِي جَنَّةٍ عَالِيَةٍ ) .قال الآلوسى : قوله : ( وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ ) شروع فى رواية حديث أهل الجنة ، وتقديم حكاية أهل النار ، لأنه أدخل فى تهويل الغاشية ، وتفخيم حديثها ، ولأن حكاية حُسْنِ حال أهل الجنة ، بعد حكاية سوء أهل النار ، مما يزيد المحكى حسنا وبهجة . . . وإنما لم تعطف هذه الجملة على تلك الجملة ، إيذانا بكمال التباين بين مضمونهما . .أى : وجوه كثيرة تكون يوم القيامة ، ذات بهجة وحسن ، وتكون متنعمة فى الجنة بما أعطاها - سبحانه - من خير عميم ، جزاء عملها الصالح فى الدنيا .","9":"( لِّسَعْيِهَا رَاضِيَةٌ ) أى : لعملها الذى عملته فى الدنيا راضية ، لأنها قد وجدت من الثواب عليه فى الآخرة ، أكثر مما كانت تتوقع وترجو .فالمراد بالسعى : العمل الذى كان يعمله الإِنسان فى الدنيا ، ويسعى به من أجل الحصول على رضا خالقه ، وهو متعلق بقوله ( راضية ) . وقدم عليه للاعتناء بشأن هذا السعى .","10":"وقوله - تعالى - : ( فِي جَنَّةٍ عَالِيَةٍ ) بيان لسمو مكانتهم . أى : هم كائنون فى جنة عالية ، مرتفعة المكان والمكانة ، فقد وصفت الجنة بالعلو ، للمبالغة فى حسنها وفى علو منزلتها ، فقد جرت العادة أن تكون أحسن الجنات ، ما كانت مرتفعة على غيرها .","11":"ثم وصف - سبحانه - هذه الجنة بجملة من الصفات الكريمة فقال : ( لاَّ تَسْمَعُ فِيهَا لاَغِيَةً ) أى : لا تسمع فى هذه الجنة كلمة ذات لغو . واللغو : هو الكلام الساقط الذى لا فائدة فيه . أى : إنك - أيها المخاطب - لا تسمع فى الجنة إلا الكلام الذى تسر له نفسك ، وتقرُّ به عينك ، فلفظ اللاغية هنا : مصدر بمعنى اللغو ، مثل الكاذبة للكذب ، وهو صفة لموصوف محذوف .","12":"( فِيهَا عَيْنٌ جَارِيَةٌ ) يريد عيونا فى غاية الكثرة كقوله : ( عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ ) فالمراد بالعين عنا : جنس العيون ، وبالجارية : التى لا ينقطع ماؤها . .","13":"( فِيهَا سُرُرٌ مَّرْفُوعَةٌ ) أى : فى الجنة أماكن يجلس عليها أهلها جلوسا مرتفعا عن الأرض .وينامون فوقها نوما هادئا لذيذا . . والسرر : جمع سرير ، وهو الشئ ذو القوائم المرتفعة الذى يتخذ للجلوس والاضطجاع .ووصف - سبحانه - هذه السرر بالارتفاع ، لزيادة تصوير حسنها .","14":"( وَأَكْوَابٌ مَّوْضُوعَةٌ ) والأكواب جمع كوب . وهو عبارة عن الإِناء الذى تشرب فيه الخمر . أى : وفى الجنة أكواب كثيرة قد وضعت بين أيدى أهلها ، بحيث يشربون من الخمر التى وضعت فيها ، دون أن يجدوا أى عناء فى الحصول عليها .","15":"( وَنَمَارِقُ مَصْفُوفَةٌ ) والنمارق : جمع نمرقة - بضم النون وسكون الميم وضم الراء - ، وهى الوسادة الصغيرة التى يتكئ عليها الجالس والمضجع . أى : وفى الجنة وسائد كثيرة ، قد صف بعضها إلى جانب بعض صفا جميلا ، بحيث يجدها الجالس قريبة منه فى كل وقت .","16":"( وَزَرَابِيُّ مَبْثُوثَةٌ ) والزرابى جمع زربية - بتثليث الزاى - وهى البساط الواسع الفاخر ، أو ما يشبه من الأشياء الثمينة التى تتخذ للجلوس عليها .والمبثوثة : أى : المنتشرة على الأرض ، من البث بمعى النشر ، كما فى قوله - تعالى - : ( وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ ) أى : وفيها بسط فاخرة جميلة . . مبسوطة فى كل مكان ، ومتفرقة فى كل مجلس .فأنت ترى أن الله - تعالى - قد وصف الجنة التى أعدها - سبحانه - لعباده المتقين بعدد من الصفات الكريمة المتنوعة .وصفها بأنها عالية فى ذاتها ، وبأنها خالية من الكلام الساقط ، وبأن ميالها لا تنقطع ، وبأن أثاثها فى غاية الفخامة ، حيث اجتمع فيها كل ما هو مريح ولذيذ .نسأل الله - تعالى - أن يجعلنا جميعا من أهلها .","17":"ثم ساق - سبحانه - أنواعا من الأدلة المشاهدة ، التى لا يستطيع أحد إنكارها ، ليلفت أنظار الناس إلى مظاهر قدرته ووحدانيته . فقال - تعالى - : ( أَفَلاَ يَنظُرُونَ إِلَى الإبل كَيْفَ خُلِقَتْ . وَإِلَى السمآء كَيْفَ رُفِعَتْ . وإلى الجبال كَيْفَ نُصِبَتْ . وَإِلَى الأرض كَيْفَ سُطِحَتْ ) .والاستفهام للتقريع والتوبيخ ، والتحريض على التأمل والتفكر ، والفاء للعطف على مقدر يقتضيه المقام ، والمراد بالنظر : التدبر فى تلك المخلوقات ، فإن من شأن هذا التدبر ، أنه يؤدى إلى الاعتبار والانتفاع . . والخطاب لأولئك الكافرين الجاهلين ، الذين أمامهم الشواهد الواضحة على وحدانية الله - تعالى - وقدرته ، ومع ذلك لم ينتبهوا لها .والمعنى : أيستمر هؤلاء الكافرون فى جهلهم وضلالهم ، وفى إنكارهم لأمر البعث والحساب والجزاء . . فلا ينظرون نظر اعتبار وتأمل ، إلى الإِبل - وهى أمام أعينهم - كيف خلقها الله ما - تعالى - بهذه الصورة العجيبة ، وأوجد فيها من الأعضاء المتناسقة ، ومن التكوين الخِلْقِى ، ما يجعلها تؤدى وظيفتها النافعة لبنى آدم ، على أكمل وجه ، فمن لبنها يشربون ، ومن لحمها يأكلون وعلى ظهرها يسافرون ، وأثقالهم عليها يحملون .وخص - سبحانه - الإِبل بالذكر من بين سائر الحيوانات ، لأنها أعز الأموال عند العرب ، وأقربها إلى مألوفهم وحاجتهم ، وأبدعها خلقا وهيئة وتكوينا .قال صاحب الكشاف : قوله - تعالى - : ( أَفَلاَ يَنظُرُونَ إِلَى الإبل ) نظر اعتبار ( كَيْفَ خُلِقَتْ ) خلقا عجيبا ، دالا على تقدير مقدر ، شاهدا بتدبير مدبر ، حيث خلقها للنهوض بالأثقال ، وجرها إلى البلاد الشاحطة ، أى البعيدة ، فجعلها تبرك حتى تحمل عن قرب ويسر ، ثم تنهض بما حملت ، وسخرها منقادة لكل من اقتادها بأزمتها ، لا تعارض ضعيفا ، ولا تمانع صغيرا .فإن قلت : كيف حسن ذكر الإِبل ، مع السماء والجبال والأرض ، ولا مناسبة؟ . .قلت : قد انتظم هذه الأشياء ، نظر العرب فى أوديتهم وبواديهم ، فانتظمها الذكر على حسب ما انتظمها نظرهم . .","18":"وقوله - تعالى - : ( وَإِلَى السمآء كَيْفَ رُفِعَتْ ) أى : وهلا نظروا إلى السماء نظر اعتبار واتعاظ ، فعرفوا أن الذى خلقها هذا الخلق البديع ، بأن رفعها بدون أعمدة .. هو الله - عز وجل - .","19":"( وإلى الجبال كَيْفَ نُصِبَت ) أى : كيف وجدت بهذا الوضع الباهر بأن نصبت على وجه الأرض ثابتا راسخا . يحمى الأرض من الاضطراب والتزلزل .","20":"( وَإِلَى الأرض كَيْفَ سُطِحَتْ ) أى : كيف وسويت وفرشت وبسطت بطريقة تجعل الناس يتمكنون من الانتفاع بخيرها ، ومن الاستقرار عليها ، وهذا لا ينافى كونها كروية ، لأن الكرة إذا اشتد عظمها . . كانت القطعة منها كالسطح فى إمكان الانتفاع بها .","21":"وبعد هذا التوبيخ لأولئك المشركين الذين عموا وصموا عن الحق ، ولم ينتبهوا لآيات الله - تعالى - الدالة على قدرته ووحدانيته . . أمر الله - تعالى - نبيه صلى الله عليه وسلم أن يداوم على التذكير بدعوة الحق ، فقال : ( فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ . لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ ) .والفاء فى قوله ( فذكر ) للتفريع ، وترتيب ما بعدها على ما قبلها . والأمر مستعمل فى طلب الاستمرار والدوام فى دعوته الناس إلى الحق ، ومفعول : \" فذكر \" محذوف العلم به .وجملة \" إنما أنت مذكر \" تعليل للأمر بالمواظبة على تبليغ الناس ما أمره بتبليغه .","22":"والمصيطر : هو المتسلط ، المتجبر ، الذى يجبر الناس على الانقياد لما يأمرهم به .وقد قرأ الجمهور هذا اللفظ بالصاد ، وقرأ ابن عامر بالسين .أى : إذا كان الأمر كما بينا لك - أيها الرسول الكريم - من أحوال الناس يوم الغاشية ، ومن أننا نحن الذين أوجدنا هذا الكون بقدرتنا . . فداوم - أيها الرسولب الكريم - على دعوة الناس إلى الدين الحق ، فهذه وظيفتك التى لا وظيفة لك سواها ، وكِلْ أمرهم بعد ذلك إلينا ، فأنت لست بمجبر لهم أو مكره إياهم على اتباعك ، وإنما أنت عليك البلاغ ونحن علينا الحساب .","23":"وقوله - سبحانه - ( إِلاَّ مَن تولى وَكَفَرَ . فَيُعَذِّبُهُ الله العذاب الأكبر ) كلام معترض بين قوله : ( فذكر . . ) وبين قوله - تعالى - بعد ذلك : ( إِنَّ إِلَيْنَآ إِيَابَهُمْ ) والاستثناء فيه استثناء منقطع ، و \" إلا \" بمعنى لكن ، و \" مَنْ \" موصولة مبتدأ . . والخبر . \" فيعذبه الله العذاب الأكبر \" .أى : داوم - أيها الرسول الكريم - على التذكير . . لكن من تولى وأعرض عن تذكيرك وإرشادك ، وأصر على كفره ، فنحن الذين سنتولى تعذيبهم تعذيبا شديدا .","24":"وقوله - سبحانه - ( إِلاَّ مَن تولى وَكَفَرَ . فَيُعَذِّبُهُ الله العذاب الأكبر ) كلام معترض بين قوله : ( فذكر . . ) وبين قوله - تعالى - بعد ذلك : ( إِنَّ إِلَيْنَآ إِيَابَهُمْ ) والاستثناء فيه استثناء منقطع ، و \" إلا \" بمعنى لكن ، و \" مَنْ \" موصولة مبتدأ . . والخبر . \" فيعذبه الله العذاب الأكبر \" .أى : داوم - أيها الرسول الكريم - على التذكير . . لكن من تولى وأعرض عن تذكيرك وإرشادك ، وأصر على كفره ، فنحن الذين سنتولى تعذيبهم تعذيبا شديدا .","25":"ثم ختم - سبحانه - السورة الكريمة بقوله : ( إِنَّ إِلَيْنَآ إِيَابَهُمْ . ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ ) .والإِياب مأخوذ من الأوب بمعنى الرجوع إلى المكان الذى كان فيه قبل ذلك . والمراد به هنا : الرجوع إلى الله - تعالى - يوم القيامة للحساب والجزاء .أى : داوم - أيها الرسول الكريم - على تذكير الناس بدعوة الحق ، بدون إجبار لهم ، أو تسلط عليهم ، واتركهم بعد ذلك وشأنهم . . فإن إلينا وحدنا رجوعهم بعد الموت لا إلى أحد سوانا .","26":"ثم إن علينا وحدنا - أيضا - حسابهم على أعمالهم ، ومجازاتهم عليها بالجزاء الذى نراه مناسبا لهم .وصدر - سبحانه - الآيتين بحرف التأكيد \" إن \" وعطف الثانية على الأولى بحرف \" ثم \" المفيد للتراخى فى الرتبة ، وقدم خبر \" إن \" فى الجلمتين على اسمها . . لإِفادة التهديد والوعيد ، وتأكيد أن رجوعهم إليه - تعالى - أمر لا شك فيه . وإن حسابهم يوم القيامة سيكون حسابا عسيرا ، لأنه صادر عمن لا تخفى عليه خافية فى الأرض ولا فى السماء ."},"89":{"1":"افتتح - سبحانه - السورة الكريمة بالقسم بخمسة أشياء لها شرفها وعظمها ، ولها فوائدها الدينية والدنيوية . . ولها دلالتها الواضحة على كمال قدرته - تعالى - .أقسم أولا - بالفجر ، وهو وقت انفجار الظلمة عن النهار من كل يوم ، ووقت بزوغ الضياء وانتشاره علىالكون بعد ليل بهيم .فالمراد بالفجر : الوقت الذى يبدأ فيه النهار فى الظهور ، بعد ظلام الليل ، والتعريف فيه للجنس ، لأن المقصود هذا الوقت من كل يوم .وقيل المراد بالفجر هنا : صلاة الفجر ، لأنها صلاة مشهودة ، أى : تشهدها الملائكة ، كما أن التعريف فيه للعهد ، فقيل : فجر يوم النحر ، وقيل : فجر يوم الجمعة . .ويبدو لنا أن الرأى الأول أرجح ، لأن قوله - تعالى - بعد ذلك ( وَلَيالٍ عَشْرٍ ) يرجح أن المراد به وقت معين . هذا الوقت يوجد مع كل يوم جديد .","2":"وأقسم - سبحانه - ثانيا بقوله : ( وَلَيالٍ عَشْرٍ ) والمراد بها : الليالى العشر الأُوَل من شهر ذى الحجة ، لأنها وقت مناسك الحج ، ففيها الإِحرام ، والطواف ، والوقوف بعرفة . .وقيل المراد بها : الليالى العشر الأواخر من رمضان وقيل : الليالى العشر الأُوَل من شهر المحرم . .قال الإِمام ابن كثير : والليالى العشر : المراد بها : عشر ذى الحجة . كما قاله ابن عباس وابن الزبير ، ومجاهد ، وغير واحد من السلف والخلف .وقد ثبت فى صحيح البخارى ، عن ابن عباس مرفوعا : \" ما من أيام العمل الصالح ، أحب إلى الله - تعالى - فيهن ، من هذه الأيام \" - يعنى : عشر ذو الحجة - قالوا : \" ولا الجهاد فى سبيل الله؟ قال : ولا الجهاد فى سبيل الله ، إلا رجلا خرج بنفسه وماله ، ثم لم يرجع من ذلك بشئ \" .وقيل : المراد بذلك : العشر الأُوَل من المحرم . وقيل : العشر الأُوَل من رمضان والصحيح القول الأول . .","3":"وأقسم - سبحانه - ثالثا ورابعا بقوله : ( والشفع والوتر ) والشفع : ما يكون ثانيا لغيره ، والوتر : هو الشئ المنفرد .وقد ذكرالمفسرون فى المراد بهذين اللفظين أقوالا متعددة ، فمنهم من يرى أنهما يعمان كل الأشياء شفعها ووترها ، ومنهم من يرى أن المراد بالشفع : يوم النحر ، لكونه اليوم العاشر من ذى الحجة ، وأن المراد بالوتر : يوم عرفة ، لأنه اليوم التاسع من شهر ذى الحجة . ومنهم من يرى أن المراد بهما : الصلاة المكتوبة ، ما كان منها شفعا ، كصلاة الظهر والعصر والعشاء والصبح ، وما كان منها وترا كالمغرب .ومنهم من يرى أن المراد بالشفع : جميع المخلوقات ، وبالوتر : الله - تعالى - الواحد الصمد .وقد رجح بعض العلماء هذا القول فقال ما ملخصه : والواقع أن أقرب الأقوال عندى - والله أعلم - . أن المراد بالوتر ، هو الله - تعالى - ، للحديث : \" إن الله وتر يحب الوتر \"وما سواه شفع . . لأنه ثبت علميا أنه لا يوجد كائن موجود بمعنى الوتر قط ، حتى الحصاة الصغيرة ، فإنه ثبت أن كل كائن جماد أو غيره مكون من ذرات ، والذرة لها نواة ومحيط .ولهذا كان القول بأن الوتر هو الله ، وبأن الشفع : جميع المخلوقات . . هو الراجح ، وهو الأعم فى المعنى .","4":"وأقسم - سبحانه - خامسا - بقوله : ( والليل إِذَا يَسْرِ ) أى : وحق الليل عندما يسرى ويمضى ، تاركا من خلفه ظلامه ، ليحل محله النهار بضيائه .أو المعنى : وحق الليل وقت أن يَسْرِى فيه السارون ، بعد أن أخذوا حظهم من النوم ، فإسناد السُّرَى إلى الليل على سبيل المجاز ، كما فى قولهم : ليل نائم ، أى : ينام فيه الناس ، وقرأ الجمهور ( يسر ) بحذف الياء وصلا وقفا ، اكتفاء عنها بالكسرة تخفيفا .وقرأ نافع وأبو عمرو بإثبات الياء عند الوصل ، وبحذفها عند الوقف .والمراد بالليل هنا : عمومه ، وقيل : المراد به هنا : ليلة القدر ، أو ليلة المزدلفة .","5":"والاستفهام فى قوله - تعالى - : ( هَلْ فِي ذَلِكَ قَسَمٌ لِّذِى حِجْرٍ ) للتقرير والتعظيم لما أقسم به - من مخلوقات . واسم الإِشارة \" ذلك \" يعود إلى تلك الأشياء التى أقسم الله - تعالى - بها .والمراد بالحِجْر العقل ، وسمى بذلك لأنه يَحْجُر صاحبه ويمنعه عن ارتكاب ما لا ينبغى ، كما سمى عقلا ، لأنه يَعْقِل صاحبه عن ارتكاب السيئات ، كما يعقِل العقالُ البعيرَ عن الضلال .والمعنى : هل فى ذلك الذى أقسمنا به من الفجر ، والليالى العشر ، والشفع والوتر . . قسم ، أى : مقسم به ، حقيق أن تؤكد به الأخبار عند كل ذى عقل سليم؟ .مما لا شك فيه أن كل ذى عقل سليم ، يعلم تمام العلم ، أن ما أقسم الله به من هذه الأشياء حقيق أن يقسم به ، لكونها - أى : هذه الأشياء - أمورا جليلة ، خليقة بالإِقسام بها لفخامة شأنها ، كما أن كل ذى عقل سليم يعلم - أيضا - أن المقسم بهذا المقسم ، وهو الله - عز وجل - صادق فيما أقسم عليه .فالمقصود من وراء القسم بهذه الأشياء ، تحقيق المقسم عليه . بأسلوب فيه ما فيه من التأكيد والتشويق وتحقيق المقسم عليه .وجواب القسم محذوف دل عليه قوله - تعالى - بعد ذلك : ( أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ ) إلى قوله : ( فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ ) .والتقدير : وحق هذه المخلوقات لتعذبن - أيها الكافرون - كما عذب الذين من قبلكم ، مثل عاد وثمود وفرعون .قال الجمل : فإن قلت : ما فائدة قوله - تعالى - : ( هَلْ فِي ذَلِكَ قَسَمٌ لِّذِى حِجْرٍ ) . بعد أن أقسم - سبحانه - بالأشياء المذكورة؟ قلنا : هو لزيادة التأكيد والتحقيق للمقسم عليه ، كمن ذكر حجة باهرة ، ثم قال : أفيما ذكرته حجة؟وجواب القسم محذوف ، أى : لتعذبن يا كفار مكة ، وقيل هو مذكور وهو قوله : ( إِنَّ رَبَّكَ لبالمرصاد ) ، وقيل محذوف لدلالة المعنى عليه ، أى لنجازين كل أحد بعمله ..","6":"ثم ذكر - سبحانه - على سبيل الاستشهاد ، ما أنزله من عذاب مهين ، بالأقوام المكذبين . فقال - تعالى - : ( أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ ) .والاستفهام فى قوله : ( أَلَمْ تَرَ . . ) للتقرير ، والرؤية : علمية ، تشبيها للعلم اليقينى بالرؤية فى الوضوح والانكشاف ، لأن أخبار هذه الأمم كانت معلومة للمخاطبين .ويجوز أن تكون الرؤية بصرية ، لكل م نشاهد آثار هؤلاء الأقوام البائدين . .والمراد بعاد : تلك القبيلة المشهورة بهذا الاسم ، والتى كانت تسكن الأحقاف ، وهو مكان فى جنوب الجزيرة العربية ، معروف للعرب ، قال - تعالى - : ( وَتِلْكَ عَادٌ جَحَدُواْ بِآيَاتِ رَبِّهِمْ وَعَصَوْاْ رُسُلَهُ واتبعوا أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ ) سموا بذلك نسبة إلى أبيهم عاد بن عُوص ، بن إرم ، بن سام ، بن نوح - عليه السلام –","7":"فقوله - تعالى - : ( إرم ) عطف بيان لعاد ، لأنه جده الأدنى .وقوله - تعالى - : ( ذَاتِ العماد ) صفة لعاد ، و \" ذات \" وصف مؤنث لأن المراد بعاد القبيلة ، سمى أولاده باسمه ، كما سمى بنو هاشم هاشما .والمقصود بهذه القبيلة عاد الأولى ، التى أرسل الله - تعالى - إليهم هودا - عليه السلام - . وكانوا معروفين بقوتهم وضخامة أجسامهم . . وقد جاء الحديث عنهم كثيرا فى القرآن الكريم ، ومن ذلك قوله - تعالى - : ( فَأَمَّا عَادٌ فاستكبروا فِي الأرض بِغَيْرِ الحق وَقَالُواْ مَنْ أَشَدُّ مِنَّا قُوَّةً . . ).","8":"وقوله - سبحانه - : ( التي لَمْ يُخْلَقْ مِثْلُهَا فِي البلاد ) صفة أخرى لقبيلة عاد .والمعنى : لقد وصل إلى علمك - أيها الرسول الكريم - بصورة يقينية ، خبر قبيلة عاد ، التى جدها الأدنى \" إرم بن سام بن نوح \" \" والتى كانت تسكن بيوتا ذات أعمدة ، ترفع عليها خيامهم ومبانيهم الفارهة . . والتى لم يخلق مثلها - أى : مثل هذه القبيلة - أحد فى ضخامة أجسام أفرادها ، وفى قوة أبدانها ، وفيما أعطاها الله - تعالى - من غنى وقوة .قال الإِمام ابن كثير ما ملخصه : قوله - تعالى - : ( أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ . إِرَمَ ذَاتِ العماد . التي لَمْ يُخْلَقْ مِثْلُهَا فِي البلاد ) هؤلاء كانوا متمردين عتاة . . فذكر - سبحانه - كيف أهلكهم .وهؤلاء عم عاد الأولى ، وهم أولاد عاد بن إرم بن عوص بن سام بن نوح ، وهم الذين أرسل الله إليهم نبيهم هودا - عليه السلام - فكذبوه فأهلكهم الله - تعالى - .فقوله : ( إِرَمَ ذَاتِ العماد ) لأنهم كانوا يسكنون بيوت الشَّعر التى ترفع بالأعمدة الشداد .وقال ها هنا : ( التي لَمْ يُخْلَقْ مِثْلُهَا فِي البلاد ) أى : القبيلة التى لم يخلق مثلها فى بلادهم ، لقوتهم وشدتهم ، وعظم تركيبهم .. فالضمير فى ( مثلها ) يعود إلى القبيلة .ومن زعم أن المراد بقوله : ( إِرَمَ ذَاتِ العماد ) مدينة إما دمشق أو الاسكندرية . . ففيه نظر . . لأن المراد إنما هو الإِخبار عن إهلاك القبيلة المسماة بعاد ، وليس المراد بالإِخبار عن مدينة أو إقليم . وإنما نبهت على ذلك لئلا يغتر بما ذكره جماعة من المفسرين من أن المراد بقوله - تعالى - : ( إِرَمَ ذَاتِ العماد . . . ) مدينة مبنية بلبن الذهب والفضة . . فهذا كله من خرافات الإِسرائيلين . .","9":"وقوله - تعالى - : ( وَثَمُودَ الذين جَابُواْ الصخر بالواد . وَفِرْعَوْنَ ذِى الأوتاد ) معطوف على ما قبله . والمراد بثمود : القبيلة المسماة بهذا الاسم ، نسبة إلى جدها ثمود ، وقد أرسل الله - تعالى - إليهم نبيهم صالحا - عليه السلام - فكذبوه ، فأهلكهم الله - تعالى - .وكانت مساكنهم بين الشام والحجاز ، ومازالت معروفة حتى الآن باسم قرى صالح .وقوله : ( جَابُواْ ) بمعنى قطعوا . من الجوب بمعنى القطع والخرق ، والصخرة الحجارة العظيمة .والواد : اسم للأرض المنخفضة بين مكانين مرتفعين ، وكان هؤلاء القوم يقطعون الصخور من الجبال ، ليتخذوا منها بيوتهم بواديهم ، أى : بالمكان الذى كانوا يسكنونه .فقوله : ( بالواد ) علم بالغلبة للمكان الذى كانوا يسكنون فيه ، ويسمى بوادى القرى ، وقد قال - تعالى - فى شأنهم : ( وَتَنْحِتُونَ مِنَ الجبال بُيُوتاً فَارِهِينَ ) والمراد بفرعون هنا : هو وقومه . والمراد بالأوتاد : الجنود والعساكر الذين يشدون ملكه ويقوونه ، كما تشد الخيام وتقوى بالأوتاد .قال الآلوسى : وصف فرعون بذلك لكثرة جنوده وخيامهم ، التى يضربون أوتادها فى منازلهم ، أو لأنه كان يدق لمن يريد تعذيبه أربعة أوتاد ، ويشده بها . .وقال بعض العلماء : ووصف فرعون بذى الأوتاد ، لأن مملكته كانت تحتوى على الأهرامات ، التى بناها أسلافه ، لأن صورة الهرم على الأرض تشبه الوتد المدقوق ، ويجوز أن يكون المراد بالأوتاد : التمكن والثبات على سبيل الاستعارة ، أى : ذى القوة . .وقال صاحب الظلال : ( وَثَمُودَ الذين جَابُواْ الصخر بالواد وَفِرْعَوْنَ ذِى الأوتاد ) وهى على الأرجح الأهرامات ، التى تشبه الأوتاد الثابتة فى الأرض المتينة البنيان ، وفرعون المشار إليه هنا ، فرعون الطاغية الجبار ، الذى أرسل الله - تعالى - إليه موسى - عليه السلام - . .والمعنى : لقد علمت - أيها الرسول الكريم - وعلم معك كل من هو أهل للخطاب ، ما فعله ربك بقبيلة عاد ، التى جدها إرم بن سام بن نوح ، والتى كانت صاحبة أعمدة عظيمة ترفع عليها بيوتها ، والتى لم يخلق فى بلادها مثلها فى القوة والغنى .وعلمت - أيضا - ما فعله ربك بقوم ثمود ، الذين قطعوا صخر الجبال ، واتخذوا منها والعساكر الذين يشدون ملكه .","10":"وقوله - تعالى - : ( وَثَمُودَ الذين جَابُواْ الصخر بالواد . وَفِرْعَوْنَ ذِى الأوتاد ) معطوف على ما قبله . والمراد بثمود : القبيلة المسماة بهذا الاسم ، نسبة إلى جدها ثمود ، وقد أرسل الله - تعالى - إليهم نبيهم صالحا - عليه السلام - فكذبوه ، فأهلكهم الله - تعالى - .وكانت مساكنهم بين الشام والحجاز ، ومازالت معروفة حتى الآن باسم قرى صالح .وقوله : ( جَابُواْ ) بمعنى قطعوا . من الجوب بمعنى القطع والخرق ، والصخرة الحجارة العظيمة .والواد : اسم للأرض المنخفضة بين مكانين مرتفعين ، وكان هؤلاء القوم يقطعون الصخور من الجبال ، ليتخذوا منها بيوتهم بواديهم ، أى : بالمكان الذى كانوا يسكنونه .فقوله : ( بالواد ) علم بالغلبة للمكان الذى كانوا يسكنون فيه ، ويسمى بوادى القرى ، وقد قال - تعالى - فى شأنهم : ( وَتَنْحِتُونَ مِنَ الجبال بُيُوتاً فَارِهِينَ ) والمراد بفرعون هنا : هو وقومه . والمراد بالأوتاد : الجنود والعساكر الذين يشدون ملكه ويقوونه ، كما تشد الخيام وتقوى بالأوتاد .قال الآلوسى : وصف فرعون بذلك لكثرة جنوده وخيامهم ، التى يضربون أوتادها فى منازلهم ، أو لأنه كان يدق لمن يريد تعذيبه أربعة أوتاد ، ويشده بها . .وقال بعض العلماء : ووصف فرعون بذى الأوتاد ، لأن مملكته كانت تحتوى على الأهرامات ، التى بناها أسلافه ، لأن صورة الهرم على الأرض تشبه الوتد المدقوق ، ويجوز أن يكون المراد بالأوتاد : التمكن والثبات على سبيل الاستعارة ، أى : ذى القوة . .وقال صاحب الظلال : ( وَثَمُودَ الذين جَابُواْ الصخر بالواد وَفِرْعَوْنَ ذِى الأوتاد ) وهى على الأرجح الأهرامات ، التى تشبه الأوتاد الثابتة فى الأرض المتينة البنيان ، وفرعون المشار إليه هنا ، فرعون الطاغية الجبار ، الذى أرسل الله - تعالى - إليه موسى - عليه السلام - . .والمعنى : لقد علمت - أيها الرسول الكريم - وعلم معك كل من هو أهل للخطاب ، ما فعله ربك بقبيلة عاد ، التى جدها إرم بن سام بن نوح ، والتى كانت صاحبة أعمدة عظيمة ترفع عليها بيوتها ، والتى لم يخلق فى بلادها مثلها فى القوة والغنى .وعلمت - أيضا - ما فعله ربك بقوم ثمود ، الذين قطعوا صخر الجبال ، واتخذوا منها والعساكر الذين يشدون ملكه .","11":"و ( الذين طَغَوْاْ فِي البلاد ) فأفسدوها ، وتجاوزوا كل حد فى العصيان والظلم .","12":"( فَأَكْثَرُواْ فِيهَا ) أى : فى البلاد ( الفساد ) عن طريق الفسوق والخروج عن طاعتنا .","13":"( فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ ) أى : فكانت نتيجة طغيانهم وفسادهم ، أن أنزل ربك عليهم ، نوعا عظيما من العذاب المهين .والسوط : آلة تتخذ من الجلود القوية ، يضرب بها الجانى ، وإضافتها إلى العذاب ، من إضافة الصفة إلى الموصوف . أى : فصب عليهم ربك عذابا . \" سوطا \" أى : كالسوط فى سرعته ، وشدته وتتابعه ، فهو تشبيه بليغ .وعبر - سبحانه - على إنزال العذاب بهم بالصب - وهو الإِفراغ لما فى الظرف بقوة - للإِيذان بكثرته وتتابعه .وسميت أنواع العذاب النازلة بهم سوطا تسمية للشئ باسم آلته .قال صاحب الكشاف : وذكر السوط . إشارة إلى أن ما أحله بهم فى الدنيا من العذاب العظيم بالقياس إلى ما أعد لهم فى الآخرة ، كالسوط إذا قيس إلى سائر ما يعذب به .وعن عمر بن عبيد : كان الحسن إذا أتى على هذه الآية قال : إن عند الله أسواطا كثيرة ، فأخذهم بسوط منها . .","14":"وقوله - سبحانه - : ( إِنَّ رَبَّكَ لبالمرصاد ) تذييل وتعليل لإِصابتهم بسوط عذاب .والمرصاد فى الأصل : اسم للمكان الذى يجلس فيه الجالس لترقب أو رؤية شئ ما .والمراد : إن ربك - أيها الرسول الكريم - يرصد عمل كل إنسان ، ويحصيه عليه ، ويجازيه به ، دون أن يخفى عليه - سبحانه - شئ فى الأرض أو السماء .وفى هذه الآيات الكريمة تخويف شديد للكافرين ، وتهديد لهم على إصرارهم فى جحودهم ، وأنهم إذا ما ساروا فى طريق الجحود والعناد ، فسيصيبهم ما أصاب هؤلاء الطغاة .","15":"ثم ذكر - سبحانه - حال الإِنسان عند اليسر والعسر ، والغنى والفقر ، والسراء والضراء فقال :( فَأَمَّا الإنسان إِذَا . . . ) .الفاء فى قوله : ( فَأَمَّا الإنسان . . . ) للتفريع على ما تقدم ، ولترتيب ما بعدها على ما قبلها .والمراد بالإِنسان هنا : جنسه . وقيل المراد به الكافر . ولفظ \" الإنسان \" مبتدأ ، وخبره : ( فَيَقُولُ ربي أَكْرَمَنِ ) .والمعنى : هذه سنة ربك - أيها العاقل - فى عباده ، أنه - تعالى - لهم بالمرصاد ، فهو يراقب أعمالهم ، ويحاسبهم عليها ، ويجازيهم بها ، والسعيد من الناس هو الذى يفقه هذه الحقيقة ، فيؤدى ما كلفه خالقه به . . . فأما الإِنسان ، الشقى الغافل عن طاعة ربه . .( إِذَا مَا ابتلاه رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ ) أى : إذا ما اختبره وامتحنه ربه بألوان من النعم ، بأن منحه المال الكثير ، والجاه العريض ، وأسباب القوة والمنعة ( فيقول ) على سبيل التباهى والتفاخر . . ( ربي أَكْرَمَنِ ) أى : ربى أعطانى ذلك ، لأنى مستحق لهذه النعم ، كما قال - تعالى - : ( وَلَئِنْ أَذَقْنَاهُ رَحْمَةً مِّنَّا مِن بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هذا لِي وَمَآ أَظُنُّ الساعة قَآئِمَةً وَلَئِن رُّجِعْتُ إلى ربي إِنَّ لِي عِندَهُ للحسنىا ) .","16":"وقوله - سبحانه - : ( وَأَمَّآ إِذَا مَا ابتلاه فَقَدَرَ عَلَيْهِ رِزْقَهُ . . ) بيان لموقف هذا الإِنسان عند فقره . أى : وأما إذا ما امتحنا هذا الإِنسان بسلب بعض النعم عنه ، وبضيق الرزق . . ( فيقول ) على سبيل التضجر والتأفف وعدم الرضا بقضائه - سبحانه - : ( ربي أَهَانَنِ ) أى : ربى أذلنى بالفقر ، وأنزل بى الهوان والشرور .وقول هذذا الإِنسان فى الحالين ، قول مذموم ، يدل على سوء فكره ، وقصور نظره ، وانطماس بصيرته ، لأنه فى حالة العطاء والعسة فى الرزق ، يتفاخر ويتباهى ، ويتوهم أن هذه النعم هو حقيق وجدير بها ، وليست من فضل الله - تعالى - وكأنه يقول ما قاله قارون : ( إِنَّمَآ أُوتِيتُهُ على عِلْمٍ عندي ) وفى حالة المنع والضيق فى الرزق يجزع ، ويأبى أن يرضى بقضاء الله وقدره . . ولا يخطر بباله أن نعم الله ، إنما هى فضل تفضل به - سبحانه - عليه ليختبره ، أيشكر أم يكفر . وأن تضييقه عليه فى الرزق ، ليس من الإِهانة فى شئ ، بل هو للابتلاء - أيضا - والامتحان ، كما قال - تعالى - : ( وَنَبْلُوكُم بالشر والخير فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ ) قال الإِمام الشوكانى عند تفسيره لهاتين الآيتين : وهذه صفة الكافر الذى لا يؤمن بالبعث ، لأنه لا كرامة عنده إلا الدنيا والتوسع فى متاعها ، ولا إهانة عنده إلا فوتها وعدم وصوله إلى ما يريد من زينتها ، فأما المؤمن فالكرامة عنده أن يكرمه الله بطاعته ، ويوفقه لعمل الآخرة .ويحتمل أن يراد الإِنسان على العموم ، لعدم تيقظه أن ما صار إليه من الخير ، وما أصيب به من الشر فى الدنيا ، ليس إلا للاختبار والامتحان ، وأن الدنيا بأسرها ، لا تعدل عند الله - تعالى - جناح بعوضة ..واقتصر - سبحانه - فى الآية الكريمة على تقتير الرزق ، فى مقابلة النعمة ، دون غير ذلك من الأمراض والآفات ، للإِشعار بأن هذا الإِنسان يعتبر دنياه جنته ومنتهى آماله ، فهو لا يفكر إلا فى المال ولا يحزن إلا من أجله ، وأن المقياس عنده لمقادير الناس هو على حسب ما عندهم من أموال كما قال شاعرهم :فلو شاء ربى كنت قيسَ بن عاصمٍ ... ولو شاء ربى كنت عمرَو بنَ مَرْثِدفأصبحت ذا مال كثير وطاف بى ... بنونَ كرامٌ ، سادةٌ لُمسوَّدولما كان هذا القول مذموما من هذا الإِنسان فى الحالين . لعدم شكره لله - تعالى - فى حالة الرخاء ، ولعدم صبره على قضائه فى حالة البأساء .","17":"لما كان الأمر كذلك جاء حرف الردع بعد ذلك فقال - تعالى - : ( كَلاَّ بَل لاَّ تُكْرِمُونَ اليتيم . وَلاَ تَحَآضُّونَ على طَعَامِ المسكين )فقوله - تعالى - : ( كلا ) زرج وردع عن قول هذا الإِنسان ( ربي أَكْرَمَنِ ) عند حصول النعمة ، وعن قوله ( ربي أَهَانَنِ ) عند حصول التقتير فى الرزق ، لأن الله - تعالى - قد يوسع على الكافر وهو مهان ومبغوض منه - تعالى - ، وقد يضيق - سبحانه - على المؤمن مع محبته له ، وكلا الأمرين حاصل بمقتضى حكمته - عز وجل - والمؤمن الصادق هو الذى يشكر عند الرخاء ، ويصبر عند البأساء .و \" بل \" هنا للإضراب الانتقالى ، من ذمهم على القبيح من القول ، إلى ذمهم بما هو أشنع منه ، وهو ارتكابهم للقبيح من الأفعال .أى : كلا ليس قولكم هذا وهو أن الإِكرام فى الإعطاء ، والإهانة فى المنع - هو القبيح فحسب ، بل هناك ما هو أقبح منه ، وهو أنكم ، أيها الكافرون - .( لاَّ تُكْرِمُونَ اليتيم ) أى : لا تعطفون على اليتيم وهو الذى مات أبوه وهو صغير ، بأن تتركوه معرضا للفقر والاحتياج ، دون أن تعملوا على تقديم يد المساعدة إليه .","18":"( وَلاَ تَحَآضُّونَ على طَعَامِ المسكين ) أى : ولا يحث بعضكم بعضا على إطعام المساكين والبائسين .ونفى الحض على إطعامهم ، نفى لإِطعامهم من باب أولى ، وفى ذلك زيادة لمذلتهم ، لأنهم لا يطعمون ، ولا يحضون غيرهم عليه ، لأنهم قوم خلت قلوبهم من الرحمة والعطف .قال الآلوسى : قوله - سبحانه - : ( بَل لاَّ تُكْرِمُونَ اليتيم ) أى : لا تعطفون على اليتيم وهو الذى مات أبوه وهو صغير ، بأن تتركوه معرضا للفقر والاحتياج ، دون أن تعملوا على تقديم يد المساعدة إليه .( وَلاَ تَحَآضُّونَ على طَعَامِ المسكين ) أى : ولا يحث بعضكم بعضا على إطعام المساكين والبائسين .ونفى الحض على إطعامهم ، نفى لإِطعامهم من باب أولى ، وفى ذلك زيادة لمذلتهم ، لأنهم لا يطعمون ، ولا يحضون غيرهم عليه ، لأنهم قوم خلت قلوبهم من الرحمة والعطف .قال الآلوسى : قوله - سبحانه - : ( بَل لاَّ تُكْرِمُونَ اليتيم .. ) إلخ . انتقال وترق من ذم هذا الإِنسان على القبيح من القول ، إلى الأقبح من الفعل ، والالتفات إلى الخطاب ، لتشديد التقريع ، وتأكيد التشنيع . . والجمع باعتبار معنى الإِنسان ، إذ المراد الجنس . أى : بل لكم أفعال وأحوال أشد شرا مما ذكر ، وأدل على تهالككم على المال ، حيث أكرمكم - سبحانه - بكثرة المال ، ولكنكم لم تؤدوا ما يلزمكم فيه من إكرام اليتيم .والمراد بطعام المسكين : إطعامه ، فالطعام مصدر بمعنى الإِطعام . . أو المراد به : الشئ المطعوم ، ويكون الكلام على حذف مضاف . أى : على بذل طعام المسكين . .","19":"وقوله - سبحانه - : ( وَتَأْكُلُونَ التراث أَكْلاً لَّمّاً ) بيان لرذيلة ثالثة من رذائلهم المتعددو . والتراث : هو المال الموروث عن الغير . والمراد بالأكل مطلق الانتفاع ، وخص الأكل بالذكر ، لأنه يشمل معظم وجوه التصرفات المالية .والَّلُّم : الجمع بدون تفرقة بين الحلال والحرام ، مأخوذ من قولهم : لَمَّ الطعام ، إذا أكله كله دون أن يترك منه شيئا .أى : ومن صفاتكم القبيحة أنكم تأكلون المال الموروث عن غيركم ، أكلا شديدا ، بحيث لا تتركون منه شيئا ، ولا تفرقون بين ما هو حلال أو حرام ، ولا بين ما يحمد وما لا يحمد ، بل تأخذون حقوقكم وحقوق غيركم من النساء والصبيان .","20":"ومن صفاتكم - أيضا - أنكم ( وَتُحِبُّونَ المال حُبّاً جَمّاً ) أى : حبا كثيرا مع حرص وشَرَه . يقال : جمّ الماء فى الحوض ، إذا كثر واجتمع ، ومنه الجَمُوع للبئر الكثيرة الماء .والحب المفرط للمال من الصفات الذميمة ، لأنه يؤدى إلى جمعه من كل طريق ، بدون تفرقة بين ما يحل منه وما يحرم .فأنت ترى أن الله - تعالى - قد وصف هذا النوع من الناس ، بأنه قد جمع فى سوء سلوكه ، بين النطق بالقبيح من الأقوال ، وبين ارتكاب القبيح من الأفعال ، وهى : ترك اليتيم بلا رعاية ، وعدم الحض على إطعام المحتاج ، وجمع المال الموروث بدون تفرقة بين حلاله وحرامه ، والإِفراط فى حب المال بطريقة ذميمة .","21":"وبعد هذا الزجر والردع لهم ، لسوء أقوالهم وأفعالهم ، أخذت السورة الكريمة فى زجرهم وردعهم عن طريق تذكيرهم بأهوال الآخرة فقال : - تعالى - : ( كَلاَّ إِذَا دُكَّتِ الأرض دَكّاً دَكّاً ) . وقوله - تعالى - : ( كَلاَّ إِذَا دُكَّتِ الأرض دَكّاً دَكّاً ) ردع لهم وزجر عن أفعالهم السابقة ، وهى عدم إكرام اليتيم ، وعدم الحض على طعام المسكين .وقوله : ( دُكَّتِ الأرض ) من والدك : بمعنى الكسر والدق والزلزلة الشديدة ، والتحطيم الجسيم ، وانتصب لفظ \" دكا \" الأول على أنه مصدر مؤكد للفعل ، وانتصاب الثانى على أنه تأكيد الأول . وقيل : تكرار \" دكا \" للدلالة على الاستيعاب ، كقولك : قرأت النحو بابا بابا ، أى : قرأته كله .قال القرطبى : قوله - تعالى - : ( كَلاَّ إِذَا دُكَّتِ الأرض . . ) أى : ما هكذا ينبغى أن يكون الأمر . فهو رد لانكبابهم على الدنيا ، وجميعهم لها ، فإن من فعل ذلك يندم يوم تدك الأرض ، ولا ينفعه الندم ، والدك .الكسر والدق ، أى : زلزلت وحركت تحريكا بعد تحريك .وقوله : ( دَكّاً دَكّاً ) أى : مرة بعد مرة ، زلزلت فكسر بعضها بعضا فتكسر كل شئ على ظهرها . .","22":"وقوله - تعالى - : ( وَجَآءَ رَبُّكَ . . . ) هذه الآية وأمثالها من آيات الصفات التى يرى السلف وجوب الإِيمان بها كما جاءت ، بمعنى أننا نؤمن بمجئ الله - تعالى - ولكن من غير تكييف ولا تمثيل ، بل نكل علم كيفية مجيئة إلى مشيئته - تعالى - .والخلف يؤولون ذلك بأى المجئ هنا بمعنى مجئ أمره وقضائه .قال الآلوسى : قوله - تعالى - : ( وَجَآءَ رَبُّكَ . . . ) قال منذر بن سعيد ، معناه : ظهر - سبحانه - للخلق هنالك ، وليس ذلك بمجئ نقلة . . وقيل : الكلام على حذف مضاف للتهويل ، أى : وجاء أمر ربك وقضاؤه . واختار جع أنه تمثيل لظهور آيات اقتداره - تعالى - وتبيين آثار قدرته وسلطانه ، مثلت حاله - سبحانه - فى ذلك ، بحال الملك إذا حضر بنفسه ظهر بحضوره من آثار الهيبة ما لا يظهر بحضور عساكره ووزرائه وخواصهعن بكرة أبيهم ، وأنت تعلم ما للسلف فى المتشابه من الكلام .( والملك ) أى : جنس المَلَكِ ، فيشمل جميع الملائكة ( صَفّاً صَفّاً ) أى : مصطفين ، أو ذوى صفوف .","23":"وقوله - تعالى - : ( وجياء يَوْمَئِذٍ بِجَهَنَّمَ ) أى : وأحضرت جهنم وظهرت وبرزت للكافرين والفاسقين يوم القيامة ، يوم تدك الأرض دكا .وقوله : ( يَوْمَئِذٍ ) منصوب بقوله ( وجئ ) . وقوله ( جهنم ) قائم مقام الفاعل .روى الإِمام مسلم فى صحيحه عن ابن مسعود قال : قال رسول الله صلى الله عليه وسلم : \" يؤتى بجهنم يومئذ لها سبعون ألف زمام ، مع كل زمام سبعون ألف ملك يجرونها . . \" .( يَوْمَئِذٍ ) أى : فى هذا اليوم العسير ، وهو يوم القيامة - وهو بدل من قوله - تعالى - : ( إِذَا دُكَّتِ الأرض ) - ( يَتَذَكَّرُ الإنسان ) أى : يتذكر ما فرط منه من ذنوب ، وما ارتكبه من سيئات ، وما وقع فيه من كفر وفسوق عن أمر ربه .( وأنى لَهُ الذكرى ) أى : ومن أين له الانتفاع بهذا التذكر ، لأنه تذكر قد جاء فى غير وقت الانتفاع به ، وهو وقت الحساب على الأعمال ، لا وقت التوبة من السيئ منها .","24":"( يَقُولُ ) هذا الانسان الشقى ( ياليتني قَدَّمْتُ لِحَيَاتِي ) أى : يقول حين يرى العذاب ماثلا أمامه ، يقول - على سبيل التحسر والتفجع - : يا ليتنى قدمت أعمالا صالحة لأجل حياتى هذه فى الآخرة ، فاللام للتعليل ، وقدمت أعمالا صالحة فى وقت حياتى فى الدنيا لأنتفع بها فى هذا اليوم ، فتكون اللام للتوقيت .","25":"( فَيَوْمَئِذٍ ) أى : ففى هذا اليوم لا ينفعه الندم ولا التحسر ، و ( لاَّ يُعَذِّبُ عَذَابَهُ أَحَدٌ ) والوثاق : الرباط الذى يقيد به الأسير .أى : ففى هذا اليوم لا يعذِّب كعذاب الله أحد ، ولا يوثِق كوثاقه أحد ، فالضمير فى قوله : ( عَذَابَهُ ) و ( ثَاقَهُ ) يعود إلى الله - ولفظ \" أحد \" فاعل .وقرأ الكسائى : ( لاَّ يُعَذِّبُ ) و ( لاَ يُوثِقُ ) - بفتح الذال المشددة ، وفتح الثاء - على البناء للمفعول ، والضمير فى قوله ( عذابه ) و ( وثاقه ) يعود للكافر .أى : فيومئذ لا يعذب أحد مثل عذاب ذلك الإِنسان الكافر المتحسر ، ولا يوثق أحد مثل وثاقه ، ولفظ \" أحد \" هنا نائب فاعل .وشبيه بهاتين الآيتين قوله - تعالى - : ( قَالَ الله إِنِّي مُنَزِّلُهَا عَلَيْكُمْ ) - أى : المائدة - ( فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فإني أُعَذِّبُهُ عَذَاباً لاَّ أُعَذِّبُهُ أَحَداً مِّنَ العالمين ).","26":"( فَيَوْمَئِذٍ ) أى : ففى هذا اليوم لا ينفعه الندم ولا التحسر ، و ( لاَّ يُعَذِّبُ عَذَابَهُ أَحَدٌ ) والوثاق : الرباط الذى يقيد به الأسير .أى : ففى هذا اليوم لا يعذِّب كعذاب الله أحد ، ولا يوثِق كوثاقه أحد ، فالضمير فى قوله : ( عَذَابَهُ ) و ( ثَاقَهُ ) يعود إلى الله - ولفظ \" أحد \" فاعل .وقرأ الكسائى : ( لاَّ يُعَذِّبُ ) و ( لاَ يُوثِقُ ) - بفتح الذال المشددة ، وفتح الثاء - على البناء للمفعول ، والضمير فى قوله ( عذابه ) و ( وثاقه ) يعود للكافر .أى : فيومئذ لا يعذب أحد مثل عذاب ذلك الإِنسان الكافر المتحسر ، ولا يوثق أحد مثل وثاقه ، ولفظ \" أحد \" هنا نائب فاعل .وشبيه بهاتين الآيتين قوله - تعالى - : ( قَالَ الله إِنِّي مُنَزِّلُهَا عَلَيْكُمْ ) - أى : المائدة - ( فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فإني أُعَذِّبُهُ عَذَاباً لاَّ أُعَذِّبُهُ أَحَداً مِّنَ العالمين ).","27":"ثم ختم - سبحانه - السورة الكريمة بهذه البشارة العظيمة للمؤمنين فقال : ( ياأيتها النفس المطمئنة . ارجعي إلى رَبِّكِ رَاضِيَةً مَّرْضِيَّةً . فادخلي فِي عِبَادِي . وادخلي جَنَّتِي ) .والنفس المطمئنة : هى النفس الآمنة من الخوف أو الحزن فى يوم القيامة . بسبب إيمانها الصادق ، وعملها الصالح ، والكلام على إرادة القول . أى : يقول الله - تعالى - على لسان ملائكته ، إكراما للمؤمنين ، عند وفاتهم ، أو عند تمام حسابهم : يأيتها النفس الآمنة المطمئنة ، الناعمة بروح اليقين ، الواثقة بفضل الله - تعالى - ورحمته .","28":"( ارجعي إلى رَبِّكِ رَاضِيَةً مَّرْضِيَّةً ) أى : ارجعى إلى ربك الذى خلقك ، وأنت راضية تمام الرضا بما أعطاك - سبحانه - من ثواب ، ومرضى عنك منه - تعالى - بسبب إيمانك الصادق ، وعملك الصالح .","29":"( فادخلي فِي عِبَادِي ) أى فادخلى فى زمرة عبادى الصالحين المرضين .","30":"( وادخلي جَنَّتِي ) التى وعدتهم بها ، والتى أعددتها لنعيمهم الدائم المقيم .وقد ذكروا أن هذه الآيات الكريمة نزلت فى شأن عثمان بن عفان لّما تصدق ببئر رومة .وقيل : نزلت فى حمزة بن عبد المطلب حين استشهد .قال القرطبى : والصحيح أنها عامة فى نفس كل مؤمن مخلص طائع . .نسأل الله - تعالى - أن يجعلنا جميعا من أصحاب النفوس المطمئنة .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم . ."},"90":{"1":"افتتحت السورة الكريمة بالقسم ، تشويقا لما يرد بعده ، وتأكيدا للمقسم عليه .و \" لا \" فى مثل هذا التركيب ، يرى المحققون أنها مزيدة للتأكيد ، والمعنى : أقسم بهذا البلد . أى : مكة المكرمة ، وقد جاء القسم بها فى قوله - تعالى - : ( والتين والزيتون . وَطُورِ سِينِينَ . وهذا البلد الأمين ) قال الشيخ محمد عبده - رحمه الله - : قوله : ( لاَ أُقْسِمُ . . ) عبارة من عبارات العرب فى القسم ، يراد بها تأكيد الخبر ، كأنه فى ثبوته وظهوره لا يحتاج إلى قسم . ويقال إنه يؤتى بها فى القسم إذا أريد تعظيم المقسم به . كأن القائل يقول : إنى لا أعظمه بالقسم ، لأنه عظيم فى نفسه ، والمعنى فى كل حال على القسم . .وقال بعض العلماء : \" لا \" هذه للنفى ، وهذه عبارة تعود العرب أن يقولوها عندما يكون المقسم عليه ظاهر أمره ، كأنه - تعالى - يقول : أنا لا أقسم بهذه الأشياء ، على إثبات هذا المطلوب الذى أذكره بعد ، لأن إثباته أظهر وأجلى وأقوى من أن يحاول محاول إثباته بالقسم .ويقال : معناه : أنا لا أقسم بهذه الأشياء على إثبات المطلوب ، لأنه أعظم وأجل وأكبر من أن يقسم عليه ، بهذه الأمور الهينة الشأن ، والغرض على هذا الوجه ، تعظيم المقسم عليه ، وتفخيم شأنه . .والإِشارة بلفظ \" هذا \" مع بيانه بالبلد ، إشارة إلى حاضر فى أذهان السامعين ، لأن مكة بعضهم كان يعيش فيها . وبعضهم كان يعرفها معرفة لاخفاء معها ، وشبيه بذلك قوله - تعالى - : ( إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَذِهِ البلدة الذي حَرَّمَهَا وَلَهُ كُلُّ شَيءٍ ) وفائدة الإِتييان باسم الإِشارة هنا : تميييز المقسم به أكمل تمييز لقصد التنيويه به .","2":"وجملة : ( وَأَنتَ حِلٌّ بهذا البلد ) معترضة بين القسم وجوابه .وقوله - تعالى - ( حل ) اسم مصدر أحل بمعنى أباح ، فيكون المعنى : وأنت - أيها الرسول الكريم - قد استحل كفار مكة إيذاءك ومحاربتك . . مع أنهم يحرمون ذلك النسبة لغيرك ، فى هذا البلد الأمين .ويصح أن يكون لفظ \" حل \" هنا بمعنى اللحال الذى هو ضد الحرام يقال : هو حل وحلال ، وحِرْمٌ وحرام . . فيكون المعنى : وأنت أيها الرسول الكريم - قد أحل الله - تعالى - لك أن تفعل بهؤلاء المشركين ما شئت من القتل أو العفو .وتكون الجملة الكريمة ، بشارة للنبى صلى الله عليه وسلم بأن الله - تعالى - سينصره على مشركى قريش ، ويمكنه من رقابهم . . وقد أنجز له - سبحانه - ذلك يوم الفتح الأكبر .قال صاحب الكشاف : أقسم الله - تعالى - بالبلد الحرام وما بعده ، على أن الإِنسان خلق مغمورا فى مكابدة المشاق والشدائد ، واعترض بين القسم والمقسم عليه بقوله : ( وَأَنتَ حِلٌّ بهذا البلد ) يعنى : زمن المكابدة أن مثلك - يا محمد - على عظم حرمتك ، يُسْتَحلُّ بهذا البلد الحرام ، كما يستحل الصيد فى غير الحرم .وفيه تثبيت لرسول الله صلى الله عليه وسلم وبعث على احتمال ما كان يكابد من أهل مكة ، وتعجيب من حالهم فى عداوته .أو سلى صلى الله عليه وسلم بالقسم ببلده ، على أن الإِنسان لا يخلو من مقاساة الشدائد ، واعترض بأن وعده فتح مكة تتميما للتسلية والتنفيس عليه فقال : ( وَأَنتَ حِلٌّ بهذا البلد ) .يعنى : وأنت حل به فى المستقبل ، تصنع فيه ما تريد من القتل والأسر .فإن قلت : أين نظير قوله : ( وَأَنتَ حِلٌّ ) فى معنى الاستقبال؟ قلت : قوله - تعالى - ( إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَّيِّتُونَ ) وكفاك دليلا قاطعا على أنه للاستقبال ، وأن تفسيره بالحال محال ، أن السورة بالاتفاق مكية ، وأين الهجرة من وقت نزولها؟ فما بال الفتح؟ويرى بعضهم أن معنى قوله - تعالى - : ( وَأَنتَ حِلٌّ بهذا البلد ) : وأنت مقيم بهذا البلد ، ونازل فيه ، وحالّ به ، وكفى فخراً لمكة أن تنزل فيها - أيها الرسول الكريم - فإن الأمكنة الشريفة تزداد شرفا بنزول رسل الله - تعالى - فيها ، فكيف وأنت خاتمهم وإمامهم؟قال بعض العلماء : وحكى ابن عطية عن بعض المتأولين : أن معنى ( وَأَنتَ حِلٌّ بهذا البلد ) وأنت ساكن بهذا البلد ، حال فيه . . وهو يقتضى أن تكون هذه الآية موضع الحال من ضمير \" أقسم \" فيكون القسم بالبلد مقيدا باعتبار بلد محمد صلى الله عليه وسلم وهو تأويل جميل ، لو ساعد عليه ثبوت استعمال \" حل \" بمعنى حالٍّ ، أى : مقيم فى مكان ، فإن هذا لم يرد فى كتب اللغة . . ولذا لم يذكر هذا المعنى صاحب الكشاف . .ويبدو لنا أن هذه الأقوال لا تعارض بينها ، بل يؤيد بعضها بعضا ، لأن الرسول صلى الله عليه وسلم قد آذاه أهل مكة ، بينما حرموا إيذاء غيره ، وأن الله - تعالى - قد مكن رسوله صلى الله عليه وسلم منهم . كما حدث فى غزوة الفتح ، وأنه صلى الله عليه وسلم قد أقام معهم فى مكة أكثر من خمسين سنة ، وكان يلقب عندهم بالصادق الأمين . .","3":"وقوله - سبحانه - : ( وَوَالِدٍ وَمَا وَلَدَ ) معطوف على المقسم به الأول وهو قوله - تعالى - : ( بهذا البلد ) . وداخل فى حيز القسم . والمراد بالوالد آدم - عليه السلام - ، والمراد بما ولد : ذريته من بعده .أى : أقسم بهذا البلد الذى له ماله من الشرف ، والمكانة السامية بين البلاد . . وأقسم بأبيكم آدم ، وبذريته من بعده . . أو أقسم بكل والد وبكل مولود .وجئ باسم الموصول \" ما \" فى قوله ( وَمَا وَلَدَ ) دون \" من \" مع أنها أكثر استعمالا فى العاقل الذى هو مراد هنا ، لأن \" ما \" أشد إبهاما ، وشدة الإِبهام المقصود بها هنا التفخيم والتعظيم .. وشبيه بذلك قوله - تعالى - : ( فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّي وَضَعْتُهَآ أنثى والله أَعْلَمُ بِمَا وَضَعَتْ . . . ) كما أن تنكير لفظ \" والد \" هنا للتعظيم أيضا .وقيل المراد بالوالد هنا : إبراهيم - عليه السلام - وبما ولد : الصالحون من ذريته .وقيل المراد بالوالد : من يولد له ، وبقوله ( وَمَا وَلَدَ ) الذى لم يولد له وعليه تكون ما نافية .وقد رجح الإِمام ابن جرير المعنى الأول فقال : والصواب من القول من ذلك ، ما قاله الذين قالوا : إن الله - تعالى - أقسم بكل والد وولده ، لأن الله - تعالى - عم كل والد وما ولد ، وغير جائز أن يخص ذلك إلا بحجة يجب التسليم لها من خبر أو عقل . ولا خبر بخصوص ذلك ولا برهان يجب التسليم له بخصوصه ، فهو على عمومه . .","4":"وقوله - تعالى - ( لَقَدْ خَلَقْنَا الإنسان فِي كَبَدٍْ ) جواب القسم . والمراد بالإِنسان : جنسه ، والكبد : الشدة والتعب والمشقة ، من المكابدة للشئ ، بمعنى تحمل المشاق والمتاعب فى فعله ، وأصله من كَبِد الرجل - بزنة طرب - فهو أَكْبَد ، إذا أصيبت كبده بالمرض ، ثم اتسع فيه فاستعمل فى كل تعب ومشقة تنال الإِنسان .والمعنى : لقد خلقنا الإِنسان لهذه الشدائد والآلام ، التى هى من طبيعة هذه الحياة الدنيا ، والتى لا يزال يكابدها وينوء بها ، ويتفاعل معها . . حتى تنتهى حياته ، ولا فرق فى ذلك بين غنى أو فقير ، وحاكم أو محكوم وصالح أو طالح . . فالكل يجاهد ويكابد ويتعب ، من أجل بلوغ الغاية التى يبتغيها .قال الآلوسى ما ملخصه : قوله : ( لَقَدْ خَلَقْنَا الإنسان فِي كَبَد ) أى : فى تعب ومشقة ، فإنه لا يزال يقاسى فنون الشدائد من وقت نفخ الروح إلى حين نزعها .وعن ابن عمر - رضى الله عنهما - يكابد الشكر على السراء ويكابد الصبر على الضراء . وقيل : لقد خلقناه منتصب القامة واقفا ، ولم نجعله منكبا على وجهه .وقيل : جعلناه منتصبا رأسه فى بطن أمه ، فإذا أذن له فى الخروج قلب رأسه إلى قدمى أمه . . وهذه الأقوال ضعيفة لا يعول عليها ، والصحيح الأول . .والحق أن تفسير الكبد بالمشقة والتعب ، هو الذى تطمئن إليه النفس؛ لأنه لا يوجد فى هذه الحياة إِنسان إلا وهو مهموم ومشغول بمطالب حياته ، وفى كبد وتعب للحصول على آماله ورغباته وغاياته ، ورحم الله القائل :تعب كلها الحياة فما أعجب ... إلا من راغب فى ازديادوقال - سبحانه - ( فِي كَبَد ) للإِشعار بأنه لشدة مقاساته ومكابدته للمشاق والمتاعب ، وعدم انفكاكه عنها . . كالظِرف بداخل المظروف فهو فى محن ومتاعب ، حتى يصير إلى عالم آخر تغاير أحوالهُ أحوالَ هذا العالم .","5":"والاستفهام فى قوله - تعالى - بعد ذلك : ( أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ .يَقُولُ أَهْلَكْتُ مَالاً لُّبَداً . أَيَحْسَبُ أَن لَّمْ يَرَهُ أَحَدٌ ) للإِنكار والتوبيخ .أى : أيظن هذا الإِنسان الذى هو فى تعب ومشقة طول حياته ، أنه قد بلغ من القوة والمنعة . . بحيث لا يقدر عليه أحد .إن كان يتوهم ذلك ، فهو فى ضلال مبين ، لأن الله - تعالى - الذى خلقه ، قادر على إهلاكه فى لمح البصر ، وقادر على أن يسلط عليه من يذله ، ويقضى عليه .ويدخل فى هذا التوبيخ دخولا أوليا ، أولئك المشركون الذين اغتروا بقوتهم ، فآذوا النبى صلى الله عليه وسلم وأصحابه إيذاء شديداً .","6":"ثم حكى - سبحانه - جانبا من أقوال هذا النوع الجاحد المغرور من بنى آدم فقال : ( يَقُولُ أَهْلَكْتُ مَالاً لُّبَداً ) أى : يقول هذا الإِنسان المغرور بقوته ، والمفتون بماله ، المتفاخر بما هو معه من حطام الدنيا . يقول - على سبيل التباهى والتعالى على غيره - لقد أنفقت مالا كثيرا ، فى عداوة النبى صلى الله عليه وسلم ، وفى إيذاء أتباعه ، وفى غير ذلك من الوجوه التى كان أهل الجاهلية يظنونها خيرا ، وما هى إلا شر محض . وعبر - سبحانه - عن إنفاق هذا الشقى لما له بقوله : ( يَقُولُ أَهْلَكْتُ . . . ) للإِشعار ، بأن ما أنفقه من مال هو شئ هالك ، لأنه لم ينفق فى الخير ، وإنما أنفق فى الشر .والمال اللُّبَد : هو المال الكثير الذى تلبد والتصق بعضه ببعض لكثرته وهو جمع لُبْدة - بضم اللام وسكون الباء - كغرفة وغرف ، وهى ما تلبد من صوف أو شعر ، أى : تجمع والتصق بعضه بعض .","7":"وقوله - سبحانه - : ( أَيَحْسَبُ أَن لَّمْ يَرَهُ أَحَدٌ ) توبيخ لهذا الغرور إثر توبيخ ، وتجهيل فى أعقاب تجهيل . أى : أيظن هذا الجاهل المغرور ، حين أنفق المال الكثير فى المعاصى والسيئات ، أن الله - تعالى - غير مطلع عليه؟ إن كان يظن ذلك فهو فى نهاية الجهالة وانطماس البصيرة ، لأن الله - تعالى - مطلع عليه ، ولا تخفى عليه خافية فى الأرض ولا فى السماء ، وسيحاسبه على ذلك حسابا عسيرا .وفى الحديث الشريف : لن تزل قدما عبد يوم القيامة حتى يسأل عن أربع : عن شبابه فيم أبلاه ، وعن عمره فيم أفناه ، وعن ماله من أين اكتسبه ، وفيم أنفقه .","8":"ثم ساق - سبحانه - بعد ذلك جانبا من مظاهر نعمه ، على هذا الإِنسان الجاهل والمغرور . فقال - تعالى - : ( أَلَمْ نَجْعَل لَّهُ عَيْنَيْنِ . وَلِسَاناً وَشَفَتَيْنِ . وَهَدَيْنَاهُ النجدين ) .والاستفهام هنا للتقرير ، لأن الله - تعالى - قد جعل له كل ذلك ، ولكنه لم يشكر الله - تعالى - على هذه النعم ، بل قابلها بالجحود والبطر . .أى : لقد جعلنا لهذا الإِنسان عينين ، يبصر بهما .","9":"وجعلنا له لسانا ينطق به ، وشفتين - وهما الجلدتان اللتان تستران الفم والأسنان - تساعدانه على النطق الواضح السليم .واقتصر - سبحانه - على العينين ، لأنهما أنفع المشاعر ، ولأن المقصود إنكار ظنه أنه لم يره أحد ، ولأن الإِبصار حاصل بذاتهما .وذكر - سبحانه - اللسام وذكر معه الشفتين ، للدلالة على أن النطق السليم ، لا يتأتى إلا بوجودهما معا ، فاللسان لا ينطق نطقا صحيحا بدون الشفتين ، وهما لا ينطقان بدونه .","10":"وقوله - تعالى - : ( وَهَدَيْنَاهُ النجدين ) بيان لنعمة أخرى هى أجل النعم وأعظمها .والنجد : الأرض المرتفعة ، وجمعه نجود ، ومنه سميت بلاد نجد بهذا الاسم ، لأنها مرتفعة عن غيرها . . والمراد بالنجدين هنا : طريق الخير . وطريق الشر ، أى : وهدينا هذا الإِنسان وأرشدناه إلى طريق الخير والشر ، عن طريق رسلنا الكرام ، وعن طريق ما منحناه من عقل ، يميز به بين الحق والباطل ، ثم وهبناه الاختيار لأحدهما ، كما قال - تعالى - : ( إِنَّا هَدَيْنَاهُ السبيل إِمَّا شَاكِراً وَإِمَّا كَفُوراً ) قال بعض العلماء : وكأنهما إنما سميا نجدين - أى : سبيل الخير والشر : لأنهما لما وضحت الدلائل ، وقربت الحجج ، وظهرت البراهين ، جعلا كالطريق المرتفعة العالية ، فى أنها واضحة لذوى الأبصار .أو إنما سميا بذلك ، للإِشارة إلى أن كل منهما وعورة يشق معها السلوك ، ولا يصبر عليها إلا من جاهد نفسه وراضها ، وليس سلوك طريق الشر بأهون من سلوك الخير ، بل الغالب أن يكون طريق الشر ، أشق وأصعب ، وأحوج إلى الجهد . .","11":"وبعد بيان هذه النعم الجليلة التى أنعم الله بها - سبحانه - على الإِنسان ، أتبع - سبحانه - ذلك بحضه على المداومة على فعل الخير ، وعلى إصلاح نفسه ، فقال - تعالى - : ( فَلاَ اقتحم العقبة ) للتفريع على ما تقدم ، والمقصود بهذه الآية الحض على فعل الخير بدل الشر .وقوله : ( اقتحم ) من الاقتحام للشئ ، بمعنى دخوله بشدة . يقال : اقتحم الجنود أرض العدو ، إذا دخلوها بقوة وسرعة ، وبدون مبالاة بارتكاب المخاطر .والعقبة فى الأصل : الطريق الوعر فى الجبل ، والمراد بها هنا : مجاهدة النفس ، وقسرها على مخالفة هواها وشهوتها ، وحملها على القول والفعل الذى يرضى الله - تعالى - .والمعنى : لقد جعلنا للإِنسان عينين ولسانا وشفتين . وهديناه النجدين . فهلا بعد كل هذه النعم ، فعل ما يرضينا ، بأن جاهد نفسه وهواه ، وبأن قدم ماله فى فك الرقاب ، وإطعام اليتامى والمساكين .قال الجمل : وقوله : ( فَلاَ اقتحم العقبة ) أى : فهلا اقتحم العقبة ، فلا بمعنى هلا التى للتحضيض . أى : الذى أنفق ماله فى عداوة النبى صلى الله عليه وسلم هلا أنفقه فى اقتحام العقبة فيأمن . .وقد استعيرت العقبة لمجاهدة النفس ، وحملها على الإِنفاق فى سبيل الخير ، لأن هذه الأعمال شاقة على النفس ، فجعلت كالذى يتكلف سلوك طريق وعر . .ويصح أن تكون \" لا \" هنا ، على معناها الحقيقى وهو النفى ، فيكون المعنى : أن هذا الإِنسان الذى جعلنا له عينين .. لم يشكرنا على نعمنا ، فلا هو اقتحم العقبة ، ولا هو فعل شيئا ينجيه من عذابنا .وإلى هذا المعنى أشار صاحب الكشاف بقوله : قوله ( فَلاَ اقتحم العقبة ) يعنى : فلم يشكر تلك الأيادى والنعم بالأعمال الصالحة : من فك الرقاب ، وإطعام اليتامى والمساكين . . بل غمط النعم ، وكفر بالمنعم . .فإن قلت : قلما تقع \" لا \" الداخلة على الماضى ، غير مكررة ، فما لها لم تكرر فى الكلام الأفصح؟ قلت : هى متكررة فى المعنى ، لأن المعنى ( فَلاَ اقتحم العقبة ) . . فلا فكَّ رقبة ، ولا أطعم مسكينا . ألا ترى أنه فسر اقتحام العقبة بذلك . .","12":"والاستفهام فى قوله - سبحانه - : ( وَمَآ أَدْرَاكَ مَا العقبة ) لتفخيم شأنها ، والتهويل من أمرها ، والتشويق إلى معرفتها .والكلام على حذف مضاف ، والتقدير : وما أدراك ما اقتحام العقبة؟","13":"ثم فسر - سبحانه - ذلك بقوله : ( فَكُّ رَقَبَةٍ ) . والمراد بفك الرقبة إعتاقها وتخليصها من الرق والعبودية . إذ الفك معناه : تخليص الشئ من الشئ . .وقد ساق الإِمام ابن كثير عند تفسيره لهذه الآية ، جملة من الأحاديث التى وردت فى فضل عتق الرقاب ، وتحريرها من الرق . .ومن هذه الأحاديث قوله صلى الله عليه وسلم \" من أعتق رقبة مؤمنة ، أعتق الله بكل إِرْبِ منها - أى عضو منها - إربا منه من النار . . . \" .وقوله صلى الله عليه وسلم : \" ومن أعتق رقبة مؤمنة فهى فكاكه من النار . . \" .وقراءة الجمهور ( فَكُّ رَقَبَةٍ ) برفع \" فك \" وإضافته إلى \" رقبة \" .وقرأ ابن كثير وأبو عمرو والكسائى : \" فك \" بفتح الكاف على أنه فعل ماض ، ونصب لفظ \" رقبة \" على أنه مفعول به .وقد ذهب جمع من المفسرين إلى أن المراد بفك الرقبة : أن يخلص الإِنسان نفسه من المعاصى والسيئات ، التى تكون سببا فى دخوله النار .","14":"وقوله - سبحانه - : ( أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ ) بيان لفضيلة ثانية من الفضائل التى تؤدى إلى مجاهدة النفس ، وحملها على طاعة الله - تعالى - .والمسغية : المجاعة ، مصدر ميميى بمعنى السَّغَب ، يقال : سغب الرجل - كفرح ونصر - إذا أصابه الجوع . ووصف اليوم بذلك على سبيل المبالغة كما فى قولهم : نهارة صائم . .وقرأ ابن كثير وأبو عمرو والكسائى \" أطعم \" بصيغة الفعل الماضى .أى : اقتحام العقبة . أى : التمكن من حمل النفس على طاعة الله - تعالى - يتمثل فى فك الرقاب . وفى إطعام المحتاجين فى يوم يشتد فيه جوعهم .","15":"وقوله - سبحانه - : ( يَتِيماً ذَا مَقْرَبَةٍ . أَوْ مِسْكِيناً ذَا مَتْرَبَة ) بيان لفضيلة ثالثة من الفضائل التى تؤدى إلى رضا الله - تعالى - .وقوله : ( يَتِيماً ) منصوب على أنه مفعول به لقوله \" إطعام \" أو أطعم على القراءة الثانية .واليتيم : هو الشخص الذى مات أوبه وهو صغير . .والمقربة : بمعنى القرابة ، مصدر ميمى ، من قرب فلان من فلان ، إذا كان بينهما نسب قريب . .والمتربة : الحاجة والافتقار الشديد ، مصدر ميمى من ترب الرجل - كطرب - إذا افتقر ، حتى لكنه قد لصق بالتراب من شدة الفقر ، وأنه ليس له مأوى سوى التراب .وأما قولهم : أترب فلان ، فمعناه استغنى ، حتى لكأن ماله قد صار كالتراب من كثرته .أى : اقتحام العقبة من أكبر مظاهره : ك الرقاب ، وإطعام الطعام لليتامى الأقارب .","16":"وللمساكين المحتاجين إلى العون والمساعدة .وخص - سبحانه - الإطعام بكونه فى يوم ذى مجاعة ، لأن إخراج الماء فى وقت القحط ، أثقل على النفس ، وأوجب لجزيل الأجر ، كما قال - تعالى - : ( لَن تَنَالُواْ البر حتى تُنْفِقُواْ مِمَّا تُحِبُّونَ ) وقيد - سبحانه - اليتيم بكونه ذا مقربة ، لأنه فى هذه الحالة يكون له حقان : حق القرابة ، وحق اليتم ، ومن كان كذلك فهو أولى بالمساعدة من غيره .","17":"وقوله - تعالى - : ( ثُمَّ كَانَ مِنَ الذين آمَنُواْ وَتَوَاصَوْاْ بالصبر وَتَوَاصَوْاْ بالمرحمة ) معطوف على قوله - تعالى - قبل ذلك : ( فَلاَ اقتحم العقبة . . . ) .و \" ثم \" هنا للتراخى الرتبى ، للدلالة على أن ما بعدها أصل لقبول ما قبلها .والمعنى : هلا كان هذا الإِنسان ممن فكوا الرقاب ، وأطعموا لليتامى والمساكين . . ثم كان - فضلا عن كل ذلك - من الذين آمنوا بالله - تعالى - إيمانا حقا ، وممن أوصى بعضهم بعضا بفضيلة الصبر ، وفضيلة التراحم والتعاطف .لقد كان من الواجب عليه . . لو كان عاقلا - أن يكون من المؤمنين الصادقين ، ولكنه لتعاسته وشقائه وغروره ، لم يكن كذلك ، لأنه لا هو اقتحم العقبة ، ولا هو آمن . .وخص - سبحانه - من أوصاف المؤمنين تواصيهم بالصبر ، وتواصيهم بالمرحمة ، لأن هاتين الصفتين على رأس الصفات الفاضلة بعد الإِيمان بالله - تعالى - :","18":"واسم الإِشارة فى قوله : ( أولئك أَصْحَابُ الميمنة ) يعود على الذين آمنوا وتواصوا بالصبر ، وتواصوا بالمرحمة . أى : أولئك الموصوفون بتلك الصفات الكريمة ، هم أصحاب الجهة اليمنى التى فيها السعداء الذين يؤتون كتابهم بأيمانهم ، فالمراد بالميمنة : جهة اليمين . .","19":"ثم بين - سبحانه - بعد ذلك سوء عاقبة الكافرين فقال : ( والذين كَفَرُواْ بِآيَاتِنَا ) أى : الدلالة على وحدانيتا وقدرتنا ( هُمْ أَصْحَابُ المشأمة ) أى : هم فى جهة الشمال التى فيها الأشقياء ، أو هم أصحاب الشؤم على أنفسهم بسبب إصرارهم على كفرهم ، .","20":"( عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ ) أى : عليهم نار مغلقة بحيث لا يستطيعون الخروج منها ، تقول آصدت الباب وأوصدته ، إذا أحكمت غلقه ، والاسم فيهما ، الإِصاد والوصاد . .نسأل الله - تعالى - أن يجعلنا من أصحاب الميمنة .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"91":{"1":"افتتح - سبحانه - هذه السورة الكريمة ، بالقسم بكائنات عظيمة النفع ، جليلة القدر ، لها آثارها فى حياة الناس والحيوان والنبات ، ولها دلالتها الواضحة على وحدانيته - تعالى - وكمال قدرته ، وبديع صنعه .فقال - سبحانه - : ( والشمس وَضُحَاهَا ) والضحى الوقت الذى ترتفع فيه الشمس بعد إشراقها ، فتكون أكمل ما تكون ضياء وشعاعا .فالمراد بضحاها : ضؤوها - كما يرى مجاهد - ، أو النهار كله - كما اختار قتادة وغيره - ، أو حرها - كما قال مقاتل - .وهذه الأقوال لا تنافر بينها ، لأن لفظ الضحى فى الأصل ، يطلق على الوقت الذى تنبسط فيه الشمس ، ويمتد النهار ، تقولك ضَحِى فلان يَضْحَى - كرضى يرضى - ، إذا برز للشمس ، وتعرض لحرها ، ومنه قوله - تعالى - : ( إِنَّ لَكَ أَلاَّ تَجُوعَ فِيهَا وَلاَ تعرى . وَأَنَّكَ لاَ تَظْمَأُ فِيهَا وَلاَ تضحى ).","2":"وقوله - تعالى - : ( والقمر إِذَا تَلاَهَا ) أى : تبعها ، تقول : فلان تلا فلانا يتلوه ، إذا تبعه ، قال بعض العلماء : فأما أن القمر تابع للشمس فيحتمل معنيين : أحدهما : أنه تال لها فى ارتباط مصالح الناس ، وتعلق منافع هذا العالم بحركته ، وقد دل علم الهيئة على أن بين الشمس والقمر من المناسبة ما ليس بين غيرهما من الكواكب . وثانيهما : أن القمر يأخذ نوره ويستمده من نور الشمس . وهذا قول الفراء قديما ، وقد قامت الأدلة عند علماء الهيئة والنجوم ، على أن القمر يستمد ضوءه من الشمس . .وقال الشيخ ابن عاشور : وفى الآية إشارة إلى أن نور القمر ، مستفاد من نور الشمس ، أى : من توجه أشعة الشمس إلى ما يقابل الأرض من القمر ، وليس نيرا بذاته ، وهذا إعجاز علمى من إعجاز القرآن . .","3":"وقوله - سبحانه - : ( والنهار إِذَا جَلاَّهَا ) أى : جلى الشمس وأظهرها وكشفها للناظرين .قال الآلوسى : وقوله : ( والنهار إِذَا جَلاَّهَا ) أى : جلى النهار الشمس ، أى : أظهرها ، فإنها تنجلى وتظهر إذا انبسط النهار ، ومضى منه مدة ، فالإِسناد مجازى كالإِسناد فى نحو : صام نهاره .وقيل : الضمير المنصوب يعود إلى الأرض ، وقيل : إلى الدنيا ، والمراد بها وجه الأرض ، وقيل : إلى الظلمة ، وجلاها حينئذ بمعنى أزالها ، وعدم ذكر المرجع على هذه الأقوال للعلم به .والأول أولى ، لذكر المرجع واتساق الضمائر . .","4":"وقوله - سبحانه - : ( والليل إِذَا يَغْشَاهَا ) أى : يغشى الليلُ الشمسَ فيغطى ضوءها ، فالضمير فى يغشاها يعود إلى الشمس .وقيل : يعود إلى الدنيا ، وقيل : إلى الأرض أى : يغشى الليل الدنيا والأرض بظلامه .والحق أن فى قوله - تعالى - ( جَلاَّهَا ) و ( يَغْشَاهَا ) إشارة واضحة إلى أن الضمير فيهما يعود إلى الشمس ، إذ النهار يجلى الشمس ويكشفها أتم انكشاف ، والليل يزيل ضوءها ويستره ، فنسب - سبحانه - إلى النهار ما يلائمه بالنسبة للشمس ، وكذلك الحال بالنسبة لليل .","5":"ثم قال - تعالى - : ( والسمآء وَمَا بَنَاهَا ) أى : وحق السماء وحق من بناها وأنشأها وأوجدها على تلك الصورة البديعة الرائعة .فما هنا اسم موصول بمعنى مَنْ ، والمراد بمن بناها : الله - عز وجل - وأوثرت على مَنْ التى تأتى للعاقل كثيرا ، لإِشعارها معنى الوصفية . أى : وحق السماء ، وحق القادر العظيم الذى بناها وأوجدها على هذه الهيئة الجميلة الدقيقة .وقد أشار إلى ذلك صاحب الكشاف فقال : و الوجه أن تكون \" ما \" موصولة - أى : فى هذه الآية وما بعدها - وإنما أوثرت على مَنْ لإِرادة معنى الوصفية ، كأنه قيل : والسماء والقادر العظيم الذى بناها .ومنهم من يرى أن \" ما \" هنا مصدرية ، فيكون المعنى : وحق السماء وبنيانها .","6":"وقوله - تعالى - : ( والأرض وَمَا طَحَاهَا ) أى : وحق الأرض ومن بسطها من كل جانب ، وجعلها مهيأة للاستقرار عليها : يقال : طحى فلان الشئ ودحاه ، إذا بسطه ووسعه .","7":"وقوله - سبحانه - : ( وَنَفْسٍ وَمَا سَوَّاهَا ) أى : وحق النفوس ، وحق من أنشأها من العدم فى أحسن تقويم ، وجعلها مستعدة لتلقى ما يكملها ويصحلها .ويبدو أن المراد بالنفس هنا : القوة المدبرة للإِنسان ، يكون المقصود بتسويتها . منحها القوى الكثيرة المتنوعة ، التى توصلها إلى حسن المعرفة ، والتمييز بين الخير والشر ، والنفع والضر ، والهدى والضلال .","8":"قالوا : وقوله : - تعالى - بعد ذلك : ( فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا ) يشير إلى أن المراد بالنفس فى قوله - تعالى - : ( وَنَفْسٍ وَمَا سَوَّاهَا ) القوة المدبرة للإِنسان ، والتى عن طريقها يدرك الأمور إدراكا واضحا ، ويختار منها ما يناسب استعداده .والإِلهام : هو التعريف والإِفهام للشئ ، أو التمكين من فعله أو تركه ، والفجور : فعل ما يؤدى إلى الخسران والشقاء . والتقوى : هى الإِتيان بالأقوال والأفعال التى ترضى الله - تعالى - وتصون الإِنسان من غضبه -عز وجل - .أى : فعرف - سبحانه - النفس الإِنسان و ألهمها وأفهمها معنى الفجور والتقوى ، وبين لها حالهما ، ووضح لها ما ينبغى أن تفعله وما ينبغى أن تتركه ، من خير أو شر ، ومن طاعة أو معصية ، بحيث يتميز عندها الرشد من الغى ، والخبيث من الطيب .ومن الآيات التى وردت فى هذا المعنى قوله - تعالى - : ( وَهَدَيْنَاهُ النجدين ) وقوله - عز وجل - : ( إِنَّا هَدَيْنَاهُ السبيل إِمَّا شَاكِراً وَإِمَّا كَفُوراً ) وقدم - سبحانه - هنا الفجور على التقوى ، مراعاة لأحوال المخاطبين بهذه السورة ، وهم كفار قريش ، الذين كانت أعمالهم قائمة على الفجور والخسران ، بسبب إعراضهم عما جاءهم به رسول الله صلى الله عليه وسلم من حق وبر .","9":"وقوله - سبحانه - : ( قَدْ أَفْلَحَ مَن زَكَّاهَا . وَقَدْ خَابَ مَن دَسَّاهَا ) يصح أن يكون جوابا للقسم . والفلاح : الظفر بالمطلوب .والتزكية : التزود من الخير والطاعة ، والحرص على تطهير النفس من كل سوء .","10":"وقوله : ( دَسَّاهَا ) أى : نقصها وأخفاها بالمعاصى والآثام . وأصل فعل دسَّى : دسَّسَ ، فلما اجتمع ثلاث سينات ، قلبت الثالثة ياء ، يقال : دس فلان الشئ إذا أخفاه وكتمه .والمعنى : وحق الشمس وضحاها ، وحق القمر إذا تلاها ، وحق النفس وحق من سواها ، وجعلها متمكنة من معرفة الخير والشر . لقد أفلح وفاز وظفر بالمطلوب ، ونجا من المكروه ، من طهر نفسه من الذنوب والمعاصى . وقد خاب وخسر نفسه . وأوقعها فى التهلكة ، من نَقَصها وأخفاها وأخملها وحال بينها وبين فعل اليخر بسبب ارتكاب الموبقات والشرور .قال الآلوسى ما ملخصه : وقوله - تعالى - : ( قَدْ أَفْلَحَ مَن زَكَّاهَا ) جواب القسم . وإليه ذهب الزجاج وغيره . والأصل : لقد أفلح ، فحذفت اللام لطول الكلام المقتضى للتخفيف . وفاعل من \" زكاها \" ضمير \" مَنْ \" والضمير المنصوب للنفس . .ويرى المحققون من العلماء أن جواب القسم محذوف ، للعلم به ، فكأنه - سبحانه - قد قال : وحق الشمس وضحاها ، وحق القمر إذا تلاها . . ليقعن البعث والحساب والجزاء ، أو لتحاسبن على أعمالكم ، ودليل هذا الجواب قوله - تعالى - بعد ذلك : ( كَذَّبَتْ ثَمُودُ بِطَغْوَاهَآ )","11":"( كَذَّبَتْ ثَمُودُ بِطَغْوَاهَآ )لأن هذه الآية الكريمة وما بعدها ، تدل على أن الله - تعالى - قد اقتضت سنته ، أن يحاسب من فسق عن أمره ، وأصر على تكذيب رسله .وعلى هذا سار صاحب الكشاف ، فقد قال : فإن قلت : فأين جواب القسم؟ قلت : هو محذوف ، تقديره : ليُدَمْدِ مَنَّ الله عليهم ، أى : على مكة لتكذيبهم رسول الله صلى الله عليه وسلم ، كما دمدم على قبيلة ثمود لأنهم كذبوا صالحا - عليه السلام - وأما قوله : ( قَدْ أَفْلَحَ مَن زَكَّاهَا ) فكلام تابع لقوله : ( فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا ) على سبيل الاستطراد ، وليس من جواب القسم فى شئ . .وقد أقسم الله - تعالى - بهذه الكائنات المختلفة ، والتى لها مالها من المنافع بالنسبة للإِنسان وغيره ، لتأكيد وحدانيته ، وكمال قدرته ، وبليغ حكمته .وبدأ - سبحانه - بالشمس ، لأنها أعظم هذه الكائنات ، وللتنويه بشأن الإِسلام ، وأن هديه كضياء الشمس ، الذى لا يترك للظلام أثرا .وقد ساق الإِمام ابن كثير عند تفسيره لهذه الآيات بعض الأحاديث ، منها ما رواه الطبرانى عن ابن عباس - رضى الله عنهما - قال : \" كان رسول الله صلى الله عليه وسلم إذا مر بهذه الآية : ( وَنَفْسٍ وَمَا سَوَّاهَا . فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا ) وقف ثم قال : \" اللهم آت نفسى تقواها أنت وليها ومولاها . وخير من زكاها \" وعن أبى هريرة رضى الله عنه . قال : \" سمعت النبى يقرأ ( فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا ) قال : \" اللهم آت نفسى تقواها ، وزكها أنت خير من زكاها ، وليها ومولاها \" \" .وبعد هذا الحديث الطويل المؤكد بالقسم ، والدال على وحدانيته ، وبديع صنعه ..","12":"أتبع ذلك ببيان ما حل بالمكذبين السابقين ، ليكون هذا البيان عبرة وعظة للمشركين المعاصرين للنبى ، فقال - تعالى - : ( كَذَّبَتْ ثَمُودُ بِطَغْوَاهَآ . إِذِ انبعث أَشْقَاهَا . فَقَالَ لَهُمْ رَسُولُ الله نَاقَةَ الله وَسُقْيَاهَا . فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنبِهِمْ فَسَوَّاهَا . وَلاَ يَخَافُ عُقْبَاهَا ) .والمراد بثمود : تلك القبيلة التى أرسل الله - تعالى - إلى أهلها صالحا - عليه السلام - لكى يأمرهم بإخلاص العبادة لله وحده . ومفعول \" كذبت \" محذوف للعلم به .والباء فى قوله \" بطغواها \" للسببية ، والطَّغْوَى : اسم مصدر من الطغيان ، وهو مجاوزة الحد المعتاد .أى : كذبت قبيلة ثمود - نبيهم صالحا - عليه السلام بسبب طغيانهم وإفراطهم فى الجحود والتكبر والعناد : وقيل : إن الباء للتعدية ، والطغوى : اسم للعذاب الذى نزل به ، والذى توعدهم به نبيهم .أى : كذبت ثمود بعذابها ، الذى توعدهم رسولهم به ، إذا استمروا فى كفرهم وطغيانهم .والظرف فى قوله - سبحانه - : ( إِذِ انبعث أَشْقَاهَا ) متعلق بقوله ( طغواها ) ، لأن وقت انبعاث أشقاهم لقتل الناقة . هو أشد أوقات طغيانهم وفجورهم .وفعل \" انبعث \" مطاوع بعث ، تقول : بعثته فانبعث ، كما تقول : كسرته فانكسر . ويصح أن يكون متعلقا بقوله : ( كذبت ) .وقوله ( أَشْقَاهَا ) أى : أشقى تلك القبيلة ، وهو قُدَار - بزنة غراب - بن سالف ، الذى يضرب به المثل فى الشؤم ، فيقال : فلان أشأم من قدار .أى : كذبت ثمود نبيها ، بسبب طغيانها ، وقت أن أسرع أشقى تلك القبيلة ، وهو قدار بن سالف ، لعقر الناقة التى نهاهم نبيهم عن مسها بسوء .وعبر - سبحانه - بقوله : ( انبعث ) للإِشعار بأنه قام مسرعا عندما أرسله قومه لقتل الناقة ، ولم يتردد فى ذلك لشدة كفره وجحوده .","13":"وقوله - تعالى - : ( فَقَالَ لَهُمْ رَسُولُ الله نَاقَةَ الله وَسُقْيَاهَا ) أى : فقال لهم رسول الله - تعالى - إليهم . وهو صالح - عليه السلام - على سبيل التحذير والإِنذار : احذروا عقر ناقة الله - تعالى - ، واحذروا سقياها ، أى : الوقت المحدد لشرابها فلا تمنعوها فيه من الشرب ، فإن لها يوم لا تشاركونها فيه الشرب ، وإن لكم يوما آخر هى لن تشارككم فيه . وقد قال لهم صالح - عليه السلام - هذا الكلام ، عندما شعر بأنهم قد بيتوا النية على عقرها .فالفاء فى قوله - تعالى - : ( فَقَالَ لَهُمْ . . . ) عاطفة على قوله ( كذبت ) لإِفادة الترتيب والتعقيب . .أى : قال لهم ذلك فى أعقاب شعوره بتصميمهم على تكذيبه ، وعلى قتل الناقة .ولفظ \" ناقة \" منصوب على التحذير ، والكلام على حذف مضاف . أى : احذروا عقر ناقة الله ، وأضيفت إلى لفظ الجلالة ، على سبيل التشريف لها ، لأنها قد جعلها - سبحانه - معجزة لنبيه صالح - عليه السلام - ودليلا على صدقه .وقوله : ( وَسُقْيَاهَا ) معطوف على ناقة الله ، وهو منصوب - أيضا - على التحذير .أى : احذروا أن تقتلوا الناقة ، واحذروا أن تشاركوها فى اليوم الخاص بشربها ، فضلا عن أن تؤذوها .","14":"وقوله - سبحانه - : ( فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنبِهِمْ فَسَوَّاهَا ) بيان لموقفهم السيئ من تحذير نبيهم لهم ، ولما أصابهم من عذاب مهلك بسبب هذا التكذيب .وقوله : ( فَدَمْدَمَ ) - بزنة فعلل - بمعنى تضعيف العذاب وترديده ، يقال : دمدمت على الشئ ، أى : أطبقت عليه ، ودمدم عليه القبر ، أى : أطبقه عليه .أى : فكذبت قوم صالح نبيهم ، وأصروا على هذا التكذيب ، وتجاوزوا ذلك إلى عقر الناقة التى نهاهم عن مسها بسوء . . فكانت نتيجة ذلك ، أن أهلكهم الله - تعالى - وأن أخذهم أخذ عزيز مقتدر ، فقد أطبق عليهم الأرض ، وسواها من فوقهم جميعا دون أن يفلت منهم أحد ، وصاروا كلهم تحت ترابها ، ونجى - سبحانه - صالحا ومن آمن معه . بفضله ورحمته .","15":"والضمير فى قوله - سبحانه - : ( وَلاَ يَخَافُ عُقْبَاهَا ) يعود إلى الله - تعالى - أى : ولا يخاف الله - تعالى -عاقبة ما فعله بهؤلاء الطغاة الأشقياء ، لأن الذى يخاف إنما هو المخلوق .أما الخالق لكل شئ ، فإنه - تعالى - لا يخاف أحدا ، لأنه لا يسأل عما يفعل ، ولأنه - تعالى - هو العادل فى أحكامه ، والضمير فى عقباها ، يعود إلى الفعلة أو إلى الدمدمة .ومنهم من جعل الضمير فى \" يخاف \" يعود إلى أشقاها ، أى : أن هذا الشقى قد أسرع إلى عقر الناقة دون أن يخشى سوء عاقبة فعله ، لطغيانه وجهله .نسأل الله - تعالى - أن يجعلنا جميعا من عباده الصالحين .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"92":{"1":"أقسم الله - سبحانه - فى افتتاح هذه السورة بثلاثة أشياء ، على أن أعمال الناس مختلفة .أقسم - أولا - بالليل فقال : ( والليل إِذَا يغشى ) أى : وحق الليل إذا يغشى النهار ، فيغطى ضياءه ، ويذهب نوره ، ويتحول الكون معه من حالة إلى حالة ، إذ عند حلول الليل يسكن الخلق عن الحركة ، ويأوى كل إنسان أو حيوان أو مأواه ، ويستقبلون النوم الذى فيه ما فيه من الراحة لأبدانهم ، كما قال - تعالى - : ( وَجَعَلْنَا الليل لِبَاساً . وَجَعَلْنَا النهار مَعَاشاً ).","2":"وأقسم - ثانيا - بالنهار فقال : ( والنهار إِذَا تجلى ) أى : وحق النهار حين ينكشف ويظهر ، ويزيل الليل وظلمته ، ويخرج الناس معه ليباشروا أعمالهم المتنوعة .","3":"وأقسم - ثالثا - بقوله : ( وَمَا خَلَقَ الذكر والأنثى ) و \" ما \" هنا يصح أن تكون موصولة ، بمعنى الذى ، فيكون - سبحانه - قد أقسم بذاته ، وجاء التعبير بما ، للدلالة على الوصفية ، ولقصد التفخيم .فكأنه - تعالى - يقول : وحق الخالق العظيم ، الذى لا يعجزه شئ ، والذى خلق نوع الذكور ، ونوع الإِناث من ماء واحد .ويصح أن تكون \" ما \" هنا حرفا مصدريا ، فيكون المعنى : وحق خَلْقِ الذكر والأنثى ، وعليه يكون - سبحانه - قد أقسم بفعل من أفعاله التى تدل على كمال قدرته ، وبديع صنعته ، حيث أوجد الذكور والإِناث من ماء واحد ، كما قال - سبحانه - : ( وَأَنَّهُ خَلَقَ الزوجين الذكر والأنثى . مِن نُّطْفَةٍ إِذَا تمنى ) وحيث وهب - سبحانه - الذكور لمن يشاء ، ووهب الإِناث لمن يشاء ، وجعل العقم لمن يشاء .","4":"وقوله - تعالى - : ( إِنَّ سَعْيَكُمْ لشتى ) هو جواب القسم . وشتى جمع شتيت . مثل : جريح وجرحى ، ومريض ومرضى . والشئ الشتيت : هو المتفرق المتناثر بعضه عن بعض ، من الشتات بمعنى الابتعاد والافتراق .والمعنى : وحق الليل إذا يغشى النهار فيستر ضياءه ، وحق النهار إذا تجلى وأسفر وأزال الليل وظلامه ، وحق الخالق العظيم القادر الذى أوجد الذكور والإِناث .وحق كل ذلك ، إن أعمالكم ومساعيكم - أيها الناس - فى هذه الحياة ، لهى ألوان شتى ، وأنواع متفرقة ، منها الهدى ومنها الضلال ، ومنها الخير ، ومنها الشر ، ومنها الطاعة ، ومنها المعصية . . وسيجازى - سبحانه - كل إنسان على حسب عمله .وحذف مفعول \" يغشى \" للتعميم ، أى يغشى كل شئ ويواريه بظلامه .وأسند - سبحانه - التجلى إلى النهار ، على سبيل المدح له بالاستنارة والإِسفار .والمراد بالسعى : العمل . وقوله \" سعيكم \" مصدر مضاف فيفيد العموم فهو فى معنى الجمع أى : إن مساعيكم لمتفرقة .قال القرطبى : السعى : العمل ، فساع فى فكاك نفسه ، وساع فى عطبها ، يدل عليه قوله صلى الله عليه وسلم : \" الناس غاديان : فمبتاع نفسه فمعتقها ، وبائع نفسه فموبقها \" .","5":"ثم فصل - سبحانه - ما أجمله فى قوله : ( إِنَّ سَعْيَكُمْ لشتى ) فقال : ( فَأَمَّا مَنْ أعطى واتقى . وَصَدَّقَ بالحسنى . فَسَنُيَسِّرُهُ لليسرى . وَأَمَّا مَن بَخِلَ واستغنى . وَكَذَّبَ بالحسنى . فَسَنُيَسِّرُهُ للعسرى . وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تردى ) والحسنى تأنيث الأحسن ، وهى فة لموصوف محذوف .أى : ( فَأَمَّا مَنْ أعطى واتقى ) حق الله - تعالى - ، بأن أنفق من ماله فى وجوه الخير : كإعتاق الرقاب ، ومساعدة المحتاجين . . ( واتقى ) المحارم والمعاصى.","6":"( وَصَدَّقَ بالحسنى ) أى : وأيقن بالخصلة الحسنى ، وهى الإِيمان بكل ما يجب الإِيمان به ، أو أيقن بالملة الحسنى ، وهى ملة الإِسلام ، أو بالمثوبة الحسنى وهى الجنة .","7":"( فَسَنُيَسِّرُهُ لليسرى ) أى : فسنهيئه للخصلة التى توصله إلى اليسر والراحة وصلاح البال ، بأن نوفقه لأداء الأعمال الصالحة التى تؤدى إلى السعادة .وحذف مفعول \" أعطى واتقى \" للعلم بهما ، أى : أعطى ما كلفه الله - تعالى - به ، واتقى محارمه .","8":"( وَأَمَّا مَن بَخِلَ ) بماله فلم يؤد حقوق الله - تعالى - فيه ، ولم يبذل شيئا من ه فى وجوه البر . ( واستغنى ) أى : واستغنى عن ثواب الله - تعالى - ، وتطاول على الناس بماله وجاهه ، وآثر متع الدنيا على نعيم الآخرة . .","9":"( وَكَذَّبَ بالحسنى ) أى : وكذب بالخصلة الحسنى التى تشمل الإِيمان بالحق ، وبيوم القيامة وما فيه من حساب وجزاء .","10":"( فَسَنُيَسِّرُهُ للعسرى ) أى : فسنهيئه للخصلة التى توصله إلى العسر والمشقة والشدة ، بأن نجعله بسبب سوء اختياره ، يؤثر الغى على الرشد ، والباطل على الحق ، والبخل على السخاء ، فتكون عاقبته فرطا ، ونهايته الخسران والبوار .والمتأمل فى هذه الآيات الكريمة يراها ، وقد وصفت المؤمنين الصادقين بثلاث صفات هى جماع كل خير ، وأساس جميع الفضائل : وصفهم بالسخاء ، وبالخوف من الله - تعالى - ، وبالتصديق بكل ما يجب التصديق به ، ورتب على ذلك توفيقهم للخصلة الحسنى . . التى تنتهى بهم إلى الفوز والسعادة .ووصف - أيضا - أهل الفسوق والفجور بثلاث صفات ، هى أساس البلاء ، ومنبع الفساد ، ألا وهى : البخل ، والغرور ، والتكذيب بكل ما يجب الإِيمان به . . ورتب - سبحانه - على ذلك تهيئتهم للخصلة العسرى ، التى توصلهم إلى سوء المصير ، وشديد العقاب . .وقد ساق الإِمام ابن كثير عند تفسيره لهذه الآيات ، جملة من الأحاديث الشريفة ، فقال ما ملخصه : قوله : ( وَكَذَّبَ بالحسنى ) أى : بالجزاء فى الدار الآخرة ( فَسَنُيَسِّرُهُ للعسرى ) أى : لطريق الشر ، كما قال - تعالى - : ( وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصَارَهُمْ كَمَا لَمْ يُؤْمِنُواْ بِهِ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ ) والآيات فى هذا المعنى كثيرة ، ودالة على أن الله يجازى من قصد الخير بالتوفيق له ، ومن قصد الشر بالخذلان ، وكل ذلك بقدر مقدر ، والأحاديث الدالة على هذا المعنى كثيرة .منها : ما أخرجه البخارى عن على بن أبى طالب - رضى الله عنه - قال :\" كنا مع رسول الله صلى الله عليه وسلم فى بقيع الغرقد فى جنازة ، فقال : \" ما منكم من أحد إلا وقد كتب مقعدة من الجنة ، ومقعدة من النار \" فقالوا : يا رسول الله أفلا نتكل؟ فقال : \" اعملوا فكل ميسر لما خلق له \" ثم قرأ : ( فَأَمَّا مَنْ أعطى واتقى . . . ) إلى قوله : ( للعسرى ) \" .","11":"و \" ما \" فى قوله - سبحانه - : ( وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تردى ) يجوز أن تكون نافية . والتردى : السقوط من أعلى إلى أسفل . يقال : تردى فلان من فوق الجبل ، إذا سقط من أعلاه إلى أسفله ، والمراد به هنا : النزول إلى القبر بعد الموت ، أو السقوط فى النار بسبب الكفر والفسوق والعصيان ، من الردى بمعنى الهلاك .أى : ولا يغنى شيئا عن هذا الشقى الذى بخل واستغنى وكذب بالحسنى ، ماله وجاهه وكل ما كان يملكه فى الدنيا ، إذا سقط يوم القيامة فى النار .ويجوز أن تكون \" ما \" استفهامية : ويكون الاستفهام المقصود به الإِنكار والتوبيخ ، أى : وماذا يغنى عن هذا الشقى ماله بعد هلاكه ، وبعد ترديه فى جهنم يوم القيامة؟ إنه لن يغنى عنه شيئا ماله الذى بخل به فى الدنيا ، بل سيهوى فى جهنم دون أن يشفع له شافع ، أو ينصره ناصر ، وصدق الله إذْ يقول : ( وَنَرِثُهُ مَا يَقُولُ وَيَأْتِينَا فَرْداً ) وإن يقول : ( وَلَقَدْ جِئْتُمُونَا فرادى كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُمْ مَّا خَوَّلْنَاكُمْ وَرَاءَ ظُهُورِكُمْ . . . ).","12":"ثم بين - سبحانه - بعد ذلك ، أنه قد أعذر إلى عباده ، حيث وضح لهم طريق الخير وطريق الشر ، وكشف لهم عن حسن عاقبة من أعطى واتقى وصدق بالحسنى ، وسوء عاقبة من بخل واستغنى وكذب بالحسنى فقال - تعالى - : ( إِنَّ عَلَيْنَا للهدى . وَإِنَّ لَنَا لَلآخِرَةَ والأولى ) . أى : إن علينا - بمقتضى حكمتنا ورحمتنا بعبادنا - أن نبين لهم طريق الحق ، وطريق الباطل ، بواسطة رسلنا ، فمن شاء بعد ذلك فليؤمن فينال الثواب ، ومن شاء بعد ذلك فليكفر فيحل به العقاب ، لأننا نجازى كل إنسان على حسب عمله ، بعد أن هديناه النجدين ، وأرشدناه إلى سبيل الرشد وسبيل الغى .","13":"وإن لنا وحدنا كل ما فى الدنيا ، وكل ما فى الآخرة . إذ الخلق والأمر بيدنا ، والعطاء والمنع لا يملكه أحد سوانا ، وهذا الكون كله تحت تصرفنا وقدرتنا .","14":"والفاء فى قوله - سبحانه - : ( فَأَنذَرْتُكُمْ نَاراً تلظى ) للإفصاح عن مقدر ، لأنها تدل على مراعاة مضمون الكلام الذى قبلها ، وتأتى بعده بما يفصله ويزيده وضوحا . .وقوله : ( تلظى ) أى : تتوقد وتتوهج وتلتهب ، وأصله تتلظى ، فحذفت إحدى التاءين تخفيفا . أى : إذا كان الأمر كما ذكرت لكم ، من حسن عاقبة من أعطى واتقى ، ومن سوء عاقبة من بخل واستغنى ، ومن أن كل شئ تحت قدرتنا وتصرفنا .. فأكون بذلك قد حذرتكم من عاب عظيم يوم القيامة ، وخوفتكم من السقوط فى نار عظيمة تلتهب وتتوقد .","15":"وهذه النار ( لاَ يَصْلاَهَآ ) أى : لا يحترق بها ( إِلاَّ الأشقى ) أى : من اشتد شقاؤه بسبب إصراره على كفره وفجوره .","16":"وقوله - تعالى - : ( الذي كَذَّبَ وتولى ) صفة لهذا الشقى ، لزيادة التشنيع عليه ، والذم له . أى : سيحترق بهذه النار هذا الإِنسان الذى بلغ الغاية فى الشقاء والتعاسة ، والذى من صفاته أنه كذب بالحق ، وأعرض عن الطاعة . وسار فى طريق الكفر والجحود ، حتى أدركه الموت ، وهو على ذلك .","17":"وكعادة القرآن الكريم فى المقابلة بين الأشرار والأخيار ، وبين العسداء والأشقياء ، جاء الحديث بعد ذلك عن حال الأتقياء ، فقال - تعالى - ( وَسَيُجَنَّبُهَا الأتقى ) أى : وسيبتعد عن هذه النار المتأججة الأتقى ، وهو من بالغ فى صيانة نفسه عن كل ما يغضب الله - تعالى - ، وحرص كل الحرص على فعل ما يرضيه - عز وجل - .فالمراد بالأشقى والأتقى : الشديد الشقاء ، والشديد والتقوى .والتعبير بقوله : ( وَسَيُجَنَّبُهَا ) يشعر بابتعاده عنها ابتعادا تاما ، بحيث تكون النار فى جانب ، وهذا الأتقى فى جانب آخر ، كما قال - تعالى - : ( إِنَّ الذين سَبَقَتْ لَهُمْ مِّنَّا الحسنى أولئك عَنْهَا مُبْعَدُونَ . لاَ يَسْمَعُونَ حَسِيَسَهَا وَهُمْ فِي مَا اشتهت أَنفُسُهُمْ خَالِدُونَ ) والفعل \" جنب \" يتعدى إلى مفعولين ، أولهما هنا هو لفظ الأتقى ، الذى ارتفع على أنه نائب فاعل ، والمفعول الثانى هو الهاء .","18":"ثم وصف - سبحانه - هذا الإِنسان المبالغ فى تقواه وطاعته لربه فقال : ( الذي يؤتى ماله يتزكى ) أى : هذا الإِنسان الشديد التقوى من صفاته أنه يقد ماله لغيره ، وينفقه فى وجوه البر والطاعة ، رجاء أن يكون عند ربه زاكيا ناميا ، خاليا من شبهة الرياء والتفاخر ، وأملا فى أن يتطهر به من الذنوب .فقوله ( يتزكى ) فى محل نصب على الحال من فاعل ( يؤتى ) أى : يؤتى ماله حال كونه لا يطلب من وراء ذلك إلا تزكية ماله ، وتطهير نفسه .","19":"وقوله - سبحانه - : ( وَمَا لأَحَدٍ عِندَهُ مِن نِّعْمَةٍ تجزى . إِلاَّ ابتغآء وَجْهِ رَبِّهِ الأعلى ) بيان لبلوغه أسمى درجات الإِخلاص والنقاء .أى : أن هذا الإِنسان الكامل فى تقاه لا يفعل ما يفعل من وجوه الخيرات ، من أجل المجازاة لغيره على نعمة سلفت من هذا الغير له ، وإنما يفعل ما يفعل من أجل شئ واحد ، وهو طلب رضا الله - تعالى - والظفر بثوابه ، والإِخلاص لعبادته - سبحانه - .","20":"قال الآلوسى : وقوله : ( إِلاَّ ابتغآء وَجْهِ رَبِّهِ الأعلى ) منصوب على الاستثناء المنقطع من قوله : ( مِن نِّعْمَةٍ ) لأن الابتغاء لا يندرج فيها ، فالمعنى : لكنه فعل ذلك لابتغاء وجه ربه - سبحانه - وطلب رضاه ، لا لمكافأة لأحد على نعمة .وجوز أن يكون نصبه على أنه مفعول لأجله ، أى : لا يؤتى ماله لأجل شئ من الأشياء إلا لأجل طلب رضا ربه ، لا لأجل شئ آخر ، فهو استثناء مفرغ من أعم العلل والأسباب ..","21":"وقوله - سبحانه - : ( وَلَسَوْفَ يرضى ) المقصود به الوعد الصادق لهذا التقى ، بما يزيد فى سروره ، وفى قرة عينه .أى : ولسوف نعطى هذا التقى الذى أعطى واتقى وصدق بالحسنى ، من أجل الظفر برضا ربه - تعالى - لا من أجل شئ آخر . . لسوف نعطيه عطاء يرضيه ويسعده ويشرح صدره .هذا ، وأكثر المفسرين على أن هذه الآيات الكريمة نزلت فى شأن سيدنا أبو بكر الصديق - رضى الله عنه - .قال الإِمام ابن جرير ما ملخصه : وذكر أن هذه الآيات نزلت فى أبى بكر الصديق . . فقد كان يعتق العجائز من النساء إذا أسلمن ، ويشترى الضعفة من العبيد فيعتقهم ، فقال له أبوه : يا بنى ، أراك تعتق أناسا ضعفاء ، فلو أنك تعتق رجالا جلداء - أى : أشداء - يقومون معك ، ويمنعونك ، ويدفعون عنك .فقال أبو بكر : أى أبت . . إنما أريد ما عند الله ، فنزلت هذه الآيات . .وقال الإِمام ابن كثير : وقد ذكر غير واحد من المفسرين ، أن هذه الآيات قد نزلت فى أبى بكر الصديق - رضى الله عنه - حتى إن بعضهم حكى الإِجماع من المفسرين على ذلك ، ولا شك أنه داخل فيها ، وأولى الأمة بعمومها ، فإن لفظها لفظ العموم ، وهو قوله : ( وَسَيُجَنَّبُهَا الأتقى . الذى يُؤْتِي مَالَهُ يتزكى . . . ) ولكنه مقدم الأمة ، وسابقهم فى جميع هذه الأوصاف ، وسائر الأوصاف الحميدة ، فإنه كان صديقا ، تقيا ، كريما ، جوادا ، بذالا لماله فى طاعة مولاه ، ونصرة رسوله صلى الله عليه وسلم . .نسأل الله - تعالى - أن يحشرنا جميعا فى زمرة عباده الأتقياء الأنقياء .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"93":{"1":"قد ذكر المفسرون فى سبب نزول هذه السورة الكريمة روايات منها : ما أخرجه الإِمام البخارى ومسلم وغيرهما عن جندب بن سفيان قال : اشتكى رسول الله صلى الله عليه وسلم فلم يقم ليلة أو ليلتين ، فأتت امرأة - وفى رواية أنها أم جميل امرأة أبى لهب - فقالت : يا محمد ، ما أرى شيطانك إلا قد تركك . فأنزل الله - تعالى - : ( والضحى . والليل إِذَا سجى . مَا وَدَّعَكَ رَبُّكَ وَمَا قلى ) .وأخرج ابن أبى شيبة والطبرانى وابن مردويه ، من حديث خولة ، وكانت تخدم النبى صلى الله عليه وسلم \" أن جروا دخل تحت سرير رسول الله صلى الله عليه وسلم فمات ، فمكث النبى صلى الله عليه وسلم أياما لا ينزل عليه الوحى ، فقال صلى الله عليه وسلم يا خولة ماذا حدث فى بيتى ، إن جبريل لا يأتينى ، قالت خوله : فقلت يا نبى الله ما أتى علينا يوم خير منّا اليوم . فأخذ برده فلبسه ، وخرج ، فقلت فى نفسى لو هيأت البيت وكنسته ، فأهويت بالمكنسة تحت السرير ، فإذا بشئ ثقيل ، لم أزل به حتى بدا لى الجرو ميتا ، فأخذته بيدى ، فألقيته خلف الدار ، فجاء صلى الله عليه وسلم ترعد لحيته - وكان إذا نزل عليه الوحى أخذته الرعدة - فقال يا خولة دثرينى ، فأنزل الله - تعالى - هذه السورة . . \"وذكر بعضهم : إن جبريل - عليه السلام - أبطأ فى نزوله على النبى صلى الله عليه وسلم ، فقال المشركون : قد قلاه ربه وودعه . فأنزل الله - تعالى - هذه الآيات . .والضحى : هو وقت ارتفاع الشمس بعد إشراقها ، وهو وقت النشاط والحركة ، والإِقبال على السعى والعمل . . ولذا خص بالقسم به ، وقيل : المراد بالضحى هنا : النهار كله ، بدليل أنه جعل فى مقابلة الليل كله .والأول أولى : لأن الضحى يطلق على وقت انتشار ضياء الشمس حين ترتفع ، وتلقى بأشعتها على الكون ، ويبرز الناس لأعمالهم المتنوعة .ومعنى \" سجل \" : سكن . يقال : سجا الليل يسجو سجوا ، إذا سكن وهدأ وأسدل ظلامه على الكون . ويقال : تسجَّى فلان بملابسه ، إذا غطى بها جميع جسده ، ومنه قولهم : سُجِّى الميت تسجية ، إذا غطى بكفنه . .","2":"قال صاحب الكشاف : قوله : ( سجى ) أى : سكن وركد ظلامه . وقيل : ليلة ساجية . أى : ساكنة الريح : وقيل معناه : سكون الناس والأصوات فيه . وسجا البحر : سكنت أمواجه . وطرف ساج ، أى : ساكن فاتر . .أى : وحق الضحى وهو الوقت الذى ترتفع فيه الشمس ، ويتم إشراقها ، ويأخذا الناس فى النشاط والحركة . . وحق الليل إذا سكن وهجع فيه الناس بعد عناء العمل .","3":"وجواب القسم قوله - تعالى - : ( مَا وَدَّعَكَ رَبُّكَ وَمَا قلى ) أى : ام تركك ربك - أيها الرسول الكريم - منذ أن اختارك لحمل رسالته ، وما أبغضك ولا كرهك ، بل أنت محل رضانا ومحبتنا ورعايتنا ..فقوله : ( ودعك ) من التوديع ، وهو فى الأصل الدعاء للمسافر ، ببلوغ الدعة ، وخفض العيش ، ثم استعير للمفارقة بعد الاتصال ، تشبيها بفراق المسافر فى انقطاع الصلة ، حيث شبه - سبحانه - انقطاع صلة الكلام بانقطاع صلة الإِقامة .والمقصود : نفى أن يكون الله - تعالى - قد قطع وحيه عن نبيه صلى الله عليه وسلم .وقوله : ( قلى ) من القِلاَ - بكسر القاف - وهو شدة البغض ، يقال : قلا فلان فلانا يقليه ، إذا كرهه وأبغضه بشدة . ومنه قوله - تعالى - : ( إِنِّي لِعَمَلِكُمْ مِّنَ القالين ) والمراد ما قطع الله - تعالى - عنك وحيه - أيها الرسول الكريم - ، وما كرهك ، وهذا رد بليغ على المشركين الذين زعم بعضهم أن الله - تعالى - قد ترك نبيه ، وزعم آخرون أنه قد أبغضه ، وحذف مفعول \" قلا \" للدلالة عليه فى قوله - تعالى - ( مَا وَدَّعَكَ ) ، وهو إيجاز لفظى لظهور : المحذوف ، ومثله قوله - تعالى - بعد ذلك : ( فآوى ) ، ( فهدى ) ، ( فأغنى ) . .","4":"ثم بشره - سبحانه - ببشارتين عظيمتين ، قد بلغتا الدرجة العليا فى السمو والرفعة ، فقال : ( وَلَلآخِرَةُ خَيْرٌ لَّكَ مِنَ الأولى . وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فترضى )أى : وللدار الآخرة وما أعده الله لك فيها من نعيم لا يحيط به وصف ، خير لك من دار الدنيا التى أعطيناك فيها من نبوة ، وكرامة ومنازل عالية ، وخلق كريم .وفضلا عن كل ذلك فأنت - أيها الرسول الكريم - سوف يعطيك ربك من خيرى الدنيا والآخرة ، كل ما يسعدك ويرضيك ، من نصر عظيم ، وفتح مبين ، وتمكين فى الأرض ، وإعلاء لكلمة الحق على يدك ، وعلى أيدى أصحابك الصادقين ، ومنازل عظمى فى الآخرة لا يعلم مقدارها إلا الله - تعالى - ، كالمقام المحمود ، والشفاعة ، والوسيلة . . . وبذلك ترضى رضاء تاما بما أعطاك - سبحانه - من نعم ومنن .فالمراد بالآخرة : الدار الآخرة التى تقابل الدار الأولى ، وهى الحياة الدنيا ، وبعضهم جعل المراد بالآخرة ، نهاية أمره صلى الله عليه وسلم فى هذه الدنيا ، والمراد بالأولى بداية أمره صلى الله عليه وسلم فى هذه الدنيا ، فيكون المعنى : ولنهاية أمرك - أيها الرسول الكريم - خير من بدايته ، فإن كل يوم يمضى من عمرك ، سيزيدك الله - تعالى - فيه ، عزا على عز ، ونصرا على نصر ، وتأييدا على تأييد . . حتى ترى الناس وقد دخلوا فى دين الله أفواجا . . وقد صدق الله - تعالى - لنبيه وعده حيث فتح له مكة ، ونشر دعوته فى مشارق الأرض ومغاربها .قال الآلوسى : وحمل الآخرة على الدار الآخرة المقابلة للدنيا ، والأولى على الدار الأولى وهى الدنيا ، هو الظاهر .. وقال بعضهم : يحتمل : أن يراد بهما نهاية أمره صلى الله عليه وسلم وبدايته ، فاللام فيها للعهد ، أو عوض عن المضاف إليه . أى : لنهاية أمرك خيرك من بدايته ، فأنت لا تزال تتزايد قوة ، وتتصاعد رفعة . .","5":"وجئ بحرف الاستقبال فى قوله - تعالى - : ( وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فترضى ) ، لإفادة أن هذا العطاء مستمر غير مقطوع ، كما فى قوله - تعالى - : ( وَلَسَوْفَ يرضى ) وحذف المفعول الثانى فى قوله : ( يُعْطِيكَ ) ، ليعم كل وجوه العطاء التى يحبها صلى الله عليه وسلم أى : ولسوف يعطيك ربك عطاء يرضيك رضاء تاما .والتعبير بقوله ( فترضى ) ، ليعم كل وجوه العطاء التى يحبها الله صلى الله عليه وسلم أى : ولسوف يعطيك ربك عطاء يرضيك رضاء تاما .والتعبير بقوله ( فترضى ) المشتمل على فاء التعقيب ، للإِشعار بأنه عطاء عاجل النفع ، وأنه سيأتى إليه صلى الله عليه وسلم فى وقت قريب ، وقد أنجز - سبحانه - وعده .قال الجمل : وقوله - سبحانه - : ( وَلَلآخِرَةُ ) اللام فيه للابتداء مؤكدة لمضمون الجملة . وإنما قيد بقوله - تعالى - ( لك ) لأنها ليست خيرا لكل واحد . وقوله : ( وَلَسَوْفَ يُعْطِيكَ . . . ) هذا وعد شامل لما أعطاه الله - تعالى - له من كمال النفس ، وظهور الأمر ، وإعلاء الدين . . واللام لام الابتداء ، والمبتدأ محذوف ، أى : ولأنت سوف يعطيك ربك ، وليست لام القسم ، لأنها لا تدخل على المضارع ، إلا مع نون التوكيد . .","6":"ثم عدد - سبحانه - نعمه على نبيه صلى الله عليه وسلم فقال : ( أَلَمْ يَجِدْكَ يَتِيماً فآوى . . ) .والاستفهام هنا للتقرير : واليتيم : هو من فقد أباه وهو صغير .أى : لقد كنت - أيها الرسول الكريم - يتيما ، حيث مات أبوك وأنت فى بطن أمك ، فآواك الله - تعالى - بفضله وكرمه ، وتعهدك برعايته وحمايته وعصمته ، وسخر لك جدك عبد المطلب ليقوم بكفالتك ، ومن بعده سخر لك عمك أبا طالب ، حيث تولى رعايتك والدفاع عنك قبل الرسالة وبعدها ، إلى أن مات .","7":"وقوله - تعالى - ( وَوَجَدَكَ ضَآلاًّ فهدى ) بيان لنعمة أخرى أنعم - سبحانه - بها على نبيه صلى الله عليه وسلم :وللمفسرين فى معنى هذه الآية كلام طويل ، نختار منه قولين : أولهما : أن المراد بالضلال هنا الحيرة فى الوصول إلى الحق ، والغفلة عما أوحاه الله - تعالى - إليه بعد ذلك من قرآن كريم ، ومن تشريعات حكيمة . . مع اعتقاده صلى الله عليه وسلم قبل النبوة أن قومه ليسوا على الدين الحق ، بدليل أنه لم يشاركهم فى عبادتهم للأصنام ، ولا فى السلوك الذى يتنافى من مكارم الأخلاق .وإلى هذا المعنى أشار صاحب الكشاف بقوله : ( ضالا ) معناه : الضلال عن علم الشرائع وما طريقه السمع . .وقال الإِمام الشيخ محمد عبده - رحمه الله - : عند تفسيره لهذه الآية ما ملخصه : نشأ صلى الله عليه وسلم موحدا ، لم يسجد لصنم ، وطاهر الخلق ، لم يرتكب فاحشة ، حتى عرف بين قومه بالصادق الأمين ، فضلال الشرك ، وضلال الهوى فى العمل ، كانا بعيدين عن ذاته الكريمة .ولكن الضلال أنواع أخر ، منها : اشتباه المآخذ على النفس ، حتى تأخذها الحيرة فيما ينبغى أن تختار . . وهذا هو الذى عناه الله - تعالى - بالضلال فى هذه الآية الكريمة .وقد هداه - سبحانه - إلى الحق بعد هذه الحيرة ، بأن اختار له دينا قويما وعلمه كيف يرشد قومه . هذا هو معنى قوله - تعالى - : ( وَوَجَدَكَ ضَآلاًّ فهدى ) ، وهو معنى قوله - تعالى - فى سورة الشورى : ( وَكَذَلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحاً مِّنْ أَمْرِنَا مَا كُنتَ تَدْرِي مَا الكتاب وَلاَ الإيمان . . . ) وليس فى وصف النبى صلى الله عليه وسلم بالضال على هذا المعنى شين له ، أو حط من شأنه ، بل هذا فخره وإكليل مجده صلى الله عليه وسلم حيث كان على غير علم فعلمه الله ، ولم يكن مطلعا على الغيب ، فأطلعه الله على ما يريد إطلاعه عليه ، وبهذا التفسير نستغنى عن خلط المفسرين فى التأويل . .أما القول الثانى فى معنى الآية الكريمة ، فهو أنه صلى الله عليه وسلم كان بين قوم مشركين ، وكان بعرضه أن يضل معهم ، ولكن الله - تعالى - حبب إليه الانفراد عنهم ، واعتزال شركهم وسوء أخلاقهم . . فكان بذلك كالشجرة المنفردة فى الصحراء ، والعرب تسمى الشجرة التى بهذه الصفة ضالة .قال القرطبى : قوله - تعالى - : ( وَوَجَدَكَ ضَآلاًّ فهدى ) أى : غافلا عما يراد بك من أمر النبوة ، فهداك ، أى : أرشدك . والضلال هنا بمعنى الغفلة .وقال قوم : ( ضالا ) أى : لم تكن تدرى القرآن الكريم والشرائع ، فهداك الله إليهما .وقال قوم ( ضالا ) أى : وجدك فى قوم ضلال فهداهم الله - تعالى - بك ، والعرب إذا وجدت شجرة منفردة فى فلاة من الأرض ، لا شجر معها ، سموها ضالة ، فيهتدى بها إلى الطريق ، فقال - سبحانه - لنبيه ( وَوَجَدَكَ ضَآلاًّ فهدى ) أى : لا أحد على دينك ، وأنت وحيد ليس معك أحد ، فهَدَيْتُ بك الخلق إلى دينى . .هذا هما القولان اللذان نرتاح إليهما ، وارتياحنا إلى أولهما أشد وأقوى؛ لأن الرسول صلى الله عليه وسلم قد نشأ فى بيئة منحرفة فى عقائدها وأخلاقها ، لم تطمئن نفسه الكريمة إليها ، إلا أنه كا نحائرا فى الوصول إلى الدين الحق ، فهداه الله - تعالى - إليه ، والهداية إلى الحق بعد الحيرة والضلال عنه ، منة عظمى ، ونعمة كبرى .وهناك أقوال أخرى ضعيفة كقولهم : ( ضالا ) أى : عن القبلة فهداك الله إليها ، أو ( ضالا ) فى شعاب مكة ، فهداك الله وردك إلى عمك أو ( ضالا ) فى سفرك مع عمك إلى الشام ، فردك الله - تعالى - إليه .","8":"وقوله - سبحانه - : ( وَوَجَدَكَ عَآئِلاً فأغنى ) بيان لنعمة ثالثة من نعمه - تعالى - على نبيه صلى الله عليه وسلم .وأصل العائل : الإِنسان الذى له عائلة لا يستطيع الإِنفاق عليها ، ثم أطلق هذا اللفظ على الإِنسان الفقير حتى ولو لم تكن له عائلة أو أسرة ، والفقر يسمى عيلة ، كما فى قوله - تعالى - : ( وَإِنْ خِفْتُمْ عَيْلَةً ) - أى : فقرا - ( فَسَوْفَ يُغْنِيكُمُ الله مِن فَضْلِهِ إِن شَآءَ . . . ) أى : وقد كنت - أيها الرسول الكريم - فقيرا ، حيث مات أبوك دون أن يترك لك مالا كثيرا ، ونشأت فى كنف جدك ثم عمك ، وأنت على هذه الحال ، ثم أغناك الله - تعالى - بفضله وكرمه بنوعين من الغنى :أما أولهما - وهو الأعظم - : فهو غنى النفس ، بأن منحك نفسا عفيفة قانعة بما أعطاك - سبحانه - من رزق ، حتى ولو كان كفافا .وأما ثانيهما : فهو الغنى المادى عن الاحتياج إلى الناس ، بما أجراه على يديك من الربح فى التجارة ، وبما وهبتك زوجك خديجة من مالها ، فعشت مستور الحال ، غير محتاج إلى من ينفق عليك .وهكذا نجد الآيات الكريمة تبين لنا أن من فضل الله - تعالى - على نبيه صلى الله عليه وسلم أنه آواه فى يتمه وصغره ، وهداه من ضلاله وحيرته ، وأغناه بعد فقره وحاجته .","9":"وبعد أن عدد - سبحانه - هذه النعم لنبيه صلى الله عليه وسلم أمره بشكرها ، وأداء حقوقها .فقال - تعالى - : ( فَأَمَّا اليتيم فَلاَ تَقْهَرْ . . ) والقهر : التغلب على الغير والإِذلال له .أى : إذا كان الأمر كما أخبرتك من أنك كنت يتيما فآويناك ، وكنت ضالا فهديناك ، وكنت فقيرا فأغنيناك ، فتذكر هذه النعم ، واشكر ربك عليها ، ومن مظاهر هذا الشكر : أن تواسى اليتيم ، وأن تكرمه . وأن تكون رفيقا به . . ولا تكن كأهل الجاهلية الذين كانوا يقهرون الأيتام ويذلونهم ويظلمونهم . .ولقد استجاب النبى صلى الله عليه وسلم لما أمره ربه به ، فأكرم اليتامى ورعاهم ، وحض على ذلك فى أحاديث كثيرة منها قوله صلى الله عليه وسلم : \" \" أنا وكافل اليتيم كهاتين فى الجنة \" وأشار صلى الله عليه وسلم . بأصبعيه السبابه والوسطى \" . ومن الآيات القرآنية التى وردت فى هذا المعنى قوله - تعالى - : ( وَلاَ تَقْرَبُواْ مَالَ اليتيم إِلاَّ بالتي هِيَ أَحْسَنُ حتى يَبْلُغَ أَشُدَّهُ . . . ) وقد تكرر الأمر برعاية اليتيم ، وبالمحافظة على ماله فى مطلع سورة النساء خمس مرات قال - تعالى - : ( وَآتُواْ اليتامى أَمْوَالَهُمْ . . . ) وقال - سبحانه - : ( وَإِنْ خِفْتُمْ أَلاَّ تُقْسِطُواْ فِي اليتامى فانكحوا مَا طَابَ لَكُمْ مِّنَ النسآء مثنى وَثُلاَثَ وَرُبَاعَ . . . ) وقال - عز وجل - : ( وابتلوا اليتامى حتى إِذَا بَلَغُواْ النِّكَاحَ . . . ) وقال سبحانه - : ( وَإِذَا حَضَرَ القسمة أُوْلُواْ القربى واليتامى والمساكين فارزقوهم مِّنْهُ وَقُولُواْ لَهُمْ . . . )وقال - تعالى - : ( إِنَّ الذين يَأْكُلُونَ أَمْوَالَ اليتامى ظُلْماً إِنَّمَا يَأْكُلُونَ فِي بُطُونِهِمْ نَاراً . . . )","10":"وقوله - سبحانه - : ( وَأَمَّا السآئل فَلاَ تَنْهَرْ ) معطوف على ما قبله . أى : وكما أننا قد هديناك بعد حيرة . . فاشكر نعمنا على ذلك ، بأن تفتح صدرك للسائل الذى يسألك العون ، أو يسألك معرفة ما يجهله من علم . فالمراد بالسائل ، ما يشمل كل سائل عن مال ، أو عن علم ، أو عن غير ذلك من شئون الحياة .قال القرطبى : قوله : ( وَأَمَّا السآئل فَلاَ تَنْهَرْ ) أى : لا تزجره ، فهو نهى عن إغلاظ القول . . وروى عن رسول الله صلى الله عليه وسلم أنه قال : \" ردوا السائل ببذل يسير ، أو رد جميل . . \"وفى حديث أبى هارون العبدى قال : كنا إذا أتينا أبا سعيد الخدرى يقول : مرحبا بوصية رسول الله صلى الله عليه وسلم ، إن رسول الله قال : \" إن الناس لكم تبع ، وإن رجالا يأتونكم من أقطار الأرض يتفقهون ، فإذا أتوكم فاستوصوا بهم خيرا . . \"","11":"وقوله - تعالى - : ( وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ ) والتحديث بالشئ : الإِخبار به ، والحديث عنه ، أى : وكما كنت عائلا فأغنيناك بفضلنا وإحساننا ، فاشكرنا على ذلك ، بأن تظهر نعمنا عليك ولا تسترها ، وأذعها بين الناس ، وأمر أتباعك أن يفعلوا ذلك ، ولكن بدون تفاخر أو مباهاة . . فإن ذكر النعم على سبيل الرياء والتفاخر والتطاول على الغير . . يبغضه الله - تعالى - ، ويعاقب صاحبه عقابا أليما .قال الإِمام ابن كثير : وقوله : ( وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ ) أى : وكما كنت عائلا فقيرا فأغناك الله ، فحدث بنعمة الله عليك ، كما جاء فى الدعاء : \" واجعلنا شاكرين لنعمتك ، مثنين بها ، قابليها ، وأتمها علينا \" وعن أبى نضرة قال : كان المسلمون يرون أن من شكر النعم أن يُحَدِّث بها . وعن النعمان بن بشير قال : سمعت رسول الله صلى الله عليه وسلم يقول على المنبر : \" من لم يشكر القليل ، لم يشكر الكثير ، ومن لم يشكر الناس ، لم يشكر الله والتحدث بنعمة الله شكر ، وتركها كفر ، والجامعة رحمة والفرقة عذاب . . \"فأنت ترى أن الله - تعالى - قد ذكر ثلاث نعم مما أنعم به على نبيه صلى الله عليه وسلم وأرشده إلى كيفية شكرها . نسأل الله - تعالى - أن يجعلنا من عباده المشركين .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"94":{"1":"الاستفهام فى قوله - سبحانه - : ( أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ ) للتقرير لأنه إذا دخل على النفى قرره ، وهذا التقرير المقصود به التذكير ، حتى يداوم على شكره - تعالى - .وأصل الشرح : البسط للشئ وتوسعته ، يقال : شرح فلان الشئ ، إذا وسعه ، ومنه شرح فلان الكتاب ، إذا وضحه ، وأزال مجمله ، وبسط ما فيه من غموض .والمراد بشرح الصدر هنا : توسعته وفتحه ، لقبول كل ما هو من الفضائل والكمالات النفسية . وإذهاب كل ما يصد عن الإِدراك السليم وعن الحق الخير والهدى .وهذا الشرح ، يشمل الشق البدنى لصدره صلى الله عليه وسلم كما يشمل الشرح المعنوى لصدره صلى الله عليه وسلم عن طريق إيداعه الإِيمان والهدى والعلم والفضائل .قال الإِمام ابن كثير : قوله : ( أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ ) يعنى : أما شرحنا لك صدرك . أى : نورناه وجعلناه فسيحا رحيبا واسعا ، كقوله ( أَفَمَن شَرَحَ الله صَدْرَهُ لِلإِسْلاَمِ . . . ) وقيل المراد بقوله : ( أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ ) شرح صدره ليلة الإِسراء ، كما تقدم من رواية مالك بن صعصعة . . وهذا وإن كان واقعا ، ولكن لا منافاة ، فإن من جملة شرح صدره صلى الله عليه وسلم الذى فعل بصدره ليلة الإِسراء ، ما نشأ عنه من الشرح المعنوى - أيضا - . .والمعنى : لقد شرحنا لك - أيها الرسول الكريم - صدرك شرحا عظيما ، بأن أمرنا ملائكتنا بشقه وإخراج ما فيه مما يتنافى مع ما هيأناك له من حمل رسالتنا إلى الناس ، وبأن أودعنا فيه من الهدى والمعرفة والإِيمان والفضائل والحكم . . ما لم نعطه لأحد سواك .ونون العظمة فى قوله - سبحانه - ( نشرح ) تدل على عظمة النعمة ، من جهة أن المنعم العظيم ، إنما يمنح العظيم من النعم ، وفى ذلك إشارة إلى أن نعمة الشرح ، مما لا تصل العقول إلى كنه جلالتها .واللام فى قوله - تعالى - : ( لك ) للتعليل ، وهو يفيد أن ما فعله الله - تعالى - به ، إنما هو من باب تكريمه ، ومن أجل تشريفه وتهيئته لحمل رسالته العظمى إلى خلقه ، فمنفعه هذا الشرح إنما تعود إليه وحده صلى الله عليه وسلم لا إلى غيره .قال الإِمام الرازى : فإن قيل : لم ذكر الصدر ولم يذكر القلب؟ فالجواب أن محل الوسوسة هو الصدر ، كما قال - تعالى - : ( الذى يُوَسْوِسُ فِي صُدُورِ الناس ) فإزالة تلك الوسوسة ، وإبدالها بدواعى الخير ، هى الشرح ، فلا جرم خص ذلك الشرح بالصدر دون القلب .قال محمد بن على الترمذى : القلب محل العقل والمعرفة ، وهو الذى يقصده الشيطان ، فالشيطان يجئ إلى الصدر الذى هو حصن القلب ، فإذا وجد مسلكا أغار فيه ، وبث فيه الهموم ، فيضيق القلب ، ولا يجد للطاعة لذة ، وإذا طرد العدو فى الابتداء ، حصل الأمن ، وانشرح الصدر ..","2":"وقوله - سبحانه - : ( وَوَضَعْنَا عَنكَ وِزْرَكَ . الذي أَنقَضَ ظَهْرَكَ ) بيان لنعمة أخرى من النعم التى أنعم بها - سبحانه - على نبيه صلى الله عليه وسلم .والمراد بالوضع هنا : الإِزالة والحط ، لأن هذا اللفظ إذا عدى بعن كان للحط والتخفيف ، وإذا عدى بعلى كان للحمل والتثقيل .تقول : وضعت عن فلان قيده : إذا أزلته عنه ، ووضعته عليه : إذا حملته إياه .والوزر : الحِمْل الثقيل .","3":"و ( أَنقَضَ ظَهْرَكَ ) أى : أثقله وأوهنه وأتعبه ، حتى سمع له نقيض ، وهو الصوت الخفى الذى يسمع من الرَّحْل الكائن فوق ظهر البعير ، إذا كان هذا الرحل ثقيلا ، ولا يكاد البعير يحمله إلا بمشقة وعسر .والمعنى : لقد شرحنا لك - أيها الرسول الكريم - صدرك ، وأزلنا عنك ما أثقل ظهرك من أعباء الرسالة ، وعصمناك من الذنوب والآثام ، وطهرناك من الأدناس ، فصرت - بفضلنا وإحساننا - جديرا بحمل هذه الرسالة ، بتبليغها على أكمل وجه وأتمه .فالمراد بوضع وزره عنه صلى الله عليه وسلم مغفرة ذنوبه ، وإلى هذا المعنى أشار الإِمام ابن كثير بقوله : قوله - تعالى - : ( وَوَضَعْنَا عَنكَ وِزْرَكَ ) بمعنى ( لِّيَغْفِرَ لَكَ الله مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ ) وقال غير واحد من السلف فى قوله : ( الذي أَنقَضَ ظَهْرَكَ ) أى : أثقلك حمله . .ويرى كثير من المفسرين أن المراد بوضع وزره عنه صلى الله عليه وسلم : إزالة العقبات التى وضعها المشركون فى طريق دعوته ، وإعانته على تبليغ الرسالة على أكمل وجه ، ورفع الحيرة التى كانت تعتريه قبل النبوة .قال بعض العلماء : وقد ذكر جمهرة المفسرين أن المراد بالوزر فى هذه الآية : الذنب ، ثم راحوا يتأولون الكلام ، ويتمحلون الأعذار ، ويختلفون فى جواز ارتكاب الأنبياء للمعاصى ، وكل هذا كلام ، ولا داعى إليه ، ولا يلزم حمل الآية عليه .والمراد - والله سبحانه وتعالى أعلى وأعلم - بالوزر : الحيرة التى اعترته صلى الله عليه وسلم قبل البعثة ، حين فكر فيما عليه قومه من عبادة الأوثان . وأيقن بثاقب فكره أن للكون خالقا هو الجدير بالعبادة ، ثم تحير فى الطريق الذى يسلكه لعبادة هذا الخالق ، وما زال كذلك حتى أوحى الله إليه بالرسالة فزالت حيرته . ولما دعا قومه إلى عبادة الله ، وقابلوا دعوته بالإِعراض . . ثقل ذلك عليه ، وغاظه من قومه أن يكذبوه . . وكان ذلك حملا ثقيلا . . شق عليه القيام به .فليس الوزر الذى كان ينقض ظهره ، ذنبا من الذنوب . . ولكنه كان هما نفسيا يفوق ألمه ، ألم ذلك الثقل الحسى . . فلما هداه الله - تعالى - إلى إنقاذ أمته من أوهامها الفاسدة . . كان ذلك بمثابة رفع الحمل الثقيل ، الذى كان ينوء بحمله . لا جرم كانت هذه الآية واردة على سبيل التمثيل ، واقرأ إن شئت قوله - تعالى - :( وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ . فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُنْ مِّنَ الساجدين . واعبد رَبَّكَ حتى يَأْتِيَكَ اليقين ) ويبدو لنا أن هذا القول الثانى ، هو الأقرب إلى الصواب . لأن الكلام هنا ليس عن الذنوب التى ارتكبها النبى صلى الله عليه وسلم قبل البعثة - كما يرى بعض المفسرين - وإنما الكلام هنا عن النعم التى أنعم بها - سبحانه - عليه والتى من مظاهرها توفيقه للقيام بأعباء الرسالة ، وبإقناع كثير من الناس بأنه على الحق ، واستجابتهم له صلى الله عليه وسلم .","4":"وقوله - سبحانه - : ( وَرَفَعْنَا لَكَ ذِكْرَكَ ) بيان لنعمة ثالثة من نعمه - تعالى - على نبيه صلى الله عليه وسلم . أى : لقد شرحنا لك - أيها الرسول الكريم - صدرك ، وأزلنا عن قلبك الحيرة التى كانت تعتريك قبل تبليغ الرسالة وبعد تبليغها ، بأن يسرنا لك كل صعب .وفوق ذلك فقد رفعنا كل ذكرك ، بأن جعنالك رفيع الشأن ، سامى المنزلة ، عظيم القدر ، ومن مظاهر ذلك : أننا جعلنا اسمك مقرونا باسمنا فى النطق بالشهادتين .وفى الأذان ، وفى الإِقامة ، وفى التشهد ، وفى غير ذلك من العبادات ، وأننا فضلناك على جميع رسلنا ، بل على جميع الخلق على الإِطلاق ، وأننا أعطيناك الشفاعة العظمى ، وجعلنا طاعتك من طاعتنا .قال الآلوسى : أخرج أبو يعلى ، وابن جرير . . عن أبى سعيد الخدرى عن النبى صلى الله عليه وسلم أنه قال : \" أتانى جبريل فقال لى : أتدرى كيف رفعك ذكرك؟ قلت : الله - تعالى- أعلم . قال : \" إذا ذُكِرتُ ذُكِرتَ معى \" \" .","5":"ثم أضاف - سبحانه - إلى هذه النعم الجليلة ، ما يدخل السرور على قلبه صلى الله عليه وسلم وما يبعث الأمل فى نفسه وفى نفوس أصحابه ، بأن بين لهم سنة من سننه التى لا تتخلف فقال : ( فَإِنَّ مَعَ العسر يُسْراً ) .والفاء للإِفصاح ، ومع بمعنى بَعْد ، وأل فى العسر لاستغراق أنواع العسر المعروفة للمخاطبين . من فقر ، وضعف ، وقلة فى الوسائل التى تؤدى إلى إدراك المطلوب . والجملة الثانية مؤكدة ومقررة للجملة الأولى . والتنكير فى قوله ( يسرا ) للتفخيم .والمعنى : إذا تقرر عندك ما أخبرنا به ، من شرح الصدر ، ووضع الوزر . ورفع الذكر . . فاعلم أنه ما من عسر إلا ويعقبه يسر ، وما من شدة إلا ويأتى بعدها الفرج ، وما من غم أو هم ، إلا وينكشف ، وتحل محله المسرة . . وما دام الأمر كذلك ، فتذرع أنت وأصحابك بالصبر ، واعتصموا بالتوكل على الله ، فإن العاقبة لكم .ففى هاتين الآيتين ما فيهما من تسلية للنبى صلى الله عليه وسلم ولأتباعه ، ومن وعد صادق بأن كل صعب يلين ، وكل شديد يهون ، وكل عسير يتيسر . متى صبر الإِنسان الصبر الجميل ، وتسلح بالعزيمة القوية ، وبالإِيمان العميق بقضاء الله - تعالى - وقدره .وأكد - سبحانه - هاتين الآيتين ، لأن هذه القضية قد تكون موضع شك ، خصوصا بالنسبة لمن تكاثرت عليهم الهموم وألوان المتاعب ، فأراد الله - سبحانه - أن يؤكد للناس فى كل زمان ومكان ، أن اليسر يعقب العسر لا محالة ، والفرج يأتى بعد الضيق ، فعلى المؤمن أن يقابل المصائب بصبر جميل ، وبأمل كبير فى تيسير الله وفرجه ونصره .وقال - سبحانه - ( مَعَ العسر يُسْراً ) ولم يقل بعد العسر يسرا ، للإِشعار بأن هذا اليسر ، ليس بعد العسر بزمن طويل ، وإنما هو سيأتى فى أعقابه بدون مهلة طويلة ، متى وطن الإِنسان نفسه على الصبر والأمل فى فرج الله - تعالى - .وقد ساق الإِمام ابن كثير عند تفسيره لهاتين الآيتين بعض الآثار ، منها ما رواه ابن أبى حاتم ، عن عائد بن شريح قال : سمعت أنس بن مالك يقول : \" كان النبى صلى الله عليه وسلم جالسا وحياله حجر فقال : \" لو جاء العسر فدخل فهذا الحجر ، لجاء اليسر حتى يدخل عليه فيخرجه \" \" .وعن الحسن قال : كانوا يقولون : لا يغلب عسر واحد يسرين اثنين .وعن قتادة : ذكر لنا أن الرسول صلى الله عليه وسلم بشر أصحابه فقال : \" لن يغلب عسر يسرين \" ومعنى هذا أن العسر مُعَرَّف فى الحالين ، فهو مفرد ، واليسر مُنَكَّر فمتعدد ، ولهذا قال : \" لن يغلب عسر يسرين \" فالعسر الأول عين الثانى ، واليسر تعدد . .وقال صاحب الكشاف : فإن قلت : كيف تعلق قوله : ( فَإِنَّ مَعَ العسر يُسْراً ) ، كأنه قال : خولناك ما خولناك فلا تيأس من فضل الله ، فإن مع العسر الذى أنتم فيه يسرا .","6":"فإن قلت \" إن مع \" للصحبة ، فما معى اصطحاب اليسر للعسر؟ قلت : أراد أن الله يصيبهم بيسر بعد العسر الذى كانوا فيه بزمان قريب ، فقرب اليسر المترقب حتى جعله كالمقارن للعسر ، زيادة فى التسلية ، وتقوية القلوب .فإن قلت : فما المراد باليسرين؟ قلت : يجوز أن يراد بهما ما تيسر لهم من الفتوح فى أيام النبى صلى الله عليه وسلم ، وما تيسر لهم فى أيام الخلفاء . . وأن يراد يسر الدنيا ويسر الآخرة .فإن قلت : فما معنى هذا التنكير؟ قلت التفخيم ، كأنه قال : إن مع العسر يسرا عظيما وأى يسر . .","7":"وبعد هذا التعديد لتلك النعم العظيمة ، أمر الله - تعالى - نبيه صلى الله عليه وسلم فى الاجتهاد فى العبادة فقال - تعالى - : ( فَإِذَا فَرَغْتَ فانصب وإلى رَبِّكَ فارغب ) .وأصل الفراغ خول الإِناء مما بداخله من طعام أو غيره ، والمراد به هنا الخلو من الأعمال التى تشغل الإِنسان ، والنصب : التعب والاجتهاد فى تحصيل المطلوب .أى : فإذا فرغت - أيها الرسول الكريم - من عمل من الأعمال ، فاجتهد فى مزاولة عمل آخر من الأعمال التى تقربك من الله - تعالى - ، كالصلاة ، والتهجد ، وقراءة القرآن الكريم .واجعل رغبتك فى جميع أعمالك وعباداتك ، من أجل إرضاء ربك ، لا من أجل شئ آخر ، فهو وحده القادر على إبلاغك ما تريد ، وتحقيق آمالك .فالمقصود بهاتين الآيتين حثه صلى الله عليه وسلم وحث أتباعه فى شخصه على استدامة العمل الصالح ، وعدم الانقطاع عنه ، مع إخلاص النية لله - تعالى - فإن المواظبة على الأعمال الصالحة مع الإخلاص فيها ، تؤدى إلى السعادة التى ليس بعدها سعادة .ولقد استجاب صلى الله عليه وسلم لهذا الإِرشاد الحكيم ، \" فقد قام الليل حتى تورمت قدماه ، وعندما سئل مل كل هذه العبادة ، وقد غفر الله لك ما تقدم من ذنبك؟ قال : \" أفلا أكون عبدا شكورا \" \" .وسار أصحابه من بعده على هذا الهدىالقويم : فعمروا حياتهم بالباقيات الصالحات من الأعمال ، دون أن يكون للفراغ السيئ ، مكان فى حياتهم ، بل واصلوا الجهاد بالجهاد ، وأعمال البر بمثلها .ومن أقوال عمر بن الخطاب - رضى الله عنه - : إنى لأكره لأحدكم أن يكون خاليا ، لا فى عمل دنيا ولا دين \" .وفى رواية أنه قال : \" إنى لأنظر إلى الرجل فيعجبنى ، فإذا قيل : إنه لا عمل له سقط من عينى \" .","8":"وبعد هذا التعديد لتلك النعم العظيمة ، أمر الله - تعالى - نبيه صلى الله عليه وسلم فى الاجتهاد فى العبادة فقال - تعالى - : ( فَإِذَا فَرَغْتَ فانصب وإلى رَبِّكَ فارغب ) .وأصل الفراغ خول الإِناء مما بداخله من طعام أو غيره ، والمراد به هنا الخلو من الأعمال التى تشغل الإِنسان ، والنصب : التعب والاجتهاد فى تحصيل المطلوب .أى : فإذا فرغت - أيها الرسول الكريم - من عمل من الأعمال ، فاجتهد فى مزاولة عمل آخر من الأعمال التى تقربك من الله - تعالى - ، كالصلاة ، والتهجد ، وقراءة القرآن الكريم .واجعل رغبتك فى جميع أعمالك وعباداتك ، من أجل إرضاء ربك ، لا من أجل شئ آخر ، فهو وحده القادر على إبلاغك ما تريد ، وتحقيق آمالك .فالمقصود بهاتين الآيتين حثه صلى الله عليه وسلم وحث أتباعه فى شخصه على استدامة العمل الصالح ، وعدم الانقطاع عنه ، مع إخلاص النية لله - تعالى - فإن المواظبة على الأعمال الصالحة مع الإخلاص فيها ، تؤدى إلى السعادة التى ليس بعدها سعادة .ولقد استجاب صلى الله عليه وسلم لهذا الإِرشاد الحكيم ، \" فقد قام الليل حتى تورمت قدماه ، وعندما سئل مل كل هذه العبادة ، وقد غفر الله لك ما تقدم من ذنبك؟ قال : \" أفلا أكون عبدا شكورا \" \" .وسار أصحابه من بعده على هذا الهدىالقويم : فعمروا حياتهم بالباقيات الصالحات من الأعمال ، دون أن يكون للفراغ السيئ ، مكان فى حياتهم ، بل واصلوا الجهاد بالجهاد ، وأعمال البر بمثلها .ومن أقوال عمر بن الخطاب - رضى الله عنه - : إنى لأكره لأحدكم أن يكون خاليا ، لا فى عمل دنيا ولا دين \" .وفى رواية أنه قال : \" إنى لأنظر إلى الرجل فيعجبنى ، فإذا قيل : إنه لا عمل له سقط من عينى \" .نسأل الله - تعالى - أن يجعلنا جميعا ممن يعمرون أوقاتهم بالأعمال الصالحة ، والخالصة لوجهه الكريم .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"95":{"1":"إلا أن خلافهم فى المراد بقوله - تعالى - : ( والتين والزيتون ) ، وقد ذكر الإِمام القرطبى هذا الخلاف فقال ما ملخصه : قوله : ( والتين والزيتون ) : قال ابن عباس وغيره : هو تينكم الذى تأكلون ، وزيتونكم الذى تعصرون منه الزيت . قال - تعالى - : ( وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنبُتُ بالدهن وَصِبْغٍ لِّلآكِلِيِنَ ) وهى شجرة الزيتون .وقال أبو ذر : \" أهدى للنبى صلى الله عليه وسلم سلة تين ، فقال : \" كلوا \" وأكل منها . ثم قال : \" لو قلت إن فاكهة نزلت من الجنة ، لقلت هذه . . \" \" .وعن معاذ : أنه استاك بقضيب زيتون ، وقال : سمعت النبى صلى الله عليه وسلم يقول : \" نعم السواك الزيتون من الشجرة المباركة \" .وقال الإِمام ابن جرير بعد أن ساق ملة من الأقوال من المقصود بالتين والزيتون : والصواب من القول فى ذلك عندنا ، قول من قال : التين : هو التين الذى يؤكل . والزيتون : هو الزيتون الذى يعصر منه الزيت ، لأن ذلك هو المعروف عند العرب ، ولا يعرف جبل يسمى تينا ، ولا جبل يقال له زيتون . إلا أن يقول قائل : المراد من الكلام القسم بمنابت التين ، ومنابت الزيتون ، فيكون ذلك مذهبا ، وإن لم يكن على صحة ذلك أنه كذلك ، دلالة فى ظاهر التنزيل ..وما ذهب إليه الإِمامان : ابن جرير والقرطبى ، من أن المراد بالتين والزيتون ، حقيقتهما ، هو الذى نميل إليه ، لأنه هو الظاهر من معنى اللفظ ، ولأنه ليس هناك من ضرورة تحمل على مخالفته ، ولله - تعالى - أن يقسم بما شاء من مخلوقاته ، فهو صاحب الخلق والأمر ، تبارك الله رب العالمين .","2":"اتفق المفسرون على أن المراد بطور سينين : الجبل الذى كلم الله - تعالى - عليه موسى - عليه السلام - وسينين ، وسيناء ، وسينا ، اسم للبقعة التى فيها هذا الجبل ، بإضافة \" طور \" إلى ما بعده ، من إضافة الموصوف إلى الصفة .قال الإِمام الشوكانى : \" وطور سينين \" هو الجبل الذى كلم الله عليه موسى ، اسمه الطور . ومعنى سينين : المبارك الحسن . . وقال مجاهد : سينين كل جبل فيه شجر مثمر ، فهو سينين وسيناء . وقال الأخفش : طور : جبل . وسينين شجر ، واحدته سينه ، ولم ينصرف سينين كما لم ينصرف سيناء ، لأنه جعل اسما للبقعة .وأقسم - سبحانه - به ، لأنه من البقاع المباركة ، وأعظم بركة حلت به ووقعت فيه ، تكليم الله - تعالى - ، لنبيه موسى - عليه السلام - .","3":"كما اتفقوا - أيضا - على أن المراد بالبلد الأمين : مكة المكرمة ، وسمى بالأمين لأن من دخله كان آمنا ، وقد حرمها - تعالى - على جميع خلقه ، وحرم شجرها وحيوانها ، وفى الحديث الصحيح ، أن النبى صلى الله عليه وسلم قال بعد فتحتها : \" إن الله حرم مكة يوم خلق السموات والأرض فهى حرام إلى أن يقوم الساعة ، لم تحل لأحد قبلى ، ولن تحل لأحد بعدى ، ولم تحل لى إلا ساعة من نهار ، فلا يُعْضَد - أى : يقطع - شجرها - ولا ينفر صيدها ، ولا تحل لقطتها إلا لمنشد . . \" .","4":"وجملة : ( لَقَدْ خَلَقْنَا الإنسان في أَحْسَنِ تَقْوِيمٍ . . . ) وما عطف عليه جواب القسم .أى : وحق التين الذى هو أحسن الثمار ، صورة وطعما وفائدة ، وحق الزيتون الذى يكفى الناس حوائج طعامهم وإضاءتهم ، وحق هذا البلد الأمين ، وهو مكة المكرمة ، وحق طور سنين الذى كلم الله - تعالى - عليه نبيه موسى تكليما . . وحق هذه الأشياء . . لقد خلقلنا الإِنسان فى أعدل قامة ، وأجمل صورة ، وأحسن هيئة ، ومنحناه بعد ذلك ما لم نمنحه لغيره ، من بيان فصيح ، ومن عقل راجح ، ومن علم واسع ، ومن إرادة وقدرة على تقحيق ما يبتغيه فى هذه الحياة ، بإذننا ومشيئتنا .والتقويم فى الأصل : تصيير الشئ على الصورة التى ينبغى أن يكون عليها فى التعديل والتركيب . تقول : قومت الشئ تقويماً ، إذا جعلته على أحسن الوجوه التى ينبغى أن يكون عليها . . فى التعديل والتركيب . تقول : قومت الشئ تقويماً ، إذا جعلته على أحسن الوجوه التى ينبغى أن يكون عليها . . وهذا الحسن يشمل الظاهر والباطن للإِنسان .والمراد بالإِنسان هنا : جنسه . أى : لقد خلقنا - بقدرتنا وحكمتنا - جنس الإِنسان فى أكمل صورة ، وأحكم عقل . .","5":"وقوله - تعالى - : ( ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ ) معطفو على ما قبله وداخل فى حيز القسم . وضمير الغائب يعود إلى الإِنسان .وحقيقة الرد : إرجاع الشئ إلى مكانه السابق ، والمراد به هنا : تصيير الإِنسان على حالة غير الحالة التى كان عليها ، وأسفل : أفعل تفضيل ، أى : أشد سفالة مما كان يتوقع .وللمفسرين فى هذه الآية الكريمة اتجاهات منها : أن المراد بالرد هنا : الرد على الكبر والضعف ، كما قال - تعالى - : ( الله الذي خَلَقَكُمْ مِّن ضَعْفٍ ثُمَّ جَعَلَ مِن بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِن بَعْدِ قُوَّةٍ ضَعْفاً وَشَيْبَةً يَخْلُقُ مَا يَشَآءُ وَهُوَ العليم القدير ) وعلى هذا الرأى يكون المردودين إلى أسفل سافلين ، أى : إلى أرذل العمر ، هم بعض أفراد جنس الإِنسان ، لأنه من المشاهد أن بعض الناس هم الذين يعيشون تلك الفترة الطويلة من العمر ، كما قال - تعالى - : ( هُوَ الذي خَلَقَكُمْ مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلاً ثُمَّ لتبلغوا أَشُدَّكُمْ ثُمَّ لِتَكُونُواْ شُيُوخاً وَمِنكُمْ مَّن يتوفى مِن قَبْلُ ولتبلغوا أَجَلاً مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ ) وقد رجح ابن جرير هذا الرأى فقال : \" وأولى الأقوال فى ذلك عندى بالصحة ، وأشبهها بتأويل الآية ، قول من قال معناه : ثم رددناه إلى أرذل العمر .إلى عمر الخرفى الذين ذهبت عقولهم من الهرم والكبر ، فهو فى أسفل من سفل فى إدبار العمر ، وذهاب العقل . . \" .ومنها : أن المراد بالرد هنا : الرد إلى النار ، والمعنى : لقد خلنا الإِنسان فى أحسن تقويم ، ثم رددناه إلى أقبح صورة ، وأخس هيئة . . حيث ألقينا به فى أسفل سافلين ، أى : فى النار ، بسبب استحبابه العمى على الهدى ، والكفر على الإِيمان .وقد رجح هذا الرأى ابن كثير فقال : قوله : ( ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ ) أى : إلى النار . . أى : ثم بعد هذا الحسن والنضارة ، مصيره إلى النار ، إن لم يطع الله - تعالى - ويتبع الرسل . ولهذا قال : ( إِلاَّ الذين آمَنُواْ وَعَمِلُواْ الصالحات . . . ) .","6":"( إِلاَّ الذين آمَنُواْ وَعَمِلُواْ الصالحات . . . )وعلى هذا الرأى - أيضا - ، يكون المردودون إلى \" أسفل سافلين \" أى : إلى النار ، هم بعض أفراد جنس الإِنسان ، وهم الكفار ، والفاسقون عن أمره - تعالى - .ومنها : أن المراد بالرد إلى أسفل سافلين هنا : الانحراف والارتداد عن الفطرة التى فطر الله - تعالى - الناس عليها ، بأن يعبد الإِنسان مخلوقاً مثله ، ويترك عبادة خالقه ، ويطيع نفسه وشهواته وهواه . . ويترك طاعة ربه - عز وجل - .وقد فصل الأستاذ الإِمام هذا المعنى فقال ما ملخصه : \" أقسم - سبحانه - أنه قوم الإِنسان أحسن تقويم ، وركبه أحسن تركيب ، وأكد - سبحانه - ذلك بالقسم ، لأن الناس بسبب غفلتهم عما كرمهم الله به ، صاروا كأنهم ظنوا أنفسهم كسائر أنواع العجماوات ، يفعلون كما تفعل ، لا يمنعهم حياء ولا تردهم حشمة . فانحطت بذلك نفوسهم عن مقامها ، الذى كان لها بمقتضى الفطرة . . فهذا قوله : ( ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ ) ، أى : صيرناه أسفل من كثير من الحيوانات التى كانت أسفل منه ، لأن الحيوان المفترس - مثلاً - إنما يصدر فى عمله عن فطرته التى فطر عليها ، لم ينزل عن مقامه ، ولم ينحط عن منزلته فى الوجود .أما الإِنسان فإنه بإهماله عقله ، وجهله بما ينبغى أن يعمله لتوفير سعادته وسعادة إخوانه ، ينقلب أرذل من سائر أنواع الحيوان ، ولطالما قلت : \" إذا فسد الإِنسان فلا تسل عما يصدر عنه من هذيان أو عدوان \" .والذى يتأمل الرأى الثانى والثالث يرى أن بينهما تلازماً ، لأن الانحراف عن الفطرة السوية يؤدى إلى الدخول فى النار وبئس القرار ، وهذان الرأيان أولى بالقبول ، لأن الاستثناء فى قوله - تعالى - بعد ذلك : ( إِلاَّ الذين آمَنُواْ وَعَمِلُواْ الصالحات فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ ) يؤيد ذلك ، إذ المعنى عليها : لقد خلقنا الإِنسان فى أحسن تقويم ، ثم رددناه إلى النار بسبب انحرافه عن الفطرة ، وإيثاره الغى على الرشد ، والكفر على الإِيمان .إلا الذين آمنوا وعملوا الصالحات ، وساروا على مقتضى فطرتهم ، فأخلصوا لله - تعالى - العبادة والطاعة . . فلهم أجر غير مقطوع عنهم أو غير ممنون به عليهم ، بل هم قد اكتسبوا هذا الأجر الدائم العظيم ، بسبب إيمانهم وعملهم الصالح .قال الآلوسى ما ملخصه : قوله : ( ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ ) ، \" ثم \" هنا للتراخى الزمانى أو الرتبى ، والرد يجوز أن يكون بمعنى الجعل ، فينصب مفعولين أصلهما المبتدأ والخبر . فأسفل مفعول ثان ، والمعنى : ثم جعلناه من أهل النار ، الذين هم أقبح ، وأسفل من كل سافل . . ويجوز أن يكون الرد بمعناه المعروف ، وأسفل منصوب بنزع الخافض .أى : رددناه إلى أسفل الأمكنة السافلة وهو جهنم . .وقوله : ( إِلاَّ الذين آمَنُواْ وَعَمِلُواْ الصالحات ) استثناء متصل من ضمير \" رددناه العائد على الإِنسان ، فإنه فى معنى الجمع ، فالمؤمنون لا يردون أسفل سافلين يوم القيامة ، بل يزدادون بهجة إلى بهجتهم . وحسنا على حسنهم . . \" .","7":"و \" ما \" فى قوله - سبحانه - : ( فَمَا يُكَذِّبُكَ بَعْدُ بالدين ) اسم استفهام مبتدأ ، وخبره جملة \" يكذبك \" . والخطاب للإِنسان الذين خلقه الله - تعالى - فى أحسن تقويم ، ففى الكلام التفات من الغيبة إلى الخطاب . والاستفهام للإِنكار والتعجيب من هذا الإِنسان .والمعنى : فأى شئ يحملك - أيها الإِنسان - على التكذيب بالدين وبالبعث وبالجزاء ، بعد أن خلقناك فى أحسن تقويم ، وبعد أن أقمنا لك الأدلة على أن دين الإِسلام هو الدين الحق ، وعلى أن رسولنا صادق فيما يبلغك عن ربه - عز وجل -؟فالمقصود بقوله - تعالى - : ( يُكَذِّبُكَ ) : يجعلك مكذباً ، أى : لا عذر لك فى التكذيب بالحق ، وقيل : الخطاب للنبى صلى الله عليه وسلم ، وتكون \" ما \" بمعنى \" مَنْ \" ويكون الاستفهام بها عن ذوات المخاطبين ، أى : فمن ذا الذى يكذبك - أيها الرسول الكريم - ويكذب بيوم الدين والجزاء ، بعد أن ظهرت الدلائل على صدقك . . ؟إن كل عاقل يجب عليه أن يصدقك ولا يكذبك ، ولا يعرض عنك .","8":"والاستفهام فى قوله - تعالى - : ( أَلَيْسَ الله بِأَحْكَمِ الحاكمين ) للتقرير : إذا الجملة الكريمة تحقيق لما ذكر من خلق الإِنسان فى أحسن تقويم ، ثم رده إلى أسفل سافلين .فكأنه - تعالى - يقول : إن الذى فعل ذلك كله هو أحكم الحاكمين خلقاً وإيجاداً . وصنعاً وتدبيراً ، وقضاء وتقديراً ، فيجب على كل عاقل أن يخلص له العبادة والطاعة وأن يتبع رسوله صلى الله عليه وسلم فى كل ما جاء به من عند ربه - عز وجل - .وقد روى الإِمام الترمذى عن أبى هريرة قال : قال رسول الله صلى الله عليه وسلم :\" من قرأ منكم ( والتين والزيتون . . . ) ثم انتهى إلى قوله - تعالى - ( أَلَيْسَ الله بِأَحْكَمِ الحاكمين ) فليقل : بلى ، وأنا على ذلك من الشاهدين \" .نسأل الله - تعالى - أن يجعلنا جميعاً من عباده الصالحين .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"96":{"1":"وقد أجمع المحققون من العلماء ، على ن هذه الآيات الكريمة ، أول ما نزل على الرسول صلى الله عليه وسلم من قرآن على الإطلاق ، فقد أخرج الشيخان وغيرهما عن عائشة قالت : أول ما بدئ به رسول الله صلى الله عليه وسلم من الوحى ، الرؤيا الصالحة فى النوم . فكان لا يرى رؤيا إلا جاءت مثل فلق الصبح . ثم حبب إليه الخلاء فكان يخلو بغار حراء فيتحنث - أى : فيتعبد - فيه الليالى ذوات العدد ، ثم يرجع إلى خديجة فيتزود لذلك ، حتى جاءه الحق وهو فى غار حراء . فجاءه الملك فقال له : ( اقرأ ) قال : ما أنا بقارئ ، قال صلى الله عليه وسلم فأخذنى فغطنى حتى بلغ منى الجهد ، ثم أرسلنى فقال : ( اقرأ ) فقلت : ما أنا بقارئ ، فأخذنى فغطنى الثانية حتى بلغ منى الجهد ، ثم أرسلنى فقال : ( اقرأ ) فقلت : ما أنا بقارئ ، فأخذنى فغطنى الثالثة حتى بلغ منى الجهد ، ثم أرسلنى فقال : ( اقرأ باسم رَبِّكَ الذي خَلَقَ . خَلَقَ الإنسان مِنْ عَلَقٍ . . ) .وما ورد من أحاديث تفيد أن أول سورة نزلت هى \" سورة الفاتحة \" فمحمول على أن أول سورة نزلت كاملة هى سورة الفاتحة .كذلك ما ورد من أحاديث فى أن أول ما نزل سورة المدثر ، محمول على أن أول ما نزل بعد فترة الوحى . أما صدر سورة العلق فكان نزوله قبل ذلك .قال الآلوسى - بعد أن ساق الأحاديث التى وردت فى ذلك - : \" وبالجملة فالصحيح - كما قال بعض وهو الذى أختاره - أن صدر هذه السورة الكريمة ، هو أول ما نزل من القرآن على الإِطلاق . وفى شرح مسلم : الصواب أن أول ما نزل \" اقرأ \" أى : مطلقاً ، وأول ما نزل بعد فترة الوحى ، \" يأيها المدثر \" ، وأما قول من قال من المفسرين ، أول ما نزل الفاتحة ، فبطلانه أظهر من أن يذكر \" .والذى نرجحه ونميل إليه أن أول من قرآن على الإطلاق ، هو صدر هذه السورة لكريمة إلى قوله ( مَا لَمْ يَعْلَمْ ) ، لورود الأحاديث الصحيحة بذلك . أما بقيتها فكان نزوله متأخراً .قال الأستاذ الإِمام \" أما بقية السورة فهو متأخر النزول قطعاً ، وما فيه من ذكر أحوال المكذبين ، يدل على أنه إنما نزل بعد شيوع خبر البعثة ، وظهور أمر النبوة ، وتحرش قريش لإيذائه صلى الله عليه وسلم \" .وقد افتتحت السورة الكريمة بطلب القراءة من النبى صلى الله عليه وسلم مع أنه كان أميا لتهيئة ذهنه لما سيلقى عليه صلى الله عليه وسلم من وحى . . فقال - سبحانه - : ( اقرأ باسم رَبِّكَ الذي خَلَقَ ) . أى : اقرأ - أيها الرسول الكريم - ما سنوحيه إليك من قرآن الكريم- ما سنوحيه إليك من قرآن كريم - ولتكن قراءتك ملتبسة باسم ربك ، وبقدرته وإرادته ، لا باسم غيره ، فهو - سبحانه - الذى خلق الأشياء جميعها ، والذى لا يعجزه أن يجعلك قارئاً ، بعد كونك لم تكن كذلك .وقال - سبحانه - ذاته بقوله : ( الذي خَلَقَ ) للتذكير بهذه النعمة ، لأن الخلق هو أعظم النعم ، وعليه تترتب جميعها .","2":"وجملة ( خَلَقَ الإنسان مِنْ عَلَقٍ ) بدل من قوله ( الذي خَلَقَ ) بدل بعض من كل ، إذ خلق الإِنسان بمثل جزءا من خلق المخلوقات التى لا يعلمها إلا الله .و \" العلق \" الدم الجامد ، وهو الطورالثانى من أطوار خلق الإِنسان .وقيل : العلق : مجموعة من الخلايا التى نشأت بطريقة الانقسام عن البويضة الملقحة ، وسمى \" علقا \" لتعلقه بجدار الرحم .والمقصود من هذه الجملة الكريمة بيان مظهر من مظاهر قدرته - تعالى - فكأنه - سبحانه - يقول : إن من كان قادراً على أن يخلق من الدم الجامد إنساناً يسمع ويرى ويعقل . . قادر - أيضاً - على أن يجعل منك - أيها الرسول الكريم - قارئاً ، وإن لم تسبق لك القراءة .وخص - سبحانه - خلق الإِنسان بالذكر ، لأنه أشرف المخلوقات ولأن فيه من بدائع الصنع والتدبير ما فيه .","3":"وقوله - تعالى - ( اقرأ وَرَبُّكَ الأكرم ) أى : امض لما أمرتك به من القراءة ، فإن ربك الذى أمرك بالقراءة هو الأكرم من كل كريم ، والأعظم من كل عظيم .قالوا : وإنما كرر - سبحانه - الأمر بالقراءة ، لأنه من الملكات التى لا ترسخ فى النفس إلا بالتكرار والإِعادة مرة فمرة .وجملة ( وَرَبُّكَ الأكرم ) مستأنفة لقصد بيان أنه - تعالى - أكرم من كل من يلتمس منه العطاء ، وأنه - سبحانه - قادر على أن يمنح نبيه نعمة القراءة ، بعد أن كان يجهلها .","4":"وقوله - تعالى - : ( الذى عَلَّمَ بالقلم ) أى : علم الإنسان الكتابة بالقلم ، ولم يكن له علم بها ، فاستطاع عن طريقها أن يتفاهم مع غيره ، وأن يضبط العلوم والمعارف ، وأن يعرف أخبار الماضين وأحوالهم ، وأن يتخاطب بها مع الذين بينه وبينهم المسافات الطويلة .ومفعولا \" علَّم \" محذوفان ، دل عليهما قوله ( بالقلم ) أى : علم ناسا التكابة بالقلم .وتخصيص هذه الصفة بالذكر ، للإِيماء إلى إزالة ما قد يخطر بباله صلى الله عليه وسلم من تعذر الراءة بالنسبة له ، لجهله بالكتابة ، فكأنه - تعالى - يقول له : إن من علم غيرك القراءة والكتابة بالقلم ، قادر على تعليمك القراءة وأنت لا تعرف الكتابة ، ليكون ذلك من معجزاتك الدالة على صدقك ، وكفاك بالعلم فى الأمة معجزة .","5":"وجملة ( عَلَّمَ الإنسان مَا لَمْ يَعْلَمْ ) خبر عن قوله - تعالى - : ( وَرَبُّكَ الأكرم ) وما بينهما اعتراض ، ويصح أن تكون بدل اشتمال مما قبلها وهو قوله ( عَلَّمَ بالقلم ) أى : علم الإِنسان بالقلم وبدونه ما لم يكن يعلمه من الأمور على اختلافها ، والمراد بالإِنسان فى هذه الآيات جنسه .والمتأمل فى هذه الآيات الكريمة ، يراها قد جمعت أصول الصفات الإِلهية ، كالوجود ، والوحدانية ، والقدرة والعلم ، والكرم .قال الإِمام ابن كثير عند تفسيره لهذه الآيات : فأول شئ من القرآن هذه الآيات الكريمات المباركات ، وهو أول رحمة رحم الله بها العباد ، وأول نعمة أنعم الله بها عليهم ، وفيها التنبيه على ابتداء خلق الإِنسان من علقه ، وأن من كرمه - تعالى - أن علم الإِنسان ما لم يعلم ، فشرفه وكرمه بالعلم ، وهو القدر الذى امتاز به أبو البرية آدم على الملائكة . .وقال المرحوم الشيخ محمد عبده : ثم إنه لا يوجد بيان أبرع ولا دليل أقطع على فضل القراءة والكتابة والعلم بجميع أنواعه ، من افتتاح الله كتابه وابتدائه الوحى ، بهذه الآيات الباهرات ، فإن لم يهتد المسلمون بهذا الهدى ، ولم ينبههم النظر فيه إلى النهوض ، وإلى تمزيق تلك الحجب التى حجبت عن أبصارهم نور العلم . . وإن لم يسترشدوا بفاتحة هذا الكتاب المبين ، ولم يستضيئوا بهذا الضياء الساطع . . فلا أرشدهم الله . .","6":"ثم بين - سبحانه - بعد ذلك الأسباب التى تحمل الإِنسان على الطغيان فقال : ( كَلاَّ إِنَّ الإنسان ليطغى . أَن رَّآهُ استغنى ) .و \" كلا \" حرف ردع وزجر لمن تكبر وتمرد . . فهو زجر عما تضمنه ما بعدها ، لأن ما قبلها ليس فيه ما يوجب الزجر والردع ، ويصح أن تكون \" كلا \" هنا بمعنى حقا . وقوله : ( يطغى ) من الطغيان ، وهو تجاوز الحق فى التكبر والتمرد . والضمير فى قوله ( رآه ) يعود على الإِنسان الطاغى ، والجملة متعلقة بقوله ( يطغى ) بحذف لام التعليل ، والرؤية بمعنى العلم .والمعنى : حقا إن الإِنسان ليتعاظم ويتكبر ويتمرد على الحق .والمراد بالإِنسان هنا : جنسه؛ لأن من طبع الإِنسان أن يطغى ، إذا ما كثرت النعم بين يديه ، إلا من عصمه الله - تعالى - منهذا الخُلُقِ الذميم ، بأن شكره - سبحانه - على نعمه ، واستعملها فى طاعته .","7":"لأنه رأى نفسه ذا غنى فى المال والجاه والعشيرة ، ورآها - لغروره وبطره - ليست فى حاجة إلى غيره .والمراد بالإِنسان هنا : جنسه؛ لأن من طبع الإِنسان أن يطغى ، إذا ما كثرت النعم بين يديه ، إلا من عصمه الله - تعالى - منهذا الخُلُقِ الذميم ، بأن شكره - سبحانه - على نعمه ، واستعملها فى طاعته .وقيل المراد بالإِنسان هنا : أبو جهل ، وأن هذه الآيات وما بعدها حتى آخر السورة قد نزلت فى أبى جهل ، فقد أخرج البخارى عن ابن عباس قال : قال أبو جهل : لئن رأيت محمدا يصلى عند الكعبة ، لأطأن على عنقه ، فبلغ ذلك النبى صلى الله عليه وسلم فقال : \" لئن فعل لأخذته الملائكة \" . ونزول هذه الآيات فى شأن أبى جهل لا يمنع عموم حكمها ، ويدخل فى هذا الحكم دخولا أوليا أبو جهل ، إذ العبرة بعموم اللفظ لا بخصوص السبب .","8":"وقوله - تعالى - : ( إِنَّ إلى رَبِّكَ الرجعى ) تهديد ووعيد لهذا الطاغى ، والرُّجْعَى : مصدر بمعنى الرجوع . تقول : رجع إليه رجوعا ومرجعا ورجعى بمعنى واحد .والمعنى : لا تحزن - أيها الرسول الكريم - مما تفوه به هذا الطاغى وأمثاله ، فإن إلى ربك وحده مرجعهم ، وسيشاهدون بأعينهم ما أعددناه لهم من عذاب مهين ، وسيعلمون حق العلم أن ما يتعاظمون به من مال ، لن يغنى عنهم من عذاب الله شيئا يوم القيامة .","9":"ثم عجَّب - سبحانه - نبيه صلى الله عليه وسلم من حال هذا الشقى وأمثاله ، فقال : ( أَرَأَيْتَ الذي ينهى . عَبْداً إِذَا صلى ) . فالاستفهام فى قوله - تعالى - : ( أَرَأَيْتَ . . . ) للتعجيب من جهالة هذا الطاغى ، وانطماس بصيرته ، حيث نهى عن الخير ، وأمر بالشر ، والمراد بالعبد : رسول الله صلى الله عليه وسلم وتنكيره للتفخيم والتعظيم .أى : أرأيت وعلمت - أيها الرسول الكريم - حالا أعجب وأشنع من حال هذا الطاغى الأحمق ، الذى ينهاك عن إقامة العبادة لربك الذى خلقك وخلقه .","10":"ثم عجَّب - سبحانه - نبيه صلى الله عليه وسلم من حال هذا الشقى وأمثاله ، فقال : ( أَرَأَيْتَ الذي ينهى . عَبْداً إِذَا صلى ) . فالاستفهام فى قوله - تعالى - : ( أَرَأَيْتَ . . . ) للتعجيب من جهالة هذا الطاغى ، وانطماس بصيرته ، حيث نهى عن الخير ، وأمر بالشر ، والمراد بالعبد : رسول الله صلى الله عليه وسلم وتنكيره للتفخيم والتعظيم .أى : أرأيت وعلمت - أيها الرسول الكريم - حالا أعجب وأشنع من حال هذا الطاغى الأحمق ، الذى ينهاك عن إقامة العبادة لربك الذى خلقك وخلقه .","11":"وقوله - سبحانه - : ( أَرَأَيْتَ إِن كَانَ على الهدى . أَوْ أَمَرَ بالتقوى ) خطاب آخر للنبى صلى الله عليه وسلم أى : أرأيت - أيها الرسول الكريم - إن صار هذا الإِنسان - الطاغى والكافر - على الهدى ، فاتبع الحق ، ودعا إلى البر والتقوى . . أما كان ذلك خيرا له من الإِصرار على الكفر .","12":"ومن نهيه إياك عن الصلاة ، فجواب الشرط محذوف للعلم به .فالمراد بالهدى : اهتداؤه إلى الصراط المستقيم ، والمراد بالتقوى : صيانة نفسه عن كل ما يغضب الله - تعالى - ، وأمره غيره بذلك .","13":"وقوله - تعالى - : ( أَرَأَيْتَ إِن كَذَّبَ وتولى . أَلَمْ يَعْلَم بِأَنَّ الله يرى ) .أى : أرأيت - أيها الرسول الكريم - إن كذب هذا الكافر بما جئته به من عندنا ، وتولى وأعرض عما تدعوه إليه من إيمان وطاعة لله رب العالمين . أرأيت إن فعل ذلك ، أفلا أرشده عقله إلى أن خالق هذا الكون يراه ، وسيجازيه بما يستحقه من عذاب مهين؟فالمقصود من هذه الآيات الكريمة التى تكرر فيها لفظ \" أرأيت \" ثلاث مرات : تسلية النبى صلى الله عليه وسلم . وتعجيبه من حال هذا الإِنسان الطاغى الشقى ، الذى أصر على كفره . وآثر الغى على الرشد . والشرك على الإِيمان . . وتهديد هذا الكافر الطاغى بسوء المصير ، لأن الله - تعالى - مطلع على أعماله القبيحة . . وسيعاقبه العقاب الأكبر .","14":"قال صاحب الكشاف : فإن قلت : فأين جواب الشرط - أى فى قوله - تعالى - : ( أَرَأَيْتَ إِن كَانَ على الهدى ) ؟ قلت : هو محذوف تقديره : إن كان على الهدى ، ألم يعلم بأن الله يرى ، وإنما حذف لدلالة ذكره فى جواب الشرط الثانى .فإن قلت : فكيف صح أن يكون \" ألم يعلم \" جوابا للشرط؟ قلت : كما صح فى قولك : إن أكرمتك أتكرمنى؟ وإن أحسن إليك زيد هل تحسن إليه؟ ..","15":"وقوله - سبحانه - : ( كَلاَّ لَئِن لَّمْ يَنتَهِ لَنَسْفَعاً بالناصية ) ردع وزجر لهذا الكافر الطاغى الناهى عن الخير ، ولكل من يحاول أن يفعل فعله .والسفع : الجذب بشدة على سبيل الإِذلال والإِهانة ، تقول : سفعت بالشئ ، إذا جذبته جذبا شديدا بحيث لا يمكنه التفلت أو الهرب . . . وقيل : هو الاحتراق ، من قولهم : فلان سفعته النار ، إذا أحرقته وغيرت وجهه وجسده . والناصية : الشعر الذى يكون فى مقدمة الرأس . أى : كلا ليس الأمر كما فعل هذا الإِنسان الطاغى ، ولئن لم يقلع عما هو فيه من كفر وغرور ، لنقهرنه ، ولنذلنه ، ولنعذبنه عذابا شديدا فى الدنيا والآخرة .والتعبير بقوله - تعالى - : ( لَنَسْفَعاً بالناصية ) يشعر بالأخذ الشديد ، والإِذلال المهين ، لأنه كان من المعروف عند العرب ، أنهم كانوا إذا أرادوا إذلال إِنسان وعقابه ، سحبوه من شعر رأسه .والتعريف فى الناصية ، للعهد التقديرى . أى : بناصية ذلك الإِنسان الطاغى ، الذى كذب وتولى ، ونهى عن إقامة الصلاة .","16":"وقوله - تعالى - : ( نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ ) بدل من الناصية ، وجاز إبدال النكرة من المعرفة ، لأن النكرة قد وصفت ، فاستقلت بالفائدة .وخاطئة : اسم فاعل من خطئ فلان - كعلم - فهو خاطئ وهو الذى يأتى الذنب متعمدا ، ووصفت الناصية بأنها خاطئة مبالغة فى تعمد هذا الإِنسان الارتكاب المنكر ، على حد قولهم : نهار صائم ، أى : صائم صاحبه ، ولأن الناصية هى مظهر الغرور والكبرياء .أى : لئن لم ينته هذا الفاجر المغرور عن كفره . . لنذلنه إذلالا شديدا . . ولنسحبنه إلى النار من ناصيته التى طالما كذبت بالحق ، وتعمدت ارتكاب المنكر . .","17":"وقوله - سبحانه - : ( فَلْيَدْعُ نَادِيَهُ ) رد على غروره وتفاخره بعشيرته ، فقد جاء فى الحديث الشريف أن أبا جهل عندما نهى النبى صلى الله عليه وسلم عن الصلاة ، نهره النبى صلى الله عليه وسلم وزجره وأغلظ له القول . . فقال أبو جهل : أتهددنى يا محمد وأنا أكثر هذا الوادى ناديا ، فأنزل الله - سبحانه - : ( فَلْيَدْعُ نَادِيَهُ . سَنَدْعُ الزبانية ) .وأصل النادى : المكان الذى يجتمع فيه الناس للحديث ، ولا يسمى المكان بهذا الاسم إلا إذا كان معدا لهذا الغرض ، ومنه دار الندوة ، وهى دار كان أهل مكة يجتمعون فيها للتشاور فى مختلف أمورهم ، وسمى بذلك لأن الناس يَنْدُون إليه ، أى : يذهبون إليه ، أو ينتدون فيه ، أى : يجتمعون للحديث فيه . يقال : ندا القوم نَدْواً - من باب غزا - إذا اجتمعوا .والأمر فى قوله - تعالى - : ( فَلْيَدْعُ ) للتعجيز ، والكلام على حذف مضاف . أى : فليدع هذا الشقى المغرور أهله وعشيرته لإيذاء النبى صلى الله عليه وسلم ، ولمنعه من الصلاة ، إن قدروا على ذلك ، فنحن من جانبنا سندع الزبانية ، وهم الملائكة الغلاظ الموكلون بعقاب هذا المغرور وأمثاله .","18":"ولفظ الزبانية فى كلام العرب : يطلق على رجال الشرطة الذين يزبنون الناس ، أى : يدفعونهم إلى ما يريدون دفعهم إليه بقوة وشدة وغلظة ، جمع زِبْنيَّة ، وأصل اشتقاقه من الزَّبْنِ ، وهو الدفع الشديد ، ومنه قولهم : حرب زبون ، إذا اشتد الدفع والقتال فيها ، وناقة زبون إذا كانت تركل من يحلبها .والمقصود بهاتين الآيتين ، التهكم بهذا الإِنسان المغرور ، والاستخفاف به وبكل من يستنجد به ، ووعيده بأنه إن استمر فى غروره ونهيه عن الصلاة فسيسلط الله - تعالى - عليه ملائكة غلاظا شدادا . لا قبل له ولا لقومه بهم .","19":"وقوله - تعالى - : ( كَلاَّ لاَ تُطِعْهُ واسجد واقترب ) ردع آخر لهذا الكافر عن الغرور والبطر والطغيان ، وإبطال لدعواه أنه سيدع أهل نادية ، وتأكيد لعجزه عن منع الرسول صلى الله عليه وسلم عن الصلاة .\nأى : كلا ليس الأمر كما قال هذا المغرور من أن أهله وعشيرته سينصرونه ، وسيقفون إلى جانبه فى منعك أيها الرسول الكريم - من الصلاة ، فإنهم وغيرهم أعجز نم أن يفعلوا ذلك ، وعليك - أيها الرسول الكريم - أن تمضى فى طريقك وأن تواظب على أداء الصلاة فى المكان الذى تختاره ، ولا تطع هذا الشقى ، فإنه جاهل مغرور ، واسجد لربك وتقرب إليه - تعالى - بالعبادة والطاعة ، وداوم على ذلك .\nفالمقصود بهذه الآية الكريمة ، حض النبى صلى الله عليه على المداومة على الصلاة فى الكعبة ، وعدم المبالاة بنهى الناهين عن ذلك ، فإنهم أحقر من أن يفعلوا شيئا . .\nنسأل الله - تعالى - أن يجعلنا جميعا من عباده الصالحين .\nوصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"97":{"1":"الضمير المنصوب فى قوله - تعالى - ( أَنزَلْنَاهُ ) يعود إلى القرآن الكريم ، وفى الإِتيان بهذا الضمير للقرآن ، مع أنه لم يجر له ذكر ، تنويه بشأنه ، وإيذان بشهره أمره . حتى إنه ليُسْتَغْنَى عن التصريح به ، لحضوره فى أذهان المسلمين .والمراد بإنزاله : ابتداء نزوله على النبى صلى الله عليه وسلم ، لأنه من المعروف أن القرآن الكريم ، قد نزل على النبى صلى الله عليه سولم منجما ، فى مدة ثلاث وعشرين سنة تقريبا .ويصح أن يكون المراد بأنزلناه ، أى : أنزلناه جملة من اللوح المحفوظ إلى سماء الدنيا ، ثم نزل بعد ذلك منجما على النبى صلى الله عليه وسلم .قال الإِمام ابن كثير : قال ابن عباس وغيره : أنزل الله - تعالى - القرآن جملة واحدة من اللوح المحفوظ إلى بيت العزة من السماء الدنيا ، ثم نزل مفصلا بحسب الوقائع ، فى ثلاث وعشرين سنة ، على رسول الله صلى الله عليه وسلم .والقَدْر الذى أضيفت إليه الليلة ، بمعنى الشرف والعظمة ، مأخوذ من قولهم : لفلان قدر عند فلان ، أى : له منزلة رفيعة ، وشرف عظيم ، فسميت هذه الليلة بذلك ، لعظم قدرها وشرفها ، إذ هى الليلة التى نزل فيها قرآن ذو قدر ، بواسطة ملك ذى قدر ، على رسول ذى قدر ، لأجل إكرام أمه ذات قدر ، هذه الأمة يزداد قدرها وثوابها عند الله - تعالى - إذا ما أحيوا تلك الليلة بالعبادات والطاعات .","2":"ويصح أن يكون المراد بالقدر هنا : التقدير ، لأن الله - تعالى - يقدر فيها ما يشاء تقديره بعباده ، إلا أن القول الأول أظهر ، لأن قوله - سبحانه - بعد ذلك : ( وَمَآ أَدْرَاكَ مَا لَيْلَةُ القدر ) يفيد التعظيم والتفخيم .أى : إنا ابتدأنا بقدرتنا وحكمتنا ، إنزال هذا القرآن العظيم ، على رسولنا محمد صلى الله عليه وسلم فى ليلة القدر ، التى لها ما لها عندنا من قدر وشرف وعظم . . لأن للطاعات فيها قدرا كبيرا ، ثوابا جزيلا .وليلة القدر هذه هى الليلة التى قال الله - تعالى - فى شأنها فى سورة الدخان : ( إِنَّآ أَنزَلْنَاهُ فِي لَيْلَةٍ مُّبَارَكَةٍ إِنَّا كُنَّا مُنذِرِينَ . فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ . أَمْراً مِّنْ عِنْدِنَآ إِنَّا كُنَّا مُرْسِلِينَ . رَحْمَةً مِّن رَّبِّكَ إِنَّهُ هُوَ السميع العليم ) وهذه الليلة هى من ليالى شهر رمضان ، بدليل قوله - تعالى - : ( شَهْرُ رَمَضَانَ الذي أُنْزِلَ فِيهِ القرآن هُدًى لِّلنَّاسِ وَبَيِّنَاتٍ مِّنَ الهدى والفرقان ) قال بعض العلماء : ومن تسديد ترتيب المصحف ، أن سورة القدر وضعت عقب سورة العلق ، مع أنها أقل عددَ آياتٍ من سورة البينة وسور بعدها ، وكأن ذلك إيماء إلى أن الضمير فى ( أنزلناه ) يعود إلى القرآن ، الذى ابتدئ نزوله بسورة العلق .وقال صاحب الكشاف : عظم - سبحانه - القرآن من ثلاثة أوجه : أحدها : أن أسند إنزاله إليه ، وجعله مختصا به دون غيره ، والثانى : أنه جاء بضميره دون اسمه الظاهر ، شهادة له بالنباهة والاستغناء عن التنبيه عليه ، والثالث : الرفع من مقدار الوقت الذى أنزل فيه .روى أنه جملة واحدة فى ليلة القدر من اللوح المحفوظ إلى السماء الدنيا ، وأملاه جبريل على السفرة ثم كان ينزل به على رسول الله صلى الله عليه وسلم نجوما فى ثلاث وعشرين سنة .وعن الشعبى : المعنى أنا ابتدأنا إنزاله فى ليلة القدر . .وقوله - تعالى - : ( وَمَآ أَدْرَاكَ مَا لَيْلَةُ القدر ) تنويه آخر بشرف هذه الليلة ، وتفخيم لشأنها ، حتى لكأن عظمتها أكبر من أن تحيط بها الكلمات والألفاظ .أى : وما الذى يدريك بمقدار عظمتها وعلو قدرها ، إن الذى يعلم مقدار شرفها هو الله - تعالى - علام الغيوب .","3":"ثم - بين - سبحانه - مظاهر فضلها فقال : ( لَيْلَةُ القدر خَيْرٌ مِّنْ أَلْفِ شَهْرٍ ) أى : ليلة القدر أفضل من ألف شهر ، بسبب ما أنزل فيها من قرآن كريم يهدى للتى هى أقوم . ويخرج الناس من الظلمات إلى النور ، وبسبب أن العباد فيها أكثر ثواباً ، وأعظم فضلا من العبادة فى أشهر كثيرة ليس فيها ليلة القدر .والعمل القليل قد يفضل العمل الكثير ، باعتبار الزمان والمكان ، وإخلاص النية ، وحسن الأداء ، ولله - تعالى - أن يخص بعض الأزمنة والأمكنة والأشخاص بفضائل متميزة .والتحديد بألف شهر يمكن أن يكون مقصودا . ويمكن أن يراد منه التكثير . وأن المراد أن أقل عدد تفضله هذه الليلة هو هذا العدد . فيكون المعنى : أن هذه الليلة تفضل الدهر كله .","4":"ثم ذكر - سبحانه - بعد ذلك مزية أخرى لهذه الليلة المباركة فقال : ( تَنَزَّلُ الملائكة والروح فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ ) .أى : ومن مزايا وفضائل هذه الليلة أيضا ، أن الملائكة - وعلى رأسهم الروح الأمين جبريل - ينزلون فيها أفواجا إلى الأرض ، بأمره - تعالى - وإذنه ، وهم جميعا إنما ينزلونمن أجل أمر من الأمور التى يريد إبلاغها إلى عباده ، وأصل \" تنزل \" تتنزل ، فحذفت إحدى التاءين تخفيفا ، ونزول الملائكة إلى الأرض ، من أجل نشر البركات التى تحفهم ، فنزولهم فى تلك الليلة يدل على شرفها ، وعلى رحمة الله - تعالى - بعباده .والروح : هو جبريل ، وذكره بخصوصه بعد ذكر الملائكة ، من باب ذكر الخاص بعد العام ، لمزيد الفضل ، واختصاصه بأمور لا يشاركه فيها غيره .وقوله - سبحانه - ( بِإِذْنِ رَبِّهِم ) متعلق بقوله : ( تنزل ) ، والباء للسببية ، أى : يتنزلون بسبب إذن ربهم لهم فى النزول .قال الجمل ما ملخصه . وقوله : ( مِّن كُلِّ أَمْرٍ ) يجوز فى \" من \" وجهان : أحدهما أنها بمعنى اللام ، وتتعلق بتنزل ، تنزل من أجل كل أمر قضى إلى العام القابل .والثانى : أنها بمعنى الباء ، أى : تنزل بكل أمر قضاه الله - تعالى - فيها من موت وحياة ورزق .وليس المراد أن تقدير الله لا يحدث إلا فى تلك الليلة بل المراد إظهار تلك المقادير لملائكته .","5":"وقوله - تعالى - : ( سَلاَمٌ هِيَ حتى مَطْلَعِ الفجر ) بيان لمزية ثالثة من مزايا هذه الليلة ، وقوله ( سَلاَمٌ ) مصدر بمعنى السلامة ، وهو خبر مقدم ، و ( هى ) مبتدأ مؤخر ، وإنما قدم الخبر تعجيلا للمسّرة ، وقد أخبر عن هذه الليلة بالمصدر على سبيل المبالغة ، أو على سبيل تأويل المصدر باسم الفاعل ، أو على تقدير مضاف . . والمراد بمطلع الفجر : طلوعه وبزوغه .أى : هذه الليلة يظلها ويشملها السلام المستمر ، والأمان الدائم ، لكل مؤمن يحييها فى طاعة الله - تعالى - إلى أن يطلع الفجر ، أو هى ذات سلامة حتى مطلع الفجر ، أو هى سالمة من كل أذى وسوء لكل مؤمن ومؤمنة حتى طلوع الفجر .هذا وقد أفاض العلماء فى الحديث عن فضائل ليلة القدر ، وعن وقتها . وعن خصائصها . . وقد لخص الإِمام القرطبى ذلك تلخيصا حسناً فقال : وهنا ثلاث مسائل :الأولى : فى تعيين ليلة القدر . . والذى عليه المعظم أنها ليلة سبع وعشرين . . والجمهور على أنها فى كل عام من رمضان . . وقيل : أخفاها - سبحانه - فى جميع شهر رمضان ، ليجتهدوا فى العمل والعبادة طمعا فى إدراكها .الثانية : فى علاماتها : ومنها أن تطلع الشمس فى صبيحتها بيضاء لاشعاع لها .الثالثة : فى فضائلها . . وحسبك قوله - تعالى - ( لَيْلَةُ القدر خَيْرٌ مِّنْ أَلْفِ شَهْرٍ ) وقوله : ( تَنَزَّلُ الملائكة والروح فِيهَا ) وفى الصحيحين \" من قام ليلة القدر إيماناً واحتسابا غفر الله له ما تقدم من ذنبه . . \" .نسأل الله - تعالى - أن يجعلنا من المنتفعين بهذه الليلة المباركة .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"98":{"1":"\" مِنْ \" فى قوله - تعالى - ( مِنْ أَهْلِ الكتاب ) للبيان ، وقوله - سبحانه - ( مُنفَكِّينَ ) : للعلماء فى معنى هذا اللفظ أقوال متعددة ، منها : أنه اسم فاعل من انفك بمعنى انفصل ، يقال : فككت الشئ فانفك إذا افترق ما كان ملتحما منه .والبينة : الحجة الظاهرة التى يتميز بها الحق من الباطل ، وأصلها من البيان بمعنى الظهور والوضوح ، لأن بها تتضح الأمور ، أو من البينونة بمعنى الانفصال ، لأن بها ينفصل الحق عن الباطل بعد التباسهما .","2":"والمراد بها هنا : رسول الله صلى الله عليه وسلم ، لقوله - تعالى - بعد ذلك : ( رَسُولٌ مِّنَ الله يَتْلُواْ صُحُفاً مُّطَهَّرَةً ) ، ولأنه صلى الله عليه وسلم كان فى ذاته برهانا على صحة ما ادعاه من النبوة ، لتحليه بكمال العقل وبمكارم الأخلاق ، ولإِتيانه بالمعجزات التى تؤيد أنه صادق فيما يبلغه عن ربه .والمعنى : لم يكن الذين كفورا من أهل الكتاب ، وهم اليهود والنصارى ، ولم يكن - أيضاً - الذين كذبوا الحق من المشركين ، ولم يكن الجميع بمفارقين وبمنفصلين عن كفرهم وشركهم ، ( حتى تَأْتِيَهُمُ البينة ) التى هى الرسول صلى الله عليه وسلم فلما أتتهم هذه البينة ، منهم من آمن ومنهم من استمر على كفره وشركه وضلاله .وإلى هذا المعنى أشار صاحب الكشاف بقوله : \" كان الكفار من الفريقين ، أهل الكتاب ، وعبدة الأصنام ، يقولون قبل مبعث النبى صلى الله عليه وسلم : لا ننفك عما نحن عليه من ديننا ، ولا نتركه حتى يبعث النبى المكتوب فى التوراة والإنجيل ، وهو محمد صلى الله عليه وسلم ، فحكى الله - تعالى - ما كانوا يقولونه ، ثم قال : ( وَمَا تَفَرَّقَ الذين أُوتُواْ الكتاب ) ، يعنى أنهم كانوا يَعِدُون باجتماع الكلمة ، والاتفاق على الحق ، إذا جاءهم الرسول ، ثم ما فرقهم عن الحق ، ولا أقرهم على الكفر ، إلا مجئ الرسول صلى الله عليه وسلم ، ونظيره فى الكلام أن يقول الفقير الفاسق لمن يعظه : لست بمنفك عما أنا فيه حتى يرزقنى الله - تعالى - الغنى ، فيرزقه الله الغنى فيزداد فسقا ، فيقول له واعظة : لم تكن منفكا عن الفسق حتى توسر ، وما غمست رأسك فى الفسق إلا بعد اليسار ، يذكره ما كان يقوله توبيخا وإلزاما .وانفكاك الشئ من الشئ ، أن يزايله بعد التحامه به . كالعظم إذا انفك من مفصله .والمعنى : أنهم متشبثون بدينهم لا يتركونه إلا عند مجئ البينة .ومنهم من يرى : أن ( مُنفَكِّينَ ) بمعنى متروكين لا بمعنى تاركين ، أى : لم يكونوا جميعا متروكين على ما هم عليه من الكفر والشرك ، حتى تأتيهم البينة ، على معنى قوله - تعالى - : ( أَيَحْسَبُ الإنسان أَن يُتْرَكَ سُدًى ) أو المعنى : لم يكن هؤلاء القوم منفكين من أمر الله - تعالى - وقدرته ونظره لهم ، حتى يبعث الله - تعالى - إليهم رسولا منذرا ، تقوم عليهم به الحجة ، ويتم على من آمن النعمة ، فكأنه - تعالى - قال : ما كانوا ليتركوا سدى ..وهناك أقوال أخرى فى معنى الآية رأينا أن نضرب عنها صفحا لضعفها .وقد قدم الله - تعالى - ذكر أهل الكتاب فى البيان ، لأن كفرهم أشنع وأقبح . إذ كانوا يقرأون الكتب ، ويعرفون أوصاف النبى صلى الله عليه وسلم فكانت قدرتهم على معرفة صدقه أكبر وأتم . وفى التعبير عنهم بأهل الكتاب دون اليهود والنصارى ، تسجيل للغفلة وسوء النية عليهم . حيث علموا الكتاب . وعرفوا عن طريقه أن هناك رسولا كريما قد أرسله الله - تعالى - لهدايتهم ، ومع ذلك كفروا به ، كما قال - تعالى - : ( فَلَمَّا جَآءَهُمْ مَّا عَرَفُواْ كَفَرُواْ بِهِ فَلَعْنَةُ الله عَلَى الكافرين ) وقوله - سبحانه - : ( رَسُولٌ مِّنَ الله يَتْلُواْ صُحُفاً مُّطَهَّرَةً ) بدل من \" البيِّنَةِ \" على سبيل المبالغة ، حيث جعل - سبحانه - الرسول نفس البيئة .أى : لم يفارقوا دينهم حتى جاءهم رسول كريم ، كائن من عند الله - تعالى - لكى يقرأ على مسامعهم صحفا من القرآن الكريم ، مطهرة ، أى : منزهة عن الشرك والكفر والباطل .","3":"وهذه الصحف من صفاتها - أيضا - أنها ( فِيهَا كُتُبٌ قَيِّمَةٌ ) أى : فيها سور آيات قرآنية مستقيمة لا عوج فيها ، بل هى ناطقة بالحق والخير والصدق والهداية ، وبأخبار الأنبياء السابقين وبأحوالهم مع أقوامهم .فقوله : ( قَيِّمَةٌ ) بمعنى مستقيمة لا عوج فيها ولا اضطراب ، من قولهم : قام فلان يقوم ، إذا استوى على قدميه فى استقامة .","4":"ثم بين - سبحانه - ما كان عليه أهل الكتاب من جحودهم للحق ، ومن إنكارهم له مع علمهم به ، فقال - تعالى - ( وَمَا تَفَرَّقَ الذين أُوتُواْ الكتاب إِلاَّ مِن بَعْدِ مَا جَآءَتْهُمُ البينة ) . أى : أن الجاحدين والمعاندين والحاسدين لك - أيها الرسول الكريم - من أهل الكتاب ، ما تفرقوا فى أمره ، وما اختلفوا فى شأن نبوتك . . إلأا من بعد أن جئتهم أنت بما يدل على صدقك ، دلالة لا يجحدها إلا جهول ، ولا ينكرها إلا حسود ، ولا يعرض عنها إلا من طغى وآثر الحياة الدنيا .فالآية الكريمة كلام مستأنف ، المقصود به تسليته صلى الله عليه وسلم عما أصابه من هؤلاء الجاحدين فكأنه - سبحانه - يقول له : لا تحزن - أيها الرسول الكريم - لإِعراض من أعرض عن دعوتك من أهل الكتاب ، فإن إعراضهم لم يكن عن جهل ، وإنما عن عناد وجحود وحسد لك على ما آتاك الله من فضله .وإنما خص - سبحانه - هنا أهل الكتاب بالذكر ، مع أن الكلام فى أول السورة كان فيهم وفى المشركين ، للدلالة على شناعة حالهم ، وقبح فعالهم ، لأن الإِعراض عن الحق ممن له كتاب ، أشد قبحا ونكرا ، ممن ليس له كتاب وهم المشركون .والاستثناء فى الآية مفرغ ، والمستثنى منه عموم الأوقات . والمعنى : لم يتفرق الجاحدون من الذين أوتوا الكتاب فى وقت من الأوقات ، إلا فى الوقت الكائن بعد مجئ البينة لهم .ومن الآيات القرآنية الكثيرة التى وردت فى هذا المعنى قوله - تعالى - ( وَمَا تفرقوا إِلاَّ مِن بَعْدِ مَا جَآءَهُمُ العلم بَغْياً بَيْنَهُمْ ).","5":"ثم بين - سبحانه - ما كان يجب عليهم أن يفعلوه ، فقال : ( وَمَآ أمروا إِلاَّ لِيَعْبُدُواْ الله مُخْلِصِينَ لَهُ الدين حُنَفَآءَ وَيُقِيمُواْ الصلاة وَيُؤْتُواْ الزكاة وَذَلِكَ دِينُ القيمة ) .والواو فى قوله - تعالى - ( وَمَآ أمروا ) للحال ، فهذه الجملة حالية ، والمقصود منها بيان أن هؤلاء الضالين ، قد بلغوا النهاية فى قبح الأفعال ، وفى فساد العقول ، إذ أنهم تفرقوا واختلفوا وأعرضوا عن الهدى ، فى حال أنهم لم يؤمروا إلا بما فيه صلاحهم .وقوله : ( حنفاء ) من الحَنف ، وهو الميل من الدين الباطل إلى الدين الحق . كما أن الجنف هو الميل من الحق إلى الباطل .أى : أن هؤلاء الكافرين من أهل الكتاب تفرقوا واختلفوا فى شأن الحق ، والحال ، أنهم لم يؤمروا إلا بعبادة الله - تعالى - وحده ، مخلصين له الطاعة ، ومائلين عن الأديان الباطلة إلى الدين الحق ، مؤمنين بجميع الرسل بدون تفرقة بينهم ، إذ ملتهم جميعا وادحدة ، ولم يؤمروا - أيضا - إلا بإقامة الصلاة فى أوقاتها بخشوع وإخلاص لله رب العالمين ، وبإيتاء الزكاة التى تطهرهم وتزكيهم .( وذلك ) الذى أمرناهم به من إخلاص العبادة لنا ، ومن أداء فرائضنا ( دِينُ القيمة ) . أى : دين الملة المستقيمة القيمة ، أو دين الكتب القيمة .ولفظ \" القيمة \" بزنة فيعلة - من القوامة ، وهى غاية الاستقامة ، وهذا اللفظ صفة لموصوف محذوف .","6":"ثم - بين - سبحانه - سوء عاقبة هؤلاء الجاحدين من أهل الكتاب ومن المشركين فقال : ( إِنَّ الذين كَفَرُواْ مِنْ أَهْلِ الكتاب والمشركين فِي نَارِ جَهَنَّمَ خَالِدِينَ فِيهَآ ) .أى : إن الذين أصروا على كفرهم بعد أن تبين لهم ، من اليهود والنصارى ، ومن المشركين الذين هم عبدة الأصنام . . مكانهم المهيأ لهم هو نار جهنم ، حالة كونهم خالدين فيها خلودا أبديا ( أولئك ) الموصوفون بتلك الصفات الذميمة ( هُمْ شَرُّ البرية ) أى : هم شر كل صنف من أصناف المخلوقات ، لإِصرارهم على الكفر والإِشراك مع علمهم بالحق .ولفظ \" البرية \" من البرَى وهو التراب ، لأنهم قد خلقوا فى الأصل منه ، يقال : فلان برَاه الله - تعالى - يبرُوه بَرْواً . أى : خلقه وقرأ نافع بالهمز ، من قولهم برأ الله - تعالى - الخلق يبرؤهم ، أى : خلقهم .وقدم سبحانه - أهل الكتاب فى المذمة ، لأن جنايتهم فى حق الرسول صلى الله عليه وسلم أشد ، إذا كانوا يستفتحون به على المشركين ويقولون لهم : إن نبيا قد أظللنا زمانه ، وإننا عند مبعثه سنتبعه .. فلما بعث صلى الله عليه وسلم كفروا به .وقد تضمنت هذه الآية الكريمة أمرين : الأول : أن هؤلاء الضالين خالدون فى النار ، والثانى : أنهم شر المخلوقات التى خلقها الله - تعالى - .","7":"ثم بين - سبحانه - بعد ذلك حسن عاقبة المؤمنين فقال : ( إِنَّ الذين آمَنُواْ وَعَمِلُواْ الصالحات ) أى : وعملوا الأعمال الصالحات ( أولئك هُمْ خَيْرُ البرية ) أى : أولئك هم خير المخلوقات التى خلقها الله - تعالى - .","8":"( جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِى مِنْ تَحْتِهَا الأنهار خَالِدِينَ فِيهَآ أَبَداً ) أى : خالدين فى تلك الجنات خلودا أبديا .( رِّضِىَ الله عَنْهُمْ وَرَضُواْ عَنْهُ ) أى : قبل الله - تعالى - منهم أعمالهم ورضيها عنده ، وفرحوا هم ورضوا بما أعطاهم من خير عميم .فالمراد برضاء - تعالى - عنهم : قبوله لأعمالهم ، وبرضاهم عنه : فرحهم بما أعطاهم من فضله . ( ذلك ) أى : العطاء الجزيل ( لِمَنْ خَشِيَ رَبَّهُ ) أى : كائن وثابت لمن خاف مقام ربه ونهى النفس عن الهوى .نسأل الله - تعالى - أن يجعلنا جميعا من أصحاب الميمنة .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"99":{"1":"قوله - تعالى - : ( زُلْزِلَتِ ) أى : حركت تحريكا شديدا لا يعلم مقداره إلا الله - تعالى - ، إذ الزلزال : الحركة الشديدة مع الاضطراب ، وهو بفتح الزاى اسم لذلك ، وبكسرها مصدر بمعنى التحرك والاضطراب ، وشبيه بهذه الآية قوله - تعالى - : ( إِذَا رُجَّتِ الأرض رَجّاً ) ويكون هذا الزلزال الشديد ، عندما يأذن الله - تعالى - بقيام الساعة ، ويبعث الناس للحساب .وافتتح - سبحانه - الكلام بظرف الزمان ( إذا ) ، لإِفادة تحقق وقوع الشرط .وقوله : ( زِلْزَالَهَا ) مصدر مضاف لفاعله . أى : إذا زلزلت الأرض زلزالها الذى لا يماثله زلزال آخر فى شدته وعظمته وهوله ، كما قال - تعالى - : ( ياأيها الناس اتقوا رَبَّكُمْ إِنَّ زَلْزَلَةَ الساعة شَيْءٌ عَظِيمٌ ) .","2":"وقوله - تعالى - : ( وَأَخْرَجَتِ الأرض أَثْقَالَهَا ) بيان لأثر آخر من آثار ما يحدث فى هذا اليوم الهائل الشديد .والأثقال : جمع ثِقْل - بكسر فسكون - وهو المتاع الثقيل ، ومنه قوله - تعالى - : ( وَتَحْمِلُ أَثْقَالَكُمْ إلى بَلَدٍ لَّمْ تَكُونُواْ بَالِغِيهِ إِلاَّ بِشِقِّ الأنفس ) والمراد بها هنا : ما يكون فى جوف الأرض من أموات وكنوز وغير ذلك مما يكون فى باطنها . قال أبو عبيدة والأخفش : إذا كان الميت فى جوف الأرض فهو ثقل لها ، وإذا كان فوقها فهو ثقل عليها ، وإنما سمى الجن والإِنس بالثقلين لأن الأرض تثقل بهم . . .","3":"والمراد بالإِنسان فى قوله - سبحانه - : ( وَقَالَ الإنسان مَا لَهَا ) جنسه فيشمل المؤمن والكافر .وقوله ( ما لها ) مبتدأ وخبر ، والاستفهام : المقصود به التعجب مما حدث من أهوال .أى : وقال كل إنسان على سبيل الدهشة والحيرة ، أى : شئ حدث للأرض ، حتى جعلها تضطرب هذا الاضطراب الشديد .قال الجمل : وفى المراد بالإِنسان هنا قولان : أحدهما : أنه اسم جنس يعم المؤمن والكافر ، وهذا يدل على قول من جعل الزلزلة من أشراط الساعة ، فيسأل بعضهم بعضا عن ذلك . والثانى : أنه الكافر خاصة ، وهذا يدل على قول من جعلها زلزلة القيامة ، لأن المؤمن عارف بها فلا يسأل عنها ، والكافر جاحد لها ، فإذا وقعت سأل عنها . .","4":"وقوله - سبحانه - : ( يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ) جواب الشرط ، و \" أخبارها \" مفعول ثان لقوله : ( تُحَدِّثُ ) والمفعول الأول محذوف . أى : إذا زلزلت الأرض زلزالها ، وأخرجت الأرض أثقالها . وقال الإِنسان ماذا حدث لها . . عندئذ تحدِّثُ الأرضُ الخلائقَ أخبارَها ، بأن تشهد للطائع بأنه كان كذلك ، وتشهد الفاسق بأنه كان كذلك .أخرج الإِمام أحمد والترمذى والنسائى عن أبى هريرة قال : \" قرأ رسول الله صلى الله عليه وسلم هذه الآية ( يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ) ثم قال : \" أتدرون ما أخبارها \"؟ قالوا : الله ورسوله أعلم . قال : \" فإن أخبارها أن تشهد على كل عبد وأمة بما عُمِل على ظهرها ، بأن تقول : عمل كذا وكذا يوم كذا وكذا . فهذه أخبارها . \" \" .والظاهر أن هذا التحديث من الأرض على سبيل الحقيقة ، بأن يخلق الله - تعالى - فيها حياة وإدراكا ، فتشهد بما عمل عليها من عمل صالح أو طالح ، كما تشهد على من فعل ذلك .وقيل : هذا مثل ضربه الله - تعالى - والمقصود منه أن كل إنسان فى هذا اليوم سيتبين جزاء عمله ، وما أعده الله - تعالى - له على ما قدم فى حياته الأولى ، ونظير ذلك أن تقول : إن هذه الدار لتحدثنا بأنها كانت مسكونة .قال بعض العلماء ما ملخصه : قوله : ( يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ) يومئذ بدل من إذا . أى : فى ذلك الوقت تحدثك الأرض أحاديثها ، وتحديث الأرض تمثيل - كما قال الطبرى وغيره - أى : أن حالها وما يقع فيها من الانقلاب ، وما لم يعهد من الخراب ، يعلم السائل ويفهمه الخبر ، وأن ما يراه لم يكن بسبب من الأسباب التى وضعها السنة الإِلهية ، حال استقرار نظام الكون ، بل ذلك بسبب ( بِأَنَّ رَبَّكَ أوحى لَهَا )","5":"( بِأَنَّ رَبَّكَ أوحى لَهَا )أى : أن ما يحدث للأرض يومئذ ، إنما هو بأمر إلهى خاص . بأن قال لها كونى كذلك فكانت كما قال لها .وعدى فعل \" أوحى \" باللام - مع أن حقه أن يتعدى بإلى كما فى قوله - تعالى - ( وأوحى رَبُّكَ إلى النحل ) لتضمينه معنى \" قال \" كما فى قوله - سبحانه - ( فَقَالَ لَهَا وَلِلأَرْضِ ائتيا طَوْعاً أَوْ كَرْهاً قَالَتَآ أَتَيْنَا طَآئِعِينَ ) والمعنى : إن الأرض تحدث الناس عن أخبارها ، وتبينها لهم ، وتشهد عليهم . . . بسبب أن ربك الذى خلقك فسواك فعدلك - أيها الإِنسان - قد أمرها بذلك .","6":"ثم بين - سبحانه - بعد ذلك أحوال الناس فى هذا اليوم فقال : ( يَوْمَئِذٍ يَصْدُرُ الناس أَشْتَاتاً لِّيُرَوْاْ أَعْمَالَهُمْ ) .والجملة الكريمة بدل من جملة \" يومئذ تحدث أخبارها \" ، وقوله ( يَصْدُرُ ) فعل مضارع من الصدَر - بفتح الدال - على الرجوع عن الشرب ، يقال : صدرَ الناس عن الوِرْد ، إذا انصرفوا عنه . و ( أَشْتَاتاً ) جمع شتيت ، أى : متفرق ، ومنه قولهم : شتت الله جمع الأعداء ، أى فرق أمرهم .وقوله - تعالى - ( لِّيُرَوْاْ ) فعل مضارع مبنى للمجهول ، وماضيه المبنى للمعلوم \" أراه \" بمعنى أطلعه . أى : فى هذا اليوم الذى تتزلزل فيه الأرض زلزلة شديدة . . يخرج الناس من قبورهم متجهين أشتاتا إلى موقف الحساب ، وكل واحد منهم مشغول بنفسه ، لكى يبصروا جزاء أعالهم ، التى عملوها فى دنياهم .وجاء فعل \" ليروا \" مبنيا للمجهول ، لأن المقصود رؤيتهم لأعمالهم ، وليس المقصود تعيين من يريهم إياها .","7":"ثم فصل - سبحانه - ما يترتب على هذه الرؤية من جزاء فقال : ( فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراً يَرَهُ .\nوَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرّاً يَرَهُ )\nو \" المثقال \" مفعال من الثقل ، ويطلق على الشئ القليل الذى يحتمل الوزن ، و \" الذرة \" تطلق على أصغر النمل ، وعلى الغبار الدقيق الذى يتطاير من التراب عند النفخ فيه . والمقصود المبالغة فى الجزاء على الأعمال مهما بلغ صغرها ، وحقر وزنها .\nوالفاء : للتفريع على ما تقدم . أى : فى هذا اليوم يخرج الناس من قبورهم متفرقين لا يلوى أحد على أحد . متجهين إلى موقف الحساب ليطلعوا على جزاء أعاملهم الدنيوية . . فمن كان منهم قد عمل فى دنياه عملا صالحا رأى ثماره الطيبة ، حتى ولو كان هذا العمل فى نهاية القلة ، ومن كان منهم قد عمل عملا سيئا فى دنياه ، رأى ثماره السيئة ، حتى ولو كان هذا العمل - أيضا - فى أدنى درجات القلة .\nفأنت ترى أن هاتين الآيتين قد جمعتا أسمى وأحكم ألوان الترغيب والترهيب ، ولذا قال كعب الأحبار : لقد أنزل الله - تعالى - على نبيه محمد صلى الله عليه وسلم آيتين ، أحصتا ما فى التوراة والإِنجيل والزبور والصحف ، ثم قرأ هاتين الآيتين .\nوقد ساق الإِمام ابن كثير عند تفسيره لهاتين عددا من الأحاديث ، منها : ما أخرجه الإِمام أحمد . \" أن صعصعة بن معاوية ، أتى النبى صلى الله عليه وسلم فقرأ عليه هاتين الآيتين ، فقال : حسبى لا أبالى أن لا أسمع غيرها \" وفى صحيح البخارى أن رسول الله صلى الله عليه وسلم قال : \" اتقوا النار ولو بشق تمرة ، ولو بكلمة طيبة \" .\nوفى الصحيح - أيضاً - أن رسول الله صلى الله عليه وسلم قال : \" لا تحقرن من المعروف شيئاً ولو أن تفرغ من دلوك فى إناء المستقى ، ولو أن تلقى أخاك ووجهك إليه منبسط \" .\nوكان صلى الله عليه وسلم يقول لعائشة : \" يا عائشة ، استترى من النار ولو بشق تمرة ، فإنها تسد من الجائع مسدها من الشبعان . يا عائشة . إياك ومحقرات الذنوب ، فإن لها من الله - تعالى - طالبا \" .\nومن الآيات الكريمة التى وردت فى معنى هاتين الآيتين قوله - تعالى - ( إِنَّ الله لاَ يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِن تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْراً عَظِيماً ) وقوله - سبحانه - : ( وَنَضَعُ الموازين القسط لِيَوْمِ القيامة فَلاَ تُظْلَمُ نَفْسٌ شَيْئاً وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وكفى بِنَا حَاسِبِينَ ) نسأل الله - تعالى - أن يجعلنا جميعا ممن يواظبون على فعل الخيرات .\nوصلى الله على سيدنا محمد وعلى آله وصحبه وسلم .","8":"ثم فصل - سبحانه - ما يترتب على هذه الرؤية من جزاء فقال : ( فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراً يَرَهُ .وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرّاً يَرَهُ )و \" المثقال \" مفعال من الثقل ، ويطلق على الشئ القليل الذى يحتمل الوزن ، و \" الذرة \" تطلق على أصغر النمل ، وعلى الغبار الدقيق الذى يتطاير من التراب عند النفخ فيه . والمقصود المبالغة فى الجزاء على الأعمال مهما بلغ صغرها ، وحقر وزنها .والفاء : للتفريع على ما تقدم . أى : فى هذا اليوم يخرج الناس من قبورهم متفرقين لا يلوى أحد على أحد . متجهين إلى موقف الحساب ليطلعوا على جزاء أعاملهم الدنيوية . . فمن كان منهم قد عمل فى دنياه عملا صالحا رأى ثماره الطيبة ، حتى ولو كان هذا العمل فى نهاية القلة ، ومن كان منهم قد عمل عملا سيئا فى دنياه ، رأى ثماره السيئة ، حتى ولو كان هذا العمل - أيضا - فى أدنى درجات القلة .فأنت ترى أن هاتين الآيتين قد جمعتا أسمى وأحكم ألوان الترغيب والترهيب ، ولذا قال كعب الأحبار : لقد أنزل الله - تعلى - على نبيه محمد صلى الله عليه وسلم آيتين ، أحصتا ما فى التوراة والإِنجيل والزبور والصحف ، ثم قرأ هاتين الآيتين .وقد ساق الإِمام ابن كثير عند تفسيره لهاتين عددا من الأحاديث ، منها : ما أخرجه الإِمام أحمد . \" أن صعصعة بن معاوية ، أتى النبى صلى الله عليه وسلم فقرأ عليه هاتين الآيتين ، فقال : حسبى لا أبالى أن لا أسمع غيرها \" وفى صحيح البخارى أن رسول الله صلى الله عليه وسلم قال : \" اتقوا النار ولو بشق تمرة ، ولو بكلمة طيبة \" .وفى الصحيح - أيضاً - أن رسول الله صلى الله عليه وسلم قال : \" لا تحقرن من المعروف شيئاً ولو أن تفرغ من دلوك فى إناء المستقى ، ولو أن تلقى أخاك ووجهك إليه منبسط \" .وكان صلى الله عليه وسلم يقول لعائشة : \" يا عائشة ، استترى من النار ولو بشق تمرة ، فإنها تسد من الجائع مسدها من الشبعان . يا عائشة . إياك ومحقرات الذنوب ، فإن لها من الله - تعالى - طالبا \" .ومن الآيات الكريمة التى وردت فى معنى هاتين الآيتين قوله - تعالى - ( إِنَّ الله لاَ يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِن تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْراً عَظِيماً ) وقوله - سبحانه - : ( وَنَضَعُ الموازين القسط لِيَوْمِ القيامة فَلاَ تُظْلَمُ نَفْسٌ شَيْئاً وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وكفى بِنَا حَاسِبِينَ ) نسأل الله - تعالى - أن يجعلنا جميعا ممن يواظبون على فعل الخيرات .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"100":{"1":"العاديات : جمع عادية ، اسم فاعل من العدو ، وهو المشى السريع ، وأصل الياء فى العاديات واو ، فلما وقعت متطرفة بعد كسرة قلبت ياء ، مثل الغازيات من الغزو .والضَّبْح : اضطراب النَّفَسِ المتردد فى الحنجرة دون أن يخرج من الفم ، والمراد به هنا : صوت أنفاس الخيل عند جريها بسرعة . وقيل : الضج نوع من السير والعدو ، يقال : ضَبَحَتْ الخيل ، إذا عدَتْ بشدة . وهو مصدر منصوب بفعله المقدر ، أى : يضبحن ضحبا ، والجملة حال من \" العاديات \" .","2":"والموريات : جمع مُورِيَة ، اسم فاعل من الإِيراء ، وهو إخراج النار ، تقول : أَوْرَى فلان ، إذا أخرج النار بزند ونحوه .والقَدْح : ضَرْب شىءٍ لكى يخرج من بينهما شرر النار .والمراد به هنا : النار التى تخرج من أثر احتكاك حوافر الخيل بالحجارة خلال عدوها بسرعة .","3":"و ( المغيرات) جمع مغيرة . وفعله أغار ، تقول : أغار فلان على فلان ، إذا باغته بفعل يؤذيه . و ( صبحا ) منصوب على الظرفية .","4":"وقوله : ( فَأَثَرْنَ بِهِ نَقْعاً ) أى : هيجن وأثرن \" النقع \" أى : الغبار من شدة الجرى . تقول : أثرت الغبار أثيره ، إذا هيجته وحركته . والنون فى \" أثرن \" ضمير العاديات .","5":"وقوله : ( فَوَسَطْنَ بِهِ جَمْعاً ) أى : فتوسطن فى ذلك الوقت جمعو الأعداء ، ففرقنها ، ومزقنها ، تقول : وسَطْتُ القومَ أسِطُهم وَسْطاً ، إذا صرت فى وسطهم .والمراد بالعاديات ، والموريات ، والمغيرات : خيل المجاهدين فى سبيل الله ، والكلام على حذف الموصوف . والمعنى : وحق الخيل التى يعتلى صهواتها المجاهدون من أجل إعلاء كلمة الله - تعالى - . والتى تجرى بهم فى ساحات القتال ، فيسمع صوت أنفاسها ، والتى تظهر شرر النار من أثر ضك حوافرها بالحجارة وما يشبهها والتى تغير على العدو فى وقت الصباح ، فتثير الغبار ، وتمزق جمعو الأعداء .وحق هذه الخيل الموصوفة بتلك الصفات . . ( إِنَّ الإنسان لِرَبِّهِ لَكَنُودٌ ) .وقد أقسم - سبحانه - بالخيل المستعملة للجهاد فى سبيله ، للتنبيه على فضلها ، وفضل ربطها ، ولما فيها من المنافع الدينية والدنيوية ، ولما يترتب على استعمالها فى تلك الأغراض من أجر وغنيمة ، ومن ترويع لجموع المشركين ، وتمزيق لصفوفهم .وأسند - سبحانه - الإِغارة إليها - مع أنها فى الحقيقة لراكبيها - ، لأن الخيول هى عدة الإِغارة ، وهى على رأس الوسائل لبلوغ النصر على الأعداء .وقيل : المراد بالعاديات : الإِبل ، إلا أن الأوصاف فى الآيات الكريمة من الضج والإِغارة . . تؤيد أن المراد بها الخيل .قال صاحب الكشاف : أقسم - سبحانه - بخيل الغزاة تعدو فتضبح . والضبح : صوت أنفاسها إذا عدون .فإن قلت : علام عطف \" فأثرن \"؟ قلت : على الفعل الذى وضع اسم الفاعل موضعه ، وهو قوله ( فالمغيرات صُبْحاً ) وذلك لصحة عطف الفعل على الاسم الذى يشبه الفعل كاسم الفاعل - لأن المعنى : واللائى عدون ، فأورين ، فأغرن .فأثرن الغبار .والتعبير بالفاء فى قوله - تعالى - : ( فَأَثَرْنَ ) ( فَوَسَطْنَ ) . وبالفعل الماضى ، للإِشارة إلى أن إثارة الغبار ، وتمزيق صفوف الأعداء ، قد تحقق بسرعة ، وأن الظفر بالمطلوب قد تم على أحسن الوجوه .","6":"وقوله - سبحانه - : ( إِنَّ الإنسان لِرَبِّهِ لَكَنُودٌ ) جواب القسم . والكنود : الجحود ، يقال : فلان كند النعمة - من باب دخل - ، إذا جحدها ولم يشكر الله عليها . وكند الحبل : أى قطعة ، وأصل الكنود : الأرض التى لا تنبت شيئا ، فشبه بها الإِنسان الذى يمنع الحق والخير ، ويجحد ما عليه من حقوق وواجبات .أى : إن فى طبع الإِنسان - إلا من عصمه الله - تعالى - الكنود لربه والكفران لنعمته ، والنسيان لمننه وإحسانه ، والغفلة عن المواظبة على شكره - تعالى - ، والتضرع إليه - سبحانه - عند الشدائد والضراء . . والتشاغل عن ذلك عند العافية والرخاء .فالمراد بالإِنسان هنا : جنسه ، إذ أن هذه الصفة غالبة على طبع الإِنسان بنسب متفاوتة ، ولا يسلم منها إلا من عصمه الله - تعالى - .وقيل : المراد بالإِنسان هنا : الكافر ، وأن المقصود به ، الوليد بن المغيرة .والأولى أن يكون المراد به الجنس ، ويدخل فيه الكافر دخولا أوليا .","7":"وقوله - تعالى - : ( وَإِنَّهُ على ذَلِكَ لَشَهِيدٌ ) أى : وإن الإِنسان على كنوده وجحوده لنعم ربه \" لشهيد \" أى : لشاهد على نفسه بذلك ، لظهور أثر هذه الصفة عليه ظهروا واضحا ، إذ هو عند لجاجه فى الطغيان يجحد الجلى من النعم ، ويعبد من دون خالقه أصناما ، مع أنه إذا سئل عن خالقه اعترف وأقر بأن خالقه هو الله - تعالى - ، كما قال - سبحانه - : ( وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ الله ) قال الإِمام الشيخ محمد عبده : قوله : ( وَإِنَّهُ على ذَلِكَ لَشَهِيدٌ ) أى : وإن الإِنسان لشهيد على كنوده ، وكفره لنعمة ربه ، لأنه يفخلر بالقسوة على من دونه ، وبقوة الحيلة على من فوقه ، وبكثرة ما فى يده من المال مع الحذق فى تحصيله ، وقلما يفتخر بالمرحمة ، وبكثرة البذل - اللهم إلا أن يريد غشا للسامع - وفى ذلك كله شهادة على نفسه بالكنود ، لأن ما يفتخر به ليس من حق شكر النعمة ، بل من آيات كفرها .ومنهم من يرى أن الضمير فى قوله - تعالى - هنا ( وأنه ) يعود على الخالق - سبحانه - أى : وإن الله - تعالى - لعليهم ولشهيد على ما يسلكه هذا الإِنسان من جحود ، فيكون المقصود من الآية الكريمة ، التهديد والوعيد .قالوا : والأول أولى ، لأنه هو الذى يتسق مع سياق الآيات ، ومع اتحاد الضمائر فيها .","8":"وقوله - تعالى - : ( وَإِنَّهُ لِحُبِّ الخير لَشَدِيدٌ ) أى : وإن هذا الإِنسان لشديد الحب لجمع المال ، ولكسبه من مختلف الوجوه بدون تفرقة - فى كثير من الأحيان - بين الحلال والحرام ، ولكنزه والتكثر منه ، وبالبخل به على من يستحقه .وصدق الله إذ يقول : ( قُل لَّوْ أَنْتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّي إِذاً لأمْسَكْتُمْ خَشْيَةَ الإنفاق وَكَانَ الإنسان قَتُوراً ) .","9":"وقوله - تعالى - : ( أَفَلاَ يَعْلَمُ إِذَا بُعْثِرَ مَا فِي القبور . وَحُصِّلَ مَا فِي الصدور . إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌ ) تهديد لهذا الإِنسان الكنود . . وتحريض له على التفكر والاعتبار ، وتذكير له بأهوال يوم القيامة .أى : أيفعل ما يفعل هذا الإِنسان الجحود لنعم ربه . . فلا يعلم مآله وعاقبته ( إِذَا بُعْثِرَ ) . أى : إذا أثير وأخرج وقلب رأسا على عقب ( مَا فِي القبور ) من أموات حيث أعاد - سبحانه - إليهم الحياة ، وبعثهم للحساب والجزاء ، كما قال - تعالى - : ( وَإِذَا القبور بُعْثِرَتْ ) أى : أثيرت وأخرج ما فيها . يقال : بعثر فلان متاعه ، إذا جعل أسفله أعلاه .","10":"( وَحُصِّلَ مَا فِي الصدور ) أى : وجمع ما فى القلوب من خير وشر وأظهر ما كانت تخفيه ، وأبرز ما كان مستورا فيها ، بحيث لا يبقى لها سبيل إلى الإِخفاء أو الكتمان .وأصل التحصيل : إخراج اللب من القشر ، والمراد به هنا : إظهار وإبراز ما كانت تخفيه الصدور ، والمجازاة على ذلك . ومفعول ( يعلم ) محذوف ، لتذهب النفس فيه كل مذهب ويجول الفكر فى استحضاره وتقديره .","11":"وقوله - تعالى - : ( إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌ ) جملة مستأنفة لزيادة التهديد ووالوعيد .أى : إن رب المبعوثين للحساب والجزاء ، ليعلم علما تاما ً بأحوالهم الظاهرة والباطنة ، فى ذلك اليوم الهائل الشديد الذى يبعث فيه الناس من قبورهم ، وسيجازى - سبحانه - الذين أساؤوا بما عملوا ، وسيجازى الذين أحسنوا بالحسنى .نسأل الله - تعالى - أن يجعلنا من أهل طاعته ومثوبته .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"101":{"1":"لفظ \" القارعة \" اسم فاعل من القرع ، وهو الضرب بشدة بحيث يحصل منه صوت شديد .والمراد بها هنا : القيامة ، ومبدؤها النفخة الأولى ، ونهايتها : قضاء الله - تعالى - بين خلقه ، بحكمه العادل ، وجزائه لكل فريق بما يستحقه من جنة أو نار .وسميت القيامة بذلك . كما سميت بالطامة ، والصاخة ، والحاقة ، والغاشية . . إلخ - لأنها قترع القلوب بأهوالها ، وتجعل الأجرام العلوية والسفلية يصطك بعضها ببعض ، فيحصل لها ما يحصل من تزلزل واضطراب وتقرع أعداء الله - تعالى - بالخزى والعذاب والنكال ، كما قال - تعالى - : ( وَلاَ يَزَالُ الذين كَفَرُواْ تُصِيبُهُم بِمَا صَنَعُواْ قَارِعَةٌ ) والاستفهام فى قوله - سبحانه - : ( وَمَآ أَدْرَاكَ مَا القارعة ) استفهام عن حقيقتها ، والمقصود به التهويل من أمرها ، والتفظيع من حالها ، وتنبيه النفوس إلى ما يكون فيها من شدائد ، تفزع لها القلوب فزعا لا تحيط العبارة بتصويره ، ولا تستطيع العقول أن تدرك كنهه .","2":"و \" القارعة \" : مبتدأ ، و \" ما \" : مبتدأ ثان ، و \" القارعة \" : خبر المبتدأ الثانى ، وجملة المبتدأ الثانى وخبره فى محل رفع خبر المبتدأ الأول .","3":"وقوله - سبحانه - : ( وَمَآ أَدْرَاكَ مَا القارعة ) معطوف على جملة \" ما القارعة \" والخطاب فى قوله ( وَمَآ أَدْرَاكَ ) لكل من يصلح له .أى : وما أدراك - أيها المخاطب - ما كنهها فى الشدة؟ إنها فى الشدة والهول شئ عظيم . لا يعلم مقدارها إلا الله - تعالى - .فالمقصود من الآيات الكريمة : تعظيم شأنها ، والتعجيب من حالها ، وأنها تختلف عن قوارع الدنيا - مهما بلغ عظمها - اختلافا كبيرا .","4":"وبعد أن بين - سبحانه - أن معرفة حقيقتها أمر عسير . . أتبع ذلك ببيان أحوال الناس وقت وقوعها فقال : ( يَوْمَ يَكُونُ الناس كالفراش المبثوث ) .و \" يوم \" منصوب بفعل مقدر . والفراش : هو الحشرة التى تتهافت نحو النار ، وسمى بذلك لأنه يتفرش وينتشر من حولها .والمبثوث : المنتشر المتفرق . تقول : بثثت الشئ ، إذا فرقته ، ومنه قوله - تعالى - : ( وَزَرَابِيُّ مَبْثُوثَةٌ ) أى : متناثرة متفرقة .أى : تحصل القارعة يوم يكون الناس فى انتشارهم وكثرتهم واضطرابهم وإقبالهم نحو الداعى لهم نحو أرض المحشر . . كالحشرات الصغيرة المتهافتة نحو النار .فأنت ترى أنه - سبحانه - قد شبه الناس فى هذا الوقت العصيب ، بالفراش المتفرق المنتشر فى كل اتجاه ، وذلك لأن الناس فى هذا اليوم يكونون فى فزع ، يجعل كل واحد منهم مشغولا بنفسه ، وفى حالة شديدة من الخوف والاضطراب .","5":"وقوله - سبحانه - : ( وَتَكُونُ الجبال كالعهن المنفوش ) بيان لحالة أخرى من الأحوال التى يكون عليها هذا الكون يوم القيامة .والعهن : الصوف ذو الألوان المتعددة ، والمنفوش : المفرق بعضه عن بعض .أى : وتكون الجبال فى ذلك اليوم ، كالصوف الذى ينفش ويفرق باليد ونحوها . لخفته وتناثر أجزائه ، حتى يسهل غزله .والمتأمل فى هذه الآيات الكريمة ، يراها قد اشتملت على أقوا الأساليب وأبلغها ، فى التحذير من أهوال يوم القيامة ، وفى الحض على الاستعداد له بالإِيمان والعمل الصالح .لأنها قد ابتدأت بلفظ القارعة ، المؤذن بأمر عظيم ، ثم ثنت بالاستفهام المستعمل فى التهويل ، ثم أعادت اللفظ بذاته بدون إضمار له زيادة فى تعظيم أمره ، ثم جعلت الخطاب لكل من يصلح له ، ثم شبهت الناس فى تشبيها تقشعر منه الجلود ، ثم وصفت الجبال - وهى المعروفة بصلابتها ورسوخها - بأنها ستكون فى هذا اليوم كالصوف المتناثر الممزق .","6":"ثم بين - سبحانه - أحوال السعداء والأشقياء فى هذا اليوم فقال : ( فَأَمَّا مَن ثَقُلَتْ مَوَازِينُهُ . فَهُوَ فِي عِيشَةٍ رَّاضِيَةٍ ) .أى : فأما من ثقلت موازين حسناته ، ورجحت أعماله الصالحة على غيرها .","7":"فهو فى عيشة مرضية . أو فى عيشة ذات رضا من صاحبها ، لأنها عيشة هنية كريمة .","8":"( وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ ) أى : خفت موازين حسناته ، وثقلت موازين سيئاته ، ( فَأُمُّهُ هَاوِيَةٌ ) أى : فمرجعه ومأواه الذى يأوى إليه ، نار سحيقة يهوى إليها بدون رحمة أو شفقة ، بسبب كفره وفسوقه .فالمراد بالأم هنا : المرجع والمأوى ، وبالهاوية : النار التى يسقط فيها ، وسميت النار بذلك . لشدة عمقها . وسمى المأوى أُمًّا ، لأن الإِنسان يأوى إليه كما يأوى ويلجأ إلى أمه .ويرى بعضهم أن المراد بأمه هنا الحقيقة ، لأن العرب يكنون عن حال المرء بحال أمه فى الخير وفى الشر ، لشدة محبتها له .","9":"قال صاحب الكشاف : قوله : ( فَأُمُّهُ هَاوِيَةٌ ) من قولهم إذا دعوا على الرجل بالهلكة ، هوت أمه ، لأنه إذا هوى - أى سقط وهلك . . فقد هوت أمه ثكلا وحزنا . . فكأنه قيل : وأما من خفت موازينه فقد هلك .وقيل : \" هاوية \" من أسماء النار ، وكأنها النار العميقة لهوى أهل النار فيها مهوى بعيدا ، كما روى : \" يهوى فيها سبعين خريفا \" أى : فمأواه النار .وقيل للمأوى : أم ، على التشبيه ، لأن الأم مأوى الولد ومفزعه . .وقال بعض العلماء : واعلم أنه يجب علينا أن نؤمن بما ذكره الله - تعالى - من الميزان فى هذه الآية وما يشبهها ، وليس علينا أن نبحث فيما وراء ذلك مما لم يثبت عن الله - تعالى - ورسوله صلى الله عليه وسلم ونكل ما وراء ذلك إلى علام الغيوب ، على أن وزن الأعمال ، أو وزن صحائفها أو وزن الصور الجميلة ، كل ذلك أمر ممكن ، لا يترتب على فرض وقوعه محالن فوقوع شئ من ذلك ، لا يعجز الله - تعالى - ولا يقف أمام قدرته الغالبة .","10":"ثم ختم - سبحانه - السورة الكريمة ، بما يزيد من هول هذه الهاوية فقال : ( وَمَآ أَدْرَاكَ مَا هِيَهْ . نَارٌ حَامِيَةٌ )أى : وأى شئ يخبرك بكنه تلك النار السحيقة؟ إننا نحن الذين نخبرك بذلك فنقول لك - أيها المخاطب - على سبيل التحذير من العمل الذى يؤدى إليها .","11":"إنها نار قد بلغت النهاية فى حرارتها .نسأل الله تعالى - أن يعيذنا جميعا منها .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"102":{"1":"قوله - سبحانه - : ( أَلْهَاكُمُ ) من اللهو وهو الغفلة عن مواطن الخير ، والانشغال عما هو نافع .والتكاثر : التبارى والتباهى بالكثرة فى شئ مرغوب فيه كالمال والجاه . .أى : شغلكم - أيها الناس - التباهى والتفاخر بكثرة الأموال والأولاد والعشيرة ، كما ألهاكم حب الدنيا عن القيام بما كلفناكم به . .","2":"( حتى زُرْتُمُ المقابر ) أى : بقيتم على هذه الحال ، حتى أتاكم الموت ، ودفنتم فى قبوركم ، وانصرف عنكم أحب الناس إليكم ، وبقيتم وحدكم .والخطاب عام لكل عاقل ، ويدخل فيه المشركون والفاسقون ، الذين آثروا الدنيا على الآخرة دخولا أوليا .فالمراد بزيارة المقابر : انتهاء الآجال ، والدفن فى القبور بعد الموت . وعبر - سبحانه - عن ذلك بالزيارة . لأن الميت يأتى إلى القبر كالزائر له ، ثم بعد ذلك يخرج منه يوم البعث والنشور ، للحساب والجزاء ، فوجوده فى القبر إنما هو وجود مؤقت بوقت يعلمه الله - تعالى - .وقد روى أن أعرابيا عندما سمع هذه الآية قال : بعثوا ورب الكعبة ، فقيل له كيف ذلك؟ فقال : لأن الزائر لابد أن يرتحل .وقد نهى النبى صلى الله عليه وسلم عن التهالك على حطام الدنيا ، فى أحاديث كثيرة منها ما رواه مسلم فى صحيحه عن عبد الله بن الشَّخَّير قال : انتهيت إلى رسول الله صلى الله عليه وسلم وهو يقول : \" ألهاكم التكاثر قال : يقول ابن آدم مالى مالى ، وهل لك من مالك يابن آدم ، آدم إلا ما أكلت فأفنيت أو لبست فأبليت ، أو تصدقت فأمضيت \" .","3":"وقوله - تعالى - : ( كَلاَّ سَوْفَ تَعْلَمُونَ . ثُمَّ كَلاَّ سَوْفَ تَعْلَمُونَ ) ردع وزجر عن الانشغال عن طاعة الله ، وعن التكاثر بالأموال والأولاد .وكرر لفظ \" كلا \" ثلاث مرات فى هذه السورة ، لتأكيد هذا الزجر والردع عن كل ما يشغل الإِنسان عن وجوه الخير والبر .والتبعير بقوله : ( سَوْفَ ) لزيادة الزجر ، ولتحقيق حصول العلم ، وحذف مفعول ( تَعْلَمُونَ ) لظهوره من المقام . أى : اتركوا التشاغل بالدنيا والتفاخر بالأموال ، فإنكم إن بقيتم على ذلك بدون توبة صادقة ، فسوف تعرفون سوء عاقبة ذلك معرفة لا يخامرهها شك ، ولا يفارقها ريب .","4":"وجملة ( ثُمَّ كَلاَّ سَوْفَ تَعْلَمُونَ ) مؤكدة تأكيدا لفظيا للجملة التى قبلها ، وهذا التأكيد المقصود منه المبالغة فى الردع والزجر والتحذير من التكاثر والتفاخر . .","5":"ثم أضاف - سبحانه - إلى كل ما سبق من تحذيرات ، زواجر أخرى فقال : ( كَلاَّ لَوْ تَعْلَمُونَ عِلْمَ اليقين . لَتَرَوُنَّ الجحيم . ثُمَّ لَتَرَوُنَّهَا عَيْنَ اليقين ) . .وجواب \" لو \" محذوف لقصد التهويل ، و \" اليقين \" فعيل بمعنى مفعول ، وعلم اليقين هو العلم الجازم المطابق للواقع الذى لا شك فيه . والإِضافة فيه من إضافة الموصوف إلى الصفة ، أو من إضافة العام إلى الخاص .أى : لو تعلمون - علما موثوقا به - سوء عاقبة انشغالكم عن ذكر الله - تعالى - وتكاثركم وتفاخركم بالأموال والأولاد . . لشغلكم هذا العلم اليقينى عما أنتم عليه من التشاغل والتكاثر .فالمقصود بهذه الجملة الكريمة : الزيادة فى ردعهم ، لأنه من عادة الغافلين المكابرين . أنك إذا ذكرتهم بالحق وبالرشاد . . زعموا أنهم ليسوا فى حاجة إلى هذا الإرشاد ، لأنهم أهل علم ومعرفة بالعواقب ، فكانت هذه الآية الكريمة بمثابة تنبيههم بأنهم ليسوا على شئ من العلم الصحيح ، لأنهم لو كانوا كذلك لما تفاخروا ، ولما تكاثروا .","6":"وقوله - سبحانه - : ( لَتَرَوُنَّ الجحيم ) جواب قسم مقدر ، قصد به تأكيد الوعيد الشديد فى التهديد ، وبيان أن المهدد به رؤية الجحيم فى الآخرة ، أى : والله لترون الجحيم فى الآخرة .","7":"ثم أكد - سبحانه - هذا المعنى تأكيدا قويا فقال : ( ثُمَّ لَتَرَوُنَّهَا عَيْنَ اليقين ) أى : ثم لترون الجحيم رؤية هى ذات اليقين ونفسه وعينه ، وذلك لأن تشاهدوها مشاهدة حقيقية ، بحيث لا يلتبس عليكم أمرها .وقد قالوا إن مراتب العلم ثلاثة : علم اليقين وهو ما كان ناتجا عن الأدلة والبراهين .وعين اليقين : وهو ما كان عن مشاهدة وانكشاف .وحق اليقين : وهو ما كان عن ملابسة ومخالطة .ومثال ذلك أن تعلم بالأدلة أن العبة موجودة ، فذلك علم اليقين ، فإذا رأيتها بعينيك فذلك عين اليقين ، فإذا ما دخلت فى جوفها فذلك حق اليقين . .فأنت ترى أنه - سبحانه - قد حذر الناس من الاشتغال عن طاعته ، ومن التباهى والتكاثر ، بأبلغ أساليب التأكيد وأقواها .","8":"ثم ختم - سبحانه - السورة بقوله : ( ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النعيم ) ، والمراد بالنعيم هنا : ما يتنعم به الإِنسان خلال حياته الدنيوية من مال وولد ، ومن طعام وشراب ، ومن متعه وشهوة . . من النعومة التى هى ضد الخشونة .أى : ثم إنكم بعد ذلك - أيها الناس - والله لتسألن يوم القيامة عن ألوان النعم التى منحكم الله - تعالى - إياها ، فمن أدى ما يجب عليه نحوها من شكر الله - تعالى - عليها كان من السعداء ، ومن جحدها وغمطها وشغلته عن طاعة ربه ، وتباهى وتفاخر بها . . كان من الأشقياء ، كما قال - تعالى - : ( وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ ) فالمراد بالسؤال إنما هو سؤال التكريم والتبشير للمؤمنين الشاكرين ، وسؤال الإِهانة والتوبيخ للفاسقين الجاحدين .والآية الكريمة دعوة حارة للناس ، إلى شكر نعمه - تعالى - واستعمالها فيما خلقت له .قال القرطبى ما ملخصه : والسؤال يكون للمؤمن والكافر . . والجمع بين الأخبار التى وردت فى ذلك : أن الكل يسألون ، ولكن سؤال الكافر توبيخ ، لأنه قد ترك الشكر ، وسؤال المؤمن سؤال تشريف ، لأنه قد شكر ، وهذا النعيم فى كل نعمة . .نسأل الله - تعالى - أن يجعلنا من عباده الشاكرين . .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"103":{"1":"للعلماء أقوال متعددة فى المقصود بالعصر هنا فمنهم من يرى أن المقصود به : الدهر كله ، لما فيه من العبر التى تدل دلالة واضحة على عظيم قدرة الله - تعالى - ، ولما فيه من الأحداث التى يراها الناس بأعينهم ، ويعرفونها عن غيرهم . .فهم يرون ويسمعون كم من غنى قد صار فقيرا ، وقوى قد صار ضعيفا ، ومسرور قد أصبح حزينا . . ورحم الله القائل :أشاب الصغير وأفنى الكبير ... كر الغداة ومر العشىقال القرطبى : قوله - تعالى - : ( والعصر ) أى : الدهر ، قال ابن عباس وغيره فالعصر مثل الدهر . . وأقسم به - سبحانه - لما فيه من التنبيه بتصرف الأحوال وتبدلها .ومنهم من يرى أن المقصود به : وقت صلاة العصر ، وقد صدر صاحب الكشاف تفسيره لهذه الآية بهذا الرأى فقال : أقسم - سبحانه - بصلاة العصر لفضلها ، بدليل قوله - تعالى - : ( حَافِظُواْ عَلَى الصلوات والصلاة الوسطى ) - وهى صلاة العصر - ، وقوله صلى الله عليه وسلم : \" من فاتته صلاة العصر فكأنما وَتِرَ أهله وماله \" ولأن التكليف فى أدائها أشق لتهافت الناس فى تجاراتهم ومكاسبهم آخر النهار . .ومنهم من يرى أن المراد بالعصر هنا : عصر النبوة . لأفضليته بالنسبة لما سبقه من عصور .وقد رجح الإِمام ابن جرير القول الأول فقال : والصواب من القول فى ذلك أن يقال : إن ربنا أقسم بالعصر ، والعصر اسم الدهر ، وهو العشى ، والليل والنهار . .","2":"وقوله - سبحانه - : ( إِنَّ الإنسان لَفِى خُسْرٍ . . . ) جواب القسم ، والمراد بالإِنسان : جنسه ويدخل فيه الكافر دخولا أوليا . والخسر مثل الخسران ، كالكفر بمعنى الكفران . .أى : إن جنس الإِنسان لا يخلو من خسران ونقصان وفقدان للربح فى مساعيه وأعماله طوال عمره ، وإن هذا الخسران يتفاوت قوة وضعفا .فأخسر الأخسرين هو الكافر الذى أشرك مع خالقه إلها آخر فى العبادة ، وأقل الناس خسارة هو المؤمن الذى خلط عملا صالحا بآخر سيئا ثم تاب إلى الله - تعالى - توبة صادقة .وجاء الكلام بأسلوب القسم ، لتأكيد المقسم عليه ، وهو أن جنس الإِنسان فى خسر .وقال - سبحانه - ( لَفِى خُسْرٍ ) للإِشعار بأن الإِنسان كأنه مغمور بالخسر ، وأن هذا الخسران قد أحاط به من كل جانب ، وتنكير لفظ \" خسر \" للتهويل . أى : لفى خسر عظيم .","3":"وقوله - سبحانه - : ( إِلاَّ الذين آمَنُواْ وَعَمِلُواْ الصالحات . . . ) استثناء مما قبله ، والمقصود بهذه الآية الكريمة تسلية المؤمنين الصادقين . . وتبشيرهم بأنهم ليسوا من هذا الفريق الخاسر .وقوله - تعالى - : ( وَتَوَاصَوْاْ ) فعل ماض ، من الوصية وهى تقديم النصح للغير مقرونا بالوعظ .و \" الحق \" : هو الأمر الذى ثبتت صحته ثبوتا قاطعا . .و \" الصبر \" : قوة فى النفس تعينها على احتمال المكاره والمشاق ..أى : أن جميع الناس فى خسران ونقصان . . إلا الذين آمنوا بالله - تعالى - إيمانا حقا ، وعملوا الأعمال الصالحات ، من صلاة وزكاة وصيام وحج . . وغير ذلك من وجوه الخير ، وأوصى بعضهم بعضا بالتمسك بالحق ، الذى على رأسه الثبات على الإِيمان وعلى العمل الصالح . . وأوصى بعضهم بعضا كذلك بالصبر على طاعة الله - تعالى - ، وعلى البلايا والمصائب والآلام . . التى لا تخلو عنها الحياة .فهؤلاء المؤمنون الصادقون ، الذين أوصى بعضهم بعضا بهذه الفضائل ليسوا من بين الناس الذين هم فى خسران ونقصان ، لأن إيمانهم الصادق وعملهم الصالح . . قد حماهم من الخسران . .قال بعض العلماء : وقد اشتملت هذه السورة الكريمة على الوعيد الشديد ، وذلك لأنه - تعالى - حكم بالخسارة على جميع الناس ، إلا من كان متصفا بهذه الأشياء الأربعة ، وهى : الإِيمان ، والعمل الصالح ، والتواصى بالحق ، والتواصى بالصبر ، فدل ذلك على أن النجاة معلقة بمجموع هذه الأمور ، وأنه كما يجب على الإِنسان أن يأتى من الأعمال ما فيه الخير والنفع ، يجب عليه - أيضا - أن يدعو غيره إلى الدين ، وينصحه بعمل الخير والبر ، ويأمر بالمعروف وينهى عن المنكر ، ويحب لأخيه ما يحب لنفسه ، وأن يثبت على ذلك ، فلا يحيد عنه ، ولا يزحزحه عن الدعوة إليه ما يلاقيه من مشاق .نسأل الله - تعالى - أن يجعلنا من أصحاب هذه الصفات .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"104":{"1":"الويل : لفظ يدل على الذم وعلى طلب العذاب والهلكة . . وقيل : اسم لواد فى جهنم .والهُمَزة من الهَمْز ، بمعنى الطعن فى أعراض الناس ، ورميهم بما يؤذيهم . .واللُّمَزة من اللمز ، بمعنى السخرية من الغير ، عن طريق الإِشارة باليد أو العين أو غيرهما .قال الجمل : الهمزة واللمزة : هم المشاؤون بالنميمة ، المفرقون بين الأحبة الباغون العيب للبرئ ، فعلى هذا هما بمعنى واحد .وقيل : الهمزة الذى يعيبك فى الغيب ، واللمزة الذى يعيبك فى الوجه وقيل : العكس .وحاصل هذه الأقوال يرجع إلى أصل واحد ، وهو الطعن وإظهار العيب ، ويدخل فى ذلك من يحاكى الناس فى أقوالهم وأفعالهم وأصواتهم ليضحكوا منه . .ولفظ \" ويل \" مبتدأ وساغ الابتداء مع كونه نكرة ، لأنه دعاء عليهم ، وقوله : ( لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ ) خبره ، وهمزة ولمزة وصفان لموصوف محذوف .أى : عذاب شديد ، وخزى عظيم ، لكل من يطعن فى أعراض الناس ، ويغض من شأنهم ، ويحقر أعمالهم وصفاتهم ، وينسب إليهم ما هم برآء منه من عيوب .والتعبير بقوله : ( هُمَزَةٍ لُّمَزَةٍ ) يدل على أن تلك الصفات القبيحة ، كانت عادة متأصلة فيهم ، لأن اللفظ الذى بزنة فُعَلَة - بضم الفاء وفتح العين - يؤتى به للدلالة على أن الموصوف به ديدنه ودأبه الإِتيان بهذا الوصف ، ومنه قولهم : فلان ضُحَكة : إذا كان يكثر من الضحك .كما أن لفظ \" فُعْلَة \" - بضم الفاء وسكون العين - يؤتى به للدلالة على أن الموصوف به ، يكثر أن يفعل به ذلك ، ومنه قولهم : فلان ضُحْكة ، إذا كان الناس يكثرون الضحك منه .","2":"وقوله - سبحانه - : ( الذى جَمَعَ مَالاً وَعَدَّدَهُ ) زيادة تشنيع وتقبيح للهمزة اللمزة . .ومعنى \" عدده \" : جعله عدته وذخيرته ، وأكثر من عده وإحصائه لحرصه عليه ، والجملة الكريمة فى محل نصب على الذم .أى : عذاب وهلاك لكل إنسان مكثر من الطعن فى أعراض الناس ، ومن صفاته الذميمة أنه فعل ذلك بسبب أنه جمع مالا كثيرا ، وأنفق الأوقات الطويلة فى عده مرة بعد أخرى ، حبا له وشغفا به وتوهما منه أن هذا المال الكثير هو مناط التفاضل بين الناس .وقرأ ابن عامر وحمزة والكسائى ( جمَّع ) - بتشديد الميم - وهو مبالغة فى ( جمع ) بتخفيف الميم .","3":"وقوله - تعالى - : ( يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ ) ، صفة أخرى من صفاته القبيحة ، والجملة يصح أن تكون مستأنفة استنئافا بيانيا ، جوابا لسؤال مقدر ، كأنه قيل : ما باله يجمع المال ويهتم به؟ فكان الجواب : يحسب أن ماله أخلده .ويصح أن تكون حالا من فاعل \" جمع \" أى : هذا الجاهل المغرور جمع المال وعدده ، حالة كونه يظن أن ماله يخلده فى الدنيا ، ويجعله فى مأمن من حوادث الدهر .قال الأستاذ الإِمام محمد عبده : أى أن الذى يحمل هذا الهمزة اللمزة على الحط من أقدار الناس ، هو جمعه المال وتعديده . . فكلما نظر إلى كثرة ما عنده منه ، انتفخ وظن أنه من رفعة المكانة ، بحيث يكون كل ذ فضل ومزية دونه . . ويظن أن ما عنده من المال ، قد حفظ له حياته التى هو فيها ، وأرصدها عليه ، فهو لا يفارقها إلى حياة أخرى ، يعاقب فيها على ما كسب من سيئ الأعمال . .","4":"ثم بين - سبحانه - بعد ذلك سوء عاقبة هذا الجاهل المغرور فقال : ( كَلاَّ لَيُنبَذَنَّ فِي الحطمة . وَمَآ أَدْرَاكَ مَا الحطمة ) .و \" كلا \" حرف زجر وردع ، والمراد به هنا إبطال ما توهمه هذا المغرور من حسبانه أن ماله سيخلده . والنبذ : الطرح للشئ والإِلقاء به مع التحقير والتصغير من شأنه .والحُطَمة من الحَطْم ، وهو كسر الشئ بشدة وقوة ، ويقال : رجل حطمة ، إذا كان شديداً فى تحطيمه وكسره لغيره ، والمراد بالحطمة هنا : النارر الشديدة الاشتعال : التى لا تبقى على شئ إلا وأحرقته .أى : كلا ليس الأمر كما زعم هذا الهمزة واللمزة ، من أن ماله سيخلده ، بل الحق أنه والله ليطرحن بسبب أفعاله القبيحة فى النار التى تحطم كل شئ يلقى فيها ، والتى لا يعرف مقدار شدتها واشتعالها إلا الله - تعالى - .","5":"فالمقصود بالاستفهام فى قوله - تعالى - : ( وَمَآ أَدْرَاكَ مَا الحطمة ) تهويل أمر هذه النار ، وتفظيع شأنها ، وبيان أن كنهها لا تدركه عقول البشر . .","6":"وقوله - سبحانه - ( نَارُ الله الموقدة ) بيان للحطمة وتفصيل لأمرها بعد إبهامها .أىك الحطمة هى نار الله - تعالى - الشديدة الإِحراق ، وأضيفت إلى الله - تعالى لزيادة الترويع والتخويف منها ، لأن خالقها - عز وجل - هو الذى لا يعجزه شئ .","7":"وقوله - تعالى - : ( التي تَطَّلِعُ عَلَى الأفئدة ) صفة أخرى من صفات هذه النار ، وقوله : ( تَطَّلِعُ ) من الاطلاع ، بمعنى الوصول إلى الشئ بسرعة ، والكشف عن خباياه ، والنفاذ إلى منتهاه .أى : سيلقى بهذا الشقى فى نار الله - تعالى - الموقدة ، التى تصل إلى أعماق الأفئدة والقلوب ، فتحيط بها ، وتنفذ إليها ، فتحرقها إحراقا تاما .وخصت الأفئدة التى هى القلوب بالذكر ، لأنها ألطف ما فى الأبدان وأشدها تألما بأدنى أذى يصيبها ، أو لأنها محل العقائد الزائفة ، والنيات الخبيثة ، ومنشأ الأعمال السيئة ، التى استحق هذا الهمزة اللمزة بسببها العقاب الشديد .","8":"ثم وصف - سبحانه - هذه النار بصفة ثالثة فقال : ( إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ ) أى : إن هذه النار من صفاتها - أيضا - أنها مطبقة ومغلقة عليهم بحيث لا يستطيعون الخروج منها ، فقوله ( مُّؤْصَدَةٌ ) اسم مفعول من قولك أوصدت الباب ، إذا أغلقته بشدة ، بحيث لا يستطاع الخروج منه . .","9":"ثم وصف - سبحانه - هذه النار بصفة ثالثة فقال : ( إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ ) أى : إن هذه النار من صفاتها - أيضا - أنها مطبقة ومغلقة عليهم بحيث لا يستطيعون الخروج منها ، فقوله ( مُّؤْصَدَةٌ ) اسم مفعول من قولك أوصدت الباب ، إذا أغلقته بشدة ، بحيث لا يستطاع الخروج منه . ."},"105":{"1":"الاستفهام فى قوله - تعالى - : ( أَلَمْ تَرَ . . . ) للتقرير بما تواتر نقله وعمله صلى الله عليه وسلم وعلمه غيره علما مستفيضا . . حتى إن العرب كانوا يؤرخون بتلك الحادثة ، فيقولون : هذا الأمر حدث فى عام الفيل ، أو بعده أو قبله . . والمراد بالرؤية هنا : العلم المحقق .وعبر - سبحانه - عن العلم بالرؤية ، لأن خبر هذه القصة - كما أشرنا كان من الشهرة بمكان ، فالعلم الحاصل بها مساو فى قوة الثبوت للرؤية والمشاهدة .والمعنى : لقد علمت - أيها الرسول الكريم - علما لا يخالطه ريب أو لبس ، ما فعله ربك بأصحاب الفيل ، الذين جاءوا لهدم الكعبة ، حيث أهلكناهم إهلاكا شنيعا ، كانت فى العبرة والعظة ، والدلالة الواضحة على قدرتنا ، وعلى حمايتنا لبيتنا الحرام .وأوقع - سبحانه - الاستفهام عن كيفية ما أنزله بهم ، لا عن الفعل ذاته ، لأن الكيفية أكثر دلالة على قدرته - تعالى - وعلى أنه - سبحانه - لا يعجزه شئ .وفى التعبير بقوله : ( فَعَلَ رَبُّكَ . . . ) إشارة إلى أن هذا الفعل لا يقدر عليه أحد سواه - سبحانه - فهو الذى ربى نبيه صلى الله عليه وسلم وتعهده بالرعاية ، وهو الكفيل بنصره على أعدائه ، كما نصر أهل مكة ، على جيوش الحبشة . . وهم أصحاب الفيل .ووصفوا بأنهم \" أصحاب الفيل \" لأنهم أحضروا معهم الفيلة ، ليستعينوا بها على هدم الكعبة ، وعلى إذلال أهل مكة .","2":"والاستفهام فى قوله - تعالى - : ( أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ ) للتقرير - أيضا - أى : لقد جعل الله - تعالى - مكر أصحابا الفيل وسعيهم لتخريب الكعبة ، فى ( تَضْلِيلٍ ) أى : فى تخسير وإبطال وتضييع ، بأن تبرهم - سبحانه - تتبيرا ودمرهم تدميرا .والكيد : إرادة وقوع الإِضرار بالغير فى خفية ، وسمى - سبحانه - ما فعله أبراهة وجيشه كيدا ، مع أنهم جاءوا لهدم الكعبة جهارا نهارا . . لأنهم كانوا يضمرون من الحقد والحسد والعداوة لأهل مكة ، أكثر مما كانوا يظهرونه ، فهم - كما قال - تعالى - : ( قَدْ بَدَتِ البغضآء مِنْ أَفْوَاهِهِمْ وَمَا تُخْفِي صُدُورُهُمْ أَكْبَرُ . . ) والمقصود بالتضليل هن : التضييع والإِبطال . تقول : ضللت كيد فلان ، إذا جعلته باطلا ضائعا .","3":"ثم بين - سبحانه - مظاهر إبطاله لكيدهم فقال : ( وَأَرْسَلَ عَلَيْهِمْ طَيْراً أَبَابِيلَ ) .والطير : اسم جمع لكل ما من شأنه أن يطير فى الهواء ، وتنكيره للتنويع والتهويل ، والأبابيل : اسم جمع لا واحد له من لفظه ، وقيل هو جمع إِبَّالة ، وهى حزمة الحطب الكبيرة ، شبهت بها الجماعة من الطير فى تضامنها وتلاصقها .أى : لقد جعل الله - تعالى - كيد هؤلاء المعتدين فى تضييع وتخسير . . بأن أرسل إليهم جماعات عظيمة من الطير ، أتتهم من كل جانب فى تتابع ، فكانت سببا فى إهلاكهم والقضاء عليهم .. ( وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلاَّ هُوَ ).","4":"وجملة : \" ترميهم بحجارة من سجيل \" بيان لما فعلته تلك الطيور بإذن الله - تعالى - ، وهى حال من قوله ( طيرا ) ، والسجيل : الطين اليابس المتحجر . .قال بعض العلماء : قوله : ( تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ ) أى : من طين متحجر محرق . أو بحجارة من جملة العذاب المكتوب المدون فى السجيل ، وهو الديوان الذى كتب فيه عذاب الكفار ، كما أن السجيل هو الديوان الذى كتبت فيه أعمالهم . واشتقاقه من الإِسجال بمعنى الإِرسال .وعن عكرمة : كانت ترميهم بحجارة معها كالحِمَّصةِ ، فإذا أصاب أحدَهم حجرٌ منها ، خرج به الجُدَرِى ، وكان ذلك أول يوم رئى فيه الجدرى بأرض العرب .وقال ابن عباس : كان الحجر إذا وقع على أحدهم نفط جلده أى : احترق - فكان ذلك أول الجدرى . وقيل : إن أول ما رؤيت الحصبة والجدرى بأرض العرب ذلك العام .وقال ابن جُزَى فى تفسيره : إن الحجر كان يدخل من رأس أحدهم ويخرج من أسفله .ووقع فى سائرهم الجدرى والأسقام ، وانصرفوا وماتوا فى الطريق متفرقين ، وتمزق أبرهة قطعة قطعة . .","5":"وقوله - سبحانه - ( فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍ ) بيان للآثار الفظيعة التى ترتبت على ما فعلته الحجارة التى أرسلتها الطيور عليهم بإذن الله - تعالى - .والعصف : ورق الزرع الذى يبقى فى الأرض بعد الحصاد وتعصفه الرياح فتأكله الحيوانات . أو هو التبن الذى تأكله الدواب .أى : سلط الله - تعالى - عليهم طيرا ترميهم بحجارة من طين متحجر ، فصاروا بسبب ذلك صرعى هالكين ، حالهم فى تمزقهم وتناثرهم كحال أوراق الأشجار اليابسة أو التبن الذى تأكله الدواب .وهكذا نرى السورة الكريمة قد ساقت من مظاهرة قدرة الله - تعالى - ما يزيد المؤمنين إيمانا على إيمانهم ، وثباتا على ثباتهم ، وما يحمل الكافرين على الاهتداء إلى الحق ، والإِقلاع عن الشرك والجحود لو كانوا يعقلون .نسأل الله - تعالى - أن يجعلنا من عباده الشاكرين .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"106":{"1":"الإِيلاف : مصدر آلفت الشئ إيلافا و \" إلفا \" إذا لزمته وتعودت عليه . وتقول : آلفت فلانا الشئ ، إذا ألزمته إياه . والإِيلاف - أيضا - اجتماع الشمل مع الالتئام ، ومنه قوله - تعالى - ( واذكروا نِعْمَتَ الله عَلَيْكُمْ إِذْ كُنْتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُمْ بِنِعْمَتِهِ إِخْوَاناً . . . ) ولفظ \" إيلاف \" مضاف لمفعوله وهو قريش ، والفاعل هو الله - تعالى - : و \" قريش \" هم ولد النضر بن كنانه - على الأرجح - وهو الجد الثالث عشر للنبى صلى الله عليه وسلم .قال القرطبى ما ملخصه : وأما قريش فهم بنو النضر بن كنانة بن خزيمة بن مدركة بن إلياس ، بن مضر ، فكل من كان من ولد النضر فهو قرشى .وسموا قريشا ، لتجمعهم بعد التفرق ، إذ التقرش : التكسب ، ويقال : قرَشَ فلان يقرُشُ قَرْشا - كقتل - ، إذا كسب المال وجمعه . .وقوله : ( إِيلاَفِهِمْ ) بدل أو عطف بيان من قوله ( لإِيلاَفِ قُرَيْشٍ ) ، وهو من أسلوب الإِجمال فالتفصيل للعناية بالخبر ، ليتمكن فى ذهن السامع كما فى قوله - تعالى - : ( لعلي أَبْلُغُ الأسباب . أَسْبَابَ السماوات . . . ) واللام فى قوله - تعالى - : ( لإِيلاَفِ . . . ) للتعليل . والجار والمجرور متعلق بقوله - تعالى - : ( فَلْيَعْبُدُواْ . . . ) وتقدير الكلام : من الواجب على أهل مكة أن يخلصوا العبادة لله - لأنه - سبحانه - هو الذى جمعهم بعد تفرق ، وألف بينهم ، وهيأ لهم رحلتين فيهما ما فيهما من النفع والأمن .وزيدت الفاء فى قوله - تعالى - : ( فَلْيَعْبُدُواْ . . . ) لما فى الكلام من معنى الشرط ، فكأنه - سبحانه - يقول لهم : إن لم تعبدونى من أجل نعمى التى لا تحصى ، فاعبدونى من أجل أنى جعلتكم تألفون هاتين الرحلتين النافعتين فى أمان واطمئنان ، وأنى جمعت شملكم ، وألفت بينكم . .قال صاحب الكشاف : \" لإِيلاف قريش \" متعلق بقوله : ( فَلْيَعْبُدُواْ ) أمرهم أن يعبدوه لأجل إيلافهم الرحتلين .فإن قلت : فلم دخلت الفاء؟ قلت : لما فى الكلام من معنى الشرط ، لأن المعنى : إما لا فليعبدوه لإِيلافهم . على معنى أن نعم الله عليهم لا تحصى ، فإن لم يعبدوه لسائر نعمه ، فليعبدوه لهذه الواحدة التى هى نعمة ظاهرة .وقيل المعنى : اعجبوا لإِيلاف قريش . وقيل هو متعلق بما قبله - فى السورة السابقة - أى : فجعلهم كعصف مأكول . لإِيلاف قريش ، وهذا بمنزلة التضمين فى الشعر ، وهو أن يتعلق معنى البيت بالذى قبله . .","2":"وقوله - سبحانه - : ( رِحْلَةَ الشتآء والصيف ) بيان لمظهر من مظاهر هذا الإِيلاف الذى منحه - سبحانه - لهم ، والرحلة هنا : اسم لارتحال القوم من مكان إلى آخر ، ولفظ \" رحلة \" منصوب على أنه مفعول به لقوله ( إِيلاَفِهِمْ ) . .والمراد بهذه الرحلة : ارتحالهم فى الشتاء إلى بلاد اليمن ، وفى الصيف إلى بلاد الشام ، من أجل التجارة ، واجتلاب الربح .واستدرار الرزق ، والاستكثار من القوت واللباس وما يشبههما من مطالب الحياة .وقيل : المراد برحلة الشتاء والصيف : رحلة الناس إليهم فى الشتاء والصيف للحج والعمرة ، فقد كان الناس يأتون إلى مكىة فى الشتاء والصيف لهذه الاغراض ، فيجد أهل مكة من وراء ذلك الخير والنفع ، كما قال - تعالى - : ( لِّيَشْهَدُواْ مَنَافِعَ لَهُمْ ).","3":"وبعد أن ذكرهم - سببحانه - بنعمه أمرهم بشكره ، فقال : ( فَلْيَعْبُدُواْ رَبَّ هذا البيت . . . ) أى : إن كان الأمر كما ذكرنا لهم ، فليخلصوا العبادة لله - تعالى - الذى حمى لهم البيت الحرام ، والكعبة المشرفة ، ممن أرادهما بسوء . .","4":"( الذي أَطْعَمَهُم مِّن جُوعٍ ) أى : الذى وسع لهم الرزق ، ومهد لهم سبيله ، عن طريق الوفود التى تأتى إليهم من مشارق الأرض ومغاربها .( وَآمَنَهُم مِّنْ خَوْفٍ ) أى : والذى أوجد لهم الأمن بعد الخوف ، والسعة بعد الضيق ، ببركة هذا البيت الحرام .وتنكير \" جوع \" و \" خوف \" للتعظيم ، أى : أطعمهم بدلا من جوع شديد ، وآمنهم بدلا من خوف عظيم ، كانوا معرضين لهما ، وذلك كله من فضله - سبحانه - عليهم ، ومن رحمته بهم ، حيث أتم عليهم نعمتين بهما تكمل السعادة ، ويجتمع السرور .ومن الآيات التى تشبه هذه الآية قوله - تعالى - : ( أَوَلَمْ يَرَوْاْ أَنَّا جَعَلْنَا حَرَماً آمِناً وَيُتَخَطَّفُ الناس مِنْ حَوْلِهِمْ . . . ) وقوله - سبحانه - : ( أَوَلَمْ نُمَكِّن لَّهُمْ حَرَماً آمِناً يجبى إِلَيْهِ ثَمَرَاتُ كُلِّ شَيْءٍ رِّزْقاً . . . ) وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"107":{"1":"( فَذَلِكَ الذي يَدُعُّ اليتيم )أى : فذلك الذى يكذب بالبعث والحساب والجزاء ، من أبرز صفاته القبيحة . أنه \" يدع اليتيم \" أى : يقسو عليه ، ويزجره زجرا عنيفا ، ويسد كل باب خير فى وجهه ، ويمع كل حق له . .فقوله : ( يَدُعُّ ) من الدع وهو الدفع الشديد ، والتعنيف الشنيع للغير . .","2":"( وَلاَ يَحُضُّ على طَعَامِ المسكين ) أى : أن من صفاته الذميمة - أيضا - أنه لا يحث أهله وغيرهم من الأغنياء على بذل الطعام للبائس المسكين ، وذلك لشحه الشديد ، واستيلاء الشيطان عليه ، وانطماس بصيرته عن كل خير .وفى هذه الآية والتى قبلها دلالة واضحة على أن هذا الانسان المكذب الدين قد بلغ النهاية فى السوء والقبح ، فهو لقسوة قلبه لا يعطف على يتيم ، بل يحتقره ويمنع عنه كل خير ، وهو لخبث نفسه لا يفعل الخير ، ولا يحض غيره على فعله ، بل يحض على الشرور والآثام .ولما كانت هذه الصفات الذميمة ، لا تؤدى إلى إخلاص أو خشوع لله - تعالى - وإنما تؤدى إلى الرياء وعدم المبالاة بأداء التكاليف التى أوجبها - سبحانه - على خلقه . .","3":"لما كان الأمر كذلك ، وصف - سبحانه - هؤلاء المكذبين بالبعث والجزاء بأوصاف أخرى ، فقال : ( فَوَيْلٌ لِّلْمُصَلِّينَ . الذين هُمْ عَن صَلاَتِهِمْ سَاهُونَ . الذين هُمْ يُرَآءُونَ . وَيَمْنَعُونَ الماعون ) .والفاء فى قوله : ( فَوَيْلٌ ) للتفريع والتسبب ، والويل : الدعاء بالهلاك والعذاب الشديد .وهو مبتدأ ، وقوله ( لِّلْمُصَلِّينَ ) خبره .","4":"والمراد بالسهو هنا : الغفلة والترك وعدم المبالاة . . أى : فهلاك شديد ، وعذاب عظيم ، لمن جمع هذه الصفات الثلاث ، بعد تكذيبه بيوم الدين ، وقسوته على اليتيم ، وامتناعه عن إطعام المسكين .وهذه الصفات الثلاث أولها : الترك للصلاة ، وعدم المبالاة بها ، والإِخلال بشروطها وأركانها وسننها وآدابها .","5":"وثانيها : أداؤها رياء وخداعا لا عن إخلاص وطاعة لله رب العالمين كما قال - تعالى - :( إِنَّ المنافقين يُخَادِعُونَ الله وَهُوَ خَادِعُهُمْ وَإِذَا قاموا إِلَى الصلاة قَامُواْ كسالى يُرَآءُونَ الناس وَلاَ يَذْكُرُونَ الله إِلاَّ قَلِيلاً )","6":"وثالثها : منع الماعون : أى منع الخير والمعروف والبر عن الناس . فالمراد بمنع الماعون : مع كل فضل وخير عن سواهم . فلفظ \" الماعون \" أصله \" معونة \" والألف عوض من الهاء . والعون : هو مساعدة الغير على بلوغ حاجته . . فالمراد بالماعون : ما يستعان به على قضاء الحوائج ، من إناء أو فأس ، أو نار ، أو ما يشبه ذلك .ومنهم من يرى أن المراد بالماعون هنا : الزكاة لأنه جرت عادة القرآن الكريم أن يذكر الزكاة بعد الصلاة .قال الإِمام ابن كثير : قوله : ( وَيَمْنَعُونَ الماعون ) أى : لا أحسنوا عبادة ربهم ، ولا أحسنوا إلى خلقه ، حتى ولا بإعارة ما ينتفع به ، ويستعان به ، مع بقاء عينه ورجوعه إليهم ، فهؤلاء لمنع الزكاة ومنع القربات أولى وأولى . .وسئل ابن مسعود عن الماعون فقال : هو ما يتعاوره الناس بينهم من الفأس والقِدْر . .وهكذا نرى السورة الكريمة قد ذمت المكذبين بيوم الدين ذما شديدا حيث وصفتهم بأقبح الصفات وأشنعها .نسأل الله - تعالى - أن يعيذنا من ذلك .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم .","7":"وثالثها : منع الماعون : أى منع الخير والمعروف والبر عن الناس . فالمراد بمنع الماعون : مع كل فضل وخير عن سواهم . فلفظ \" الماعون \" أصله \" معونة \" والألف عوض من الهاء . والعون : هو مساعدة الغير على بلوغ حاجته . . فالمراد بالماعون : ما يستعان به على قضاء الحوائج ، من إناء أو فأس ، أو نار ، أو ما يشبه ذلك .ومنهم من يرى أن المراد بالماعون هنا : الزكاة لأنه جرت عادة القرآن الكريم أن يذكر الزكاة بعد الصلاة .قال الإِمام ابن كثير : قوله : ( وَيَمْنَعُونَ الماعون ) أى : لا أحسنوا عبادة ربهم ، ولا أحسنوا إلى خلقه ، حتى ولا بإعارة ما ينتفع به ، ويستعان به ، مع بقاء عينه ورجوعه إليهم ، فهؤلاء لمنع الزكاة ومنع القربات أولى وأولى . .وسئل ابن مسعود عن الماعون فقال : هو ما يتعاوره الناس بينهم من الفأس والقِدْر . .وهكذا نرى السورة الكريمة قد ذمت المكذبين بيوم الدين ذما شديدا حيث وصفتهم بأقبح الصفات وأشنعها .نسأل الله - تعالى - أن يعيذنا من ذلك .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"108":{"1":"الكوثر : فَوْعل من الكثرة ، مثل النَّوْفل من النفل ، ومعناه : الشئ البالغ فى الكثرة حد الإِفراط ، والعرب تسمى كل شئ كثر عدده ، وعظم شأنه : كوثرا ، وقد قيل لأعرابية بعد رجوع ابنها من سفر : بم آب ابنك؟ قالت : آب بكوثر . أى : بشئ كثير .قال الإِمام القرطبى ما ملخصه : واختلف أهل التأويل فى الكوثر الذى أعطيه النبى صلى الله عليه وسلم على ستة عشر قولاً : الأول : أنه نهى فى الجنة ، رواه البخارى عن أنس ، ورواه الترمذى - أيضاً - عن ابن عمر . . الثانى : أنه حوض للنبى صلى الله عليه وسلم فى الموقف . . الثالث : أنه النبوة والكتاب . . الرابع : أنه القرآن . . الخامس : الإِسلام .ثم قال - رحمه الله - قلت : أصح هذه الأقوال الأول والثانى ، لأنه ثابت عن النبى صلى الله عليه وسلم نص فى الكوثر . . وجميع ما قيل بعد ذلك فى تفسيره قد أعطيه صلى الله عليه وسلم زيادة على حوضه . . .وافتتح - سبحانه - الكلام بحرف التأكيد ، للاهتمام بالخبر ، وللإِشعار بأن المعطى شئ عظيم . . أى : إنا أعطيناك بفضلنا وإحساننا - أيها الرسول الكريم - الكوثر ، أى : الخير الكثير الذى من جملته هذا النهر العظيم ، والحوض المطهر . . فأبشر بذلك أنت وأمتك ، ولا تلتفت إلى ما يقوله أعداؤك فى شأنك .","2":"والفاء فى قوله - تعالى - : ( فَصَلِّ لِرَبِّكَ وانحر ) لترتيب ما بعدها على ما قبلها ، والمراد بالصلاة : المداومة عليها .أى : ما دمنا قد أعطيناك هذه النعم الجزيلة ، فداوم على شكرك لنا ، بأن تواظب على أداء الصلاة أداء تاما ، وبأن تجعلها خالصة لربك وخالقك ، وبأن تواظب - أيضاً - على نحرك الإِبل تقرباً إلى ربك . كما قال - سبحانه - ( قُلْ إِنَّ صَلاَتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي للَّهِ رَبِّ العالمين . لاَ شَرِيكَ لَهُ وبذلك أُمِرْتُ وَأَنَاْ أَوَّلُ المسلمين )","3":"ثم بشره - سبحانه - ببشارة أخرى فقال : ( إِنَّ شَانِئَكَ هُوَ الأبتر ) والشانئ : هو المبغض لغيره ، يقال : شَنَأَ فلان شَنْئاً ، إذا أبغضه وكرهه .والأبتر فى الأصل : هو الحيوان المقطوع الذنب ، والمراد به هنا : الإِنسان الذى لا يبقى له ذكر . ولا يدوم له أثر . .شبه بقاء الذكر الحسن بذنب الحيوان ، لأنه تابع له وهو زينته ، وشبه الحرمان من ذلك ببتر الذي وقطعه .والمعنى : إن مبغضك وكارهك - أيها الرسول الكريم - هو المقطوع عن كل خير ، والمحروم من كل ذكر حسن .قال الإِمام ابن كثير : \" كان العاص بن وائل إذا ذكر رسول الله صلى الله عليه وسلم قال : دعوه فإنه رجل أبتر لا عقب له ، فإذا هلك انقطع ذكره ، فأنزل الله - تعالى - هذه السورة \" .وقال السدى : كانوا إذا مات ذكور الرجل قالوا : بتر ، فلما مات أبناء النبى صلى الله عليه وسلم قالوا : بتر محمد فأنزل الله هذه الآية .وهذا يرجع إلى ما قلناه من أن الأبتر إذا مات انقطع ذكره ، فتوهموا لجهلهم أنه إذا مات بنوه ينقطع ذكره ، وحاشا وكلا ، بل أبقى الله ذكره على رءوس الأشهاد ، وأوجب شرعه على رقاب العباد ، مستمرا على دوام الآباد ، إلى يوم الحشر والمعاد ، صلوات الله وسلامه عليه دائماً إلى يوم الثناد . . .نسأل الله - تعالى - أن يجعلنا من أهل شفاعته يوم القيامة .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"109":{"1":"أى : قل - أيها الرسول الكريم - لهؤلاء المشركين الذين جاؤوك ليساوموك على أن تعبد آلهتهم مدة ، وهم يعبدون إلهك مدة أخرى . . قل لهم على سبيل الحزم والتأكيد \" لا أعبد \" أنا الذى تعبدونه من آلهة باطلة ، ولا أنتم عابدون الإِله الحق الذى أعبده ، لجهلكم وجحودكم . وعكوفكم على ما كان عليه آباؤكم من ضلال .وافتتحت السورة الكريمة بفعل الأمر \" قل \" للاهتمام لما سيأتى بعده من كلام المقصود منه إبلاغه إليهم ، وتكليفهم بالعمل به .ونودوا بوصف الكافرين ، لأنهم كانوا كذلك ، ولأن فى هذا النداء تحقيرا واستخفافا بهم .","2":"و \" ما \" هنا موصولة بمعنى الذى ، وأوثرت على \" مَن \" لأنهم ما كانوا يشكون فى ذات الآلهة التى يعبدونها ، ولافى ذات الإلهة الحق الذى يبعده النبى صلى الله عليه وسلم ، وإنما كانوا يشكون فى أوصافه - تعالى - ، من زعمهم أن هذه الأصنام ما يعبدونها إلا من أجل التقرب إليه .ويقولون : ( هؤلاء شُفَعَاؤُنَا عِندَ الله ) مع أن الله - تعالى - منزه عن ذلك ، فالمقصود من \" ما \" هنا : الصفة ، وليس الذات ، فكأنه قال : لا أعبد الباطل الذى تعبدونه ، وأنتم لجهلكم لا تعبدون الإله الحق الذى أعبده .","3":"وقوله - تعالى - : ( وَلاَ أَنتُمْ عَابِدُونَ مَآ أَعْبُدُ . وَلاَ أَنَآ عَابِدٌ مَّا عَبَدتُّمْ ) تأكيد وتقرير لما اشتمل عليه الكلام السابق . . \" وما \" هنا مصدرية ، فكأنه قبل : ولا أنا عابد عبادتكم ، ولا أنتم عابدون عبادتى .فالآيتان السابقتان تنفيان الاتحاد بينه صلى الله عليه وسلم وبينهم فى المعبود ، وهاتان الآيتان تنفيان الاتحاد فى العبادة ، والمقصود من ذلك المبالغة التامة فى البراءة من معبوداتهم الباطلة ، ومن عبادتهم الفاسدة ، وأنه صلى الله عليه وسلم ومن معه من المؤمنين ، لا يعبدون إلا الله - عز وجل - ، وهم بذلك يكونون قد اهتدوا إلى العبادة الصحيحة .","4":"وقوله - تعالى - : ( وَلاَ أَنتُمْ عَابِدُونَ مَآ أَعْبُدُ . وَلاَ أَنَآ عَابِدٌ مَّا عَبَدتُّمْ ) تأكيد وتقرير لما اشتمل عليه الكلام السابق . . \" وما \" هنا مصدرية ، فكأنه قبل : ولا أنا عابد عبادتكم ، ولا أنتم عابدون عبادتى .فالآيتان السابقتان تنفيان الاتحاد بينه صلى الله عليه وسلم وبينهم فى المعبود ، وهاتان الآيتان تنفيان الاتحاد فى العبادة ، والمقصود من ذلك المبالغة التامة فى البراءة من معبوداتهم الباطلة ، ومن عبادتهم الفاسدة ، وأنه صلى الله عليه وسلم ومن معه من المؤمنين ، لا يعبدون إلا الله - عز وجل - ، وهم بذلك يكونون قد اهتدوا إلى العبادة الصحيحة .","5":"وقوله - تعالى - : ( وَلاَ أَنتُمْ عَابِدُونَ مَآ أَعْبُدُ . وَلاَ أَنَآ عَابِدٌ مَّا عَبَدتُّمْ ) تأكيد وتقرير لما اشتمل عليه الكلام السابق . . \" وما \" هنا مصدرية ، فكأنه قبل : ولا أنا عابد عبادتكم ، ولا أنتم عابدون عبادتى .فالآيتان السابقتان تنفيان الاتحاد بينه صلى الله عليه وسلم وبينهم فى المعبود ، وهاتان الآيتان تنفيان الاتحاد فى العبادة ، والمقصود من ذلك المبالغة التامة فى البراءة من معبوداتهم الباطلة ، ومن عبادتهم الفاسدة ، وأنه صلى الله عليه وسلم ومن معه من المؤمنين ، لا يعبدون إلا الله - عز وجل - ، وهم بذلك يكونون قد اهتدوا إلى العبادة الصحيحة .","6":"وقوله - تعالى - : ( لَكُمْ دِينُكُمْ وَلِيَ دِينِ ) تذييل مؤكد لما قبله . والدين : يطلق بمعنى العقيدة التى يعتقدها الإِنسان يدين بها ، وبمعنى الملة التى تجرى أقواله وأفعاله على مقتضاها ، وبمعنى الحساب والجزاء . ومنه قولهم : دنت فلانا بما صنع ، أى : جازيته على صنيعه .واللفظ هنا شامل لكل ذلك ، أى : لكم - أيها الكافرون - دينكم وعقيدتكم التى تعتقدونها ولا تتجاوزكم إلى غيركم من المؤمنين الصادقين ، فلا عن رسولهم ومرشدهم صلى الله عليه وسلم ، ولى دينى وعقيدتى التى هى عقيدة التوحيد ، والتى بايعنى عليها أتباعى المؤمنون ، وهى مقصورة علينا ، وأنتم محرومون منها ، وسترون سوء عاقبة مخالفتكم لى .وقدم - سبحانه - المسند على المسند إليه ، لإِفادة القصد والاختصاص فكأنه قيل : لكم دينكم لا لغيركم ، ولى دينى لا لغيرى والله - تعالى - هو أحكم الحاكمين بينى وبينكم .وبذلك نرى السورة الكريمة ، قد قطعت كل أمل توهم الكافرون عن طريقه الوصول إلى مهادنة النبى صلى الله عليه وسلم ، وإلى الاستجابة لشئ من مطالبهم الفاسدة ، وإنما هو صلى الله عليه وسلم برئ براءة تامة منهم ومن معبوداتهم وعباداتهم .وصلى على سيدنا محمد وعلى آله وصحبه وسلم ."},"110":{"1":"النصر : التغلب على العدو ، والإِعانة على بلوغ الغاية ، ومنه قولهم : قد نصر الغيث الأرض ، أى : أعان على إظهار نباتها .والمراد به هنا : إعانة الله - تعالى - لنبيه صلى الله عليه وسلم على أعدائه ، حتى حقق له النصر عليهم .والفتح : يطلق على فتح البلاد عَنْوَةً والتغلب على أهلها ، ويطلق على الفصل والحكم بين الناس ، ومنه قوله - تعالى - : ( رَبَّنَا افتح بَيْنَنَا وَبَيْنَ قَوْمِنَا بالحق وَأَنتَ خَيْرُ الفاتحين ) والمراد به : هنا فتح مكة . وما ترتب عليه من إعزاز الدين ، وإظهار كلمة الحق .","2":"قال الإِمام ابن كثير : والمراد بالفتح هنا فتح مكة قولا واحدا ، فإن أحياء العرب كانت تتلوم - أى : تنتظر - بإسلامها فتح مكة ، يقولون : إن ظهر على قومه فهو نبى ، فلما فتح الله عليه مكة ، دخلوا فى دين الله أفواجا ، فلم تمض سنتان حتى استوسقت - أى : اجتمعت - جزيرة العرب على الإِيمان ، ولم يبق فى سائر قبائل العرب إلا مظهر للإِسلام ، ولله الحمد والمنة .والأفواج : جمع فوج ، وهو الجماعة والطائفة من الناس","3":"وقوله ( فَسَبِّحْ ) جواب إذا والمعنى : إذا أتم الله - عليك - أيها الرسول الكريم - وعلى أصحابك النصر ، وصارت لكم الكلمة العليا على أعدائكم ، وفتح لكم مكة ، وشاهدت الناس يدخلون فى دين الإِسلام ، جماعات ثم جماعات كثيرة بدون قتال يذكر .إذا علمت ورأيت كل ذلك ، فداوم وواظب على تسبيح ربك ، وتنزيهه عن كل ما لا يليق به شكرا له على نعمه ، وداوم - أيضا - على طلب مغفرته لك وللمؤمنين .( إنه ) عز وجل - ( كان ) وما زال ( توابا ) أى : كثير القبول لتوبة عباده التائبين إليه ، كما قال - سبحانه - : ( وَهُوَ الذي يَقْبَلُ التوبة عَنْ عِبَادِهِ وَيَعْفُواْ عَنِ السيئات وَيَعْلَمُ مَا تَفْعَلُونَ ) نسأل الله - تعالى - أن يجعلنا من عباده التائبين توبة صادقة نصوحا .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"111":{"1":"معنى ( تَبَّتْ ) هلكت وخسرت ، ومنه قوله - تعالى - : ( وَمَا كَيْدُ فِرْعَوْنَ إِلاَّ فِي تَبَابٍ ) - سبحانه - : ( وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ ) وقوله : ( وَتَبَّ ) أى : وقد تب وهلك وخسر ، فالجملة الأولى دعاء عليك بالهلاك والخسران ، والجملة الثانية : إخبار عن أن هذا الدعاء قد استجيب ، وأن الخسران قد نزل به فعلا .أى : خسرت وخابت يدا أبى لهب ، وقد نزل هذا الهلاك والخسران به ، بسبب عداوته الشديدة للحق ، الذى جاء به النبى صلى الله عليه وسلم من عند ربه - سبحانه - .والمراد باليدين هنا : ذاته ونفسه ، من باب إطلاق الجزء وإرادة الكل ، كما فى قوله - تعالى - : ( ذلك بِمَا قَدَّمَتْ يَدَاكَ ) ويجوز أن يكون المراد باليدين حقيقتهما ، وذلك لأنه كان يقول : يعدنى محمد صلى الله عليه وسلم بأشياء ، لا أدرى أنها كائنة ، يزعم أنها بعد الموت ، فلم يضع فى يدى شئ من ذلك ، ثم ينفخ فى يديه ويقول : تبا لكما ما أرى فيكما شيئا .","2":"وقوله - سبحانه - ( مَآ أغنى عَنْهُ مَالُهُ وَمَا كَسَبَ ) كلام مستأنف للانتقال من ذمه والدعاء عليه بالهلاك ، إلى بيان أن ماله وجاهه . . لن يغنى عنه من عذاب الله - تعالى - شيئا .أى : أن أبا لهب لن يغنى عنه ماله الكثير ، وكسبه الوفير من حطام الدنيا . . لن يغنى عنه شيئا من عذاب الله - تعالى - ، أو شيئا من انتشار رسالة الله - تعالى - فى الأرض ، فإن الله - سبحانه - ناصر نبيه صلى الله عليه وسلم ومؤيده بروح منه .والتعبير بالماضى فى قوله : ( مَآ أغنى . . . ) لتحقيق وقوع عدم الإِغناء .والراجح أن \" ما \" الأولى نافية ، والثانية موصولة ، أى : ما أغنى عنه شيئا ماله الذى ورثه عن أبيه ، وأيضا ما أغنى عنه شيئا ماله الذى جمعه واكتسبه هو بنفسه عن طريق التجارة وغيرها .","3":"وقوله - سبحانه - : ( سيصلى نَاراً ذَاتَ لَهَبٍ ) بيان للعاقبة السيئة التى تنتظره ، بعد هذا الذم والتأنيب والوعيد . أى : سيلقى بأبى لهب فى نار شديدة الحرارة ، تشوى الوجوه والأبدان ، ووصف - سبحانه - النار بأنها \" ذات لهب \" لزيادة تقرير المناسبة بين اسمه وكفره ، إذ هو معروف بأبى لهب ، والنار موصوفة بأنها ذات لهب شديد .","4":"ثم أعقب - سبحانه - ذلك ، بذم زوجه التى كانت تشاركه العداوة لرسول الله صلى الله عليه وسلم فقال : ( وامرأته حَمَّالَةَ الحطب . فِي جِيدِهَا حَبْلٌ مِّن مَّسَدٍ ) .وقوله : ( وامرأته ) معطوف على الضمير المستتر العائد على أبى لهب فى قوله ( سيصلى ) وانتصاب لفظ \" حمالةَ \" على الذم بفعل مضمر ، لأن المقصود به هنا الذم ، وقرأ الجمهور ( حَمَّالَةَ ) - بالرفع - على أنه صفة لها ، أو خبر لمبتدأ محذوف ، أى : هى حمالة الحطب .والمقصود بقوله - تعالى - ( حَمَّالَةَ الحطب ) الحقيقة ، فقد روى أنها كانت تحمل بنفسها حزمة الشَّوْك والحسك والسَّعْدَان ، فتنثرها بالليل فى طريقه صلى الله عليه وسلم ، لإِيذائه به ، ويصح أن يكون المراد بهذه الجملة الكناية عن مشيها بين الناس بالنميمة ، وإشاعة السوء حول الرسول صلى الله عليه وسلم فإنه يقول لمن يمشى بالنميمة ليفسد بين الناس ، إنسان يحمل الحطب بين الناس ، أى : أنه يفسد بينهم .ويصح أن يكون المقصود بهذه الجملة ، حملها للذنوب والخطايا ، من قولهم : فلان يَحْطِب على ظهره ، إذا كان يكتسب الذنوب والخطايا ، فاستعير الحطب لذلك .وقد رجح الإِمام ابن جرير القول الأول ، لأنها كانت تحمل الشوك فتطرحه فى طريق النبى صلى الله عليه وسلم .","5":"وقوله - سبحانه - : ( فِي جِيدِهَا حَبْلٌ مِّن مَّسَدٍ ) زيادة فى تبشيع صورتها ، وتحقير هيئتها .والجيد : العنق ، والمسد : الليف المتين الذى فتل بشدة ، يقال : حبل ممسود ، أى مفتول فتلا قويا .والمعنى : سيصلى أبو لهب نارا شديدة ، وستصلى معه امرأته التى تضع الشوك فى طريق النبى صلى الله عليه وسلم هذه النار المشتعلة - أيضا - ، وسيزيد الله - تعالى - فى إذلالها وتحقيرها ، بأن يأمر ملائكته بأن تضع فى عنقها حبلا مفتولا فتلا قويا ، على سبيل الإِذلال والإِهانة لها ، لأنها كانت فى الدنيا تزعم أنها من بنات الأشراف الأكابر .روى عن سعيد بن المسيب أنه قال : كان لها قلادة ثمينة فقالت : لأبيعنها ولأنفقن ثمنها فى عداوة محمد صلى الله عليه وسلم فأبدلها الله عنها حبلا فى جيدها من مسد النار .والذى يتأمل هذه السورة الكريمة ، يراها قد اشتملت على أوضح الأدلة وأبلغ المعجزات الدالة على صدق النبى صلى الله عليه وسلم فيما يبلغه عن ربه ، فإن الله - تعالى - قد أخبر بشقاء أبى لهب وامرأته ، وأنهما سيصليان نارا ذات لهب . . وقد علما بما جاء فى هذه السورة من عقاب الله لهما . . ومع ذلك فقد بقيا على كفرهما حتى فارقا الحياة ، دون أن ينطقا بكلمة التوحيد ، ولو فى الظاهر - فثبت أن هذا القرآن من عند الله ، وأن الرسول صلى الله عليه وسلم صادق فيما يبلغه عن ربه - عز وجل - .نسأل الله - تعالى - أن يلحقنا بعباده الصالحين .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"112":{"1":"قد افتتحت بفعل الأمر \" قل \" لإِظهار العناية بما بعد هذا الأمر من توجيهات حكيمة ، ولتلقينه صلى الله عليه وسلم الرد على المشركين الذين سألوه أن ينسب لهم ربه .و ( هو ) ضمير الشأن مبتدأ ، والجملة التى بعده خبر عنه .والأحد : هو الواحد فى ذاته وفى صفاته وفى أفعاله ، وفى كل شأن من شئونه ، فهو منزه عن التركيب من جواهر متعددة ، أو من مادة معينة ، كما أنه - عز وجل - منزه عن الجسمية والتحيز ، ومشابهة غيره .وفى الإِتيان بضمير الشأن هنا : إشارة إلى فخامة مضمون الجملة ، مع ما فى ذلك من زيادة التحقيق والتقرير ، لأن الضمير يشير إلى شئ مبهم تترقبه النفس ، فإذا جاء الكلام من بعده زال الإِبهام ، وتمكن الكلام من النفس فضل تمكن .وجئ بالخبر نكره وهو لفظ \" أحد \" لأن المقصود الإِخبار عن الله - تعالى - بأنه واحد ، ولو قيل : الله الأحد ، لأفاد أنه لا واحد سواه ، وليس هذا المعنى مقصودا هنا ، وإنما المقصود إثبات أنه واحد فى ذاته وصفاته وأفعاله . . ونفى ما زعمه المشركون وغيرهم ، من أنه - تعالى - مركب من أصول مادية أو غير مادية ، أو من أنه له شريك فى ملكه .","2":"وقوله - سبحانه - ( الله الصمد ) أى : الله - تعالى - هو الذى يَصْمدُ إليه الخلق فى حوائجهم ، ويقصدونه وحده بالسؤال والطلب . . مأخوذ من قولهم صمد فلان إلى فلان . بمعنى توجه إليه بطلب العون والمساعدة .قال صاحب الكشاف : والصمد فعل بمعنى مفعول ، من صمد إليه إذا قصده ، وهو - سبحانه - المصمود إليه فى الحوائج ، والمعنى : هو الله الذى تعرفونه وتقرون بأنه خالق السموات والأرض ، وخالقكم ، وهو واحد متوحد بالإِلهية لا يشارك فيها ، وهو الذى يصمد إليه كل مخلوق لا يستغنون عنه ، وهو الغنى عنهم . .وجاء لفظ \" الصمد \" محلى بأل ، لإِفادة الحصر فى الواقع ونفس الأمر ، فإن قصد الخلق إليه - سبحانه - فى الحوائج ، أعم من الصد الإِرادى ، والقصد الطبيعى ، والقصد بحسب الاستعداد الأصلى ، الثابت لجميع المخلوقات إذ الكل متجه إليه - تعالى - طوعا وكرها .","3":"وقوله - سبحانه - : ( لَمْ يَلِدْ ) تنزيه له - تعالى - عن أن يكون له ولد أو بنت ، لأن الولادة تقتضى انفصال مادة منه ، وذلك يقتضى التركيب المنافى للأحدية والصمدية ، أو لأن الولد من جنس أبيه ، وهو - تعالى - منزه عن مجانسه أحد .وقوله : ( وَلَمْ يُولَدْ ) تنزيه له - تعالى - عن أن يكون له أب أو أم ، لأن المولودية تقتضى - أيضا - التركيب المنافى للأحدية والصمدية ، أو لاقتضائها سبق العدم ، أو المجانسة ، وكل ذلك مستحيل عليه - تعالى - فهو - سبحانه - :( الأول والآخر والظاهر والباطن وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ )","4":"وقوله - عز وجل - ( وَلَمْ يَكُنْ لَّهُ كُفُواً أَحَدٌ ) تنزيه له - تعالى - عن الشبيه والنظير والمماثل .والكفؤ : هو المكافئ والمماثل والمشابه لغيره فى العمل أو فى القدرة .أى : ولم يكن أحد من خلقه مكافئاً ولا مشاكلا ولا مناظرا له - تعالى - فى ذاته ، أو صفاته ، أو أفعاله ، فهو كما قال - تعالى - : ( لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السميع البصير ) وبذلك نرى أن هذه السورة الكريمة قد تضمنت نفى الشصرك بجميع ألوانه .فقد نفى - سبحانه - عن ذاته التعددد بقوله : ( الله أَحَدٌ ) ونفى عن ذاته النقص والاحتياج بقوله : ( الله الصمد ) ونفى عن ذاته أن يكون والدا أو مولودا بقوله : ( لَمْ يَلِدْ وَلَمْ يُولَدْ ) ، ونفى عن نفسه الأنداد والأشباه بقوله : ( وَلَمْ يَكُنْ لَّهُ كُفُواً أَحَدٌ ) .كما نراها قد تضمنت الرد على المشركين وأهل الكتاب ، وغيرهم من أصحاب الفرق الضالة ، الذين يقولون ، بالتثليث ، وبأن هناك آلهة أخرى تشارك الله - تعالى - فى ملكه .وبغير ذلك من الأقاويل الفاسدة والعقائد الزائفة . . - سبحانه وتعالى - عما يقولون علوا كبيرا .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم ."},"113":{"1":"الفلق : أصله شق الشئ عن الشئ ، وفصل بعض عن بعض ، والمراد به هنا : الصبح ، وسمى فلقا لإِنفلاق الليل وانشقاقه عنه ، كما فى قوله - تعالى - : ( فَالِقُ الإصباح ) أى : شاقٌّ ظلمة آخر الليل عن بياض الفجر . .ويصح أن يكون المراد به ، كل ما يفلقه الله - تعالى - من مخلوقات كالأرض التى تنفلق عن النبات ، والجبال التى تنفلق عن عيون الماء . .أى : قل - أيها الرسول الكريم - أعوذ وأستجير وأعتصم ، بالله - تعالى - الذى فلق الليل ، فانشق عنه الصباح ، والذى هو رب جميع الكائنات ، ومبدع كل المخلوقات . .","2":"قل أعوذ بهذا الرب العظيم ( مِن شَرِّ مَا خَلَقَ ) أى : من شر كل ذى شر من المخلوقات ، لأنه لا عاصم من شرها إلا خالقها - عز وجل - إذ هو المالك لها ، والمتصرف فى أمرها ، والقابض على ناصيتها ، والقادر على تبديل أحوالها ، وتغيير شئونها .","3":"ثم قال - تعالى - : ( وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ) والغاسق : الليل عندما يشتد ظلامه ، ومنه قوله - تعالى - : ( أَقِمِ الصلاة لِدُلُوكِ الشمس إلى غَسَقِ الليل . . . ) أى : إلى ظلامه .وقوله : ( وقب ) من الوقوب ، وهو الدخول ، يقال : وقبت الشمس إذا غابت وتوارت فى الأفق . أى : وقل أعوذ به - تعالى - من شر الليل إذا اشتد ظلامه ، وأسدل ستاره على كل شئ واختفى تحت جنحه ما كان ظاهرا .ومن شأن الليل عندما يكون كذلك ، أن يكون مخيفا مرعبا ، لأن الإِنسان لا يتبين ما استتر تحته من أعداء .","4":"ثم قال - سبحانه - : ( وَمِن شَرِّ النفاثات فِي العقد ) وأصل النفاثات جمع نفَّاثَة ، وهذا اللفظ صيغة مبالغة من النَّفث ، وهو النفخ مع ريق قليل يخرج من الفم .والعُقَد : جمع عُقْدة من العَقْدِ الذى هو ضد الحل ، وهى اسم لكل ما ربط وأحكم ربطه .والمراد بالنفاثات فى العقد : النساء السواحر ، اللائى يعقدن عقدا فى خيوط وينفثن عليها من أجل السحر .وجئ بصيغة التأنيث فى لفظ \" النفاثات \" لأن معظم السحرة كن من النساء .ويصح أن يكون النفاثات صفة للنفوس التى تفعل ذلك ، فيكون هذا اللفظ شاملا للذكور والإِناث .وقيل المراد بالنفاثات فى العقد : النمامون الذين يسعون بين الناس والفساد ، فيقطعون بما أمر الله به أن يوصل . . وعلى ذلك تكون فى \" النفاثة \" للمبالغة كعلامة وفهامة ، وليست للتأنيث .أى : وقل - أيضا - أستجير بالله - تعالى - من شرور السحرة والنمامين ، ومن كل الذين يفسدون فى الأرض ولا يصلحون .","5":"ثم ختم - سبحانه - السورة الكريمة بقوله : ( وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ) أى إذا ظهر ما فى نفسه من الحسد وعمل بمقتضاه بترتيب مقدمات الشر ، ومبادى الأضرار بالمحسود قولا وفعلا ..وقد نهى النبى صلى الله عليه وسلم عن الحسد فى أحاديث كثيرة منها قوله : \" لا تباغضوا ولا تحاسدوا . . \" .ومنها قوله : \" إياكم والحسد فإنه يأكل الحسنات ، كما تأكل النار الحطب \" .هذا ، وقد تكلم العلماء كلاما طويلا عند تفسيرهم لقوله - تعالى - : ( وَمِن شَرِّ النفاثات فِي العقد ) عن السحر ، فمنهم من ذهب إلى أنه لا حقيقة له وإنما هو تخييل وتمويه . .وجمهورهم على إثباته ، وأن له آثارا حقيقية ، وأن الساحر قد يأتى بأشياء غير عادية ، إلا أن الفاعل الحقيقى فى كل ذلك هو الله - تعالى - .وقد بسطنا القول فى هذه المسألة عند تفسيرنا لقوله - تعالى - فى سورة البقرة : ( واتبعوا مَا تَتْلُواْ الشياطين على مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ ولكن الشياطين كَفَرُواْ يُعَلِّمُونَ الناس السحر . . . ) نسأل الله - تعالى - أن يعيذنا من شرار خلقه . .وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم . ."},"114":{"1":"أى : قل - أيها الرسول الكريم - أعوذ وألتجئ وأعتصم \" برب الناس \" أى : بمربيهم ومصلح أمورهم ، وراعى شئونهم . . إذ الرب هو الذى يقوم بتدبير أمر غيره ، وإصلاح حاله . .","2":"( مَلِكِ الناس ) أى المالك لأمرهم ملكا تاما . والمتصرف فى شئونهم تصراف كاملا . .","3":"( إله الناس ) أى : الذى يدين له الناس بالعبودية والخضوع والطاعة لأنه هو وحده الذى خلقهم وأوجدهم فى هذه الحياة ، وأسبغ عليهم من النعم ما لا يحصى . .وبدأ - سبحانه - بإضافة الناس إلى ربهم ، لأن الربوبية من أوائل نعم الله - تعالى - على عباده ، وثنى بذكر المالك ، لأنه إنما يدرك ذلك بعد أن يصير عاقلا مدركا ، وختم بالإِضافة إلى الألوهية ، لأن الإِنسان بعد أن يدرك ويتعلم ، يدرك أن المستحق للعبادة هو الله رب العالمين .قال الجمل : وقد وقع ترتيب هذه الإِضافات على الوجه الأكمل ، الدال على الوحدانية ، لأن من رأى ما عليه من النعم الظاهرة والباطنة ، علم أن له مربيا ، فإذا درج فى العروج . .علم أنه - تعالى - غنى عن الكل ، والكل راجع إليه ، وعن أمره تجرى أمورهم ، فيعلم أنه ملكهم ، ثم يعلم بانفراده بتدبيرهم بعد إبداعهم ، أنه المستحق للألوهية بلا مشارك فيها . .وإنما خصت هذه الصفات بالإضافة إلى الناس - مع أنه - سبحانه - رب كل شئ - على سبيل التشريف لجنس الإِنسان ، ولأن الناس هم الذين أخطأوا فى حقه - تعالى - ، إذ منهم من عبد الأصنام ، ومنهم من عبد النار ، ومنهم من عبد الشمس إلى غير ذلك من المبعودات الباطلة التى هى مخلوقاتة له - تعالى - .قال صاحب الكشاف : فإن قلت : لم قيل : \" برب الناس \" مضافا إليهم خاصة . قلت : لأن الاستعاذة وقعت من شر الموسوس فى صدور الناس . فكأنه قيل : أعوذ من شر الموسوس إلى الناس بربهم ، الذى يملك عليهم أمورهم ، كما يستغيث بعض الموالى إذا اعتراهم خطب بسيدهم ومخدومهم ووالى أمرهم .فإن قلت : \" ملك الناس . إله الناس \" ما هما من رب الناس؟ قلت : هما عطفا بيان ، كقولك : سيرة أبى حفص عمر الفاروق . بين بملك الناس ، ثم زيد بيانا بإله الناس . .فإن قلت : فهلا اكتفى بإظهار المضاف إليه الذى هو الناس مرة واحدة؟ قلت : أظهر المضاف إليه الذى هو الناس لأن عطف البيان للبيان ، فكان مظنة للإِظهار دون الإِضمار . .","4":"وقوله - سبحانه - : ( مِن شَرِّ الوسواس الخناس ) متعلق بقوله ( أَعُوذُ ) .والوسواس : اسم للوسوسة وهى الصوت الخفى ، والمصدر الوِسْوَاس - بالكسر - ، والمراد به هنا : الوصف . من باب إطلاق اسم المصدر على الفاعل ، أو هو وصف مثل : الثرثار .و \" الخناس \" صيغة مبالغة من الخنوس ، وهو الرجوع والتأخر ، والمراد به : الذى يلقى فى نفس الإِنسان أحاديث السوء .","5":"وقوله : ( الذى يُوَسْوِسُ فِي صُدُورِ الناس ) صفة لهذا الوسواس الخناس وزيادة توضيح له . .","6":"وقوله : ( مِنَ الجنة والناس ) زيادة بيان للذى يوسوس فى صدور الناس ، وأن الوسوسة بالسوء تأتى من نوعين من المخلوقات : تأتى من الشياطين المعبر عنهم بالجِنّةِ . . وتأتى من الناس .وقدم - سبحانه - الجِنَّة على الناس ، لأنهم هم أصل الوسواس ، إذ أنهم مختفون عنا ، ولا نراهم ، كما قال - تعالى - : ( إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لاَ تَرَوْنَهُمْ ) فلفظ الجِنَّة - بكسر الجيم - مأخوذ من الجَنِّ - بفتح الجيم - على معنى الخفاء والاستتار .والمعنى : قل - أيها الرسول الكريم - أعوذ وأعتصم وأستجير ، برب الناس ، ومالكهم ومعبودهم الحق ، من شر الشيطان الموسوس بالشر ، والذى يخنس ويتأخر ويندحر ، إذا ما تيقظ له الإِنسان ، واستعان عليه بذكر الله - تعالى - .والذى من صفاته - أيضا - أنه يوسوس فى صدور الناس بالسوء والفحشاء ، حيث يلقى فيها خفية ، ما يضلها عن طريق الهدى والرشاد .وهذا الوسواس الخناس ، قد يكون من الجن ، وقد يكون من الإِنس ، فعليك - أيها الرسول الكريم - أن تستعيذ بالله - تعالى - من شر النوعين جميعا .قال - تعالى - : ( وَكَذَلِكَ جَعَلْنَا لِكُلِّ نِبِيٍّ عَدُوّاً شَيَاطِينَ الإنس والجن يُوحِي بَعْضُهُمْ إلى بَعْضٍ زُخْرُفَ القول غُرُوراً . . . ) قال قتادة : إن من الجن شياطين ، وإن من الإِنس شيطاطين ، فنعوذ بالله من شياطين الإِنس والجن .وقال الإِمام ابن كثير : هذه ثلاث صفات من صفات الله - عز وجل - الربوبية ، والملك ، والألوهية .فهو رب كل شئ ومليكه وإله ، فميع الأشياء مخلوقة له . . فأمر سبحانه - المستعيذ أن يتعوذ بالمتصف بهذه الصفات ، من شر الوسواس الخناس ، وهو الشيطان الموكل بالإِنسان ، فإنه ما من أحد من بنى آدم ، إلا وله قرين يزين له الفواحش . . والمعصوم من عمصه الله .وقد ثبت فى الصحيح أن رسول الله صلى الله عليه وسلم قال : \" \" ما منكم من أحد إلا قد وكل به قرينه \" قالوا : وأنت يا رسول الله؟ قال : \" نعم ، إلا أن الله - تعالى - أعاننى عليه فأسلم ، فلا يأمرنى إلا بخير \" \" .ومن الأحاديث التى وردت فى فضل هذه السور الثلاث : الإِخلاص والمعوذتين ، ما أخرجه البخارى عن عائشة - رضى الله عنها - \" أن النبى صلى الله عليه وسلم كان إذا أوى إلى فراشه كل ليلة ، جمع كفيه ثم ينفث فيهما فيقرأ هذه السور ، فم يمسح بهما ما استطاع من جسده ، ويبدأ بها على رأسه ووجهه ، وما أقبل من جسده ، يفعل ذلك ثلاث مرات \" ."}};
